    // MARK: - Battery and telemetry

    func chargeDroneAndContinue() {
        batteryState.chargePercent = 100
        showBatteryDepletedDialog = false
        setFlightMode(.hover, reason: "battery_recovery_hover")
        lockControlsToCurrentState(overrideThrottle: Double(resolvedFlightBaseline(for: .hover).hoverLockThrottle))
    }

    /// Battery thermal-runaway/rupture: visual consequence only (flame + smoke, instant power
    /// loss) — no secondary component damage, matching a fire that starts *because* the pack
    /// failed rather than one more structural failure of its own. Idempotent: a second trigger
    /// while already on fire is a no-op, so the impact path and the per-tick overheat/discharge
    /// checks can both call this without double-igniting.
    private func igniteBatteryFireIfNeeded(reason: String) {
        guard !batteryFireActive, componentGraph.component(id: "battery") != nil else { return }
        batteryFireActive = true
        batteryFireIgnitedAtSimulationTime = TimeInterval(simulationTime)
        // Otherwise this would still read >= batteryOverheatDurationSec on the very next check
        // once the fire's own timeline clears batteryFireActive, re-igniting it immediately.
        sustainedMaxThrottleSeconds = 0.0
        batteryState.chargePercent = 0.0
        damageEventRecorder.record(
            timestamp: TimeInterval(simulationTime),
            type: .subsystemFailed,
            componentID: "battery",
            reason: reason
        )
    }

    /// Per-tick ignition check plus the flame → smoke-tail → out timeline once burning.
    ///
    /// Overheat trigger: holding throttle at (near) 100% continuously for
    /// `batteryOverheatDurationSec` — eases off the instant the operator lets go, by design (a
    /// pilot who backs off periodically is managing the pack, not abusing it). At that point the
    /// pack is asked to sustain its computed "critical" continuous current — capacity x a generic
    /// hobby-LiPo C-rating — and real packs can't do that indefinitely without heat damage.
    /// Requiring *both* the duration and the current actually being at/above that critical level
    /// (rather than duration alone) means a already-weakened/damaged pack, which draws more
    /// current for the same throttle, can cross it sooner — consequence compounds on prior damage.
    /// The over-discharge leg specifically wants continued *load* on an empty pack (a paperweight
    /// sitting at 0% on the ground is not the failure mode) — mirrors `BatteryState.isDepleted`'s
    /// 0.1% floor.
    private func updateBatteryFireState(deltaTime: Float) {
        if !batteryFireActive {
            if isArmed, state.throttle >= Self.batteryOverheatThrottleThreshold {
                sustainedMaxThrottleSeconds += deltaTime
            } else {
                sustainedMaxThrottleSeconds = 0.0
            }

            let criticalContinuousCurrentA = (selectedDroneProfile.batteryCapacitymAh / 1000.0) *
                Self.batteryContinuousDischargeCRating
            let isDrawingCriticalCurrent = batteryState.currentDrawA >= criticalContinuousCurrentA * 0.9

            if sustainedMaxThrottleSeconds >= Self.batteryOverheatDurationSec, isDrawingCriticalCurrent {
                igniteBatteryFireIfNeeded(reason: "battery_sustained_overcurrent")
            } else if batteryState.chargePercent <= 0.1, batteryState.powerDrawW > 5.0 {
                igniteBatteryFireIfNeeded(reason: "battery_over_discharge")
            }
        }

        guard batteryFireActive, let ignitedAt = batteryFireIgnitedAtSimulationTime else {
            return
        }
        let elapsed = Float(TimeInterval(simulationTime) - ignitedAt)
        let flameActive = elapsed < Self.batteryFireFlameDurationSec
        let smokeActive = elapsed < Self.batteryFireFlameDurationSec + Self.batteryFireSmokeTailDurationSec
        sceneController.updateBatteryFireVisual(
            flameActive: flameActive,
            smokeActive: smokeActive,
            localPosition: componentGraph.component(id: "battery")?.localPosition ?? .zero
        )
        if !flameActive, !smokeActive {
            batteryFireActive = false
            batteryFireIgnitedAtSimulationTime = nil
        }
    }

    func simulateAgainFromStart() {
        showBatteryDepletedDialog = false
        reset()
    }

    func exportTelemetry() {
        let metadata = buildTelemetryMetadata()

        let panel = NSOpenPanel()
        panel.canChooseDirectories = true
        panel.canChooseFiles = false
        panel.canCreateDirectories = true
        panel.allowsMultipleSelection = false
        panel.message = String(localized: "telemetry.export.select_folder")
        panel.prompt = String(localized: "common.export")

        guard panel.runModal() == .OK else {
            return
        }

        switch telemetryExporter.exportNow(metadata: metadata, destinationDirectory: panel.url) {
        case let .success(url):
            telemetryExportAlert = TelemetryExportAlert(
                titleKey: "telemetry.export.success",
                message: url.path
            )
        case let .failure(error):
            telemetryExportAlert = TelemetryExportAlert(
                titleKey: "telemetry.export.failure",
                message: error.localizedDescription
            )
        }
    }

    // MARK: - Project persistence

    func assignProjectContext(id: String, name: String) {
        currentProjectID = id
        currentProjectName = name
    }

    func renameProject(_ name: String) {
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        currentProjectName = trimmed
        hasUnsavedChanges = true
    }

    func saveProject() -> Result<ProjectRecordSummary, Error> {
        let snapshot = buildProjectSnapshot()
        do {
            let saved = try projectStorage.saveProject(
                id: currentProjectID,
                name: currentProjectName,
                snapshot: snapshot
            )
            hasUnsavedChanges = false
            currentProjectID = saved.id
            currentProjectName = saved.name

            _ = telemetryExporter.persistInternalSession(metadata: buildTelemetryMetadata())
            return .success(saved)
        } catch {
            return .failure(error)
        }
    }

    func saveProjectAs(name: String) -> Result<ProjectRecordSummary, Error> {
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            return .failure(ProjectStorageError.writeFailed)
        }
        currentProjectID = projectStorage.createProjectID()
        currentProjectName = trimmed
        return saveProject()
    }

    func loadProject(id: String) -> Result<ProjectRecordSummary, Error> {
        do {
            let snapshot = try projectStorage.loadProject(id: id)
            applyProjectSnapshot(snapshot)
            currentProjectID = snapshot.projectID
            currentProjectName = snapshot.projectName
            hasUnsavedChanges = false

            let summary = projectStorage.listProjects().first(where: { $0.id == id }) ??
                ProjectRecordSummary(
                    id: snapshot.projectID,
                    name: snapshot.projectName,
                    createdAt: snapshot.savedAt,
                    modifiedAt: snapshot.savedAt,
                    lastOpenedAt: snapshot.savedAt,
                    lastSavedAt: snapshot.savedAt
                )
            return .success(summary)
        } catch {
            return .failure(error)
        }
    }

    func duplicateCurrentProject(newName: String) -> Result<ProjectRecordSummary, Error> {
        do {
            let duplicated = try projectStorage.duplicateProject(id: currentProjectID, newName: newName)
            return .success(duplicated)
        } catch {
            return .failure(error)
        }
    }

    func deleteCurrentProject() -> Result<Void, Error> {
        do {
            try projectStorage.deleteProject(id: currentProjectID)
            return .success(())
        } catch {
            return .failure(error)
        }
    }

    func performAutosaveIfNeeded() {
        let snapshot = buildProjectSnapshot()
        try? projectStorage.autosave(projectID: currentProjectID, snapshot: snapshot)
    }

    private func refreshKeyBindingDiagnostics() {
        bindingsViewModel.refresh()
        keyBindingSections = bindingsViewModel.sections
        keyBindingConflicts = bindingsViewModel.conflicts
    }

    private func regenerateEnvironment() {
        clearMissionPlan()
        cancelPendingTerrainDensityRegeneration()
        clearTargetMarker()
        autoPathPlanner.invalidate()
        navigationSnapshot = .idle
        autoFlightGoal = nil
        autoFlightGoalIndex = 0
        if mode == .returnHome {
            returnHomeStage = .ascend
        }
        sceneController.regenerateEnvironment(terrain)
        sceneController.setWorldBoundsVisible(isBoundaryBarrierVisible)
        refreshSceneLaunchAsset()
        homePosition = currentSpawnPoint()
        enforceRuntimeSafetyAndBounds(context: "regenerate_environment")
        sceneController.update(
            with: state,
            camera: cameraConfiguration,
            damage: damageState,
            thermal: thermalState,
            diagnosticMode: diagnosticMode,
            deltaTime: 0.0
        )
        resetTerrainMapTrail()
        refreshTerrainMapSnapshot(recordTrail: false)
    }

    private func scheduleTerrainRegeneration(
        resetAfter: Bool,
        delayNanoseconds: UInt64 = 90_000_000
    ) {
        let requiresReset = pendingTerrainRegenerationRequiresReset || resetAfter
        cancelPendingTerrainDensityRegeneration()
        pendingTerrainRegenerationRequiresReset = requiresReset
        pendingTerrainRegenerationTask = Task { @MainActor [weak self] in
            try? await Task.sleep(nanoseconds: delayNanoseconds)
            guard !Task.isCancelled, let self else {
                return
            }
            self.commitPendingTerrainDensityRegeneration()
        }
    }

    private func cancelPendingTerrainDensityRegeneration() {
        pendingTerrainRegenerationTask?.cancel()
        pendingTerrainRegenerationTask = nil
        pendingTerrainRegenerationRequiresReset = false
    }

    private func commitPendingTerrainDensityRegeneration() {
        let requiresReset = pendingTerrainRegenerationRequiresReset
        pendingTerrainRegenerationTask = nil
        pendingTerrainRegenerationRequiresReset = false
        regenerateEnvironment()
        if requiresReset {
            reset()
        }
    }

    /// One timer fire: advances the world by `timeScale` ticks and presents once.
    ///
    /// Time acceleration is *more steps*, never a bigger step. `SimpleDronePhysicsEngine.step`
    /// clamps the delta it is given to 1/20 s and walks it in fixed 1/90 s substeps, so handing it
    /// a larger delta would silently discard the extra time rather than simulate it — and even if
    /// it did not, integrating attitude at 0.7 s per step is meaningless for an airframe whose
    /// roll mode settles in about a second.
    ///
    /// The catch-up steps run the whole simulation — physics, autopilot, collision analysis — and
    /// skip only presentation, so what the operator watches at 64x is the same flight they would
    /// have watched at 1x, just sampled less often.
    private func runSimulationFrame() {
        // No automatic cancellation. `operatorIsOnTheControls` is written by
        // `updateControlValues(markManual:)`, which every UI setter goes through — so opening a
        // panel or pressing a header button counted as "flying" and silently dropped the world
        // back to 1x. The operator's rule stands: if the speed is set, it is set, and only the
        // operator unsets it.
        let steps = max(1, timeScale.stepsPerFrame)
        guard steps > 1 else {
            tick()
            return
        }

        // One wall-clock delta for the whole frame, spent as `steps` equal simulated steps. Taking
        // the delta once is what makes the multiplier exact: reading the clock per step would give
        // every step after the first a delta of nearly zero.
        let now = CACurrentMediaTime()
        let wallDelta = Float(max(1.0 / 240.0, min(now - (lastTimestamp ?? now), 1.0 / 20.0)))

        // A frame that overruns its own budget must not spiral: each overrun would make the next
        // frame's wall delta larger, which asks for even more work. Stop early and report what was
        // actually achieved instead of falling further behind.
        let budget = Self.simulationTickInterval * 3.0
        let frameStarted = CACurrentMediaTime()
        var completed = 0

        for index in 0..<steps {
            isCatchUpStep = index < steps - 1
            forcedDeltaTime = wallDelta
            tick()
            completed += 1
            if isCatchUpStep, CACurrentMediaTime() - frameStarted > budget {
                // Present this one after all, so the frame the operator sees is the last one
                // simulated rather than a stale one.
                isCatchUpStep = false
                forcedDeltaTime = wallDelta
                tick()
                completed += 1
                break
            }
        }

        isCatchUpStep = false
        forcedDeltaTime = nil
        achievedTimeScale = Double(completed)
    }

    private func startSimulationLoop() {
        simulationTimer?.invalidate()
        simulationTimer = Timer(timeInterval: Self.simulationTickInterval, repeats: true) { [weak self] _ in
            guard let self else {
                return
            }
            MainActor.assumeIsolated {
                self.runSimulationFrame()
            }
        }
        simulationTimer?.tolerance = Self.simulationTickInterval * 0.08

        if let simulationTimer {
            RunLoop.main.add(simulationTimer, forMode: .common)
        }
    }

    // MARK: - Mission scenario (SAR)

    var hasMissionScenario: Bool { missionScenarioConfiguration != nil }

    var activeMissionScenarioKind: MissionScenarioKind? {
        missionScenarioConfiguration?.parameters.kind
    }

    /// One-time setup when the view model was launched with a mission scenario: applies the
    /// environment (terrain/weather/time-of-day), installs the payload, then spawns the scenario
    /// and starts the runtime. Runs on the first tick so the scene graph is fully constructed.
    private func bootstrapMissionScenarioIfNeeded() {
        guard !didBootstrapMissionScenario, let config = missionScenarioConfiguration else { return }
        didBootstrapMissionScenario = true

        let params = config.parameters
        setTerrainPreset(params.terrain)
        // Search missions need real cover to search through — the terrain preset's generic
        // default density (0.72 for forest) reads too sparse for "the target could be behind any
        // of these trees" to feel true. Player picks the density preset in MissionSetupView
        // (MissionTerrainDensity); the small mission boost on top (see
        // TerrainConfiguration.missionDensityBoost) is now just a safety margin, not the main
        // lever — most of the visible density now comes from concentrating generation around the
        // search sector (see ScenePopulationService.generateForest's sector-bias split) rather
        // than from maxing out density/cap multipliers across the whole map.
        terrain.missionDensityBoost = true
        setTerrainDensity(Double(params.terrainDensity.densityValue))
        // Object count is capped at a fixed pool regardless of map size (see
        // ScenePopulationService.maxCollidableObjectCount, a collision/pathfinding performance
        // ceiling) — so density alone barely helps if the map is much bigger than the search
        // sector; that fixed pool just spreads thinner. Shrink the map to fit the sector instead,
        // which makes the same tree count read as a real forest. Mutating mapScale directly
        // (rather than calling setTerrainMapScale) skips its resetAfter:true, which would wipe
        // the drone back to spawn mid-bootstrap.
        //
        // `MissionDifficulty.recommendedMapScale` shrinks easy/medium down to `.x8` — right for
        // SAR (a smaller search sector should feel like a smaller, tighter search), but this same
        // fixed-pool-cap-regardless-of-map-size mechanic backfires for Fire Response: confirmed via
        // a user's Debug log + testing that easy/medium's `.x8` map crams roughly the same ambient
        // tree count into 1/4 the area of hard's `.x16`, so easy/medium missions were the *more*
        // GPU-taxed ones, backwards from what difficulty would suggest. Fire Response's own
        // difficulty scaling already lives in fireZoneRadiusMeters/fireTreeCount/spread rate, not
        // overall map size, so it always gets the larger `.x16` regardless of difficulty instead of
        // inheriting SAR's shrink-for-easier-difficulty logic.
        // A difficulty/mission-kind baseline is a floor, not a ceiling. Two separate reasons a
        // fixed-wing aircraft needs more room than that baseline:
        //  1. A large/long-range airframe (e.g. the MQ-9B SkyGuardian, 24 m wingspan) needs more
        //     maneuvering room in general — `DroneModelProfile.preferredMapScaleMin` already
        //     computes exactly this per aircraft (turn radius/maneuver comfort, used elsewhere for
        //     free-flight map selection).
        //  2. Confirmed via user testing: even a merely medium airframe (FT5 Łoś) that does NOT
        //     trip `preferredMapScaleMin` still flew clean past the world boundary — signal-loss
        //     locks flight controls entirely (see `signal_loss.lost_message`), and unlike a
        //     multirotor a fixed-wing can't just stop and hover to avoid it. It can't loiter in
        //     place while working a mission's target cluster; every attack pass needs a wide
        //     banking turn to reposition, and that turn's radius alone can exceed a "just barely
        //     big enough" map's margin even when nothing about the airframe looks oversized on
        //     paper. So ANY fixed-wing gets a flat floor here, not just ones flagged by
        //     `preferredMapScaleMin`.
        let fixedWingFloor: MapScale = (
            selectedDroneProfile.airframeClass == .fixedWing ||
                selectedDroneProfile.airframeClass == .hybridVTOL
        ) ? .x32 : .x4
        let missionKindBaseline = params.kind == .fireResponse ? MapScale.x16 : params.difficulty.recommendedMapScale
        let aircraftMinScale = selectedDroneProfile.operationalProfile.preferredMapScaleMin
        let recommendedScale = [missionKindBaseline, aircraftMinScale, fixedWingFloor]
            .max { $0.numericPreset < $1.numericPreset }!
        if terrain.mapScale != recommendedScale {
            terrain.mapScale = recommendedScale
            terrain.safeSpawnRadius = recommendedSafeSpawnRadius(for: recommendedScale)
            scheduleTerrainRegeneration(resetAfter: false)
        }
        setWeatherPreset(params.weather)
        setWeatherIntensity(Double(params.weatherIntensity))
        // The scenario's coarse choice is now a *starting* time, not a fixed one: the world clock
        // takes it as its start hour and runs from there.
        resetWorldClock(to: params.timeOfDay)

        setPayloadType(config.payloadType)
        if config.payloadType == .fireHose {
            setFireHoseRigging(
                diameterClass: config.fireHoseDiameterClass,
                lengthMeters: Double(config.fireHoseLengthMeters)
            )
        } else if config.payloadType == .fireCapsuleLauncher {
            setFireCapsuleRigging(
                size: config.fireCapsuleSize,
                count: config.fireCapsuleCount
            )
        }
        attachPayload()

        let dock = sceneController.currentDockSpawnPoint()
        // Concentrate forest generation around the sector/zone instead of the whole map — set
        // before the still-pending debounced regen (scheduled above) fires, so this terrain
        // mutation rides along with the others into the same regeneration pass.
        switch params.kind {
        case .searchAndRescue:
            let placement = MissionScenarioPlacement.generate(
                parameters: params,
                worldHalfExtent: terrain.worldHalfExtent,
                dockPosition: SIMD2<Float>(dock.x, dock.z)
            )
            terrain.missionSearchSectorCenter = placement.sectorCenter
            terrain.missionSearchSectorRadius = placement.sectorRadius
            let target = sceneController.spawnMissionSearchScenario(placement: placement)
            missionScenarioTargetWorldPosition = target
            missionScenarioRuntime = MissionScenarioRuntime(configuration: config, placement: placement)
            publishMissionScenarioState()
        case .fireResponse:
            // Only the hose has a real physical tether to the truck. The capsule launcher has no
            // such hard constraint, but it still needs a real, difficulty-scaled "operational
            // reach" here — a recharge system depends on the truck sitting a meaningful (and
            // harder-scaling) distance from the fire, so a fallback to the world's own half-extent
            // would place the truck absurdly far away regardless of difficulty. Any other payload
            // (no tether, no recharge logistics) still falls back to the unconstrained half-extent.
            let riggedTetherLength: Float
            switch config.payloadType {
            case .fireHose:
                riggedTetherLength = config.fireHoseLengthMeters
            case .fireCapsuleLauncher:
                riggedTetherLength = FireCapsuleTuning.truckOperationalReachMeters(for: params.difficulty)
            default:
                riggedTetherLength = terrain.worldHalfExtent
            }
            let placement = FireZonePlacement.generate(
                parameters: params,
                worldHalfExtent: terrain.worldHalfExtent,
                dockPosition: SIMD2<Float>(dock.x, dock.z),
                tetherLengthMeters: riggedTetherLength
            )
            // Deliberately NOT setting terrain.missionSearchSectorCenter/Radius here (unlike SAR):
            // ScenePopulationService's sector-bias concentrates a near-fixed ambient-forest object
            // budget (~26 clusters × 12-24 trees each) into that radius regardless of how small it
            // is — fine for SAR's 90-320m search sectors, but the hose-tether-derived fire zone
            // can be a small fraction of that (as low as a few meters for a short narrow hose),
            // which crammed hundreds of overlapping ambient trees on top of the dedicated fire
            // trees. The fire zone already gets its own dense, guaranteed tree population from
            // `spawnFireResponseScenario`; the ambient forest doesn't need to also pile in.
            sceneController.spawnFireResponseScenario(placement: placement)
            fireResponseRuntime = FireResponseRuntime(configuration: config, placement: placement)
            publishFireResponseState()
        }
    }

    private func updateMissionScenarioRuntime(deltaTime: TimeInterval) {
        guard var runtime = missionScenarioRuntime,
              runtime.isActive,
              let target = missionScenarioTargetWorldPosition else { return }

        // Detection requires the operator to actually be watching the payload feed — the gimbal
        // is slaved to drone body orientation (it has no independent mouse-look; aim comes from
        // yaw/pitch sliders in the Camera module) plus a small fixed offset, so without this gate
        // the target could be "found" just by flying near it while looking through any other
        // camera, with nobody ever looking at the payload picture.
        let isWatchingPayloadFeed = cameraConfiguration.mode == .payloadOptics && isMountedPayloadCameraAvailable
        // Detection must mean "crosshair is actually on the target", not "target is somewhere in
        // the wide-FOV frame" — 0.7x half-FOV (tried previously) still covered most of the
        // picture at wide zoom. 0.08x requires the target to sit within ~8% of the frame's half
        // extent from center: a real, deliberate aim, not just generic framing. Floored so very
        // high zoom (FOV ~1°) doesn't demand literally sub-pixel precision.
        let liveFovHalfAngle = Float(payloadCameraController.opticsState.currentFieldOfViewDegrees) * 0.5
        let effectiveConeHalfAngle = min(
            runtime.tuning.coneHalfAngleDegrees,
            max(0.3, liveFovHalfAngle * 0.08)
        )
        let sample = isWatchingPayloadFeed
            ? sceneController.payloadCameraMissionSample(
                targetWorldPosition: target,
                maxRangeMeters: runtime.tuning.maxRangeMeters,
                coneHalfAngleDegrees: effectiveConeHalfAngle
            )
            : nil
        runtime.tick(deltaTime: deltaTime, sample: sample)
        missionScenarioRuntime = runtime
        publishMissionScenarioState()

        if let outcome = runtime.outcome {
            handleMissionScenarioOutcome(outcome)
        }
    }

    private func publishMissionScenarioState() {
        guard let runtime = missionScenarioRuntime else { return }
        missionScenarioObjectiveState = runtime.objectiveState
        missionScenarioRemainingSeconds = runtime.remainingClampedSeconds
        missionScenarioDetectionProgress = runtime.detectionProgress
        missionScenarioOutcome = runtime.outcome
    }

    private func handleMissionScenarioOutcome(_ outcome: MissionScenarioOutcome) {
        guard !didReportMissionScenarioOutcome else { return }
        didReportMissionScenarioOutcome = true
        switch outcome {
        case let .success(elapsed):
            print("[MissionScenario] target detected after \(String(format: "%.1f", elapsed))s")
        case .failureTimeout:
            print("[MissionScenario] failed — time limit reached")
        case .aborted:
            print("[MissionScenario] aborted")
        }
    }

    // MARK: - Mission scenario (Fire Response)

    private func updateFireResponseRuntime(deltaTime: TimeInterval) {
        guard var runtime = fireResponseRuntime, runtime.isActive else { return }

        runtime.tick(
            deltaTime: deltaTime,
            aimedFireIndex: hoseOpticsState.aimedFireTreeIndex,
            isSpraying: hoseOpticsState.isSpraying
        )
        fireResponseRuntime = runtime
        sceneController.updateFireResponseVisuals(
            treeStatuses: runtime.treeStatuses,
            viewerWorldPosition: finiteVector(state.position, fallback: lastFiniteState.position)
        )
        publishFireResponseState()

        if let outcome = runtime.outcome {
            handleFireResponseOutcome(outcome)
        }
    }

    private func publishFireResponseState() {
        guard let runtime = fireResponseRuntime else { return }
        fireResponseObjectiveState = runtime.objectiveState
        fireResponseRemainingSeconds = runtime.remainingClampedSeconds
        fireResponseBurningCount = runtime.burningCount
        fireResponseTotalCount = runtime.treeStatuses.count
        fireResponseOutcome = runtime.outcome
    }

    private func handleFireResponseOutcome(_ outcome: FireResponseOutcome) {
        guard !didReportFireResponseOutcome else { return }
        didReportFireResponseOutcome = true
        switch outcome {
        case let .success(elapsed):
            print("[FireResponse] all fires extinguished after \(String(format: "%.1f", elapsed))s")
        case .failureTimeout:
            print("[FireResponse] failed — time limit reached")
        case .aborted:
            print("[FireResponse] aborted")
        }
    }

    /// Increment-1 manual test hook: extinguishes the fire nearest the drone's current position,
    /// bypassing the (not-yet-built) hose-aim requirement. Exposed for a temporary HUD debug
    /// button; removed once the real hose payload lands.
    func debugExtinguishNearestFireResponseTree() {
        guard var runtime = fireResponseRuntime, runtime.isActive else { return }
        runtime.debugExtinguishNearestFire(to: currentPlanarPosition())
        fireResponseRuntime = runtime
        sceneController.updateFireResponseVisuals(
            treeStatuses: runtime.treeStatuses,
            viewerWorldPosition: finiteVector(state.position, fallback: lastFiniteState.position)
        )
        publishFireResponseState()
        if let outcome = runtime.outcome {
            handleFireResponseOutcome(outcome)
        }
    }

    /// Sets how fast the world runs.
    ///
    /// Fast-forward is for watching, not for flying: at 32× a single rendered frame covers half a
    /// second of flight, so a hand on the sticks cannot close a control loop. Rather than refuse
    /// the setting, the loop drops back to real time the moment the operator touches anything —
    /// the same rule the assists follow, so the pilot never fights a hidden mode.
    func setTimeScale(_ scale: SimulationTimeScale) {
        guard scale != timeScale else { return }
        timeScale = scale
        if scale == .realtime { achievedTimeScale = 1.0 }
    }


    /// Advances the world's clock and pushes the consequences out — the displayed time, and the
    /// scene's lighting when the sun has actually moved.
    ///
    /// Called once per simulation tick with that tick's simulated `dt`. Under time acceleration
    /// the tick runs more often, so the day speeds up on its own: the multiplier lives in how
    /// often simulated time is advanced, not in a second factor here that could drift out of step
    /// with the physics.
    private func advanceWorldClock(bySimulatedSeconds seconds: Double) {
        worldClock.advance(bySimulatedSeconds: seconds)

        let text = worldClock.formattedTime
        if text != worldClockText { worldClockText = text }
        let phase = worldClock.phase
        if phase != worldDayPhase { worldDayPhase = phase }

        let elevation = worldClock.sunElevationDegrees
        guard abs(elevation - lastAppliedSunElevationDegrees) >= 0.25 else { return }
        lastAppliedSunElevationDegrees = elevation
        sceneController.applyWorldClock(worldClock)
    }

    /// Puts the world clock at a known time and relights the scene for it immediately, rather than
    /// waiting for the sun to drift a quarter-degree.
    private func resetWorldClock(to timeOfDay: TimeOfDay) {
        worldClock = WorldClock(timeOfDay: timeOfDay)
        worldClockText = worldClock.formattedTime
        worldDayPhase = worldClock.phase
        lastAppliedSunElevationDegrees = worldClock.sunElevationDegrees
        sceneController.applyWorldClock(worldClock)
    }

    /// Obstacles the proximity analysis should consider this tick.
    ///
    /// A swept tube along the velocity rather than a sphere around the aircraft. The
    /// distinction only starts to matter once the horizon grows: a sphere costs
    /// horizon², so a 900 m horizon would sweep some three thousand broad-phase cells
    /// every tick, while a tube of the same reach touches a few dozen — and a tube is
    /// the more honest shape anyway, because what an aircraft doing 600 m/s needs to
    /// know about is what lies ahead of it, not what it left behind.
    ///
    /// Below the horizon's anchor speed this is the sphere query it has always been —
    /// the same call, the same radius, the same obstacles — so every aircraft that is
    /// not going fast enough for the horizon to open up is untouched.
    private func collisionCandidateObstacles(
        at position: SIMD3<Float>,
        velocity: SIMD3<Float>
    ) -> [CollisionObstacle] {
        let speed = simd_length(velocity)
        let margin = collisionService.spatialQueryRadius
        let horizon = collisionService.broadPhaseDistance(forSpeedMps: speed)
        guard speed.isFinite, speed > 1.0, horizon > margin else {
            return sceneController.nearbyEnvironmentObstacles(near: position, radius: margin)
        }
        let ahead = position + (velocity / speed) * horizon
        return sceneController.nearbyEnvironmentObstacles(
            from: position,
            to: ahead,
            margin: margin
        )
    }

    private func tick() {
        let frameStart = CACurrentMediaTime()
        let now = CACurrentMediaTime()

        // v1.4.6: drive interacting → activeIdle transition (key window, no input for 1 s).
        // The reverse (activeIdle → interacting) is triggered immediately by noteUserInteraction().
        if currentVisibilityState == .activeVisible,
           performancePolicy.activityState == .interacting,
           now - lastUserInteractionAt >= 1.0 {
            refreshActivityPolicy(now: now)
        }
        // Arming happens while the window may already be non-key (the operator arms from the
        // tactical map). Nothing else re-evaluates the policy in that case — `noteUserInteraction`
        // is gated on `.activeVisible` — so the flight would run at half rate until the main window
        // was clicked. See `localVehicleIsBeingFlown`.
        if currentVisibilityState == .inactiveVisible,
           performancePolicy.activityState == .backgroundIdle,
           localVehicleIsBeingFlown {
            refreshActivityPolicy(now: now)
        }

        // v1.4.3+: when throttled, run only 1 in N full ticks. Online work is split:
        //   • stopRendering=false (inactive): scene interpolation runs on skip ticks too so
        //     remote replicas stay smooth between 30 Hz full ticks.
        //   • stopRendering=true (minimized/hidden): skip-ticks do nothing but TX rate-check;
        //     full tick (5 Hz) handles cleanup, interpolation, and scene apply.
        if performancePolicy.isThrottled {
            backgroundTickSkipCounter += 1
            if backgroundTickSkipCounter < performancePolicy.backgroundTickDivisor {
                if onlineRuntimeContext != nil {
                    if shouldPresentThisStep {
                        cleanupOnlineRemoteSnapshotsIfNeeded(now: now)
                        updateOnlineInterpolatedRemoteStates(now: now)
                    }
                    publishOnlineVehicleSnapshotIfNeeded(now: now)
                }
                return
            }
            backgroundTickSkipCounter = 0
        }

        bootstrapMissionScenarioIfNeeded()

        guard let lastTimestamp else {
            self.lastTimestamp = now
            let resolvedInput = updateInputPipeline(deltaTime: 0.0)
            let controllerSnapshot = inputManager.snapshot(for: .gameController)
            if isSpectatorMode {
                updateSpectatorRuntime(deltaTime: 0.0)
                return
            }
            syncControllerInteractionMode()
            processControllerUIInput(
                using: controllerResolvedControlState(from: controllerSnapshot),
                deltaTime: 0.0
            )
            processInputActions(
                using: resolvedInput.applyingInteractionMode(
                    controllerInteractionMode,
                    controllerSnapshot: controllerSnapshot
                )
            )
            syncMissionDeliveryState(triggerAutoRelease: false)
            refreshFlightControlDiagnostics()
            refreshCompassOverlay()
            refreshPayloadCameraStatus(deltaTime: 0.0)
            return
        }

        // While fast-forwarding, every step of the frame advances the same simulated delta:
        // the wall clock is read once per frame, not once per step.
        let dt = forcedDeltaTime
            ?? Float(max(1.0 / 240.0, min(now - lastTimestamp, 1.0 / 20.0)))
        self.lastTimestamp = now
        simulationTickCounter &+= 1
        state.armState = isArmed ? .armed : .disarmed
        invalidateFixedWingRouteTrackingContextCache()
        impactSeverityAccumulator = max(0.0, impactSeverityAccumulator - dt * 3.6)
        if physicalState == .crashed {
            collisionAftermathState = .crashed
        } else if impactSeverityAccumulator < 0.18, signalLossCause == nil {
            collisionAftermathState = .nominal
        } else if collisionAftermathState == .impactRecovery, impactSeverityAccumulator > 2.4 {
            collisionAftermathState = .damaged
        }

        let resolvedInput = updateInputPipeline(deltaTime: TimeInterval(dt))
        let controllerSnapshot = inputManager.snapshot(for: .gameController)
        // Keep interacting (60 FPS) whenever the UAV is armed, regardless of velocity.
        if currentVisibilityState == .activeVisible, isArmed {
            noteUserInteraction()
        }
        cleanupOnlineRemoteSnapshotsIfNeeded(now: now)
        refreshDiagnosticHz(now: now)
        updateOnlineInterpolatedRemoteStates(now: now)
        if isSpectatorMode {
            if shouldPresentThisStep {
                updateSpectatorRuntime(deltaTime: dt)
            }
            return
        }
        syncControllerInteractionMode()
        processControllerUIInput(
            using: controllerResolvedControlState(from: controllerSnapshot),
            deltaTime: TimeInterval(dt)
        )
        let interactionAwareInput = resolvedInput.applyingInteractionMode(
            controllerInteractionMode,
            controllerSnapshot: controllerSnapshot
        )
        processInputActions(using: interactionAwareInput)
        applyContinuousCameraLook(deltaTime: dt, controlState: interactionAwareInput)
        applyContinuousCameraZoom(deltaTime: dt)
        #if DEBUG
        phaseClock = frameStart
        markTickPhase(.input)
        #endif

        // Physics must not run before the ground exists.
        //
        // An imported world takes tens of seconds to prepare, and the session is live throughout.
        // Measured at startup: eight ticks of free fall before `[MeshWorld] collision installed`,
        // velocity already −0.57 m/s and accelerating, because with no collision surface the support
        // query returns nothing and the safety floor sits a metre under a ground height that is
        // still zero. The aircraft was therefore *below the terrain* by the time the terrain
        // arrived — seen as being carried off the pad and left under the textures.
        // ⚠️ Simulated time advances *below* the running guard, not above it.
        //
        // It used to be stamped as soon as the frame delta was known, which meant a stopped
        // simulation still accumulated simulated seconds: the aircraft stood frozen while the
        // world clock kept running, and the day went past it. Anything keyed on `simulationTime`
        // — the world clock, the capture-hold timers — was measuring wall time wearing a
        // simulated name whenever the operator paused.
        guard !isAwaitingImportedWorld, isSimulationRunning else {
            syncMissionDeliveryState(triggerAutoRelease: false)
            refreshFlightControlDiagnostics()
            if shouldPresentThisStep {
                sceneController.update(
                    with: state,
                    camera: cameraConfiguration,
                    damage: damageState,
                    thermal: thermalState,
                    diagnosticMode: diagnosticMode,
                    deltaTime: 0.0
                )
            }
            refreshCompassOverlay()
            refreshPayloadCameraStatus(deltaTime: 0.0)
            syncPayloadLifecycleEvents()
            return
        }

        simulationTime += dt
        advanceWorldClock(bySimulatedSeconds: Double(dt))

        let blocksSimulationForSignalLoss = signalState.isInteractionBlocking &&
            signalLossCause != .impactDamage
        if blocksSimulationForSignalLoss {
            syncMissionDeliveryState(triggerAutoRelease: false)
            refreshFlightControlDiagnostics()
            renderSignalLossFrame()
            refreshCompassOverlay()
            refreshPayloadCameraStatus(deltaTime: TimeInterval(dt))
            syncPayloadLifecycleEvents()
            return
        }

        collisionCooldown = max(0.0, collisionCooldown - dt)
        groundImpactCooldown = max(0.0, groundImpactCooldown - dt)
        supportReacquireBlockTimer = max(0.0, supportReacquireBlockTimer - dt)
        decayFixedWingAssistOverrideTimers(deltaTime: dt)
        componentFailureRuntime.tick(deltaTime: dt)
        if !componentFailureRuntime.isEmpty {
            // Intermittent failures toggle over time — re-bake their factors.
            refreshDamagePhysicsModels()
        }

        applyResolvedFlightControls(deltaTime: dt, controlState: interactionAwareInput)
        updateHandLaunchPOVWalk(deltaTime: dt)
        updateMissionReplayLifecycle()
        activeFixedWingLaunchDynamics = nil
        updateAutopilotTargets(deltaTime: dt)
        #if DEBUG
        markTickPhase(.guidance)
        #endif
        let pathfindingMs = autoPathPlanner.lastPlanDurationMs

        _ = updateFleetStatus(deltaTime: dt)

        let prePhysicsCollisionObstacles = collisionCandidateObstacles(
            at: state.position,
            velocity: state.velocity
        )
        let prePhysicsCollisionAnalysis = collisionService.analyze(
            input: CollisionAnalysisInput(
                dronePosition: state.position,
                droneVelocity: state.velocity,
                droneRadius: activeAirframeUsesWingNavigation
                    ? fixedWingNavigationEnvelopeRadius
                    : selectedDroneProfile.collisionRadius,
                // Fleet spacing is handled separately; feeding wingmen back into leader
                // collision avoidance makes formation flight self-block on map guidance.
                obstacles: prePhysicsCollisionObstacles,
                weather: weather
            )
        )
        collisionAnalysis = prePhysicsCollisionAnalysis
        #if DEBUG
        markTickPhase(.collisionPre)
        #endif

        handleAutoCollisionInterventions(deltaTime: dt)

        // Evaluate avoidance every tick for a fixed wing, not only when the assist happens to be
        // steering.
        //
        // Hooked inside the assist branch it never ran during `mode == .takeoff` — the whole
        // departure, which on an open-data city is exactly when it matters. The log shows the cost:
        // `avoid=clear turnR=-1` (never evaluated) for the entire launch, then `avoid=blocked` on
        // the first tick of manual flight, and a building at 200 J immediately after. Evaluating
        // here keeps the reading honest and lets the result be acted on the moment steering is
        // available. The call caches per tick, so the assist path below reuses this result.
        fixedWingPhysicsThrottleCeiling = (
            launchState == .aborted || launchCradleHoldActive
        ) ? 0.0 : nil
        refreshVTOLWingborneAvoidanceLatch()
        if forwardAvoidanceCoversActiveAirframe,
           let wing = selectedDroneProfile.fixedWingParameters {
            // Hold the escape course briefly after it clears.
            //
            // Avoidance and guidance were writing the same axis on alternating ticks: whichever
            // had an opinion that tick won, and the flight log shows the result as `rollCmd`
            // changing sign almost every second — −2, +12, −10, +2, −28, +24, +28, −24, +40 — with
            // the bank reaching ±44° until the airspeed bled from 20 to 10.6 m/s and the aircraft
            // fell out of the sky. `avoid=clear` on many of those very ticks: the aircraft was not
            // dodging anything, it was being fought over. One controller has to own the axis for
            // longer than a single tick, so the escape course persists for a second after the
            // threat reads clear, and guidance resumes only once that has expired.
            #if DEBUG
            markTickPhase(.fixedWing)
            #endif
            let avoidanceTarget = fixedWingForwardAvoidanceTarget(wing: wing)
            #if DEBUG
            markTickPhase(.avoidanceProbe)
            #endif
            if fixedWingAvoidanceNoSafeTrajectory {
                // A stale one-second hold must never outrank a newly blocked trajectory. The crash
                // log ended in exactly `avoid=blocked hold=fresh`: the old course was applied for
                // another 21 metres and the blocked escape below was never reached.
                fixedWingAvoidanceHoldCourse = nil
                fixedWingAvoidanceHoldRemaining = 0.0
                fixedWingAvoidanceHoldSign = 0
                fixedWingAvoidanceHoldWasFresh = false
            } else if let avoidanceTarget, fixedWingAvoidanceHeadingOffset != nil {
                // Re-arm only while the avoidance layer is actually asking for a course change.
                //
                // The `avoidanceTarget != nil` test alone was not that question. A target survives
                // in `fixedWingAvoidanceCachedTarget` and keeps being handed back while the layer's
                // own verdict — the offset printed as `avoid=` — reads clear, so the hold was
                // refreshed to a full second on every tick and never lapsed. Because the hold owns
                // the lateral axis (`applyFixedWingCollisionAvoidance` writes roll absolutely), the
                // assist's guidance could not reach the aircraft no matter what it was pointed at.
                //
                // The flight log is unambiguous: `hold=held heldCrs=-164` unchanged for forty
                // seconds with `avoid=clear risk=0.00 obstacle=none`, `rollCmd` flat at 0.0,
                // `activeWaypointIndex` stuck at 0 and the aircraft leaving the map on that
                // committed course. Nothing was being avoided; the axis was simply never returned.
                //
                // Commit to a side; do not re-pick it every tick.
                //
                // With the hold in place the two controllers stopped fighting, and the log then
                // showed the remaining half of the problem: the escape *offset itself* alternated
                // sign every single sample — −30, +20, −31, +28, −31, +27, −27, +18, −20 — because
                // a fresh solution is computed each tick and the two sides of an obstacle score
                // almost identically. Refreshing the held target on every solution dutifully
                // adopted each flip. A detour side, once chosen, is kept until the hold lapses:
                // an aeroplane that changes its mind about which way to pass a building flies into
                // it, which is the documented failure mode this commitment exists to prevent.
                // Hold the escape *course*, not a point in the world.
                //
                // Holding a fixed point is self-defeating: the aircraft turns toward it, overshoots
                // it, and the bearing to that same point reverses — so the bank command flips sign
                // by construction, which is what the log kept showing (rollCmd −25, +21, −2, −30,
                // +30, −18 …) even with the side committed. A course does not reverse when the
                // aircraft reaches it; it simply stops asking for bank.
                let newCourse = fixedWingCourseRadians(from: avoidanceTarget - currentPlanarPosition())
                // Sign taken from the returned course, not from `fixedWingAvoidanceHeadingOffset`.
                // That variable is the probe's own diagnostic reading, not necessarily the side of
                // the target actually handed back, so committing on it compared the wrong two
                // things and let the opposite side through.
                let newSign = shortestAngleRadians(newCourse - state.orientation.z) < 0.0 ? -1 : 1
                // The predictor already owns side commitment and permits one opposite-side switch
                // only after that complete rollout proves clear. A second sign veto here used to
                // discard the new safe course while endlessly extending the old unsafe hold.
                fixedWingAvoidanceHoldWasFresh = fixedWingAvoidanceHoldCourse == nil ||
                    abs(shortestAngleRadians(newCourse - (fixedWingAvoidanceHoldCourse ?? newCourse))) > 0.01
                fixedWingAvoidanceHoldCourse = newCourse
                fixedWingAvoidanceHoldSign = newSign
                fixedWingAvoidanceHoldRemaining = 1.0
                fixedWingAvoidanceReleaseRemaining = 0.0
                fixedWingAvoidanceReleaseCourseRadians = nil
            } else {
                fixedWingAvoidanceHoldRemaining = max(0.0, fixedWingAvoidanceHoldRemaining - dt)
            }
            if fixedWingLaunchClimbProtectionActive {
                // The launch controller owns the departure — see
                // `fixedWingLaunchClimbProtectionActive`. A *proven clear* escape below may still
                // steer, because that is a real solution rather than a least-bad prefix; the
                // blocked branches are skipped entirely so they cannot cut launch power, cap
                // launch pitch, or take both lateral axes away from an aircraft that has no
                // energy to spend on either.
                if fixedWingAvoidanceHoldRemaining > 0.0,
                   !fixedWingAvoidanceNoSafeTrajectory,
                   let heldCourse = fixedWingAvoidanceHoldCourse {
                    let heading = SIMD2<Float>(-sin(heldCourse), -cos(heldCourse))
                    applyFixedWingCollisionAvoidance(
                        target: currentPlanarPosition() + heading * 200.0,
                        wing: wing,
                        deltaTime: dt
                    )
                }
            } else if fixedWingAvoidanceNoSafeTrajectory,
               let avoidanceTarget {
                // `blocked` means that no single constant-course rollout stays clear for the full
                // horizon. It must never mean wings-level flight into the obstruction already
                // detected. Fly the committed candidate with the longest collision-free prefix,
                // keep roll/yaw under one owner, and climb while the route planner finds a new
                // piecewise path.
                applyFixedWingCollisionAvoidance(
                    target: avoidanceTarget,
                    wing: wing,
                    deltaTime: dt
                )
                let climbFloor = fixedWingAvoidanceClimbFloorDegrees(
                    wing: wing,
                    requireLowAltitude: false
                )
                if climbFloor > 0.0, !operatorHasFullManualAuthority {
                    updateControlValues({ values in
                        values.pitch = max(values.pitch, Double(climbFloor))
                    }, markManual: false)
                }
            } else if fixedWingAvoidanceNoSafeTrajectory {
                // If even the short local proof is unavailable, preserve the actual momentum
                // course while climbing and slowing. A blind 80° bank command is not avoidance.
                let groundTrack = SIMD2<Float>(state.velocity.x, state.velocity.z)
                let emergencyCourse = simd_length(groundTrack) > 0.5
                    ? fixedWingCourseRadians(from: groundTrack / simd_length(groundTrack))
                    : state.orientation.z
                let direction = SIMD2<Float>(-sin(emergencyCourse), -cos(emergencyCourse))
                applyFixedWingCollisionAvoidance(
                    target: currentPlanarPosition() + direction * 200.0,
                    wing: wing,
                    deltaTime: dt
                )
            } else if fixedWingAvoidanceHoldRemaining > 0.0,
                      let heldCourse = fixedWingAvoidanceHoldCourse {
                // Rebuilt from the current position every tick, so the aircraft flies *along* the
                // committed course instead of chasing a receding point.
                let heading = SIMD2<Float>(-sin(heldCourse), -cos(heldCourse))
                applyFixedWingCollisionAvoidance(
                    target: currentPlanarPosition() + heading * 200.0,
                    wing: wing,
                    deltaTime: dt
                )
            } else {
                // Retain ownership while blending both roll and yaw to the hidden assist output.
                // A roll-only additive fade was overwritten later in this same tick by the assist,
                // so it never reached physics; yaw switched owners with no fade at all.
                fixedWingAvoidanceHoldCourse = nil
                let hasAvoidanceCommand = fixedWingAvoidanceLateralCommandWasActive
                    || fixedWingAvoidanceReleaseCourseRadians != nil
                if fixedWingAvoidanceReleaseCourseRadians == nil, hasAvoidanceCommand {
                    fixedWingAvoidanceReleaseRemaining = Self.fixedWingAvoidanceReleaseDuration
                    fixedWingAvoidanceReleaseCourseRadians = Float(controlValues.yaw)
                        .degreesToRadians
                }
                if hasAvoidanceCommand {
                    var releaseCourse = fixedWingAvoidanceReleaseCourseRadians
                        ?? state.orientation.z
                    let nominalRoll = fixedWingLatestAssistRollCommandDegrees
                        ?? fixedWingLatestAutopilotRollCommandDegrees
                    let nominalCourse = fixedWingLatestAssistCourseCommandRadians
                        ?? fixedWingLatestAutopilotCourseCommandRadians
                    if let targetRoll = nominalRoll,
                       let targetCourse = nominalCourse {
                        let alpha = 1.0 - exp(-max(0.0001, dt) / 0.22)
                        fixedWingAvoidanceBiasDegrees += (
                            targetRoll - fixedWingAvoidanceBiasDegrees
                        ) * alpha
                        releaseCourse = shortestAngleRadians(
                            releaseCourse + shortestAngleRadians(
                                targetCourse - releaseCourse
                            ) * alpha
                        )
                        fixedWingAvoidanceReleaseRemaining = max(
                            0.0,
                            fixedWingAvoidanceReleaseRemaining - dt
                        )
                        let rollConverged = abs(
                            targetRoll - fixedWingAvoidanceBiasDegrees
                        ) <= 0.15
                        let courseConverged = abs(shortestAngleRadians(
                            targetCourse - releaseCourse
                        )) <= Float(0.25).degreesToRadians
                        if fixedWingAvoidanceReleaseRemaining <= 0.0,
                           rollConverged,
                           courseConverged {
                            // The final avoidance-owned write exactly equals the nominal owner;
                            // the later merge can take over without a residual discontinuity.
                            fixedWingAvoidanceBiasDegrees = targetRoll
                            releaseCourse = targetCourse
                            fixedWingAvoidanceReleaseRemaining = 0.0
                            fixedWingAvoidanceLateralCommandWasActive = false
                        }
                    }
                    fixedWingAvoidanceReleaseCourseRadians = releaseCourse
                    fixedWingAvoidanceAppliedBiasDegrees = Double(fixedWingAvoidanceBiasDegrees)
                    updateControlValues({ values in
                        values.roll = Double(fixedWingAvoidanceBiasDegrees)
                        values.yaw = Double(releaseCourse.radiansToDegrees)
                    }, markManual: false)
                    if !fixedWingAvoidanceLateralCommandWasActive,
                       fixedWingAvoidanceReleaseRemaining <= 0.0 {
                        fixedWingAvoidanceAppliedBiasDegrees = 0.0
                        fixedWingAvoidanceReleaseCourseRadians = nil
                    }
                } else {
                    fixedWingAvoidanceAppliedBiasDegrees = 0.0
                    fixedWingAvoidanceBiasDegrees = 0.0
                    fixedWingAvoidanceReleaseCourseRadians = nil
                    fixedWingAvoidanceLateralCommandWasActive = false
                }

            }
            // The mesh-horizon governor trades speed for manoeuvre room. That trade is wrong during
            // the launch climb-out, where the aircraft has no speed to give and the corridor is
            // already committed.
            if let governedSpeed = fixedWingMeshSpeedGovernorTargetMps,
               !fixedWingLaunchClimbProtectionActive,
               !operatorHasFullManualAuthority {
                let trueAirspeed = max(0.0, state.forwardAirspeed)
                if trueAirspeed > governedSpeed + 0.25 {
                    let overspeedFraction = (
                        (trueAirspeed - governedSpeed) / max(1.0, governedSpeed)
                    ).clamped(to: 0.0...1.0)
                    let governorBaseline = resolvedFlightBaseline(for: .autoPath)
                    let cruiseReference = governorBaseline.cruiseReferenceThrottle
                    let throttleCap = max(
                        max(
                            wing.minThrottle,
                            governorBaseline.effectiveMinimumSafeFlightThrottle
                        ),
                        cruiseReference * (0.58 - overspeedFraction * 0.20)
                    )
                    fixedWingPhysicsThrottleCeiling = min(
                        fixedWingPhysicsThrottleCeiling ?? throttleCap,
                        throttleCap
                    )
                    updateControlValues({ values in
                        // This runs after both guidance and blocked/climb handling, so a 92% power
                        // fallback cannot defeat the mesh-horizon governor on the same tick.
                        values.throttle = min(values.throttle, Double(throttleCap))
                    }, markManual: false)
                }
            }
            #if DEBUG
            markTickPhase(.avoidanceApply)
            #endif
        }

        #if DEBUG
        // Fixed-wing pitch telemetry, once a second.
        //
        // Rebuilt rather than restored: the stashed version reads state that no longer exists in
        // this tree (climb-out latch, forward-avoidance offset, guidance counters), so it cannot
        // compile here. These are the fields that actually settle the open question — whether the
        // autopilot is *commanding* descent or the aircraft is failing to hold the angle it was
        // given. `pitchCmd` is the command, `pitchActual` the attitude; the same pair for roll.
        if selectedDroneProfile.airframeClass == .fixedWing {
            wingTelemetryAccumulator += dt
            if wingTelemetryAccumulator >= 1.0 {
                wingTelemetryAccumulator = 0.0
                print(String(
                    format: "[WingTick] mode=%@ y=%.1f speed=%.1f pitchCmd=%.1f pitchActual=%.1f "
                        + "vy=%.2f rollCmd=%.1f roll=%.1f p=%.0f q=%.0f Ixx=%.0f "
                        + "throttle=%.2f risk=%.2f obstacle=%@ "
                        + "why=%@ pending=%@ avoid=%@ turnR=%.0f hold=%@ heldCrs=%.0f "
                        + "band=%.0f-%.0f nav=%d state=%@ sup=%@ "
                        + "asstRoll=%@ avOwns=%@ holdRem=%.2f avCrsErr=%@ avRawBank=%@ "
                        // How far round the active waypoint the aircraft has already turned. 360
                        // is the orbit-trap threshold that arms the emergency abeam pass.
                        + "swept=%.0f",
                    mode.rawValue,
                    Double(state.position.y),
                    Double(simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))),
                    controlValues.pitch,
                    Double(state.orientation.y.radiansToDegrees),
                    Double(state.velocity.y),
                    controlValues.roll,
                    Double(state.orientation.x.radiansToDegrees),
                    // Roll and pitch RATE, and the roll inertia the solver is using.
                    //
                    // Without the rates an attitude that jumps between samples is
                    // ambiguous — a genuine departure and a mis-extracted angle look
                    // identical once a second — and that ambiguity cost a whole
                    // round of flight testing. Without the inertia there is no way
                    // to see from a log that the solver is flying a different
                    // aeroplane from the one the aerodynamics describe, which is
                    // exactly what a scene-scale mass graph makes it do.
                    Double(state.bodyAngularVelocity.x.radiansToDegrees),
                    Double(state.bodyAngularVelocity.y.radiansToDegrees),
                    Double(vehicleMassProperties.inertiaDiagonal.x),
                    controlValues.throttle,
                    Double(collisionAnalysis.riskScore),
                    (collisionAnalysis.nearestObstacleID.flatMap {
                        sceneController.obstacleSourceLabel(for: $0)
                    } ?? collisionAnalysis.nearestObstacleSource ?? "none") as NSString,
                    lastFlightModeReason as NSString,
                    (pendingFixedWingAssistMode.map { "\($0)" } ?? "none") as NSString,
                    (fixedWingAvoidanceNoSafeTrajectory
                        ? fixedWingAvoidanceHeadingOffset.map {
                            String(format: "blocked(%+.0f)", $0.radiansToDegrees)
                        } ?? "blocked"
                        : fixedWingAvoidanceHeadingOffset.map {
                            String(format: "%+.0f", $0.radiansToDegrees)
                        } ?? "clear") as NSString,
                    Double(fixedWingAvoidancePredictedTurnRadiusMeters ?? -1.0),
                    (fixedWingAvoidanceHoldCourse == nil
                        ? "off"
                        : (fixedWingAvoidanceHoldWasFresh ? "fresh" : "held")) as NSString,
                    Double((fixedWingAvoidanceHoldCourse ?? 0.0).radiansToDegrees),
                    // The band the planner filters obstacles by, how many survived, and why
                    // auto-advance is parked. Between them these say whether a "препятствие"
                    // hold is a real obstruction or a planner looking at the wrong altitude.
                    Double(fixedWingProtectedAltitudeRange().lowerBound),
                    Double(fixedWingProtectedAltitudeRange().upperBound),
                    navigationBaseObstacles().count,
                    "\(fixedWingAssistState.interceptState)" as NSString,
                    (fixedWingAssistState.autoAdvanceSuppressedReason ?? "-") as NSString,
                    // Who actually wrote the roll axis this tick. `hold=` above answers only
                    // whether a held *course value* exists, not whether the hold is live or who
                    // owns the stick — reading it as ownership cost a wrong diagnosis. `asstRoll`
                    // is what the assist asked for, `avOwns` whether avoidance took the axis,
                    // `holdRem` the hold's remaining seconds.
                    (fixedWingLatestAssistRollCommandDegrees.map {
                        String(format: "%.1f", $0)
                    } ?? "nil") as NSString,
                    (fixedWingAvoidanceLastCommandTick == simulationTickCounter
                        ? "yes"
                        : "no") as NSString,
                    Double(fixedWingAvoidanceHoldRemaining),
                    (fixedWingAvoidanceDiagCourseErrorDegrees.map {
                        String(format: "%+.1f", $0)
                    } ?? "-") as NSString,
                    (fixedWingAvoidanceDiagRawBankDegrees.map {
                        String(format: "%+.1f", $0)
                    } ?? "-") as NSString,
                    Double(fixedWingAssistState.activeWaypointSweptHeadingDegrees ?? -1.0)
                ))
            }
        }

        // Tailsitter ground geometry, once a second.
        //
        // A tailsitter is the one airframe whose contact geometry at rest is nowhere near its
        // origin: it stands on its tail, ~0.4 m below the point physics measures from, and three
        // separate layers each carry their own idea of where "the ground" is — the physics clamp
        // (rest-normalized), the impact detector (raw lowest sphere) and the renderer (a hand-typed
        // lift constant). `raw` vs `clr` below is exactly that disagreement in metres; `lift` is
        // what the renderer is adding. If the model sits in the terrain, one of these three
        // disagrees with the other two, and this line says which.
        // Widened from tailsitters to every hybrid VTOL.
        //
        // The ground-geometry fields below are only interesting on a tailsitter, but everything
        // after them — the navigation band, which guidance branch ran, the route's own altitude
        // against the commanded one, whether the avoidance layer was even covering the airframe —
        // is what any VTOL flight has to be read from. Gating the whole line on the tailsitter
        // left the tilt-rotors with no per-tick record at all: two recorded flights flew into the
        // same building and the log could not say what altitude their route was validated at, nor
        // whether avoidance was running when they did it.
        if selectedDroneProfile.airframeClass == .hybridVTOL {
            tailsitterTelemetryAccumulator += dt
            if tailsitterTelemetryAccumulator >= 1.0 {
                tailsitterTelemetryAccumulator = 0.0
                let attitude = attitudeQuaternion(of: state)
                let restAttitude = VehicleContactProfile.restOrientation(
                    for: selectedDroneProfile.airframeStyle
                )
                let supportY = supportSurfaceY(for: state.position)
                let lowest = vehicleContactProfile.lowestContact(
                    position: state.position,
                    orientation: attitude
                )
                let restOffset = vehicleContactProfile.lowestPointOffset(orientation: restAttitude)
                let liveOffset = vehicleContactProfile.lowestPointOffset(orientation: attitude)
                let rawHeight = (lowest?.point.y ?? state.position.y) - supportY
                print(String(
                    format: "[VtolTick] mode=%@ phys=%@ vtol=%@ prog=%.2f y=%.2f supY=%.2f "
                        + "agl=%.2f raw=%.2f clr=%.2f L=%.2f Lrest=%.2f lift=%.2f "
                        + "pitch=%.1f roll=%.1f vy=%.2f thr=%.2f armed=%@ "
                        // Measurement 1 — what the planner was looking at on this leg: the
                        // altitude band it filters obstacles by, and how many survived. A leg
                        // planned through a 60 m building shows up here as a band that excludes it.
                        // Measurement 2 — which layer owned the leg. `fwdCov` is
                        // `forwardAvoidanceCoversActiveAirframe`, which for a hybridVTOL requires
                        // BOTH an auto-controlled mode AND `vtolWingborneAvoidanceLatched` (set at
                        // wingborne >= 0.65, cleared below 0.45). `avCmd` is per-tick, not a latch.
                        + "band=%.0f-%.0f nav=%d fwdCov=%@ auto=%@ vtolWhy=%@ wbLatch=%@ wb=%.2f avCmd=%@ "
                        // What the avoidance layer actually asked for, so a bank held toward a
                        // building can be attributed instead of guessed. `avOff` is its own verdict
                        // (the `avoid=` field of `[WingTick]`), `avCrsErr` the course error it is
                        // steering out and `avRawBank` the bank it demanded before filtering;
                        // `rollCmd` is what reached the aircraft. Frozen `avCrsErr`/`avRawBank`
                        // mean the layer did not run this tick, whatever `avCmd` says.
                        + "avOff=%@ avCrsErr=%@ avRawBank=%@ rollCmd=%.1f "
                        // Which guidance branch actually ran, and the altitude it asked for against
                        // the leg's own route altitude. `vtolWhy` says whether a route exists;
                        // these say what was done about it. A `why`/`dAlt` pair that alternates
                        // between the route altitude and the aircraft's own height is the blocked
                        // hold fighting the leg — the porpoise, not a climb command.
                        + "why=%@ rAlt=%.1f dAlt=%.1f lift=%.0f node=%@ mReason=%@",
                    mode.rawValue as NSString,
                    "\(physicalState)" as NSString,
                    "\(state.vtolPhase)" as NSString,
                    Double(state.vtolTransitionProgress),
                    Double(state.position.y),
                    Double(supportY),
                    Double(state.position.y - supportY),
                    Double(rawHeight),
                    Double(rawHeight + restOffset),
                    Double(liveOffset),
                    Double(restOffset),
                    Double(vehicleGroundRestOffset),
                    Double(state.orientation.y.radiansToDegrees),
                    Double(state.orientation.x.radiansToDegrees),
                    Double(state.velocity.y),
                    controlValues.throttle,
                    (isArmed ? "yes" : "no") as NSString,
                    Double(fixedWingProtectedAltitudeRange().lowerBound),
                    Double(fixedWingProtectedAltitudeRange().upperBound),
                    navigationBaseObstacles().count,
                    (forwardAvoidanceCoversActiveAirframe ? "yes" : "no") as NSString,
                    (mode.isAutoControlled ? "yes" : "no") as NSString,
                    (mode.isAutoControlled
                        ? hybridVTOLRouteGuidanceDiagnostic ?? "-"
                        : "-") as NSString,
                    (vtolWingborneAvoidanceLatched ? "yes" : "no") as NSString,
                    Double(state.vtolWingborneBlend),
                    (fixedWingAvoidanceLastCommandTick == simulationTickCounter
                        ? "yes"
                        : "no") as NSString,
                    (fixedWingAvoidanceNoSafeTrajectory
                        ? fixedWingAvoidanceHeadingOffset.map {
                            String(format: "blocked(%+.0f)", $0.radiansToDegrees)
                        } ?? "blocked"
                        : fixedWingAvoidanceHeadingOffset.map {
                            String(format: "%+.0f", $0.radiansToDegrees)
                        } ?? "clear") as NSString,
                    (fixedWingAvoidanceDiagCourseErrorDegrees.map {
                        String(format: "%+.1f", $0)
                    } ?? "-") as NSString,
                    (fixedWingAvoidanceDiagRawBankDegrees.map {
                        String(format: "%+.1f", $0)
                    } ?? "-") as NSString,
                    controlValues.roll,
                    (fixedWingLastTransitionReason ?? "-") as NSString,
                    Double(hybridVTOLNavigationBandAltitude ?? -1.0),
                    Double(fixedWingAutopilotAltitudeCommand ?? -1.0),
                    Double(hybridVTOLRouteAltitudeLift),
                    (hybridVTOLRouteNodeDiagnostic ?? "-") as NSString,
                    (lastFlightModeReason ?? "-") as NSString
                ))
            }
        }
        #endif

        let control = buildControlInput(from: controlValues)
        let context = DroneSimulationContext(
            profile: selectedDroneProfile,
            activeUAVProfile: activeUAVProfile,
            weather: weather,
            damageState: damageState,
            batteryState: batteryState,
            collisionRisk: collisionAnalysis.riskScore,
            windVector: weather.windVector,
            vehicleMassModel: vehicleMassModel,
            fixedWingLaunchDynamics: activeFixedWingLaunchDynamics,
            fixedWingThrottleCeiling: selectedDroneProfile.airframeClass == .fixedWing
                ? fixedWingAirspeedLimitedThrottleCeiling()
                : nil,
            vehicleMassProperties: vehicleMassProperties,
            contactProfile: vehicleContactProfile,
            rotorModel: vehicleRotorModel,
            aeroDamage: vehicleAeroDamage,
            jammedSurfaces: componentFailureRuntime.jammedSurfaces(),
            powerSystemFactor: componentFailureRuntime.functionalFactor(componentID: "battery"),
            controlSystemFactor: componentFailureRuntime.functionalFactor(componentID: "flightController"),
            groundHeight: currentGroundHeight(),
            atmosphere: currentAtmosphere(),
            fuelState: fuelState,
            engineState: state.engineRuntime,
            fuelPropulsion: fuelPropulsionBackend
        )

        let previousState = state
        let physicsStart = CACurrentMediaTime()
        #if DEBUG
        markTickPhase(.wingLog)
        #endif
        state = physicsEngine.step(
            state: state,
            control: control,
            context: context,
            deltaTime: dt
        )
        enforceRuntimeSafetyAndBounds(context: "tick.physics")
        applySupportSurfaceConstraint(previousState: previousState)
        applyWaterImmersionIfNeeded(deltaTime: dt)
        applyPayloadSelfInteractionIfNeeded(deltaTime: dt)
        #if DEBUG
        markTickPhase(.physics)
        #endif
        let structuralLoadState = state
        let physicsTimeMs = (CACurrentMediaTime() - physicsStart) * 1000.0

        var postPhysicsCollisionAnalysis: CollisionAnalysisSnapshot
        let sweptCollisionObstacles = sceneController.nearbyEnvironmentObstacles(
            from: previousState.position,
            to: state.position,
            margin: max(selectedDroneProfile.collisionRadius, vehicleContactProfile.boundingRadius) + 1.0
        )
        var impactReport: ImpactReport?
        // Lifted by `vehicleGroundRestOffset` — see that property. Zero for every airframe that
        // rests on its belly or gear, so this changes nothing for them.
        let contactLift = vehicleBodyOriginWorldOffset
        if let vehicleContact = collisionService.firstSweptVehicleCollision(
            contactSpheres: vehicleContactProfile.spheres,
            fromPosition: previousState.position + contactLift,
            toPosition: state.position + contactLift,
            fromOrientation: attitudeQuaternion(of: previousState),
            toOrientation: attitudeQuaternion(of: state),
            obstacles: sweptCollisionObstacles
        ) {
            if vehicleContact.isSupportSurfaceContact {
                // A slow roof landing remains a light touch. A hard gear,
                // wingtip or prop contact uses the real swept contact even
                // when the vehicle CG is already outside the roof footprint.
                if let report = resolveSupportSurfaceImpactIfNeeded(
                    contact: vehicleContact,
                    previousState: previousState,
                    deltaTime: dt
                ) {
                    impactReport = report
                    postPhysicsCollisionAnalysis = CollisionAnalysisSnapshot(
                        riskScore: 1.0,
                        nearestObstacleDistance: 0.0,
                        nearestObstacleID: vehicleContact.obstacle.id,
                        nearestObstacleSource: vehicleContact.obstacle.source,
                        timeToCollision: 0.0,
                        emergencyAction: collisionEmergencyAction(for: report.tier),
                        contactNormal: vehicleContact.contactNormal
                    )
                } else {
                    postPhysicsCollisionAnalysis = .safe
                }
            } else {
                // Impulse-based contact: the vehicle stops at its own pose along
                // the step, receives a proper linear+angular impulse with lever
                // arm and material restitution/friction, and takes damage
                // localized to the struck component. No teleport, no velocity
                // zeroing, no forced disarm here.
                let report = impactResolutionService.resolve(
                    contact: vehicleContact,
                    previousPosition: previousState.position,
                    state: &state,
                    graph: &componentGraph,
                    massProperties: vehicleMassProperties,
                    airframeClass: selectedDroneProfile.airframeClass,
                    bodyOriginWorldOffset: contactLift,
                    rotorsSpinning: state.throttle > 0.05 && isArmed,
                    deltaTime: dt,
                    applyDamage: collisionCooldown <= 0.0,
                    restingSpeedThreshold: crashResolutionRestingSpeedThreshold
                )
                impactReport = report
                postPhysicsCollisionAnalysis = CollisionAnalysisSnapshot(
                    riskScore: 1.0,
                    nearestObstacleDistance: -0.02,
                    nearestObstacleID: vehicleContact.obstacle.id,
                    nearestObstacleSource: vehicleContact.obstacle.source,
                    timeToCollision: 0.0,
                    emergencyAction: collisionEmergencyAction(for: report.tier),
                    contactNormal: vehicleContact.contactNormal
                )
            }
        } else {
            let postPhysicsCollisionObstacles = collisionCandidateObstacles(
                at: state.position,
                velocity: state.velocity
            )
            postPhysicsCollisionAnalysis = collisionService.analyze(
                input: CollisionAnalysisInput(
                    dronePosition: state.position,
                    droneVelocity: state.velocity,
                    droneRadius: activeAirframeUsesWingNavigation
                        ? fixedWingNavigationEnvelopeRadius
                        : selectedDroneProfile.collisionRadius,
                    obstacles: postPhysicsCollisionObstacles,
                    weather: weather
                )
            )
        }

        // Flat terrain is not represented by the obstacle broad phase. Feed
        // touchdown through the same contact/impulse/damage path so a hard
        // landing can bend gear, break propellers and bounce instead of being
        // silently clamped to Y with its velocity erased.
        if impactReport == nil,
           let groundReport = resolveGroundImpactIfNeeded(
               previousState: previousState,
               deltaTime: dt
           ) {
            impactReport = groundReport
            postPhysicsCollisionAnalysis = CollisionAnalysisSnapshot(
                riskScore: 1.0,
                nearestObstacleDistance: 0.0,
                nearestObstacleID: nil,
                nearestObstacleSource: groundReport.obstacleSource,
                timeToCollision: 0.0,
                emergencyAction: collisionEmergencyAction(for: groundReport.tier),
                contactNormal: groundReport.contactNormal
            )
        }

        collisionAnalysis = postPhysicsCollisionAnalysis
        #if DEBUG
        markTickPhase(.collisionPost)
        #endif
        var needsCollisionAnalysisRefresh = false
        if let report = impactReport {
            applyImpactConsequences(report)
            if report.tier != .lightTouch, collisionCooldown <= 0.0 {
                collisionCooldown = collisionCooldownDuration(for: report.obstacleSource, tier: report.tier)
            }
            enforceRuntimeSafetyAndBounds(context: "tick.collision_damage")
            needsCollisionAnalysisRefresh = true
        } else if postPhysicsCollisionAnalysis.nearestObstacleDistance <= -0.02 {
            // Top faces of support surfaces (roofs, container/crate tops) are excluded from the
            // collision analysis (see CollisionAnalysisService.isPassiveTopSupport*), and the
            // support-surface floor clamp has already seated a landed drone, so any penetration
            // reported here is a genuine wall / underside strike the sweep missed (slow push).
            if resolveObstaclePenetration(using: postPhysicsCollisionAnalysis) {
                enforceRuntimeSafetyAndBounds(context: "tick.collision_resolve")
                needsCollisionAnalysisRefresh = true
            }
        }


        if impactReport == nil, !needsCollisionAnalysisRefresh {
            advanceStructuralDamage(
                previousState: previousState,
                loadState: structuralLoadState,
                deltaTime: dt
            )
        }
        enforceComponentFunctionalState()

        if needsCollisionAnalysisRefresh {
            let refreshedCollisionObstacles = collisionCandidateObstacles(
                at: state.position,
                velocity: state.velocity
            )
            collisionAnalysis = collisionService.analyze(
                input: CollisionAnalysisInput(
                    dronePosition: state.position,
                    droneVelocity: state.velocity,
                    droneRadius: activeAirframeUsesWingNavigation
                        ? fixedWingNavigationEnvelopeRadius
                        : selectedDroneProfile.collisionRadius,
                    obstacles: refreshedCollisionObstacles,
                    weather: weather
                )
            )
        }

        advanceSonicBoom(deltaTime: dt)
        updatePhysicalState(previousState: previousState, deltaTime: dt)
        if let launchDynamics = activeFixedWingLaunchDynamics,
           launchDynamics.phase == .held || launchDynamics.phase == .catapultRail {
            transitionPhysicalState(.takeoffTransition)
        }
        applyGroundedSafetyIfNeeded(deltaTime: dt)
        refreshFixedWingLaunchPresentation()

        #if DEBUG
        // Launch detector: a sudden upward position jump with low vertical velocity is a teleport
        // (collision push-out / support snap), not real climb — the "thrown up several meters" bug.
        let verticalJump = state.position.y - previousState.position.y
        if verticalJump > 0.5, state.velocity.y < verticalJump / dt * 0.5 {
            print(
                "[LaunchDetect] up-jump dy=\(verticalJump) prevY=\(previousState.position.y) " +
                "newY=\(state.position.y) velY=\(state.velocity.y) physState=\(physicalState) " +
                "collisionSource=\(collisionAnalysis.nearestObstacleSource ?? "n/a") " +
                "dist=\(collisionAnalysis.nearestObstacleDistance)"
            )
        }
        #endif

        handleModeTransitions()
        enforceRuntimeSafetyAndBounds(context: "tick.post_mode")
        updateSignalLossSequence(deltaTime: dt)
        updateFiberOpticTether(deltaTime: dt)
        updateControlLinkFailsafeSequence(deltaTime: dt)
        updateControlLinkFailsafeLatchRecovery(deltaTime: dt)
        armBlockReason = resolveArmAuthorization().reason
        syncMissionDeliveryState(triggerAutoRelease: false)

        if blocksSimulationForSignalLoss {
            refreshFlightControlDiagnostics()
            renderSignalLossFrame()
            refreshCompassOverlay()
            syncPayloadLifecycleEvents()
            return
        }

        syncMissionDeliveryState(triggerAutoRelease: true)
        updateMissionExecutionRuntime()

        let maneuverAggressiveness = (abs(Float(controlValues.roll)) + abs(Float(controlValues.pitch))) / 120.0
        batteryState = batteryThermalService.updateBattery(
            current: batteryState,
            input: BatteryComputationInput(
                droneProfile: selectedDroneProfile,
                weather: weather,
                damageState: damageState,
                speedMps: simd_length(state.velocity),
                verticalSpeedMps: abs(state.velocity.y),
                throttle: state.throttle,
                maneuverAggressiveness: maneuverAggressiveness,
                propulsionDrawsFromBattery: fuelPropulsionBackend == nil
            ),
            deltaTime: dt
        )

        if let powerplant = activeUAVProfile?.powerplant,
           powerplant.energySource == .fuel,
           let currentFuel = fuelState {
            fuelState = fuelBurnService.update(
                current: currentFuel,
                input: FuelBurnInput(
                    powerplant: powerplant,
                    throttle: state.throttle,
                    // "Running" now means the engine is actually firing, which it is
                    // not while it primes, cranks or after it has been shut down.
                    engineRunning: state.engineRuntime?.runState.isFiring
                        ?? (isArmed && state.physicalState != .crashed),
                    atmosphere: currentAtmosphere().state(worldY: state.position.y),
                    leakKgPerSec: 0.0,
                    shaftPowerKW: state.engineRuntime?.shaftPowerKW,
                    // Only for jets, and only because their thrust stopped being a
                    // function of the throttle lever alone. A propeller aircraft is
                    // still billed on shaft power, which is where its fuel actually goes.
                    thrustNewtons: powerplant.drivesPropeller
                        ? nil
                        : state.propulsionThrustNewtons
                ),
                deltaTime: dt
            )
        }

        thermalState = batteryThermalService.updateThermal(
            current: thermalState,
            throttle: state.throttle,
            weather: weather,
            damageState: damageState,
            collisionRisk: collisionAnalysis.riskScore,
            maneuverAggressiveness: maneuverAggressiveness,
            deltaTime: dt,
            propulsionDrawsFromBattery: fuelPropulsionBackend == nil
        )
        updateBatteryFireState(deltaTime: dt)

        if batteryState.isDepleted {
            disarm(forceEmergency: true)
            updateControlValues({ values in
                values.throttle = 0.0
            }, markManual: false)
            if !showBatteryDepletedDialog {
                showBatteryDepletedDialog = true
            }
        }

        applyMissionSafetyRuntimeIfNeeded()
        sampleMissionObservationIfNeeded()
        updateThunderstormLightning(deltaTime: dt)

        let renderStart = CACurrentMediaTime()
        if shouldPresentThisStep {
            sceneController.setDamageVibrationLevel(
                vehicleRotorModel.vibrationLevel * state.motorThrottle
            )
            sceneController.applyWeatherVisual(weather)
            sceneController.update(
                with: state,
                camera: cameraConfiguration,
                damage: damageState,
                thermal: thermalState,
                diagnosticMode: diagnosticMode,
                deltaTime: dt
            )
            sceneController.updateFleetWingmen(
                wingmen,
                profile: selectedDroneProfile,
                throttle: state.throttle,
                deltaTime: dt
            )
        }
        refreshCompassOverlay()
        refreshPayloadCameraStatus(deltaTime: TimeInterval(dt))
        syncPayloadLifecycleEvents()
        updateMissionScenarioRuntime(deltaTime: TimeInterval(dt))
        updateFireResponseRuntime(deltaTime: TimeInterval(dt))
        recordDetachedVehiclePartImpactEvents()
        // Make secondary debris impacts visible to the outgoing LAN event
        // tail in this publish cycle. The end-of-tick flush remains in place
        // for any events produced later in the frame.
        flushDamageEventAdapters()
        publishOnlineVehicleSnapshotIfNeeded(now: now)
        let renderTimeMs = (CACurrentMediaTime() - renderStart) * 1000.0

        #if DEBUG
        markTickPhase(.systems)
        #endif

        collisionDebugAccumulator += dt
        let collisionDebugStateChanged = (lastCollisionDebugEnabled != collisionDebugEnabled)
        if shouldPresentThisStep,
           (collisionDebugEnabled && collisionDebugAccumulator > 0.12) || collisionDebugStateChanged {
            sceneController.updateCollisionDebug(risk: collisionAnalysis, enabled: collisionDebugEnabled)
            sceneController.updatePathDebug(
                path: navigationSnapshot.waypoints,
                currentWaypointIndex: navigationSnapshot.currentWaypointIndex,
                start: navigationSnapshot.start,
                goal: navigationSnapshot.goal,
                enabled: collisionDebugEnabled && (mode == .autoPath || mode == .returnHome)
            )
            collisionDebugAccumulator = 0.0
            lastCollisionDebugEnabled = collisionDebugEnabled
        }

        diagnosticsSamplingAccumulator += dt
        if shouldPresentThisStep,
           diagnosticsSamplingAccumulator >= 0.45 || cachedDiagnostics.activeObjectCount == 0 {
            let sceneStats = sceneController.sceneDiagnostics()
            let nextDiagnostics = SimulationDiagnostics(
                frameTimeMs: (CACurrentMediaTime() - frameStart) * 1000.0,
                physicsTimeMs: physicsTimeMs,
                renderTimeMs: renderTimeMs,
                pathfindingTimeMs: pathfindingMs,
                activeObjectCount: sceneStats.activeObjectCount,
                activePhysicsBodyCount: sceneStats.activePhysicsBodyCount,
                activeParticleCount: sceneStats.activeParticleCount
            )
            cachedDiagnostics = nextDiagnostics
            if diagnostics != nextDiagnostics {
                diagnostics = nextDiagnostics
            }
            diagnosticsSamplingAccumulator = 0.0
        }

        #if DEBUG
        markTickPhase(.sceneDiagnostics)
        #endif

        hudPublishAccumulator += dt
        let shouldPublishHUD = hudPublishAccumulator >= 0.15 || telemetry.timestampISO8601.isEmpty
        let shouldPersistTelemetry = telemetrySamplingAccumulator + dt >= 0.2
        if shouldPublishHUD || shouldPersistTelemetry {
            refreshFixedWingAssistRuntimeDebugState()
            refreshSceneMissionWaypointCaptureAltitude()
            refreshTerrainMapSnapshotIfVisible(recordTrail: true)
            let latestWarnings = buildWarnings()
            let latestTelemetry = buildTelemetrySnapshot()

            if shouldPublishHUD {
                if warnings != latestWarnings {
                    warnings = latestWarnings
                }
                telemetry = latestTelemetry
                hudPublishAccumulator = 0.0
            }

            if shouldPersistTelemetry {
                telemetryExporter.append(snapshot: latestTelemetry)
                telemetrySamplingAccumulator = 0.0
            }
        }

        telemetrySamplingAccumulator += dt

        #if DEBUG
        markTickPhase(.hudPublish)
        #endif

        if !hasUnsavedChanges,
           simd_length(state.velocity) > 0.03 || abs(state.throttle) > 0.02 || mode != .manual {
            hasUnsavedChanges = true
        }

        refreshMissionStatus()
        flushDamageEventAdapters()
        recordMissionReplayFrameIfNeeded()
        recordMissionReplayWarningsIfNeeded()

        autosaveAccumulator += dt
        if autosaveAccumulator >= 6.0 {
            performAutosaveIfNeeded()
            autosaveAccumulator = 0.0
        }

        #if DEBUG
        markTickPhase(.persistence)
        phaseTickCount += 1
        phaseTelemetryAccumulator += dt
        if phaseTelemetryAccumulator >= 1.0, phaseTickCount > 0 {
            let ticks = Double(phaseTickCount)
            let perTick = phaseTotals.map { $0 * 1000.0 / ticks }
            let total = perTick.reduce(0.0, +)
            let breakdown = TickPhase.allCases
                .map { String(format: "%@=%.2f", $0.label, perTick[$0.rawValue]) }
                .joined(separator: " ")
            print(String(
                format: "[Phase] hz=%.0f tick=%.2fms %@ | objs=%d bodies=%d parts=%d nav=%d env=%d",
                ticks / Double(phaseTelemetryAccumulator),
                total,
                breakdown as NSString,
                cachedDiagnostics.activeObjectCount,
                cachedDiagnostics.activePhysicsBodyCount,
                cachedDiagnostics.activeParticleCount,
                navigationBaseObstacles().count,
                sceneController.environmentObstacles.count
            ))
            phaseTotals = [Double](repeating: 0.0, count: TickPhase.allCases.count)
            phaseTickCount = 0
            phaseTelemetryAccumulator = 0.0
        }
        #endif
    }

    /// HUD/state consequences of an impulse-resolved impact. The physical
    /// response (impulse, positional correction, localized graph damage) has
    /// already been applied by `ImpactResolutionService` — this maps the
    /// report onto aftermath state, severity accumulation, the legacy damage
    /// projection and possible internal failures. Signal/FPV loss is no
    /// longer automatic on a severe hit: it only happens when the hit
    /// actually took out the radio/flight controller
    /// (`evaluateImpactInternalFailures`).
    private func applyImpactConsequences(_ report: ImpactReport) {
        let wasAlreadyDamaged = recordedPhysicalImpactCount > 0
        lastCollisionSource = report.obstacleSource ?? lastCollisionSource
        lastCollisionDetail = String(
            format: "comp=%@ E=%.1fJ vN=%.2f j=%.2f tier=%@",
            report.componentID,
            report.impactEnergyJ,
            report.normalClosingSpeed,
            report.appliedImpulse,
            report.tier.rawValue
        )

        #if DEBUG
        // Light touches used to be invisible, and that is how a ground-contact loop
        // ran twenty times a second for a whole flight without appearing in a log.
        // Counted rather than printed per event, so a landing rollout does not bury
        // everything else.
        if report.tier == .lightTouch {
            lightTouchImpactCount += 1
            lightTouchImpactElapsed += 1.0
            if lightTouchImpactCount % 20 == 0 {
                print("[GroundTouch] \(lightTouchImpactCount) light contacts on "
                      + "\(report.componentID) src=\(report.obstacleSource ?? "?") "
                      + "— a run of these means the contact solver is re-firing on an "
                      + "airframe that is already resting on the ground")
            }
        }
        if report.tier != .lightTouch {
            let damageSummary = report.damage
                .map { entry in
                    "\(entry.componentID):\(String(format: "%.2f", entry.integrityBefore))→\(String(format: "%.2f", entry.integrityAfter))"
                }
                .joined(separator: ",")
            print(
                "[Impact] tier=\(report.tier.rawValue) comp=\(report.componentID) " +
                "src=\(report.obstacleSource ?? "?") E=\(String(format: "%.1f", report.impactEnergyJ))J " +
                "vN=\(String(format: "%.2f", report.normalClosingSpeed)) " +
                "j=\(String(format: "%.2f", report.appliedImpulse)) " +
                {
                    guard let probe = sceneController.obstacleDiagnostics(for: report.obstacleID) else {
                        // Nothing resolves this id at all — which is itself the answer, and the
                        // reason the push-out could not act on it.
                        return "origin=unresolved tris=? "
                    }
                    return "origin=\(probe.origin) tris=\(probe.triangleCount) "
                }() +
                "dmg=[\(damageSummary)]"
            )
        }
        #endif

        if report.impactEnergyJ > 0.0 || report.appliedImpulse > 0.0 {
            recordedPhysicalImpactCount &+= 1
            damageEventRecorder.record(
                timestamp: TimeInterval(simulationTime),
                type: wasAlreadyDamaged ? .secondaryImpact : .impact,
                componentID: report.componentID,
                colliderID: report.obstacleID.uuidString,
                worldPoint: report.contactPoint,
                impulseNs: report.appliedImpulse,
                energyJ: report.impactEnergyJ,
                reason: report.obstacleSource ?? "physical_contact"
            )
        }

        if !report.damage.isEmpty {
            // Localized damage went into the graph — project onto the legacy
            // DamageState so overlay/diagnostics/battery model keep working.
            damageState = componentGraph.projectedLegacyDamageState(base: damageState)

            // Roll for new failure modes and re-bake the physics-facing
            // damage models (rotor thrust factors, aero deltas).
            let assignedFailures = componentFailureRuntime.noteDamage(
                entries: report.damage,
                graph: componentGraph,
                currentAileron: state.aileronDeflection,
                currentElevator: state.elevatorDeflection,
                currentRudder: state.rudderDeflection
            )
            for entry in report.damage {
                let meaningfulDelta = entry.integrityBefore - entry.integrityAfter >= 0.0005
                guard meaningfulDelta || entry.integrityAfter <= 0.0001 else { continue }
                damageEventRecorder.record(
                    timestamp: TimeInterval(simulationTime),
                    type: entry.integrityAfter <= 0.0001 ? .componentFailed : .componentDamaged,
                    componentID: entry.componentID,
                    worldPoint: report.contactPoint,
                    energyJ: report.impactEnergyJ,
                    integrityBefore: entry.integrityBefore,
                    integrityAfter: entry.integrityAfter,
                    residualStrengthBefore: entry.residualStrengthBefore,
                    residualStrengthAfter: entry.residualStrengthAfter,
                    reason: "localized_impact"
                )
                if entry.componentID == "battery", entry.integrityAfter <= 0.0001,
                   entry.integrityBefore > 0.0001, report.tier == .criticalImpact {
                    igniteBatteryFireIfNeeded(reason: "battery_impact_rupture")
                }
            }
            for assigned in assignedFailures {
                let componentID = assigned.split(separator: ":", maxSplits: 1).first.map(String.init)
                let mode = componentID.flatMap { componentFailureRuntime.failures[$0]?.mode }
                damageEventRecorder.record(
                    timestamp: TimeInterval(simulationTime),
                    type: .subsystemFailed,
                    componentID: componentID,
                    failureMode: mode,
                    reason: assigned
                )
            }
            refreshDamagePhysicsModels()
            #if DEBUG
            if !assignedFailures.isEmpty {
                print("[DamageFx] failures assigned: \(assignedFailures.joined(separator: ", "))")
            }
            let factors = vehicleRotorModel.rotors
                .map { "\($0.slot)=\(String(format: "%.2f", $0.thrustFactor))" }
                .joined(separator: " ")
            print("[DamageFx] rotors: \(factors) vib=\(String(format: "%.2f", vehicleRotorModel.vibrationLevel))")
            #endif
        }

        for entry in report.connectionDamage {
            damageEventRecorder.record(
                timestamp: TimeInterval(simulationTime),
                type: entry.stateAfter == .attached ? .componentDeformed : .connectionLoosened,
                componentID: entry.childComponentID,
                connectionID: entry.connectionID,
                worldPoint: report.contactPoint,
                impulseNs: report.appliedImpulse,
                energyJ: report.impactEnergyJ,
                residualStrengthBefore: entry.residualStrengthBefore,
                residualStrengthAfter: entry.residualStrengthAfter,
                reason: "connection_impact"
            )
        }

        detachFailedSubtrees(
            rootComponentIDs: componentGraph.failedConnectionRootIDs,
            reason: "impact_connection_failure",
            impactMotions: Dictionary(
                uniqueKeysWithValues: report.detachedPartMotions.map {
                    ($0.rootComponentID, $0)
                }
            )
        )

        guard report.tier != .lightTouch else { return }

        let severityGain: Float
        switch report.tier {
        case .lightTouch:
            severityGain = 0.0
        case .scrape:
            severityGain = 0.45
        case .heavyImpact:
            severityGain = 0.9
        case .criticalImpact:
            severityGain = 1.4
        }
        impactSeverityAccumulator = max(
            impactSeverityAccumulator,
            report.normalClosingSpeed * severityGain
        )

        switch report.tier {
        case .lightTouch:
            break
        case .scrape:
            collisionAftermathState = .impactRecovery
            // Handing a wing aircraft to `.manual` is not handing it to the operator.
            //
            // A multirotor that drops out of auto stays roughly where it is and waits. A fixed
            // wing or a hybrid VTOL in cruise keeps flying, and with no stick input it flies
            // wherever it was last trimmed. One recorded flight brushed a façade with a wing tip,
            // lost the autopilot to this line, and collected two more contacts and a shed wing
            // panel on the way out. A scrape is a reason to warn, not a reason to stop flying the
            // aircraft; heavy and critical hits below still take control away.
            if mode.isAutoControlled, selectedDroneProfile.airframeClass == .multirotor {
                setFlightMode(.manual, reason: "auto_mode_cancelled_minor_collision")
            }
            evaluateImpactInternalFailures(report)
        case .heavyImpact:
            collisionAftermathState = .damaged
            if selectedDroneProfile.airframeClass == .multirotor, physicalState != .crashed {
                setFlightMode(.hover, reason: "multicopter_collision_hover_recovery")
            }
            evaluateImpactInternalFailures(report)
        case .criticalImpact:
            // A severe hit changes only damage/control authority. Surviving
            // propulsion and aerodynamic sections remain in the normal
            // solver and determine whether the aircraft recovers or tumbles.
            collisionAftermathState = .damaged
            evaluateImpactInternalFailures(report)
        }
    }

    private func resolveSupportSurfaceImpactIfNeeded(
        contact: VehicleSweptContact,
        previousState: DroneState,
        deltaTime: Float
    ) -> ImpactReport? {
        guard groundImpactCooldown <= 0.0 else { return nil }
        let normal = simd_length_squared(contact.contactNormal) > 0.0001
            ? simd_normalize(contact.contactNormal)
            : SIMD3<Float>(0.0, 1.0, 0.0)
        let orientation = attitudeQuaternion(of: previousState)
        let rates = selectedDroneProfile.airframeClass == .multirotor
            ? previousState.angularVelocity
            : previousState.bodyAngularVelocity
        let omegaWorld = simd_act(orientation, SIMD3<Float>(rates.y, rates.z, rates.x))
        let previousCoM = previousState.position + vehicleBodyOriginWorldOffset + simd_act(
            orientation,
            vehicleMassProperties.centerOfMassOffset
        )
        let incomingVelocity = previousState.velocity + simd_cross(
            omegaWorld,
            contact.contactPoint - previousCoM
        )
        let closingSpeed = -simd_dot(incomingVelocity, normal)
        guard closingSpeed > 0.35 else { return nil }

        let previousLinearNormal = simd_dot(previousState.velocity, normal)
        let currentLinearNormal = simd_dot(state.velocity, normal)
        if previousLinearNormal < currentLinearNormal {
            state.velocity += normal * (previousLinearNormal - currentLinearNormal)
        }
        let report = impactResolutionService.resolve(
            contact: contact,
            previousPosition: previousState.position,
            state: &state,
            graph: &componentGraph,
            massProperties: vehicleMassProperties,
            airframeClass: selectedDroneProfile.airframeClass,
            bodyOriginWorldOffset: vehicleBodyOriginWorldOffset,
            rotorsSpinning: state.throttle > 0.05 && isArmed,
            deltaTime: deltaTime,
            applyDamage: true,
            restingSpeedThreshold: crashResolutionRestingSpeedThreshold
        )
        groundImpactCooldown = report.tier == .lightTouch ? 0.05 : 0.16
        return report
    }

    /// How far clear of the surface the airframe must get before a return to it
    /// counts as an impact again. Sized above the ground clamp's own jitter and
    /// above a wheel rolling over a bump, and below any descent worth resolving.
    private static let groundImpactRearmHeightMeters: Float = 0.20
    /// And for how long. One tick of clearance is noise; a fifth of a second of it
    /// is an aircraft that genuinely left the ground.
    private static let groundImpactRearmSeconds: Float = 0.20

    private func resolveGroundImpactIfNeeded(
        previousState: DroneState,
        deltaTime: Float
    ) -> ImpactReport? {
        guard groundImpactCooldown <= 0.0 else { return nil }

        let currentOrientation = attitudeQuaternion(of: state)
        let previousOrientation = attitudeQuaternion(of: previousState)
        let support = supportSurfaceContact(for: state.position)
        let supportY = support?.height ?? supportSurfaceY(for: state.position)
        var normal = support?.normal ?? SIMD3<Float>(0.0, 1.0, 0.0)
        if simd_length_squared(normal) < 0.0001 {
            normal = SIMD3<Float>(0.0, 1.0, 0.0)
        } else {
            normal = simd_normalize(normal)
        }

        let fallbackSphere = VehicleContactSphere(
            componentID: componentGraph.component(id: "gear.main") != nil ? "gear.main" : "frame",
            offset: .zero,
            radius: max(0.05, selectedDroneProfile.collisionRadius * 0.22)
        )
        let currentLowest = vehicleContactProfile.lowestContact(
            position: state.position,
            orientation: currentOrientation
        ) ?? (sphere: fallbackSphere, point: state.position)
        let previousLowest = vehicleContactProfile.lowestContact(
            position: previousState.position,
            orientation: previousOrientation
        ) ?? (sphere: fallbackSphere, point: previousState.position)

        // Rest-normalized, exactly as the physics ground clamp is.
        //
        // The clamp holds `origin.y >= supportY + max(0, L(attitude) - L(rest))`, so at the rest
        // attitude the origin sits *on* the surface and every contact sphere below the origin is
        // below it too. For a tailsitter that is the whole tail — it stands on it, ~0.4 m under
        // the origin — and comparing the raw lowest sphere against `supportY` therefore reports a
        // 0.4 m ground penetration that is the aircraft simply standing where it belongs. Adding
        // L(rest) back makes "touching the ground" mean the same quantity here as in the clamp.
        // Every other airframe rests belly-down with L(rest) ~ 0 and is unaffected.
        let restGroundOffset = vehicleGroundRestOffset
        let currentHeight = currentLowest.point.y - supportY + restGroundOffset
        let previousSupportY = supportSurfaceY(for: previousState.position)
        let previousHeight = previousLowest.point.y - previousSupportY + restGroundOffset

        // An aircraft that is *on* the ground is not arriving at it.
        //
        // The old window — clear by 18 mm last tick, within 35 mm this one — is
        // narrower than the ground clamp's own jitter. An airframe resting or
        // sliding on the surface crosses it every few ticks forever, so the impulse
        // solver re-fired twenty times a second at whatever the lowest contact
        // happened to be. Every one of those was a `.lightTouch`, which is not
        // logged and does no damage, so nothing in a flight log said it was
        // happening — and the only visible symptom was an attitude that jittered a
        // degree per tick while altitude, speed and pitch sat frozen. A heavy
        // aircraft that got a wing down at speed was then held there by the same
        // solver that was supposed to be modelling its arrival.
        //
        // Requiring real clearance first — more than the gear's own travel, and for
        // more than a single tick — restores what this check is for: an aircraft
        // that was flying and is now touching. Resting on the ground is the ground
        // clamp's business, and sliding along it is the weight-on-wheels model's.
        let hadRealClearance = previousHeight > Self.groundImpactRearmHeightMeters
            && groundContactClearElapsed >= Self.groundImpactRearmSeconds
        if previousHeight > Self.groundImpactRearmHeightMeters {
            groundContactClearElapsed += deltaTime
        } else {
            groundContactClearElapsed = 0.0
        }
        guard currentHeight <= 0.035, hadRealClearance else { return nil }

        let rates = selectedDroneProfile.airframeClass == .multirotor
            ? previousState.angularVelocity
            : previousState.bodyAngularVelocity
        let omegaBodyAxes = SIMD3<Float>(rates.y, rates.z, rates.x)
        let omegaWorld = simd_act(previousOrientation, omegaBodyAxes)
        let previousCoM = previousState.position + vehicleBodyOriginWorldOffset + simd_act(
            previousOrientation,
            vehicleMassProperties.centerOfMassOffset
        )
        let incomingContactVelocity = previousState.velocity + simd_cross(
            omegaWorld,
            previousLowest.point + vehicleBodyOriginWorldOffset - previousCoM
        )
        // How hard the aircraft came *down* onto the ground, not how fast it was
        // travelling across it.
        //
        // `-dot(v, n)` is the right closing speed against a wall. Against a support
        // surface it is not: the normal tilts with every slope and undulation the
        // terrain has, and the projection then charges the whole ground speed to
        // the impact. Measured in flight, an aircraft doing 31.7 m/s along a field
        // with 0.63 m/s of sink registered a 6.38 m/s closing speed and a 6.3 kJ
        // hit — enough to tear the main gear off during an ordinary ground roll,
        // on ground that merely rose ahead of it. Wheels and skids ride over that;
        // they do not collide with it. The vertical closure is the honest measure,
        // and a genuine arrival — a stall onto the ground, a dive into a hillside —
        // has all of its energy there anyway.
        let projectedClosingSpeed = -simd_dot(incomingContactVelocity, normal)
        let closingSpeed = min(projectedClosingSpeed, max(0.0, -incomingContactVelocity.y))
        guard closingSpeed > 0.35 else { return nil }

        // The legacy engine/support constraint may already have erased the
        // downward component. Restore the pre-contact normal velocity so the
        // impulse solver sees the real approach speed.
        let previousLinearNormal = simd_dot(previousState.velocity, normal)
        let currentLinearNormal = simd_dot(state.velocity, normal)
        if previousLinearNormal < currentLinearNormal {
            state.velocity += normal * (previousLinearNormal - currentLinearNormal)
        }

        let elevatedStructure = supportY > 0.05
        let source = elevatedStructure
            ? "ground.structure"
            : "ground.\(terrain.preset.rawValue.lowercased())"
        let obstacle = CollisionObstacle(
            id: UUID(),
            center: SIMD3<Float>(state.position.x, supportY - 0.25, state.position.z),
            radius: 500.0,
            source: source,
            baseY: supportY - 0.5,
            topY: supportY,
            planarHalfExtents: SIMD2<Float>(repeating: 500.0)
        )
        let contactPoint = SIMD3<Float>(currentLowest.point.x, supportY, currentLowest.point.z)
        let syntheticContact = VehicleSweptContact(
            obstacle: obstacle,
            componentID: currentLowest.sphere.componentID,
            contactPoint: contactPoint,
            contactNormal: normal,
            hitFraction: 1.0,
            isSupportSurfaceContact: true,
            sphereOffset: currentLowest.sphere.offset,
            sphereRadius: currentLowest.sphere.radius
        )
        let report = impactResolutionService.resolve(
            contact: syntheticContact,
            previousPosition: previousState.position,
            state: &state,
            graph: &componentGraph,
            massProperties: vehicleMassProperties,
            airframeClass: selectedDroneProfile.airframeClass,
            bodyOriginWorldOffset: vehicleBodyOriginWorldOffset,
            rotorsSpinning: state.throttle > 0.05 && isArmed,
            deltaTime: deltaTime,
            applyDamage: true,
            restingSpeedThreshold: crashResolutionRestingSpeedThreshold
        )
        groundImpactCooldown = report.tier == .lightTouch ? 0.05 : 0.16
        return report
    }

    /// How much strength aerodynamic heating has taken out of the structure right now.
    ///
    /// Zero for every aircraft in the catalogue at the speeds they fly; it starts to
    /// matter only once a skin temperature passes the material's working limit, which
    /// takes sustained flight above about Mach 2.
    /// Decides whether the operator hears a boom this tick, and plays it if so.
    ///
    /// The listener is the ground station, not the camera. A chase camera flies inside the
    /// cone with the aircraft and would never hear anything; an aircraft never hears its
    /// own boom at all. The person standing at the launch point is the one the effect is
    /// about, and the delay between the aircraft passing overhead and the bang arriving is
    /// most of what makes it recognisable.
    private func advanceSonicBoom(deltaTime: Float) {
        guard selectedDroneProfile.airframeClass != .multirotor else { return }
        let atmosphere = currentAtmosphere().state(worldY: state.position.y)
        let lengthM = (activeUAVProfile?.dimensions.fuselageLengthMillimeters
            ?? selectedDroneProfile.dimensionsUnfoldedMm.y) / 1000.0
        guard let boom = sonicBoomTracker.update(
            aircraftPosition: state.position,
            aircraftVelocity: state.velocity,
            mach: state.machNumber,
            observerPosition: homePosition,
            atmosphere: atmosphere,
            aircraftMassKg: selectedDroneProfile.takeoffMassKg,
            aircraftLengthM: lengthM,
            deltaTime: deltaTime
        ) else { return }

        simulationAudio.playSonicBoom(
            overpressurePa: boom.overpressurePa,
            durationSeconds: SimulationAudioService.nWaveDuration(
                aircraftLengthM: lengthM,
                slantRangeMeters: boom.slantRangeMeters
            ),
            delaySeconds: boom.arrivalDelaySeconds
        )
        recordMissionReplayEvent(
            .warning,
            message: String(
                format: NSLocalizedString("event.sonic_boom", comment: ""),
                boom.mach,
                boom.overpressurePa,
                boom.arrivalDelaySeconds
            )
        )
    }

    private func currentThermalWeakening() -> Float {
        guard let wing = selectedDroneProfile.fixedWingParameters else { return 0.0 }
        let limits = FlightEnvelopeLimits.derived(
            maxAirspeedMps: wing.maxAirspeed,
            stallAlphaRad: FixedWingAerodynamics.stallAngleOfAttack(for: wing.family),
            dragDivergenceMach: FixedWingAerodynamics.dragDivergenceMach(for: wing.family),
            structuralQualityFactor: selectedDroneProfile.structuralQualityFactor,
            skinMaterial: selectedDroneProfile.skinMaterial
        )
        let hottest = state.aeroThermal.hottestK
        guard hottest > limits.maxSkinTemperatureK else { return 0.0 }
        return min(1.0, (hottest - limits.maxSkinTemperatureK) / 250.0)
    }

    private func advanceStructuralDamage(
        previousState: DroneState,
        loadState: DroneState,
        deltaTime: Float
    ) {
        let result = structuralLoadSolver.evaluate(
            graph: &componentGraph,
            previousState: previousState,
            state: loadState,
            airframeClass: selectedDroneProfile.airframeClass,
            rotorModel: vehicleRotorModel,
            deltaTime: deltaTime,
            airDensity: currentAtmosphere().state(worldY: state.position.y).airDensity,
            thermalWeakening: currentThermalWeakening()
        )
        for entry in result.connectionDamage {
            let meaningfulDelta = entry.residualStrengthBefore - entry.residualStrengthAfter >= 0.002
            guard meaningfulDelta || entry.stateBefore != entry.stateAfter else { continue }
            damageEventRecorder.record(
                timestamp: TimeInterval(simulationTime),
                type: entry.stateAfter == .attached ? .componentDeformed : .connectionLoosened,
                componentID: entry.childComponentID,
                connectionID: entry.connectionID,
                residualStrengthBefore: entry.residualStrengthBefore,
                residualStrengthAfter: entry.residualStrengthAfter,
                reason: "structural_load_progression"
            )
        }
        detachFailedSubtrees(
            rootComponentIDs: result.failedConnectionRootIDs,
            reason: "structural_overload"
        )
    }

    private func enforceComponentFunctionalState() {
        let batteryAvailable = componentGraph.integrity(id: "battery") > 0.001 &&
            componentFailureRuntime.functionalFactor(componentID: "battery") > 0.20
        let controllerAvailable = componentGraph.integrity(id: "flightController") > 0.05 &&
            componentFailureRuntime.functionalFactor(componentID: "flightController") > 0.20
        let radioAvailable = componentGraph.integrity(id: "radio") > 0.05 &&
            componentFailureRuntime.functionalFactor(componentID: "radio") > 0.20
        let rootDestroyed = ["frame", "fuselage"].contains { id in
            componentGraph.component(id: id) != nil && componentGraph.integrity(id: id) <= 0.001
        }

        if !radioAvailable, signalLossCause == nil {
            signalLossCause = .impactDamage
            damageEventRecorder.record(
                timestamp: TimeInterval(simulationTime),
                type: .subsystemFailed,
                componentID: "radio",
                reason: "radio_function_unavailable"
            )
            enterSignalLostState(cause: .impactDamage)
        }

        guard isArmed, !batteryAvailable || !controllerAvailable || rootDestroyed else { return }
        let componentID: String
        let reason: String
        if rootDestroyed {
            componentID = componentGraph.component(id: "frame") != nil ? "frame" : "fuselage"
            reason = "primary_structure_destroyed"
        } else if !batteryAvailable {
            componentID = "battery"
            reason = "power_source_unavailable"
        } else {
            componentID = "flightController"
            reason = "flight_controller_unavailable"
        }
        collisionAftermathState = .damaged
        damageEventRecorder.record(
            timestamp: TimeInterval(simulationTime),
            type: .subsystemFailed,
            componentID: componentID,
            reason: reason
        )
        damageEventRecorder.record(
            timestamp: TimeInterval(simulationTime),
            type: .controlAuthorityLost,
            componentID: componentID,
            reason: reason
        )
        disarm(forceEmergency: true, preserveCrashDynamics: false)
    }

    private func detachFailedSubtrees(
        rootComponentIDs: [String],
        reason: String,
        impactMotions: [String: ImpactDetachedPartMotion] = [:]
    ) {
        var detachedParts: [VehicleDetachedSubtree] = []
        for rootID in Set(rootComponentIDs).sorted() {
            if let part = componentGraph.detachSubtree(rootComponentID: rootID) {
                detachedParts.append(part)
                componentFailureRuntime.removeFailures(componentIDs: part.componentIDs)
                vehicleContactProfile = vehicleContactProfile.removing(componentIDs: part.componentIDs)
                damageEventRecorder.record(
                    timestamp: TimeInterval(simulationTime),
                    type: .componentDetached,
                    componentID: part.rootComponentID,
                    reason: reason,
                    detachedComponentIDs: Array(part.componentIDs),
                    massPropertiesRevision: componentGraph.massPropertiesRevision
                )
            }
        }
        guard !detachedParts.isEmpty else { return }

        vehicleMassProperties = componentGraph.massProperties
        damageState = componentGraph.projectedLegacyDamageState(base: damageState)
        // Clone the currently deformed source geometry before refreshing the
        // attached-airframe overlay hides/resets the detached source nodes.
        let orientation = attitudeQuaternion(of: state)
        let rates = selectedDroneProfile.airframeClass == .multirotor
            ? state.angularVelocity
            : state.bodyAngularVelocity
        let omegaBodyAxes = SIMD3<Float>(rates.y, rates.z, rates.x)
        let retainedLegacyComponents = Set(
            componentGraph.attachedComponents.compactMap(\.legacyComponent)
        )
        for part in detachedParts {
            let impactMotion = impactMotions[part.rootComponentID]
            sceneController.spawnDetachedVehiclePart(
                part,
                retainedLegacyComponents: retainedLegacyComponents,
                vehicleWorldPosition: state.position + vehicleBodyOriginWorldOffset,
                vehicleOrientation: orientation,
                inheritedVelocity: state.velocity,
                inheritedAngularVelocity: omegaBodyAxes,
                initialCenterOfMassVelocityWorld: impactMotion?.centerOfMassVelocityWorld,
                initialAngularVelocityWorld: impactMotion?.angularVelocityWorld
            )
        }
        sceneController.reconcileDetachedVehicleVisuals(componentGraph)
        refreshDamagePhysicsModels()
        damageEventRecorder.record(
            timestamp: TimeInterval(simulationTime),
            type: .massPropertiesChanged,
            reason: reason,
            detachedComponentIDs: detachedParts.flatMap { Array($0.componentIDs) },
            massPropertiesRevision: componentGraph.massPropertiesRevision
        )
        #if DEBUG
        // Losing a part without an impact reads in the log as an object count that silently went
        // up. Say which part left and why, so an airframe that sheds a wing in level flight is
        // distinguishable from one that hit something.
        print(
            "[Detach] reason=\(reason) parts=[\(detachedParts.map(\.rootComponentID).joined(separator: ","))] " +
            "spd=\(String(format: "%.1f", state.forwardAirspeed)) " +
            "alt=\(String(format: "%.1f", state.position.y)) " +
            "wb=\(String(format: "%.2f", state.vtolWingborneBlend))"
        )
        #endif
    }

    private func recordDetachedVehiclePartImpactEvents() {
        for event in sceneController.consumeDetachedVehiclePartImpactEvents() {
            damageEventRecorder.record(
                timestamp: TimeInterval(simulationTime),
                type: .secondaryImpact,
                componentID: event.rootComponentID,
                colliderID: event.colliderID.uuidString,
                worldPoint: event.worldPoint,
                impulseNs: event.impulseNs,
                energyJ: event.energyJ,
                reason: "detached_part_impact:\(event.colliderSource)",
                detachedComponentIDs: event.detachedComponentIDs,
                massPropertiesRevision: componentGraph.massPropertiesRevision
            )
        }
    }

    private func flushDamageEventAdapters() {
        let events = damageEventRecorder.consumePendingEvents()
        guard !events.isEmpty else { return }
        recentDamageEvents.append(contentsOf: events)
        if recentDamageEvents.count > 32 {
            recentDamageEvents.removeFirst(recentDamageEvents.count - 32)
        }
        for event in events {
            let replayType: MissionReplayEventType
            switch event.type {
            case .impact, .secondaryImpact:
                replayType = .impact
            case .componentDamaged, .componentDeformed, .connectionLoosened, .componentFailed:
                replayType = .componentDamaged
            case .componentDetached:
                replayType = .componentDetached
            case .subsystemFailed:
                replayType = .subsystemFailed
            case .massPropertiesChanged:
                replayType = .massPropertiesChanged
            case .controlAuthorityReduced, .controlAuthorityLost:
                replayType = .controlAuthorityReduced
            case .vehicleSettled:
                replayType = .vehicleSettled
            }
            let subject = event.componentID.map { " [\($0)]" } ?? ""
            let payload = MissionReplayDamagePayload(
                sequenceNumber: event.sequenceNumber,
                canonicalEventTypeRawValue: event.type.rawValue,
                vehicleID: onlineRuntimeContext?.localVehicleID,
                componentID: event.componentID,
                connectionID: event.connectionID,
                colliderID: event.colliderID,
                impulseNs: event.impulseNs,
                energyJ: event.energyJ,
                integrityBefore: event.integrityBefore,
                integrityAfter: event.integrityAfter,
                residualStrengthBefore: event.residualStrengthBefore,
                residualStrengthAfter: event.residualStrengthAfter,
                failureModeRawValue: event.failureMode?.rawValue,
                detachedComponentIDs: event.detachedComponentIDs,
                massPropertiesRevision: event.massPropertiesRevision,
                rotorThrustFactors: Dictionary(
                    vehicleRotorModel.rotors.map { ($0.slot, $0.thrustFactor) },
                    uniquingKeysWith: { _, latest in latest }
                ),
                reason: event.reason
            )
            recordMissionReplayEvent(
                replayType,
                message: "\(event.reason)\(subject)",
                position: event.worldPoint,
                damage: payload
            )
        }
    }

    private func collisionEmergencyAction(for tier: ImpactOutcomeTier) -> CollisionEmergencyAction {
        switch tier {
        case .lightTouch:
            return .none
        case .scrape:
            return .slowDown
        case .heavyImpact:
            return .avoid
        case .criticalImpact:
            return .avoid
        }
    }

    /// Post-impact internal failures — since the impulse rework this is the
    /// ONLY collision path that cuts signal/video: a static overlay now means
    /// the radio actually died, not "the hit was hard". Proximity damage has
    /// already reduced internal-component integrity in the graph; destroyed
    /// or heavily damaged electronics produce their functional effect here.
    private func evaluateImpactInternalFailures(_ report: ImpactReport) {
        // Radio: destroyed → immediate link loss; badly damaged → a chance,
        // growing as integrity drops.
        if signalLossCause == nil {
            let radioIntegrity = componentGraph.integrity(id: "radio")
            let radioWasDamaged = report.damage.contains { $0.componentID == "radio" }
            let radioFailed = radioIntegrity <= 0.05 ||
                (radioWasDamaged && radioIntegrity < 0.45 && componentFailureRuntime.chance(
                    probability: (0.45 - radioIntegrity) * 0.8
                ))
            if radioFailed {
                signalLossCause = .impactDamage
                enterSignalLostState(cause: .impactDamage)
            }
        }

        // Flight-controller/power effects are enforced centrally by
        // `enforceComponentFunctionalState`, avoiding duplicate events and
        // a second, competing disarm path.
    }

    private func obstacleImpactClass(for source: String?) -> ObstacleImpactClass {
        let token = (source ?? "").lowercased()
        if token.hasPrefix("tree.") {
            return .foliage
        }
        if token.hasPrefix("rock.") || token.hasPrefix("crate.") {
            return .softSurface
        }
        return .hardSurface
    }

    /// The material duration is the ceiling for a genuinely violent hit; a tier that only just
    /// cleared `.lightTouch` (a graze, a slow scrape settling against a trunk) gets a much
    /// shorter cooldown instead of the same flat material duration — otherwise a single scrape
    /// blocks the *same ongoing contact* from registering again for most of a second, which is
    /// exactly what made sustained light contact (drifting into a tree, settling against a wall)
    /// barely damage anything: one small tick, then silence while the aircraft is still touching
    /// it. `.lightTouch` itself never reaches this function (see call sites' `tier != .lightTouch`
    /// guard) — it never needs a cooldown since it does no damage to rate-limit in the first place.
    private func collisionCooldownDuration(for source: String?, tier: ImpactOutcomeTier) -> Float {
        let materialDuration: Float
        switch obstacleImpactClass(for: source) {
        case .foliage:
            materialDuration = 0.18
        case .softSurface:
            materialDuration = 0.34
        case .hardSurface:
            materialDuration = 0.70
        }
        switch tier {
        case .lightTouch:
            return 0.0
        case .scrape:
            return materialDuration * 0.18
        case .heavyImpact:
            return materialDuration * 0.55
        case .criticalImpact:
            return materialDuration
        }
    }

    /// Scripted-event crash (mission scenario `forcedCrashRequired`, payload
    /// proximity events) — NOT reachable from physical collisions anymore;
    /// those go through `applyImpactConsequences`, where signal loss only
    /// follows an actual radio failure.
    private func applySevereCollisionConsequences(source: String?) {
        lastCollisionSource = source ?? lastCollisionSource
        collisionAftermathState = .damaged
        signalLossCause = .impactDamage
        enterSignalLostState(cause: .impactDamage)
        damageEventRecorder.record(
            timestamp: TimeInterval(simulationTime),
            type: .controlAuthorityLost,
            reason: source ?? "scripted_control_loss"
        )
        disarm(forceEmergency: true, preserveCrashDynamics: false)
        updateControlValues({ values in
            values.throttle = 0.0
        }, markManual: false)
    }

    /// Real, localized strikes rather than the old full-screen sun-intensity flash (removed from
    /// DroneSceneController's `updateWeatherAnimation`) — minutes apart per the user's spec ("от
    /// 60 до 600 секунд"), at a random point near the drone, with a small chance of actually
    /// hitting it.
    private func updateThunderstormLightning(deltaTime: Float) {
        guard weather.preset == .thunderstorm else {
            return
        }
        nextLightningStrikeCountdown -= deltaTime
        guard nextLightningStrikeCountdown <= 0 else {
            return
        }
        nextLightningStrikeCountdown = Float.random(in: 60...600)

        // Same non-zero-floor pattern as the visual darkening elsewhere in this preset — a
        // freshly-picked storm (intensity 0) still carries a real, if smaller, chance of a hit.
        let hitChance = 0.05 + weather.normalizedIntensity * 0.05
        let isHit = Float.random(in: 0...1) < hitChance

        let impactPosition: SCNVector3
        let boltHeight: Float
        if isHit {
            impactPosition = SCNVector3(state.position.x, state.position.y, state.position.z)
            boltHeight = max(40.0, state.position.y + 45.0)
            applyLightningStrikeDamage()
        } else {
            let radius = Float.random(in: 30...220)
            let angle = Float.random(in: 0...(2.0 * Float.pi))
            impactPosition = SCNVector3(
                state.position.x + cos(angle) * radius,
                0.0,
                state.position.z + sin(angle) * radius
            )
            boltHeight = Float.random(in: 50...75)
        }

        if !performancePolicy.stopRendering {
            sceneController.triggerLightningStrike(impactPosition: impactPosition, boltHeight: boltHeight)
        }
    }

    /// A struck aircraft takes real damage ("шанс никогда же не равен 0... приведет к
    /// поломке") — reuses the same collision-damage pipeline as a physical impact rather than
    /// inventing a separate one.
    private func applyLightningStrikeDamage() {
        damageState = damageState.applyingCollisionDamage(impactEnergy: 9.0)
        synchronizeLegacyDamageIntoGraph(reason: "lightning_strike")
        lastCollisionSource = "lightning_strike"
        collisionAftermathState = .damaged
        impactSeverityAccumulator = max(impactSeverityAccumulator, 2.0)
        state.angularVelocity += SIMD3<Float>(
            Float.random(in: -0.8...0.8),
            Float.random(in: -0.4...0.4),
            Float.random(in: -0.8...0.8)
        )
    }

    private func resolveObstaclePenetration(using analysis: CollisionAnalysisSnapshot) -> Bool {
        let penetration = max(0.0, -analysis.nearestObstacleDistance)
        guard penetration > 0.0001,
              let obstacleID = analysis.nearestObstacleID,
              let obstacle = sceneController.obstacle(for: obstacleID) else {
            return false
        }

        let normal: SIMD3<Float>
        if let contactNormal = analysis.contactNormal,
           simd_length_squared(contactNormal) > 0.0001 {
            normal = simd_normalize(contactNormal)
        } else {
            normal = horizontalPushNormal(awayFrom: obstacle)
        }

        let orientation = attitudeQuaternion(of: state)
        let fallback = VehicleContactSphere(
            componentID: componentGraph.component(id: "frame") != nil ? "frame" : "fuselage",
            offset: .zero,
            radius: max(0.05, selectedDroneProfile.collisionRadius)
        )
        let bodyOriginPosition = state.position + vehicleBodyOriginWorldOffset
        let sphere = (vehicleContactProfile.spheres.isEmpty ? [fallback] : vehicleContactProfile.spheres)
            .min { lhs, rhs in
                let lhsCenter = lhs.worldCenter(position: bodyOriginPosition, orientation: orientation)
                let rhsCenter = rhs.worldCenter(position: bodyOriginPosition, orientation: orientation)
                return simd_distance_squared(lhsCenter, obstacle.center) <
                    simd_distance_squared(rhsCenter, obstacle.center)
            } ?? fallback
        let center = sphere.worldCenter(position: bodyOriginPosition, orientation: orientation)
        let contactPoint = center - normal * sphere.radius
        let report = impactResolutionService.resolvePenetration(
            penetrationDepth: penetration,
            contactNormal: normal,
            contactPoint: contactPoint,
            obstacle: obstacle,
            componentID: sphere.componentID,
            sphereRadius: sphere.radius,
            state: &state,
            graph: &componentGraph,
            massProperties: vehicleMassProperties,
            airframeClass: selectedDroneProfile.airframeClass,
            bodyOriginWorldOffset: vehicleBodyOriginWorldOffset,
            rotorsSpinning: state.throttle > 0.05 && isArmed,
            deltaTime: 1.0 / 60.0,
            applyDamage: collisionCooldown <= 0.0,
            restingSpeedThreshold: crashResolutionRestingSpeedThreshold
        )
        applyImpactConsequences(report)
        if report.tier != .lightTouch, collisionCooldown <= 0.0 {
            collisionCooldown = collisionCooldownDuration(for: report.obstacleSource, tier: report.tier)
        }
        return true
    }

    private func horizontalPushNormal(awayFrom obstacle: CollisionObstacle) -> SIMD3<Float> {
        var away = SIMD3<Float>(
            state.position.x - obstacle.center.x,
            0.0,
            state.position.z - obstacle.center.z
        )

        if simd_length_squared(away) < 0.0001 {
            let fallback = SIMD3<Float>(state.velocity.x, 0.0, state.velocity.z)
            if simd_length_squared(fallback) > 0.0001 {
                away = simd_normalize(fallback)
            } else {
                away = SIMD3<Float>(0.0, 0.0, 1.0)
            }
        } else {
            away = simd_normalize(away)
        }

        return away
    }

    private func applyPayloadSelfInteractionIfNeeded(deltaTime: Float) {
        guard payloadSelfInteractionTimer > 0.0, payloadSelfInteractionSeverity > 0.0 else {
            payloadSelfInteractionTimer = 0.0
            payloadSelfInteractionSeverity = 0.0
            payloadControlPenalty = 0.0
            return
        }

        payloadSelfInteractionTimer = max(0.0, payloadSelfInteractionTimer - deltaTime)
        let envelope = (payloadSelfInteractionTimer / 3.4).clamped(to: 0.0...1.0)
        let intensity = payloadSelfInteractionSeverity * envelope
        let phase = simulationTime * 7.0

        state.angularVelocity.z += sin(phase) * intensity * 0.30
        state.angularVelocity.x += cos(phase * 0.7) * intensity * 0.10
        state.orientation.z += sin(phase * 0.9) * intensity * 0.010
        state.orientation.x += cos(phase * 0.8) * intensity * 0.004
        state.velocity.y += sin(phase * 1.2) * intensity * 0.06
        let activePenalty = payloadControlPenalty * envelope
        if activePenalty > 0.05 {
            updateControlValues({ values in
                let rollLimit = Double(max(6.0, 18.0 * (1.0 - activePenalty)))
                let pitchLimit = Double(max(6.0, 18.0 * (1.0 - activePenalty)))
                values.roll = values.roll.clamped(to: -rollLimit...rollLimit)
                values.pitch = values.pitch.clamped(to: -pitchLimit...pitchLimit)
                values.throttle = max(0.18, values.throttle * Double(1.0 - activePenalty * 0.30))
            }, markManual: false)
        }

        if payloadSelfInteractionTimer <= 0.0 {
            payloadSelfInteractionSeverity = 0.0
            payloadControlPenalty = 0.0
        }
    }

    private func handleAutoCollisionInterventions(deltaTime: Float) {
        // Seeing obstacles is not a property of the flight mode.
        //
        // This used to require `mode.isAutoControlled`, which meant `.autoPath` and `.returnHome`
        // and nothing else. Every other mode flew blind — including the two the aircraft ends up in
        // when a failsafe takes the mission away from it. `.manual` there does not mean a pilot has
        // the aircraft, it means nobody does, and a Wingcopter carrying 25 m/s covered the last
        // 150 m to a façade with every avoidance layer switched off by that one word. The layer is
        // now armed whenever the aircraft is flying, whatever is nominally steering it.
        //
        // The exception is a real pilot. While the operator is actually on the controls the
        // aircraft is theirs and the net stays out of the way; frozen controls left behind by a
        // failsafe are not an operator, and produce no input to record.
        // Take-off and landing are deliberate approaches to a structure, flown by their own logic
        // and their own clearances. A proximity net there would refuse to let the aircraft land.
        guard isArmed,
              physicalState == .airborne,
              mode != .takeoff,
              mode != .landing else {
            clearCollisionInterventionHold()
            return
        }
        if operatorIsOnTheControls {
            // Taking the aircraft back has to work while the net is holding it, not only before.
            // The old form only declined to *arm* for a pilot; once armed, the sticks were ignored
            // until the risk band cleared or the six-second ceiling expired, so an operator who
            // flew up to a tree deliberately got the aircraft wrestled away and could not answer.
            if let suspendedMode = collisionInterventionSuspendedMode {
                resumeAfterCollisionInterventionHold(
                    suspendedMode,
                    reason: "collision_intervention_cleared"
                )
            }
            return
        }

        if isMultirotorMarkerRouteCollisionManagedByPlanner {
            return
        }

        var action = collisionAnalysis.emergencyAction

        // The net may not cut the motors. Ever, while the aircraft is flying.
        //
        // `.emergencyStop` here calls `activateEmergencyStop()`, which disarms — at altitude that
        // is not an avoidance manoeuvre, it is the crash the layer exists to prevent, and it takes
        // the aircraft down from wherever it happened to be. This guard exists so that no future
        // change to the risk model can reach that outcome by accident; one already did, and two
        // VTOLs fell out of the sky under power that was working fine. The strongest thing a
        // proximity layer is allowed to do is fly the aircraft away from what it found.
        if action == .emergencyStop {
            action = .avoid
        }

        if let suspendedMode = collisionInterventionSuspendedMode {
            guard mode == .hover else {
                // The operator, a failsafe or a landing took the aircraft while it was held.
                // Whoever owns it now owns it outright.
                clearCollisionInterventionHold()
                return
            }

            collisionInterventionHoldSeconds += deltaTime

            switch action {
            case .none, .slowDown:
                resumeAfterCollisionInterventionHold(
                    suspendedMode,
                    reason: "collision_intervention_cleared"
                )
                return
            case .hover:
                // A hover buys the stop and nothing more. The obstacle that armed the hold does
                // not move, so past the escape delay the hold must open the gap itself instead of
                // re-arming on the clearance it is not changing.
                if collisionInterventionHoldSeconds >= Self.collisionInterventionEscapeDelaySeconds {
                    action = .avoid
                }
            case .avoid, .emergencyStop:
                break
            }

            if action != .emergencyStop,
               collisionInterventionHoldSeconds >= Self.collisionInterventionMaximumHoldSeconds {
                resumeAfterCollisionInterventionHold(
                    suspendedMode,
                    reason: "collision_intervention_hold_expired"
                )
                return
            }
        }

        switch action {
        case .none, .slowDown:
            return
        case .hover:
            if collisionInterventionSuspendedMode == nil {
                collisionInterventionSuspendedMode = mode
                collisionInterventionHoldSeconds = 0.0
            }
            setFlightMode(.hover, reason: Self.collisionInterventionHoverReason)
            let holdAltitude = latchedCollisionInterventionHoldAltitude()
            let hoverLock = resolvedFlightBaseline(for: .hover).hoverLockThrottle
            // Carry the arrival throttle only while the aircraft is still below the altitude the
            // hold latched. Above it the arrival throttle is a climb command with nothing to stop
            // it, and the hold has no reason to want height it did not have when it armed.
            lockControlsToCurrentState(
                overrideThrottle: Double(
                    state.position.y >= holdAltitude - 0.25
                        ? hoverLock
                        : max(hoverLock, state.throttle)
                )
            )
            if selectedDroneProfile.airframeClass == .hybridVTOL {
                updateControlValues({ values in
                    values.roll = 0.0
                    values.pitch = 0.0
                    values.vtolTransitionLever = -1.0
                }, markManual: false)
            }
        case .avoid:
            guard let obstacleID = collisionAnalysis.nearestObstacleID,
                  let obstacle = sceneController.obstacleCenter(for: obstacleID) else {
                return
            }

            if selectedDroneProfile.airframeClass == .hybridVTOL {
                let planarOffset = SIMD2<Float>(
                    state.position.x - obstacle.x,
                    state.position.z - obstacle.z
                )
                let fallbackAway = SIMD2<Float>(-sin(state.orientation.z), -cos(state.orientation.z))
                let awayPlanar = simd_length(planarOffset) > 0.01
                    ? simd_normalize(planarOffset)
                    : fallbackAway
                // Sidestep at the height the hold owns, not at whatever height the last tick left
                // the aircraft at — `max(home + 2.4, y)` re-read `y` every tick, so each metre the
                // aircraft gained became the new floor and the escape target walked up with it.
                let avoidAltitude = max(
                    homePosition.y + 2.4,
                    min(state.position.y, latchedCollisionInterventionHoldAltitude())
                )
                let avoidTarget = clampToWorldBounds(SIMD3<Float>(
                    state.position.x + awayPlanar.x * 4.0,
                    avoidAltitude,
                    state.position.z + awayPlanar.y * 4.0
                ))
                let avoidContext = AutopilotTrackingContext(
                    state: state,
                    physicalState: physicalState,
                    target: avoidTarget,
                    targetAltitude: avoidTarget.y,
                    speedScale: 0.36,
                    yawAlignToHome: false,
                    yawOverrideRadians: state.orientation.z,
                    deltaTime: deltaTime,
                    flightBaseline: resolvedFlightBaseline(for: .hover)
                )
                applyHybridVTOLHoverAutopilotCommand(
                    context: avoidContext,
                    target: avoidTarget,
                    targetAltitude: avoidTarget.y,
                    speedScale: 0.36,
                    yawOverrideRadians: state.orientation.z,
                    vtolTransitionLever: state.vtolTransitionProgress > 0.08 ? -1.0 : 0.0,
                    minimumThrottle: resolvedFlightBaseline(for: .hover).hoverLockThrottle,
                    reason: "vtol_collision_avoidance_hover",
                    deltaTime: deltaTime
                )
                return
            }

            let away = simd_normalize(state.position - obstacle)
            updateControlValues({ values in
                values.x += Double(away.x * 1.4)
                values.z += Double(away.z * 1.4)
                values.throttle = max(
                    values.throttle,
                    Double(resolvedFlightBaseline(for: mode).hoverLockThrottle)
                )
            }, markManual: false)
        case .emergencyStop:
            clearCollisionInterventionHold()
            activateEmergencyStop()
        }
    }

    /// Hands the mission back the aircraft the hold borrowed.
    private func resumeAfterCollisionInterventionHold(
        _ suspendedMode: DroneFlightMode,
        reason: String
    ) {
        setFlightMode(suspendedMode, reason: reason)
        clearCollisionInterventionHold()
        // The hold pinned the transition lever to hover; leaving it there would make the aircraft
        // crawl the rest of the leg rotor-borne.
        prepareHybridVTOLAutopilotForForwardRoute()
    }

    private func clearCollisionInterventionHold() {
        collisionInterventionSuspendedMode = nil
        collisionInterventionHoldSeconds = 0.0
        collisionInterventionHoldAltitude = nil
    }

    /// The altitude the intervention is holding, latched on the tick it first takes control and
    /// held until `clearCollisionInterventionHold()`. See `collisionInterventionHoldAltitude`.
    private func latchedCollisionInterventionHoldAltitude() -> Float {
        if let latched = collisionInterventionHoldAltitude, latched.isFinite {
            return latched
        }
        let ceiling = max(2.0, terrain.maxFlightAltitude - 2.0)
        let latched = min(max(state.position.y, homePosition.y + 2.4), ceiling)
        collisionInterventionHoldAltitude = latched
        return latched
    }

    private var isMultirotorMarkerRouteCollisionManagedByPlanner: Bool {
        selectedDroneProfile.airframeClass == .multirotor &&
            mode == .autoPath &&
            targetMarkerState != nil &&
            activeRouteTargetSource != .none
    }

    private func applyResolvedFlightControls(
        deltaTime: Float,
        controlState: ResolvedControlState
    ) {
        guard canControlLocalVehicle, !isControlLinkFailsafeActive else { return }

        // hybridVTOL transition lever: a raw held-key input, not routed through
        // the assist/marker-guidance pipeline below (keyboard-only this pass;
        // ignored entirely by non-hybridVTOL physics).
        controlValues.vtolTransitionLever = Double(keyboardInputService.currentVTOLTransitionLever())

        // P2P 0.7: existing DroneState represents the local pilot vehicle only
        // until multi-state network physics is introduced.
        let inputState = buildFlightInputState(from: controlState)
        let routingContext = buildFlightControlRoutingContext()
        let route = flightControlRouter.route(
            inputState: inputState,
            context: routingContext,
            deltaTime: deltaTime
        )
        flightControlDiagnostics = flightControlRouter.diagnostics(
            authority: route.authority,
            inputState: inputState,
            context: routingContext
        )
        let effectiveControlMode = resolvedFlightControlMode(for: route.authority)

        let maxAltitude = Double(terrain.maxFlightAltitude)
        let effectiveAxis = route.axisInput
        let tailsitterHoverControlsActive = selectedDroneProfile.airframeStyle == .tailsitterVTOL &&
            state.vtolTransitionProgress < 0.25
        let tailsitterHoverTurnIntent = tailsitterHoverControlsActive ? -effectiveAxis.strafe : 0.0
        manualYawIntent = (route.yawInput.intent + tailsitterHoverTurnIntent).clamped(to: -1.0...1.0) *
            (route.yawInput.speedBoost ? 1.35 : 1.0)

        let hasEffectiveYawInput = abs(manualYawIntent) > 0.001
        let hasEffectiveInput =
            abs(effectiveAxis.forward) > 0.001 ||
            abs(effectiveAxis.strafe) > 0.001 ||
            abs(effectiveAxis.vertical) > 0.001 ||
            hasEffectiveYawInput
        let hasVTOLTransitionInput = abs(controlValues.vtolTransitionLever) > 0.05
        // A hand on the sticks is what "the operator is flying" means — and nothing on this path
        // ever said so.
        //
        // `lastOperatorInputAt` was written in exactly one place: `updateControlValues(markManual:
        // true)`, reached only from the UI setter API (`setX`, `setRoll`, `setThrottle`, …). Live
        // flying does not go through those; it arrives here, as resolved axis input, every tick. So
        // `operatorIsOnTheControls` stayed false for the entire duration of a manual flight, and the
        // proximity net's one exemption — "while the operator is actually on the controls the
        // aircraft is theirs and the net stays out of the way" — never fired for an actual pilot.
        // A DJI Matrice flown by hand near trees was taken into `collision_intervention_hover`
        // again and again while the operator was holding the stick.
        //
        // The test is the same `> 0.001` deflection the line above already uses to decide the
        // operator is commanding something; no new threshold, and the 1.5 s grace is unchanged.
        // Authority is deliberately *not* part of it: a stick that moves is a human regardless of
        // what the router currently thinks is steering, and that is precisely the case where the
        // aircraft has to be handed back.
        if hasEffectiveInput || hasVTOLTransitionInput {
            lastOperatorInputAt = Date()
        }
        let shouldExitHoverForManualAuthority = selectedDroneProfile.airframeStyle == .tailsitterVTOL
            ? (hasEffectiveInput || hasVTOLTransitionInput)
            : true

        if route.authority == .manual, mode == .hover, shouldExitHoverForManualAuthority {
            setFlightMode(.manual, reason: "manual_input_exit_hover")
        }

        if route.shouldCancelMarkerGuidance {
            cancelTargetMarkerAutoNavigation()
            if mode == .autoPath {
                setFlightMode(.manual, reason: "marker_guidance_cancelled")
            }
        }

        if route.shouldAttemptMarkerGuidance,
           selectedDroneProfile.airframeClass == .multirotor {
            _ = applyMultirotorTargetMarkerGuidance(deltaTime: deltaTime)
            return
        }

        if selectedDroneProfile.airframeClass == .fixedWing || selectedDroneProfile.airframeClass == .hybridVTOL {
            fixedWingAssistUsesTargetYawWhileManual = false

            if route.authority == .markerGuidance,
               targetMarkerState != nil {
                if selectedDroneProfile.airframeClass == .hybridVTOL,
                   activeRouteTargetSource != .mission,
                   hybridVTOLMarkerGuidanceReachedTarget() {
                    finishTargetMarkerAutoNavigation()
                    return
                }
                if let output = applyFixedWingMarkerGuidance(deltaTime: deltaTime),
                   output.hasCompletedRoute,
                   activeRouteTargetSource != .mission {
                    finishTargetMarkerAutoNavigation()
                }
                if selectedDroneProfile.airframeClass == .hybridVTOL,
                   activeRouteTargetSource != .mission,
                   hybridVTOLMarkerGuidanceReachedTarget() {
                    finishTargetMarkerAutoNavigation()
                }
                return
            }

            let wing = selectedDroneProfile.fixedWingParameters ?? FixedWingParameters(
                family: .conventionalSurvey,
                minSustainableSpeedMps: 10.0,
                cruiseSpeedMps: 17.0,
                climbSpeedMps: 13.0,
                stallWarningSpeedMps: 9.0,
                waypointAcceptanceRadiusMeters: 9.0,
                nominalTurnRateDegPerSec: 9.0,
                bankResponseGain: 0.72,
                climbResponseGain: 0.64,
                descentResponseGain: 0.54,
                dragFactor: 1.0,
                throttleResponseGain: 0.64,
                turnAuthority: 0.64,
                maxBankAngleDeg: 38.0
            )
            let currentHorizontalSpeed = simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
            let speedRatioUpperBound: Float = selectedDroneProfile.airframeStyle == .tailsitterVTOL ? 1.0 : 1.35
            let speedRatio = (currentHorizontalSpeed / max(wing.cruiseSpeedMps, 0.1)).clamped(to: 0.55...speedRatioUpperBound)
            let speedRatioDouble = Double(speedRatio)
            // Stall-recovery throttle bias assumes low horizontal speed means
            // "about to stall, add power" — true for a conventional fixed-wing
            // aircraft, but a hybridVTOL hovering (or a tailsitter sitting
            // nose-up) is *supposed* to read near-zero horizontal speed while
            // perfectly safe, rotor/hover-borne. Without gating, this fought
            // the pilot's own throttle-down input every tick (Q barely moved
            // the number, any other key let it climb back) and the resulting
            // thrust fighting its own correction is what read as continuous
            // shake. Scale by how much of the weight the wing is actually
            // carrying (0 in hover, 1 once genuinely wing-borne) — unchanged
            // for conventional fixedWing, which doesn't populate this field
            // and always reads 1.0 here.
            let wingBorneFraction: Double = selectedDroneProfile.airframeClass == .hybridVTOL
                ? Double(state.vtolWingborneBlend)
                : 1.0
            //
            // Two more things it must not do, both found the same way — an operator
            // holding Q and watching the number go up.
            //
            // It must not run **on the ground**: a takeoff roll is below the stall
            // warning speed for its entire length, by definition, and an aeroplane
            // with its weight on its wheels is not about to stall. On the MQ-9B the
            // bias came to +0.30 per second against the 0.156 the throttle key
            // commands, so the pilot could not close the throttle at all below
            // 29 m/s — and above it he could, which is why the same key sometimes
            // added power and sometimes took it away.
            //
            // And it must not fight an **explicit** throttle-down command anywhere.
            // A protection that quietly overrules the stick, with nothing on the
            // HUD to say so, is indistinguishable from a broken control. Hands off
            // the throttle it still works exactly as before, which is when it is
            // actually protecting anything.
            let heightAboveSupport = state.position.y - supportSurfaceY(for: state.position)
            let pilotClosingThrottle = effectiveAxis.vertical < -0.001
            let stallProtectionApplies = heightAboveSupport > 0.5 && !pilotClosingThrottle
            let stallBias = stallProtectionApplies
                ? Double(max(0.0, wing.stallWarningSpeedMps - currentHorizontalSpeed))
                    * 0.018 * Double(deltaTime) * wingBorneFraction
                : 0.0
            let rollGain = Double((effectiveControlMode == .acro ? 58.0 : 30.0) * wing.bankResponseGain) * speedRatioDouble
            let pitchAuthority = Double(effectiveControlMode == .acro ? 50.0 : 24.0)
            let pitchResponseGain = Double(effectiveAxis.forward < 0.0 ? wing.climbResponseGain : wing.descentResponseGain)
            let pitchGain = pitchAuthority * pitchResponseGain * Double(max(0.74, speedRatio))
            let rollLimit = Double(wing.maxBankAngleDeg)
            let pitchLimit = 28.0
            let throttleDelta = Double(effectiveAxis.vertical) * Double((effectiveAxis.speedBoost ? 0.54 : 0.30) * wing.throttleResponseGain) * Double(deltaTime)
            let rollCommand = tailsitterHoverControlsActive
                ? 0.0
                : (-Double(effectiveAxis.strafe) * rollGain).clamped(to: -rollLimit...rollLimit)
            let pitchCommand = (-Double(effectiveAxis.forward) * pitchGain).clamped(to: -pitchLimit...pitchLimit)
            let manualThrottle = (controlValues.throttle + throttleDelta + stallBias).clamped(to: 0.0...1.0)
            let liveTurnOverride = (!tailsitterHoverControlsActive && abs(effectiveAxis.strafe) > 0.001) || hasEffectiveYawInput
            let liveAltitudeOverride = abs(effectiveAxis.forward) > 0.001 || abs(effectiveAxis.vertical) > 0.001

            // Captured unconditionally (not just in the manual/assist branches
            // below) so the assisted launch corridor can read live stick
            // input even while `mode == .takeoff` still owns `controlValues`.
            fixedWingManualRollCommandDegrees = Float(rollCommand)
            fixedWingManualTurnInputActive = liveTurnOverride

            if liveTurnOverride {
                registerFixedWingAssistOverride(.turn)
            }
            if liveAltitudeOverride {
                registerFixedWingAssistOverride(.altitude)
            }

            let turnOverrideActive = liveTurnOverride || fixedWingAssistTurnOverrideTimeRemaining > 0.0
            let altitudeOverrideActive = liveAltitudeOverride || fixedWingAssistAltitudeOverrideTimeRemaining > 0.0

            if fixedWingAssistState.mode != .manual, mode == .manual {
                setFixedWingGuidanceSource(.none, reason: "fixed_wing_assist_active")
                let assistWaypoint = resolvedFixedWingAssistWaypoint()
                if fixedWingAssistState.mode == .waypointIntercept,
                   let assistWaypoint {
                    let cruise = fixedWingAssistCruiseAltitude(
                        waypointID: assistWaypoint.id,
                        goal: assistWaypoint.position
                    )
                    fixedWingAssistState.targetAltitudeMeters = max(
                        fixedWingAssistState.targetAltitudeMeters ?? 0.0,
                        cruise
                    )
                }
                let climbOutActive = !altitudeOverrideActive
                    && fixedWingAssistState.mode == .waypointIntercept
                    && updateFixedWingAssistClimbOut(wing: wing)
                let guidanceSnapshot = fixedWingAssistState.mode == .waypointIntercept
                    ? fixedWingAssistFlyByGuidanceSnapshot(wing: wing)
                    : nil
                let assistDebugLeg = (
                    start: guidanceSnapshot?.currentLegStart ?? fixedWingAssistSelectedRouteLeg().start,
                    end: guidanceSnapshot?.currentLegEnd ?? fixedWingAssistSelectedRouteLeg().end
                )
                let interceptTarget = guidanceSnapshot?.guidanceTarget ?? assistWaypoint?.position
                let captureTarget = guidanceSnapshot?.captureTarget ?? assistWaypoint?.position

                if let assistOutput = fixedWingAssistController.update(
                    assistState: fixedWingAssistState,
                    aircraftState: state,
                    wing: wing,
                    baseline: resolvedFlightBaseline(for: .manual),
                    currentControls: controlValues,
                    interceptTarget: interceptTarget,
                    captureTarget: captureTarget,
                    interceptDebugContext: FixedWingAssistInterceptDebugContext(
                        activeTargetSource: fixedWingAssistInterceptDebugSource(),
                        segmentCountAfterValidation: fixedWingValidatedMissionSegmentCount(),
                        activeRouteIncludesHome: fixedWingAssistActiveRouteIncludesHome(),
                        selectedWaypointID: assistWaypoint?.id,
                        guidanceTargetType: guidanceSnapshot?.guidanceMode ?? "selected_waypoint",
                        guidanceTargetPoint: interceptTarget,
                        currentLegStart: assistDebugLeg.start,
                        currentLegEnd: assistDebugLeg.end
                    ),
                    turnOverrideActive: turnOverrideActive,
                    altitudeOverrideActive: altitudeOverrideActive,
                    heightAboveSurfaceMeters: heightAboveSupportSurface(for: state.position)
                ) {
                    let previousAssistState = fixedWingAssistState
                    let captureTransitionOccurred = !previousAssistState.interceptCompleted && assistOutput.state.interceptCompleted
                    fixedWingAssistState = assistOutput.state
                    // Reported on one tick only — record it or it is gone.
                    if captureTransitionOccurred,
                       assistOutput.state.captureCompletedReason == "emergency_abeam_pass",
                       let missedID = assistOutput.state.selectedWaypointID,
                       let miss = assistOutput.state.lastWaypointMissDistanceMeters,
                       let passPoint = assistOutput.state.lastWaypointPassPosition {
                        emergencyWaypointPasses.append(EmergencyWaypointPass(
                            id: missedID,
                            position: passPoint,
                            missMeters: miss
                        ))
                        #if DEBUG
                        print(String(
                            format: "[Orbit] emergency abeam pass: waypoint missed by %.0f m after a full orbit",
                            Double(miss)
                        ))
                        #endif
                    }
                    applyFixedWingAssistFlyBySnapshot(guidanceSnapshot, to: &fixedWingAssistState)
                    syncFixedWingAssistSelection()

                    if !previousAssistState.interceptCompleted,
                       fixedWingAssistState.interceptCompleted,
                       let completedWaypointID = fixedWingAssistState.selectedWaypointID,
                       !fixedWingAssistState.capturedWaypointIDs.contains(completedWaypointID) {
                        fixedWingAssistState.capturedWaypointIDs.append(completedWaypointID)
                    }
                    var waypointChanged = false
                    if captureTransitionOccurred {
                        fixedWingCaptureHoldStartedAt = nil
                        waypointChanged = handleFixedWingAssistCaptureCompletion()
                    } else if fixedWingAssistIsHoldingForOutboundProof {
                        waypointChanged = retryFixedWingCaptureHoldIfDue()
                    } else if fixedWingAssistState.interceptCompleted {
                        // Deliberately does *not* clear `fixedWingCaptureHoldStartedAt`. Clearing
                        // it here reset the hold's own clock on every tick — see
                        // `fixedWingAssistIsHoldingForOutboundProof` for why this branch is the
                        // one that runs while the hold is live.
                        waypointChanged = updatePendingFixedWingAutoAdvanceIfNeeded()
                    }
                    if !waypointChanged {
                        refreshFixedWingAssistRuntimeDebugState(
                            precomputedGuidanceSnapshot: guidanceSnapshot,
                            recomputeGuidance: false
                        )
                    }
                    fixedWingAssistUsesTargetYawWhileManual = !turnOverrideActive
                    if let reason = assistOutput.transitionReason,
                       !captureTransitionOccurred {
                        fixedWingLastTransitionReason = reason
                    }

                    let baseDesiredRoll = turnOverrideActive
                        ? (liveTurnOverride ? rollCommand : controlValues.roll)
                        : Double(assistOutput.rollDegrees)
                    let climbOutBankLimit = Double(max(6.0, min(wing.maxInitialBankDeg, 12.0)))
                    let desiredRoll = climbOutActive && !turnOverrideActive
                        ? baseDesiredRoll.clamped(to: -climbOutBankLimit...climbOutBankLimit)
                        : baseDesiredRoll
                    let baseDesiredPitch = altitudeOverrideActive
                        ? (liveAltitudeOverride ? pitchCommand : controlValues.pitch)
                        : Double(assistOutput.pitchDegrees)
                    let desiredPitch = climbOutActive
                        ? max(
                            baseDesiredPitch,
                            Double(min(wing.maxPitchUpDeg, max(wing.initialClimbPitchDeg, 10.0)))
                        )
                        : baseDesiredPitch
                    let baseDesiredThrottle = altitudeOverrideActive
                        ? (liveAltitudeOverride ? manualThrottle : controlValues.throttle)
                        : Double(assistOutput.throttle)
                    let desiredThrottle = climbOutActive
                        ? max(
                            baseDesiredThrottle,
                            Double(max(
                                resolvedFlightBaseline(for: .takeoff).takeoffThrottleReference,
                                wing.maxThrottle * 0.92
                            ))
                        )
                        : baseDesiredThrottle
                    let altitudeTarget = assistOutput.state.mode == .altitudeHold || assistOutput.state.mode == .waypointIntercept
                        ? Double(assistOutput.state.targetAltitudeMeters ?? state.position.y)
                        : Double(state.position.y)

                    let assistOutputStillOwnsControllerState = !waypointChanged
                        && assistOutput.state.mode == fixedWingAssistState.mode
                        && assistOutput.state.selectedWaypointID
                            == fixedWingAssistState.selectedWaypointID
                    if !assistOutputStillOwnsControllerState {
                        // Auto-advance calls `engage`, which resets the controller filters. The
                        // just-returned output belongs to the completed leg and must not seed a
                        // prediction or release for the newly selected waypoint.
                        fixedWingLatestAssistRollCommandDegrees = nil
                        fixedWingLatestAssistCourseCommandRadians = nil
                    } else {
                        let nominalAssistRoll = climbOutActive
                            ? Double(assistOutput.rollDegrees).clamped(
                                to: -climbOutBankLimit...climbOutBankLimit
                            )
                            : Double(assistOutput.rollDegrees)
                        fixedWingLatestAssistRollCommandDegrees = Float(
                            liveTurnOverride ? rollCommand : nominalAssistRoll
                        )
                        fixedWingLatestAssistCourseCommandRadians = turnOverrideActive
                            ? state.orientation.z
                            : assistOutput.yawDegrees.degreesToRadians
                    }

                    // Avoidance owns roll while its hold is live.
                    //
                    // This write is the one that was undoing it. During take-off the assist does
                    // not run, avoidance is the only writer, and its command is smooth and
                    // convergent — +7.9, +5.0, +2.8, +1.9, +1.4. The instant this branch takes
                    // over, the *same* held course (heldCrs pinned at −153°) produces +21.6,
                    // +37.2, −40.0: not the avoidance formula at all, but the assist steering to
                    // its waypoint on top of it. Two writers, last one wins, and the aircraft
                    // weaves between their opinions.
                    // The comment above described the defect; this is the gate that answers it.
                    //
                    // The assist is evaluated before the current tick's avoidance pass so its
                    // hidden filters keep advancing. While an avoidance hold/release from the
                    // previous pass still owns the axes, preserve the live command here; the later
                    // avoidance pass will either refresh it or blend it to the cached nominal
                    // output. This prevents a transient owner swap inside one simulation tick.
                    // Which is why the aeroplane turned "for no reason": the reason was the assist's
                    // own waypoint command, and the layer meant to overrule it never reached the axis.
                    //
                    // Lateral guidance therefore goes to whichever layer currently has an opinion about
                    // survival: avoidance while it holds an escape course, and equally while it
                    // reports no flyable course at all — a refusal is an opinion. Everything else
                    // — pitch, throttle and altitude target — stays with the assist. Yaw belongs
                    // to the same owner as roll so rudder cannot fight an escape bank.
                    //
                    // Ownership must match the branch the avoidance pass will actually take, not
                    // the flag that names the situation. Under launch-climb protection the pass
                    // calls `applyFixedWingCollisionAvoidance` in exactly one case — a *proven
                    // clear* held escape — and deliberately writes nothing in the blocked ones.
                    // Claiming the axis there on the strength of `noSafeTrajectory` left both
                    // layers declining it in the same tick, and `values.roll = values.roll` then
                    // froze the last value written by anybody. Measured in the crash flight:
                    // `rollCmd` pinned at −4.2° for five consecutive samples with `avOwns=no`
                    // and `asstRoll` climbing 4.3 → 10.2 unheard, a left bank held into a
                    // building while the assist and the avoidance probe both asked for right.
                    let avoidanceOwnsLateral: Bool = {
                        // A hand-flown aircraft answers to its pilot. See
                        // `operatorHasFullManualAuthority`.
                        if operatorHasFullManualAuthority { return false }
                        if fixedWingLaunchClimbProtectionActive {
                            return fixedWingAvoidanceHoldRemaining > 0.0
                                && !fixedWingAvoidanceNoSafeTrajectory
                                && fixedWingAvoidanceHoldCourse != nil
                        }
                        return (fixedWingAvoidanceHoldRemaining > 0.0
                                && fixedWingAvoidanceHoldCourse != nil)
                            || fixedWingAvoidanceNoSafeTrajectory
                            || (fixedWingAvoidanceLateralCommandWasActive
                                && fixedWingAvoidanceReleaseCourseRadians != nil)
                    }()
                    updateControlValues({ values in
                        values.throttle = desiredThrottle.clamped(to: 0.0...1.0)
                        values.roll = (avoidanceOwnsLateral ? values.roll : desiredRoll)
                            .clamped(to: -rollLimit...rollLimit)
                        values.pitch = desiredPitch.clamped(to: -pitchLimit...pitchLimit)
                        if !avoidanceOwnsLateral {
                            values.yaw = turnOverrideActive
                                ? Double(state.orientation.z.radiansToDegrees)
                                : Double(assistOutput.yawDegrees)
                        }
                        values.y = altitudeTarget.clamped(to: 0.0...maxAltitude)
                    }, markManual: false)
                    return
                }
            }

            guard hasEffectiveInput else {
                return
            }
            setFixedWingGuidanceSource(.none, reason: "manual_fixed_wing_input")
            updateControlValues({ values in
                values.throttle = manualThrottle
                values.roll = rollCommand
                values.pitch = pitchCommand
                values.yaw = Double(state.orientation.z.radiansToDegrees)
                values.y = state.position.y > 0.05
                    ? Double(state.position.y).clamped(to: 0.0...maxAltitude)
                    : values.y.clamped(to: 0.0...maxAltitude)
            }, markManual: false)
            return
        }

        let climb = effectiveAxis.vertical * (effectiveAxis.speedBoost ? 5.4 : 3.0) * deltaTime
        let pitchScale: Float = effectiveControlMode == .acro ? 52.0 : 28.0
        let rollScale: Float = effectiveControlMode == .acro ? 52.0 : 26.0

        updateControlValues({ values in
            values.y = (values.y + Double(climb)).clamped(to: 0.0...maxAltitude)

            let verticalThrottleDelta = Double(effectiveAxis.vertical) * (effectiveAxis.speedBoost ? 0.40 : 0.26) * Double(deltaTime)
            values.throttle = (values.throttle + verticalThrottleDelta).clamped(to: 0.0...1.0)
            values.yaw = Double(state.orientation.z.radiansToDegrees)

            switch effectiveControlMode {
            case .stabilized, .hoverAssist:
                // W must command forward acceleration for multirotors (nose down => negative pitch in this frame convention).
                values.pitch = Double((-effectiveAxis.forward * pitchScale).clamped(to: -36.0...36.0))
                values.roll = Double((-effectiveAxis.strafe * rollScale).clamped(to: -36.0...36.0))
            case .acro:
                values.pitch = Double((-effectiveAxis.forward * pitchScale).clamped(to: -82.0...82.0))
                values.roll = Double((-effectiveAxis.strafe * rollScale).clamped(to: -82.0...82.0))
            }
        }, markManual: false)
    }

    private func processInputActions(using controlState: ResolvedControlState) {
        // Reset is a meta/administrative command ("give up, start over"), not a flight-control
        // input — it must never be swallowed by signal-loss/failsafe input blocking below, or the
        // player has no way out of a stuck sequence (e.g. a fixed-wing failsafe that can't find
        // ground to land on). Checked and handled unconditionally, before the interaction gate.
        if controlState.actions.contains(.requestReset) {
            reset()
            return
        }

        guard !signalState.isInteractionBlocking, !isControlLinkFailsafeActive else {
            return
        }

        // A real hose sprays only while the trigger is physically held, not "toggle it on and
        // walk away" — tracked every tick from the held-key state, not the one-shot action queue.
        // The agricultural sprayer reuses the same physical trigger; whichever payload is
        // actually mounted reacts, the other no-ops on its own availability guard.
        setHoseSpraying(controlState.isHoseSprayHeld)
        setAgriculturalSprayerSpraying(controlState.isHoseSprayHeld)

        for action in controlState.actions {
            switch action {
            case .requestHover:
                hover()
            case .requestReset:
                reset()
            case .dropPayload:
                releasePayload()
            case .armAircraft:
                arm()
            case .disarmAircraft:
                disarm()
            case .launchAircraft:
                // ⌘E: hand-throw / catapult release for assisted-launch
                // fixed wings. Arms the airframe first if needed, so the
                // whole launch is a single keystroke from the operator view.
                if selectedDroneProfile.airframeClass == .fixedWing,
                   activeLaunchMode().requiresLaunchObject {
                    if !isArmed {
                        arm()
                    }
                    if canInitiateTakeoffCommand {
                        takeoff()
                    }
                }
            case .selectFreeCamera:
                setCameraMode(.free)
            case .selectChaseCamera:
                setCameraMode(.follow)
            case .selectOrbitCamera:
                setCameraMode(.orbit)
            case .selectFPVCamera:
                setCameraMode(.fpv)
            case .selectTopCamera:
                setCameraMode(.top)
            case .selectPayloadOpticsCamera:
                if isMountedHoseAvailable, cameraConfiguration.mode != .payloadOptics {
                    isExternalHoseAimActive.toggle()
                    cameraLookVelocity = .zero
                    payloadGimbalLookVelocity = .zero
                    refreshHoseAimStatus()
                } else {
                    setCameraMode(.payloadOptics)
                }
            case .selectPayloadCamera:
                setCameraMode(.payload)
            case .toggleFPV:
                setCameraMode(cameraConfiguration.mode == .fpv ? .follow : .fpv)
            case .toggleTopView:
                setCameraMode(cameraConfiguration.mode == .top ? .follow : .top)
            case .toggleMissionMap:
                toggleMissionMap()
            case .togglePayloadPanel:
                togglePayloadPanel()
            case .toggleTerrainMap:
                toggleTerrainMap()
            case .toggleCompassOverlay:
                toggleCompassOverlay()
            case .toggleThermalOverlay:
                toggleThermalOverlay()
            case .toggleDamageOverlay:
                toggleDamageOverlay()
            case .selectThermalPaletteWhiteHot:
                activateThermalPalette(.whiteHot)
            case .selectThermalPaletteBlackHot:
                activateThermalPalette(.blackHot)
            case .selectThermalPaletteIron:
                activateThermalPalette(.iron)
            case .toggleRangefinderArmed:
                toggleRangefinderArmed()
            case .cycleCameraMode:
                cycleCameraMode()
            case .toggleControlPanel:
                toggleControlPanel()
            case .toggleToolPanel:
                toggleToolPanel()
            case .toggleTelemetryHUD:
                toggleCompactTelemetryHUD()
            case .zoomInCamera:
                adjustCameraZoom(inward: true)
            case .zoomOutCamera:
                adjustCameraZoom(inward: false)
            case .resetCameraOrientation:
                if isExternalHoseAimActive {
                    resetHoseGimbalOrientation()
                } else {
                    syncCameraSystem(resetOrientation: true)
                }
            case .returnHome:
                activateReturnHome()
            case .pauseMission:
                pauseMissionExecution()
            case .resumeMission:
                resumeMissionExecution()
            case .toggleControllerCursor, .openControllerHub,
                 .uiSectionPrevious, .uiSectionNext,
                 .uiPrimary, .uiSecondary,
                 .uiFocusUp, .uiFocusDown, .uiFocusLeft, .uiFocusRight:
                break
            }
        }
    }

    private func applyContinuousCameraLook(
        deltaTime: Float,
        controlState: ResolvedControlState
    ) {
        guard !signalState.isInteractionBlocking else {
            cameraLookVelocity = .zero
            payloadGimbalLookVelocity = .zero
            return
        }

        let speedMultiplier: Float = controlState.precisionMode ? 0.22 : (controlState.boostMode ? 1.85 : 1.0)
        let inputVelocity = SIMD2<Float>(
            Float(controlState.cameraPan),
            Float(controlState.cameraTilt)
        )
        let hasLookInput = abs(controlState.cameraPan) >= 0.001 || abs(controlState.cameraTilt) >= 0.001

        // External branch-pipe control deliberately takes precedence over normal camera look.
        // The current follow/orbit/free view remains unchanged while the very same continuous
        // arrow-key axes drive the nozzle yaw and pitch.
        if isExternalHoseAimActive,
           isMountedHoseAvailable,
           cameraConfiguration.mode != .payloadOptics {
            let targetVelocity = inputVelocity * (118.0 * speedMultiplier * cameraConfiguration.effectiveLookSensitivity)
            let accelerationBlend = (deltaTime * 10.0).clamped(to: 0.0...1.0)
            payloadGimbalLookVelocity = simd_mix(
                payloadGimbalLookVelocity,
                targetVelocity,
                SIMD2<Float>(repeating: accelerationBlend)
            )

            if !hasLookInput {
                let damping = max(0.0, 1.0 - deltaTime * 8.5)
                payloadGimbalLookVelocity *= damping
                if simd_length_squared(payloadGimbalLookVelocity) < 0.0001 {
                    payloadGimbalLookVelocity = .zero
                }
            }

            cameraLookVelocity = .zero
            guard simd_length_squared(payloadGimbalLookVelocity) > 0.0 else {
                return
            }
            let yawSign: Float = cameraConfiguration.invertLookX ? -1.0 : 1.0
            let pitchSign: Float = cameraConfiguration.invertLookY ? -1.0 : 1.0
            adjustHoseGimbal(
                yawDeltaDegrees: Double(payloadGimbalLookVelocity.x * deltaTime * yawSign),
                pitchDeltaDegrees: Double(payloadGimbalLookVelocity.y * deltaTime * pitchSign)
            )
            return
        }

        if isHandLaunchPOVActive {
            let targetVelocity = inputVelocity * (92.0 * speedMultiplier * cameraConfiguration.effectiveLookSensitivity)
            let accelerationBlend = (deltaTime * 12.0).clamped(to: 0.0...1.0)
            cameraLookVelocity = simd_mix(
                cameraLookVelocity,
                targetVelocity,
                SIMD2<Float>(repeating: accelerationBlend)
            )
            if !hasLookInput {
                let damping = max(0.0, 1.0 - deltaTime * 9.0)
                cameraLookVelocity *= damping
                if simd_length_squared(cameraLookVelocity) < 0.0001 {
                    cameraLookVelocity = .zero
                }
            }
            payloadGimbalLookVelocity = .zero
            guard simd_length_squared(cameraLookVelocity) > 0.0 else {
                return
            }
            sceneController.applyHandLaunchPOVLook(
                yawDeltaDeg: cameraLookVelocity.x * deltaTime,
                pitchDeltaDeg: cameraLookVelocity.y * deltaTime,
                invertX: cameraConfiguration.invertLookX,
                invertY: cameraConfiguration.invertLookY
            )
            return
        }

        switch cameraConfiguration.mode {
        case .fpv:
            let targetVelocity = inputVelocity * (92.0 * speedMultiplier * cameraConfiguration.effectiveLookSensitivity)
            let accelerationBlend = (deltaTime * 12.0).clamped(to: 0.0...1.0)
            cameraLookVelocity = simd_mix(
                cameraLookVelocity,
                targetVelocity,
                SIMD2<Float>(repeating: accelerationBlend)
            )

            if !hasLookInput {
                let damping = max(0.0, 1.0 - deltaTime * 9.0)
                cameraLookVelocity *= damping
                if simd_length_squared(cameraLookVelocity) < 0.0001 {
                    cameraLookVelocity = .zero
                }
            }

            payloadGimbalLookVelocity = .zero
            guard simd_length_squared(cameraLookVelocity) > 0.0 else {
                return
            }

            sceneController.applyCameraNudge(
                mode: cameraConfiguration.mode,
                yawDeltaDeg: cameraLookVelocity.x * deltaTime,
                pitchDeltaDeg: cameraLookVelocity.y * deltaTime,
                invertX: cameraConfiguration.invertLookX,
                invertY: cameraConfiguration.invertLookY
            )
            return
        case .payloadOptics:
            let targetVelocity = inputVelocity * (118.0 * speedMultiplier * cameraConfiguration.effectiveLookSensitivity)
            let accelerationBlend = (deltaTime * 10.0).clamped(to: 0.0...1.0)
            payloadGimbalLookVelocity = simd_mix(
                payloadGimbalLookVelocity,
                targetVelocity,
                SIMD2<Float>(repeating: accelerationBlend)
            )

            if !hasLookInput {
                let damping = max(0.0, 1.0 - deltaTime * 8.5)
                payloadGimbalLookVelocity *= damping
                if simd_length_squared(payloadGimbalLookVelocity) < 0.0001 {
                    payloadGimbalLookVelocity = .zero
                }
            }

            cameraLookVelocity = .zero
            guard simd_length_squared(payloadGimbalLookVelocity) > 0.0 else {
                return
            }

            let yawSign: Float = cameraConfiguration.invertLookX ? -1.0 : 1.0
            let pitchSign: Float = cameraConfiguration.invertLookY ? -1.0 : 1.0
            if payloadCameraOpticsState.isAvailable {
                adjustPayloadGimbal(
                    yawDeltaDegrees: Double(payloadGimbalLookVelocity.x * deltaTime * yawSign),
                    pitchDeltaDegrees: Double(payloadGimbalLookVelocity.y * deltaTime * pitchSign)
                )
            } else if rangefinderOpticsState.isAvailable {
                adjustRangefinderGimbal(
                    yawDeltaDegrees: Double(payloadGimbalLookVelocity.x * deltaTime * yawSign),
                    pitchDeltaDegrees: Double(payloadGimbalLookVelocity.y * deltaTime * pitchSign)
                )
            } else if lidarOpticsState.isAvailable {
                // Arrow keys aim the LiDAR sensor gimbal in its camera view — the scan fan follows.
                adjustLidarGimbal(
                    yawDeltaDegrees: Double(payloadGimbalLookVelocity.x * deltaTime * yawSign),
                    pitchDeltaDegrees: Double(payloadGimbalLookVelocity.y * deltaTime * pitchSign)
                )
            } else {
                adjustHoseGimbal(
                    yawDeltaDegrees: Double(payloadGimbalLookVelocity.x * deltaTime * yawSign),
                    pitchDeltaDegrees: Double(payloadGimbalLookVelocity.y * deltaTime * pitchSign)
                )
            }
            return
        case .free, .follow, .orbit, .top, .payload, .spectator:
            cameraLookVelocity = .zero
            payloadGimbalLookVelocity = .zero
            return
        }
    }

    private func nudgeCamera(yawDeg: Float, pitchDeg: Float) {
        sceneController.applyCameraNudge(
            mode: cameraConfiguration.mode,
            yawDeltaDeg: yawDeg * cameraConfiguration.effectiveLookSensitivity,
            pitchDeltaDeg: pitchDeg * cameraConfiguration.effectiveLookSensitivity,
            invertX: cameraConfiguration.invertLookX,
            invertY: cameraConfiguration.invertLookY
        )
    }

    private func syncCameraSystem(from previousMode: CameraMode? = nil, resetOrientation: Bool = false) {
        if let previousMode {
            sceneController.syncCameraTransition(from: previousMode, to: cameraConfiguration.mode)
        }

        if resetOrientation {
            if cameraConfiguration.mode == .payloadOptics {
                resetPayloadGimbalOrientation()
                resetRangefinderGimbalOrientation()
            }
            sceneController.resetCameraOrientation(for: cameraConfiguration.mode)
        }

        sceneController.update(
            with: state,
            camera: cameraConfiguration,
            damage: damageState,
            thermal: thermalState,
            diagnosticMode: diagnosticMode,
            deltaTime: 0.0
        )
    }

    private func applyContinuousCameraZoom(deltaTime: Float) {
        let keyboardSnapshot = keyboardInputService.currentInputSnapshot()
        let zoomInActive = keyboardSnapshot.activeContinuousCommands.contains(.zoomIn)
        let zoomOutActive = keyboardSnapshot.activeContinuousCommands.contains(.zoomOut)
        guard zoomInActive != zoomOutActive else {
            return
        }

        let zoomDirection: Double = zoomInActive ? 1.0 : -1.0
        let speedMultiplier: Double = keyboardSnapshot.axisInput.speedBoost || keyboardSnapshot.yawInput.speedBoost || keyboardSnapshot.lookInput.speedBoost
            ? 1.8
            : 1.0

        switch cameraConfiguration.mode {
        case .payloadOptics:
            let zoomUnitsPerSecond = 8.5 * speedMultiplier
            if payloadCameraOpticsState.isAvailable {
                setPayloadZoom(payloadCameraOpticsState.zoomLevel + zoomDirection * Double(deltaTime) * zoomUnitsPerSecond)
            } else if rangefinderOpticsState.isAvailable {
                setRangefinderZoom(rangefinderOpticsState.zoomLevel + zoomDirection * Double(deltaTime) * zoomUnitsPerSecond)
            }
        case .free:
            let zoomStep = 6.5 * speedMultiplier * Double(deltaTime) * Double(cameraConfiguration.free.zoomSensitivity)
            cameraConfiguration.free.distance = (cameraConfiguration.free.distance - Float(zoomDirection * zoomStep))
                .clamped(to: cameraConfiguration.free.minDistance...cameraConfiguration.free.maxDistance)
            sceneController.dollyFreeCamera(by: Float(-zoomDirection * zoomStep))
        case .follow, .orbit:
            let zoomStep = 6.5 * speedMultiplier * Double(deltaTime) * Double(cameraConfiguration.free.zoomSensitivity)
            let prospectiveDistance = cameraConfiguration.cameraDistance - Float(zoomDirection * zoomStep)
            if zoomInActive, prospectiveDistance <= fpvAutoEngageDistance(for: cameraConfiguration.mode) {
                engageFPVFromZoom()
            } else {
                cameraConfiguration.setCameraDistance(prospectiveDistance)
            }
        case .top:
            let zoomStep = 6.5 * speedMultiplier * Double(deltaTime) * Double(cameraConfiguration.free.zoomSensitivity)
            cameraConfiguration.setCameraDistance(
                cameraConfiguration.cameraDistance - Float(zoomDirection * zoomStep)
            )
        case .fpv:
            let fovDelta = Float(zoomDirection * 24.0 * speedMultiplier * Double(deltaTime))
            let prospectiveFov = cameraConfiguration.fov - fovDelta
            if fpvEnteredViaZoomEngage, zoomOutActive, cameraConfiguration.fov >= 109.5, prospectiveFov >= 110.0 {
                exitFPVFromZoom()
            } else {
                cameraConfiguration.fov = prospectiveFov.clamped(to: 30.0...110.0)
            }
        case .payload, .spectator:
            return
        }
    }

    /// How close the chase/orbit camera gets before handing off to FPV — mirrors
    /// `DroneSceneController.updateCameras`'s `chaseDistanceRange`/`orbitDistanceRange` lower
    /// bound exactly (both now a small fraction of the airframe's own size, not a "comfortable
    /// viewing distance"), so holding zoom in actually carries the camera visually into the
    /// airframe — passing through it — right up to the point FPV takes over, rather than
    /// stalling at an earlier, still-external distance and cutting to FPV from there.
    private func fpvAutoEngageDistance(for mode: CameraMode) -> Float {
        let dims = selectedDroneProfile.dimensions
        let subjectScale = max(selectedDroneProfile.collisionRadius * 2.0, max(dims.widthM, dims.lengthM))
        let isFixedWing = selectedDroneProfile.airframeClass == .fixedWing
        return isFixedWing ? max(0.15, subjectScale * 0.16) : max(0.10, subjectScale * 0.14)
    }

    /// Holding zoom-in past the chase camera's closest point hands off to FPV instead of just
    /// sitting at the floor — "keep pressing + until you're inside the aircraft."
    private func engageFPVFromZoom() {
        guard cameraConfiguration.mode != .fpv else { return }
        let previousMode = cameraConfiguration.mode
        lastDistanceCameraMode = previousMode
        fpvEnteredViaZoomEngage = true
        cameraConfiguration.mode = .fpv
        syncCameraSystem(from: previousMode)
        sceneController.beginCameraTransition(from: previousMode)
    }

    /// Mirror of `engageFPVFromZoom`: holding zoom-out past FPV's own widest field of view
    /// leaves FPV for whichever chase/orbit mode it was entered from, picking back up exactly at
    /// the distance it left off at so the reverse transition reads as continuous too.
    private func exitFPVFromZoom() {
        guard cameraConfiguration.mode == .fpv else { return }
        let previousMode = cameraConfiguration.mode
        let targetMode = lastDistanceCameraMode
        fpvEnteredViaZoomEngage = false
        cameraConfiguration.mode = targetMode
        cameraConfiguration.setCameraDistance(fpvAutoEngageDistance(for: targetMode))
        syncCameraSystem(from: previousMode)
        sceneController.beginCameraTransition(from: previousMode)
    }

    private func adjustCameraZoom(inward: Bool) {
        let sign: Float = inward ? -1.0 : 1.0
        let zoomStep = 0.9 * cameraConfiguration.free.zoomSensitivity

        switch cameraConfiguration.mode {
        case .free:
            cameraConfiguration.free.distance = (cameraConfiguration.free.distance + sign * zoomStep)
                .clamped(to: cameraConfiguration.free.minDistance...cameraConfiguration.free.maxDistance)
            sceneController.dollyFreeCamera(by: sign * zoomStep)
        case .follow, .orbit:
            let prospectiveDistance = cameraConfiguration.cameraDistance + sign * zoomStep
            if inward, prospectiveDistance <= fpvAutoEngageDistance(for: cameraConfiguration.mode) {
                engageFPVFromZoom()
            } else {
                cameraConfiguration.setCameraDistance(prospectiveDistance)
            }
        case .top:
            cameraConfiguration.setCameraDistance(cameraConfiguration.cameraDistance + sign * zoomStep)
        case .fpv:
            let prospectiveFov = cameraConfiguration.fov + sign * 1.2
            if fpvEnteredViaZoomEngage, !inward, cameraConfiguration.fov >= 109.5, prospectiveFov >= 110.0 {
                exitFPVFromZoom()
            } else {
                cameraConfiguration.fov = prospectiveFov.clamped(to: 30.0...110.0)
            }
        case .payloadOptics:
            let delta = inward ? 0.5 : -0.5
            if payloadCameraOpticsState.isAvailable {
                setPayloadZoom(payloadCameraOpticsState.zoomLevel + delta)
            } else if rangefinderOpticsState.isAvailable {
                setRangefinderZoom(rangefinderOpticsState.zoomLevel + delta)
            }
        case .payload:
            return
        case .spectator:
            return
        }
    }

    private func updateAutopilotTargets(deltaTime: Float) {
        if !fixedWingAutonomousRouteExecutionEnabled {
            switch mode {
            case .autoPath, .returnHome:
                disengageFixedWingAutonomousRouteExecution(
                    reason: "fixed_wing_autonomous_route_execution_disabled"
                )
                return
            case .manual, .hover, .emergencyStop, .takeoff, .landing:
                break
            }
        }

        switch mode {
        case .autoPath:
            if targetMarkerState == nil {
                updateAutoFlightPath(deltaTime: deltaTime)
            }

        case .returnHome:
            updateReturnHomePath(deltaTime: deltaTime)

        case .hover:
            navigationSnapshot = .idle
            let hoverBaseline = Double(resolvedFlightBaseline(for: .hover).hoverLockThrottle)
            updateControlValues({ values in
                values.roll = 0.0
                values.pitch = 0.0
                let throttleTarget = hoverBaseline.clamped(to: 0.0...1.0)
                values.throttle = values.throttle + (throttleTarget - values.throttle) * 0.18
                if selectedDroneProfile.airframeClass == .hybridVTOL {
                    values.vtolTransitionLever = state.vtolTransitionProgress > 0.04 ? -1.0 : 0.0
                }
            }, markManual: false)

        case .emergencyStop:
            navigationSnapshot = .idle
            updateControlValues({ values in
                values.x = Double(state.position.x)
                values.y = max(0.0, Double(state.position.y - 0.02))
                values.z = Double(state.position.z)
                values.roll = 0.0
                values.pitch = 0.0
                values.throttle = max(0.0, values.throttle - 0.02)
            }, markManual: false)

        case .manual, .takeoff, .landing:
            navigationSnapshot = .idle
            if mode == .takeoff {
                updateFixedWingLaunchSequence(deltaTime: deltaTime)
            } else if mode == .landing {
                updateHybridVTOLLandingCommand(deltaTime: deltaTime)
            }
        }
    }

    private func applyMultirotorTargetMarkerGuidance(deltaTime: Float) -> Bool {
        guard let marker = targetMarkerState else {
            navigationSnapshot = .idle
            return false
        }

        guard canStartTargetMarkerAutoNavigation else {
            cancelTargetMarkerAutoNavigation()
            navigationSnapshot = .idle
            if mode == .autoPath {
                setFlightMode(.manual, reason: "marker_auto_navigation_unavailable")
            }
            return false
        }

        let travelAltitude = targetMarkerTravelAltitude()
        let approachGoal = safeMarkerApproachGoal(marker: marker, altitude: travelAltitude)
        guard let pathTarget = prepareMultirotorMarkerPath(
            marker: marker,
            approachGoal: approachGoal,
            travelAltitude: travelAltitude,
            deltaTime: deltaTime
        ) else {
            return false
        }

        if shouldFinishMultirotorMarkerGuidance(marker: marker, approachGoal: approachGoal) {
            navigationSnapshot = .idle
            finishTargetMarkerAutoNavigation()
            return true
        }

        autoNavigationController.cancel()
        let finalGoal = approachGoal

        // Close in, do not climb over.
        //
        // Once the aircraft is on final approach, the vertical channel is pinned to the altitude it
        // arrived at (it may still come *down* toward the leg altitude, never up). A point on a
        // façade is reached by standing off from it, not by gaining height until something lines
        // up — and gaining height was exactly what the aircraft did, metre after metre, for as long
        // as the goal stayed out of reach.
        let planarToGoal = simd_distance(
            SIMD2<Float>(finalGoal.x, finalGoal.z),
            currentPlanarPosition()
        )
        let commandedAltitude = planarToGoal <= multirotorMarkerFinalApproachDistance()
            ? min(travelAltitude, state.position.y + 0.3)
            : travelAltitude

        let adjustedTarget = multirotorCollisionAvoidanceTarget(
            nominalTarget: pathTarget,
            finalGoal: finalGoal,
            travelAltitude: commandedAltitude
        ) ?? pathTarget
        let isAvoidingObstacle = simd_distance(
            SIMD2<Float>(adjustedTarget.x, adjustedTarget.z),
            SIMD2<Float>(pathTarget.x, pathTarget.z)
        ) > 0.05
        applyAutopilotTrackingControl(
            target: SIMD3<Float>(adjustedTarget.x, commandedAltitude, adjustedTarget.z),
            targetAltitude: commandedAltitude,
            speedScale: isAvoidingObstacle
                ? min(multirotorMarkerSpeedScale(), 0.72)
                : multirotorMarkerSpeedScale(),
            yawAlignToHome: false,
            deltaTime: deltaTime
        )

        #if DEBUG
        // Everything the vertical channel and the route depend on, once a second. "It climbs" has
        // now had three different causes; this prints which one is speaking rather than inviting a
        // fourth guess.
        if simulationTickCounter % 60 == 0 {
            print(String(
                format: "[Leg] y=%.1f cmdY=%.1f travel=%.1f goal=(%.1f,%.1f) planarToGoal=%.1f "
                    + "avoid=%@ src=%@ plan=%@/%@ wp=%d",
                state.position.y,
                commandedAltitude,
                travelAltitude,
                finalGoal.x, finalGoal.z,
                planarToGoal,
                isAvoidingObstacle ? "yes" : "no",
                String(describing: activeRouteTargetSource),
                String(describing: navigationSnapshot.status),
                navigationSnapshot.reason,
                navigationSnapshot.waypoints.count
            ))
        }
        #endif
        return true
    }

    /// What the aircraft does when the planner has no route to the marker: hold *this* spot.
    ///
    /// The previous hold wrote raw control values — `values.throttle = max(values.throttle, hover)`
    /// and `values.y = max(state.position.y, …)`. Neither is a hold. In `.autoPath` the engine
    /// closes no altitude loop (`SimpleDronePhysicsEngine` does that only for `.hover` /
    /// `hoverAssist`), so the floor kept whatever climb throttle the previous tick had commanded,
    /// and the commanded altitude then followed the aircraft upward — the two ratcheting against
    /// each other. To the pilot that reads as "the autopilot only ever climbs", with no hint that
    /// route planning is what failed. Now the aircraft holds the altitude it had when the hold
    /// began, flown by the same multicopter autopilot as every other leg — which already holds
    /// position when the target sits under it.
    private func holdMultirotorMarkerGuidance(travelAltitude: Float, deltaTime: Float) {
        let ceiling = max(2.0, terrain.maxFlightAltitude - 2.0)
        let holdAltitude = multirotorMarkerHoldAltitude
            ?? min(max(state.position.y, min(travelAltitude, ceiling)), ceiling)
        multirotorMarkerHoldAltitude = holdAltitude

        applyAutopilotTrackingControl(
            target: SIMD3<Float>(state.position.x, holdAltitude, state.position.z),
            targetAltitude: holdAltitude,
            speedScale: 0.0,
            yawAlignToHome: false,
            deltaTime: deltaTime
        )

        #if DEBUG
        if simulationTickCounter % 120 == 0 {
            print("[Route] no path to marker — holding at \(String(format: "%.1f", holdAltitude)) m "
                  + "(planner: \(navigationSnapshot.status)/\(navigationSnapshot.reason), grid "
                  + "\(String(format: "%.1f", autoPathPlanner.lastGridBlockedFraction * 100))% blocked "
                  + "at \(String(format: "%.2f", autoPathPlanner.lastGridCellSize)) m)")
        }
        #endif
    }

    private func prepareMultirotorMarkerPath(
        marker: TargetMarkerState,
        approachGoal: SIMD3<Float>,
        travelAltitude: Float,
        deltaTime: Float
    ) -> SIMD3<Float>? {
        let finalGoal = approachGoal
        autoPathPlanner.updateProgress(
            currentPosition: state.position,
            arrivalRadius: 1.35,
            planarOnly: true
        )

        var replanReason = autoPathPlanner.replanReasonIfNeeded(
            currentPosition: state.position,
            collisionRisk: collisionAnalysis.riskScore,
            deviationTolerance: max(2.2, terrain.worldHalfExtent * 0.025)
        )
        if replanReason == nil,
           collisionAnalysis.riskScore >= 0.42 {
            replanReason = "route_collision_risk"
        }

        if let replanReason,
           shouldRefreshMultirotorMarkerPath(for: replanReason) {
            autoPathPlanner.planIfNeeded(
                start: state.position,
                goal: finalGoal,
                terrain: terrain,
                obstacles: navigationObstaclesIncludingNoFlyZones(),
                obstacleSignature: navigationObstacleSignatureIncludingNoFlyZones(),
                droneRadius: selectedDroneProfile.collisionRadius,
                modeTag: activeRouteTargetSource == .mission ? "multirotor_mission_marker" : "multirotor_marker",
                forceRecompute: replanReason != "no_waypoints",
                reason: replanReason
            )
            multirotorMarkerLastPlanTick = simulationTickCounter
            autoPathPlanner.updateProgress(
                currentPosition: state.position,
                arrivalRadius: 1.35,
                planarOnly: true
            )
        }

        navigationSnapshot = autoPathPlanner.snapshot(currentPosition: state.position)

        let finalDistance = marker.distance(from: currentPlanarPosition())
        let plannedTarget = finalDistance <= multirotorMarkerFinalApproachDistance()
            ? finalGoal
            : autoPathPlanner.lookaheadTarget(
                currentPosition: state.position,
                minimumDistance: multirotorMarkerLookaheadDistance()
            )

        guard let plannedTarget else {
            autoNavigationController.cancel()
            let hoverThrottle = Double(resolvedFlightBaseline(for: .hover).hoverLockThrottle)
            updateControlValues({ values in
                values.x = Double(state.position.x)
                values.y = Double(max(state.position.y, min(travelAltitude, terrain.maxFlightAltitude - 2.0)))
                values.z = Double(state.position.z)
                values.roll = 0.0
                values.pitch = 0.0
                values.yaw = Double(state.orientation.z.radiansToDegrees)
                values.throttle = max(values.throttle, hoverThrottle)
            }, markManual: false)
            return nil
        }

        return correctedMultirotorMarkerPathTarget(
            plannedTarget,
            finalGoal: finalGoal,
            currentDistanceToGoal: finalDistance
        )
    }

    private func correctedMultirotorMarkerPathTarget(
        _ plannedTarget: SIMD3<Float>,
        finalGoal: SIMD3<Float>,
        currentDistanceToGoal: Float
    ) -> SIMD3<Float> {
        let plannedDistanceToGoal = simd_distance(
            SIMD2<Float>(plannedTarget.x, plannedTarget.z),
            SIMD2<Float>(finalGoal.x, finalGoal.z)
        )
        let allowedRegression = max(3.0, multirotorMarkerLookaheadDistance() * 0.45)
        guard plannedDistanceToGoal > currentDistanceToGoal + allowedRegression else {
            return plannedTarget
        }

        let directAssessment = autoPathPlanner.assessDirectPath(
            from: state.position,
            to: finalGoal,
            terrain: terrain,
            obstacles: navigationObstaclesIncludingNoFlyZones(),
            obstacleSignature: navigationObstacleSignatureIncludingNoFlyZones(),
            droneRadius: selectedDroneProfile.collisionRadius
        )
        if !directAssessment.blocked && directAssessment.maxPenalty < 0.36 {
            return finalGoal
        }

        return plannedTarget
    }

    /// Both conventional wings and hybrid VTOLs execute turn-radius-limited wing-borne legs. Their
    /// route, obstacle cache and collision broad phase must therefore share the full-body envelope
    /// from takeoff through hover handoff; changing geometry policy mid-leg invalidates the route.
    private var activeAirframeUsesWingNavigation: Bool {
        selectedDroneProfile.airframeClass == .fixedWing ||
            selectedDroneProfile.airframeClass == .hybridVTOL
    }

    /// Radius of a sphere enclosing every physical contact on the aircraft. Wing-capable
    /// navigation must protect this envelope rather than the legacy fuselage proxy, otherwise a
    /// centerline can be clear while a wingtip or lift rotor intersects a tree or facade.
    private var fixedWingNavigationEnvelopeRadius: Float {
        max(selectedDroneProfile.collisionRadius, vehicleContactProfile.boundingRadius)
    }

    /// Lateral room a straight leg must keep from a façade before it may be flown without planning.
    ///
    /// The envelope radius alone is the aircraft's own size — 1.2 m for a Wingcopter, 0.7 m for a
    /// WingtraOne — so certifying against it asks only "does this line pass *through* the wall".
    /// It does not, and that is how `[Route] direct_certified ... required=1.2 nearest=4.0
    /// src=world.building y=6..92` was approved: a straight 798 m leg routed four metres from a
    /// ninety-two-metre façade, which the aircraft then flew into at 25 m/s, twice, with the
    /// reactive layer left to do the whole job.
    ///
    /// Six metres on top is the lateral excursion these same logs show: a 10° bank held for a
    /// second at cruise moves the aircraft three to five metres off the line, and the wing has to
    /// fit in what is left. A leg that cannot hold that has to be planned around instead — which
    /// costs planner time and is exactly the trade being made. Tune here.
    private static let fixedWingRouteCertificationStandoffMeters: Float = 6.0
    private var fixedWingRouteCertificationClearance: Float {
        fixedWingNavigationEnvelopeRadius + Self.fixedWingRouteCertificationStandoffMeters
    }

    /// Whether an obstacle actually stands in the aircraft's altitude band.
    ///
    /// This replaces the old `source.contains("tree")` test, which was the only thing keeping
    /// avoidance away from the mesh cells that tile an imported world — including the ground the
    /// aircraft is flying over. Ground cells top out below the aircraft and drop out here; a
    /// façade, a bridge pylon or a tree crown at flight level stays in. A deck high overhead also
    /// drops out, so flying under a bridge is not treated as a blocked route.
    private func blocksFlightBand(_ obstacle: CollisionObstacle) -> Bool {
        let margin = max(1.0, fixedWingNavigationEnvelopeRadius)
        let altitudeBand = fixedWingProtectedAltitudeRange()
        return obstacle.topY > altitudeBand.lowerBound - margin
            && obstacle.baseY < altitudeBand.upperBound + margin
    }

    /// The aircraft occupies every altitude between its current height and the active route
    /// command while climbing/descending. Treating only the current slice made a bridge deck or
    /// elevated facade disappear until the aircraft was already inside its turn lead.
    private func fixedWingProtectedAltitudeRange(
        additionalTargetAltitude: Float? = nil
    ) -> ClosedRange<Float> {
        let current = max(0.0, state.position.y)
        var targets: [Float] = [current]
        if fixedWingAssistState.mode == .waypointIntercept,
           let altitude = fixedWingAssistState.targetAltitudeMeters,
           altitude.isFinite {
            targets.append(max(0.0, altitude))
        }
        if let altitude = fixedWingAutopilotAltitudeCommand, altitude.isFinite {
            targets.append(max(0.0, altitude))
        }
        if let altitude = activeRouteTargetAltitude, altitude.isFinite {
            targets.append(max(0.0, altitude))
        }
        if let altitude = additionalTargetAltitude, altitude.isFinite {
            targets.append(max(0.0, altitude))
        }
        let ceiling = max(current, targets.max() ?? current)

        // The ceiling may span every altitude figure in play — over-including obstacles *above* the
        // aircraft is free, they simply never intersect its path. The floor may not: it decides
        // which obstacles the planner treats as solid, and taking the minimum across route-level
        // figures planned an entire cruise as though it were being flown at the lowest altitude
        // anyone had mentioned. At 199 m over Manhattan that reinstated every tower above the
        // mission's route altitude as a wall, the grid had no free corridor left, the protected
        // reroute could not be built, and auto-advance parked on "obstacle ahead" with open sky in
        // front of the aircraft — the hold the operator had to break by hand, repeatedly.
        //
        // The aircraft can only be where it is or where it is being *commanded* to go, so those are
        // the floor. A descent is not lost: the band is bucketed to 10 m, so the set is rebuilt and
        // the lower obstacles become solid as the commanded altitude walks down towards them, with
        // `navigationBandClearanceMeters()` as the margin.
        //
        // "Commanded" has to mean the leg's own intent, not the last value written to the command.
        // For a hybrid VTOL those differ: every branch of its guidance writes
        // `fixedWingAutopilotAltitudeCommand`, so a blocked tick writes the hold altitude and a
        // ready tick writes the route altitude, and reading that here fed the branch's own output
        // back into the obstacle set the next branch is decided from. See
        // `hybridVTOLNavigationBandAltitude`, which is the stable per-leg figure.
        var floorCandidates: [Float] = [current]
        let commandedFloor = selectedDroneProfile.airframeClass == .hybridVTOL
            ? hybridVTOLNavigationBandAltitude
            : fixedWingAutopilotAltitudeCommand
        if let altitude = commandedFloor, altitude.isFinite {
            floorCandidates.append(max(0.0, altitude))
        }
        if let altitude = additionalTargetAltitude, altitude.isFinite {
            floorCandidates.append(max(0.0, altitude))
        }
        let floor = min(floorCandidates.min() ?? current, ceiling)
        // The band must never be thinner than the vehicle needs to see.
        //
        // Floor and ceiling both converge on the aircraft once it is established at its cruise
        // altitude — the flight that ended in a building logged `band=70-73` with the aircraft at
        // 70.2 m, a three-metre slab, and `nav` collapsed 18677 → 250 on that one tick. A roof a
        // metre under the aircraft is then simply not in the planner's world. Widening downward is
        // the cheap direction: obstacles below can be flown over, but only if they are known.
        let minimumHalfWidth = navigationBandClearanceMeters()
        // The edges follow `current` directly, and deliberately so.
        //
        // Snapping them to a 10 m grid was tried (2026-08-21) to stop station-keeping noise from
        // rewriting the obstacle set: a WingtraOne holding within ±2 m logged `band=29-45 nav=15217`
        // against `band=31-47 nav=5734` on alternating ticks, because the surrounding roofline sits
        // between those two figures, and the route certified on one tick then failed
        // `planner_astar_blocked_seg0` on the next. Quantising outward removed that particular
        // chatter but always widens the band, so it also enlarged the obstacle set on every
        // ordinary leg; the flight that followed was worse overall and the operator reverted it.
        // The chatter is real and still unfixed — if it is taken up again, do it by stabilising the
        // altitude the band is measured from, not by widening the band.
        return min(floor, current - minimumHalfWidth)...max(ceiling, current + minimumHalfWidth)
    }

    /// Horizontal extent only. `radius` is a 3-D bounding sphere, so for a mesh cell holding a tall
    /// building it is dominated by height and would push sidesteps tens of metres across a street.
    private func obstaclePlanarRadius(_ obstacle: CollisionObstacle) -> Float {
        if let extents = obstacle.planarHalfExtents {
            return simd_length(extents)
        }
        return obstacle.radius
    }

    /// How far the obstacle actually reaches along one planar axis.
    ///
    /// `obstaclePlanarRadius` returns `simd_length(halfExtents)` — the box's *diagonal*, which is
    /// the correct answer only for a circle. This file has already paid for that mistake once: the
    /// segment form of `planarSignedDistance` carries a comment about a 40×80 m block demanding
    /// 45 m of stand-off from its centre when its long face is only 20 m out, "which no street in a
    /// real city can satisfy". The sidestep was still sizing its offset that way, and on a measured
    /// Manhattan leg it asked for **33.3 m** of lateral displacement — then, seven ticks later,
    /// for 33.3 m in the opposite direction. Neither is reachable in that street, so the scoring
    /// was choosing between two impossible options and the tie broke on noise.
    private func obstacleSupport(_ obstacle: CollisionObstacle, along axis: SIMD2<Float>) -> Float {
        guard let extents = obstacle.planarHalfExtents else { return obstacle.radius }
        let cosYaw = cos(obstacle.yawRadians)
        let sinYaw = sin(obstacle.yawRadians)
        // Same world→local convention as `planarSignedDistance`, so the two cannot drift apart.
        let localAxis = SIMD2<Float>(
            axis.x * cosYaw - axis.y * sinYaw,
            axis.x * sinYaw + axis.y * cosYaw
        )
        return abs(localAxis.x) * extents.x + abs(localAxis.y) * extents.y
    }

    /// What the sidestep search is allowed to measure itself against.
    ///
    /// OSM worlds provide semantic building/tree shapes; photogrammetric worlds provide only mesh
    /// cells. The latter are retained here and evaluated against their triangles by fixed-wing
    /// trajectory prediction below, rather than treated as solid 24 m boxes.
    private func avoidanceObstacles(
        near position: SIMD3<Float>? = nil,
        radius: Float
    ) -> [CollisionObstacle] {
        let center = position ?? state.position
        let result = sceneController.nearbyEnvironmentObstacles(
            near: center,
            radius: radius,
            // Object-aware OSM worlds already have tight semantic obstacles. Do not synthesise a
            // large mesh square only to discard it below; photogrammetry has no semantic registry
            // and therefore must include the mesh cells.
            includeMesh: usesMeshCellsForPlanning
        )
        // Object-aware OSM worlds already publish real building/tree footprints through the same
        // query. A photogrammetric world has no semantic registry, so its mesh cells are the only
        // geometry reactive avoidance can see and must not be discarded.
        return usesMeshCellsForPlanning
            ? result
            : result.filter { !$0.source.hasPrefix("world.mesh.cell") }
    }

    /// Planar distance from a point to a triangle flattened onto X/Z. Negative inside.
    ///
    /// The degenerate case is the important one. A façade triangle is vertical, so projecting it to
    /// X/Z collapses it to a *segment* — and distance-to-segment is exactly the lateral clearance a
    /// wall offers. That is the whole reason to work in triangles here: the cell's bounding box
    /// fills in the twenty-four metre square *behind* that façade as if it were solid, and a
    /// rotorcraft flying down the open half of the tile reads as buried inside an obstacle.
    private static func planarDistance(
        from point: SIMD2<Float>,
        toTriangle a: SIMD2<Float>,
        _ b: SIMD2<Float>,
        _ c: SIMD2<Float>
    ) -> Float {
        func distanceToSegment(_ p: SIMD2<Float>, _ s: SIMD2<Float>, _ e: SIMD2<Float>) -> Float {
            let span = e - s
            let lengthSquared = simd_length_squared(span)
            guard lengthSquared > 1e-9 else { return simd_distance(p, s) }
            let t = min(1.0, max(0.0, simd_dot(p - s, span) / lengthSquared))
            return simd_distance(p, s + span * t)
        }
        func cross(_ u: SIMD2<Float>, _ v: SIMD2<Float>) -> Float { u.x * v.y - u.y * v.x }

        let edgeDistance = min(
            distanceToSegment(point, a, b),
            min(distanceToSegment(point, b, c), distanceToSegment(point, c, a))
        )
        let s0 = cross(b - a, point - a)
        let s1 = cross(c - b, point - b)
        let s2 = cross(a - c, point - c)
        let inside = (s0 >= 0.0 && s1 >= 0.0 && s2 >= 0.0)
            || (s0 <= 0.0 && s1 <= 0.0 && s2 <= 0.0)
        return inside ? -edgeDistance : edgeDistance
    }

    /// The mesh geometry that actually stands in the flight band, flattened for the clearance test.
    ///
    /// Filtering by the triangle's own vertical extent is what keeps this cheap and correct: the
    /// ground plane and every rooftop far below drop out, and what survives is the façade the
    /// aircraft could hit at this altitude.
    private func bandRelevantMeshTriangles(
        _ obstacles: [CollisionObstacle]
    ) -> [(SIMD2<Float>, SIMD2<Float>, SIMD2<Float>)] {
        let band = fixedWingProtectedAltitudeRange()
        let margin = max(1.0, fixedWingNavigationEnvelopeRadius)
        var flattened: [(SIMD2<Float>, SIMD2<Float>, SIMD2<Float>)] = []
        for obstacle in obstacles {
            guard let triangles = obstacle.meshTriangles else { continue }
            for triangle in triangles {
                guard triangle.maximum.y > band.lowerBound - margin,
                      triangle.minimum.y < band.upperBound + margin else { continue }
                flattened.append((
                    SIMD2<Float>(triangle.point0.x, triangle.point0.z),
                    SIMD2<Float>(triangle.point1.x, triangle.point1.z),
                    SIMD2<Float>(triangle.point2.x, triangle.point2.z)
                ))
            }
        }
        return flattened
    }

    /// Everything the *physics* can hit, for the clearance test alone.
    ///
    /// `avoidanceObstacles` drops `world.mesh.cell` on an object-aware OSM world, on the premise
    /// that the semantic registry already covers the same geometry. Three flights in a row falsify
    /// that premise in one place: `[Impact] src=world.mesh.cell.25.24 origin=meshCell` while the
    /// sidestep was steering around a `world.building` and reporting `inBand=1`. The layer was
    /// avoiding the thing it could see and being struck by the thing it could not.
    ///
    /// The filter itself is not wrong. A 24 m bucket is far too coarse to *steer* by: let it into
    /// the nearest-obstacle pick and sidesteps get sized off a bucket radius; let it into the
    /// threat test and half of Manhattan is a threat. So the cells come back for exactly one job —
    /// deciding whether a candidate path is clear. Coarseness there errs toward holding, which is
    /// the survivable direction, and steering still happens on semantic footprints.
    ///
    /// Costs a second registry query per tick on the path that already runs one; `colPre`/`guid`
    /// have the room, and a query that is skipped is how the last three wings came off.
    private func contactAwareClearanceObstacles(radius: Float) -> [CollisionObstacle] {
        sceneController.nearbyEnvironmentObstacles(
            near: state.position,
            radius: radius,
            includeMesh: true
        )
    }

    /// The closest point to the marker the aircraft can actually occupy.
    ///
    /// A marker dropped on a façade — which is what a click on a building gives you — cannot be
    /// reached: arrival asks for 0.85 m and the nearest safe hover point is a vehicle radius plus
    /// clearance off the wall. The aircraft therefore orbited it at two metres, pulled in by
    /// guidance and pushed out by avoidance, and the leg never completed. The goal is projected out
    /// of whatever it is buried in, and *that* point is what the route flies to and what arrival is
    /// measured against: as close as is safe, rather than a place the airframe cannot be.
    private func safeMarkerApproachGoal(
        marker: TargetMarkerState,
        altitude: Float
    ) -> SIMD3<Float> {
        // A mission waypoint is flown where the operator put it. Standing off from it would mean
        // the aircraft silently flies a different route than the one on the map — which is exactly
        // what it did: the flown track left the planned polyline. The standoff exists for a
        // hand-placed marker, where "as close as is safe" is the whole intent.
        guard activeRouteTargetSource != .mission else {
            return clampToWorldBounds(marker.worldPosition(altitude: altitude))
        }

        let altitudeBucket = Int((altitude / 4.0).rounded())
        let revision = sceneController.environmentRevision
        if let cached = markerApproachGoalCache,
           cached.markerID == marker.id,
           cached.altitudeBucket == altitudeBucket,
           cached.revision == revision,
           simd_distance(cached.markerPosition, marker.position) < 0.01 {
            return cached.goal
        }

        let rawGoal = clampToWorldBounds(marker.worldPosition(altitude: altitude))
        let droneRadius = selectedDroneProfile.collisionRadius
        // Sized so the standoff point is quiet for the avoidance layer, not merely survivable:
        // below `requiredClearance + 0.55` the sidestep search stops preferring "straight ahead",
        // and the aircraft would dance around the goal instead of settling on it.
        let safetyMargin = max(1.2, droneRadius * 1.6)
        let obstacles = avoidanceObstacles(near: rawGoal, radius: 60.0).filter { obstacle in
            // The band the goal sits in, not the one the aircraft is in: a marker on a low roof is
            // clear of the tower next to it.
            obstacle.topY > altitude - 1.0 && obstacle.baseY < altitude + 1.0
        }

        func clearance(at point: SIMD2<Float>) -> Float {
            obstacles.reduce(Float.greatestFiniteMagnitude) { partial, obstacle in
                min(partial, obstacle.planarContact(to: point, droneRadius: droneRadius).clearance)
            }
        }

        var planar = marker.position
        if clearance(at: planar) < safetyMargin {
            // Search outward for the nearest point that is genuinely clear, rather than pushing the
            // goal along one obstacle's normal: in a dense block that push lands inside the
            // neighbour, whose push sends it back, and the point never converges (measured: it left
            // 610 of 1 200 real façade markers still buried). Rings are exhaustive over direction,
            // so the answer is the closest clear point that exists, and the aircraft's own side of
            // the building is preferred so the standoff is not across the block from it.
            let aircraft = currentPlanarPosition()
            var bestScore = Float.greatestFiniteMagnitude
            var best: SIMD2<Float>?
            var fallbackClearance = -Float.greatestFiniteMagnitude
            var fallback = planar

            for step in 1...20 {
                let ringRadius = Float(step) * 2.0
                for index in 0..<24 {
                    let angle = Float(index) / 24.0 * 2.0 * .pi
                    let candidate = marker.position + SIMD2<Float>(cos(angle), sin(angle)) * ringRadius
                    let candidateClearance = clearance(at: candidate)
                    if candidateClearance > fallbackClearance {
                        fallbackClearance = candidateClearance
                        fallback = candidate
                    }
                    guard candidateClearance >= safetyMargin else { continue }
                    let score = ringRadius + simd_distance(candidate, aircraft) * 0.25
                    if score < bestScore {
                        bestScore = score
                        best = candidate
                    }
                }
                if best != nil { break }
            }
            planar = best ?? fallback
        }

        let goal = clampToWorldBounds(SIMD3<Float>(planar.x, altitude, planar.y))
        markerApproachGoalCache = MarkerApproachGoalCache(
            markerID: marker.id,
            markerPosition: marker.position,
            altitudeBucket: altitudeBucket,
            revision: revision,
            goal: goal
        )
        return goal
    }

    private struct MarkerApproachGoalCache {
        let markerID: UUID
        let markerPosition: SIMD2<Float>
        let altitudeBucket: Int
        let revision: UInt64
        let goal: SIMD3<Float>
    }

    /// One line per tick, from whichever exit the rotor-borne sidestep actually took.
    ///
    /// A Quantum Trinity Pro clipped a façade with its right wing tip at 4.35 m/s while this layer
    /// reported `avCmd=no avOff=clear` for the whole approach, with 106 obstacles inside the flight
    /// band. `avCmd` only says the *wing* corridor issued nothing; it says nothing at all about the
    /// rotor sidestep, which has seven distinct ways to return `nil` and no way to tell them apart
    /// from outside. Rather than guess which one fired, name it.
    ///
    /// `rep` is what `CollisionAnalysisService` believes the nearest obstacle is; `nearest` is what
    /// this layer measured for itself after the band filter. The two disagreeing is a finding in its
    /// own right — the report drives the gate, the measurement drives the geometry.
    ///
    /// Printed only when something is actually near, so a clean cruise leg stays silent.
    #if DEBUG
    /// Last categorical verdict printed per channel, and when.
    private var diagnosticThrottleState: [String: (key: String, tick: UInt64)] = [:]

    /// Print a trace line when it says something new, and only occasionally when it does not.
    ///
    /// These traces are not decoration — they located five defects that were invisible without
    /// them, including three of my own regressions, so thinning them is a volume problem and not a
    /// value one. Repetition is where the volume lives: `[Sidestep]` alone produced roughly two
    /// thousand lines of a 2 789-line flight, nearly all of them the same verdict re-stated sixty
    /// times a second.
    ///
    /// So the *categorical* part — which exit the layer took, whether the route certified — is the
    /// throttle key, and any change to it prints immediately. Everything continuous (clearance,
    /// distance, altitude) still gets sampled on the tick cadence, which is enough to read a trend:
    /// the decay that mattered most in this saga, `clr` falling 2.4 → 1.2 m, spanned dozens of
    /// ticks and survives one-in-ten sampling intact.
    ///
    /// The line is an autoclosure so a suppressed sample costs no `String(format:)` at all.
    private func printThrottled(
        channel: String,
        key: String,
        everyTicks: UInt64 = 10,
        _ line: @autoclosure () -> String
    ) {
        if let previous = diagnosticThrottleState[channel],
           previous.key == key,
           simulationTickCounter < previous.tick &+ everyTicks {
            return
        }
        diagnosticThrottleState[channel] = (key, simulationTickCounter)
        print(line())
    }
    #endif

    private func noteRotorBorneSidestep(
        _ outcome: String,
        inBand: Int = -1,
        nearest: Float = -1.0,
        source: String = "-",
        immediate: Bool = false,
        threatened: Bool = false,
        clearance: Float = -1.0,
        offset: Float = 0.0,
        meshTris: Int = -1
    ) {
        #if DEBUG
        guard collisionAnalysis.nearestObstacleDistance < 40.0 ||
              collisionAnalysis.riskScore >= 0.20 else { return }
        let band = fixedWingProtectedAltitudeRange()
        printThrottled(channel: "Sidestep", key: outcome, String(
            // `mtri` is how many mesh triangles stood in the flight band for the clearance test.
            // Zero next to a low `clr` means a semantic building did it; a large number next to a
            // permanent `hold_nothing_clear` means the mesh geometry is the thing pinning the
            // aircraft, and that is a different fix.
            format: "[Sidestep] %@ risk=%.2f spd=%.1f rep=%.1f band=%.0f-%.0f inBand=%d "
                + "nearest=%.1f src=%@ imm=%@ thr=%@ clr=%.1f off=%+.1f mtri=%d",
            outcome as NSString,
            Double(collisionAnalysis.riskScore),
            Double(simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))),
            Double(collisionAnalysis.nearestObstacleDistance),
            Double(band.lowerBound),
            Double(band.upperBound),
            inBand,
            Double(nearest),
            source as NSString,
            (immediate ? "y" : "n") as NSString,
            (threatened ? "y" : "n") as NSString,
            Double(clearance),
            Double(offset),
            meshTris
        ))
        #endif
    }

    private func multirotorCollisionAvoidanceTarget(
        nominalTarget: SIMD3<Float>,
        finalGoal: SIMD3<Float>,
        travelAltitude: Float
    ) -> SIMD3<Float>? {
        // A hovering hybrid VTOL is a multirotor for this purpose — same rotor-borne translation,
        // same need to slide around a façade rather than stop in front of it. It reaches here only
        // through `applyHybridVTOLAutopilotTracking`'s hover phases, so the wingborne regime still
        // belongs to the forward-avoidance layer (see `forwardAvoidanceCoversActiveAirframe`).
        //
        // Ownership is "the corridor layer is steering", not "the corridor layer holds the latch".
        // Those came apart in a measured `transitionToHover`: `wbLatch=yes` with `avCmd=no
        // avOff=clear` for a long run of ticks while the nearest obstacle closed 12.4 → 9.0 m at
        // 19.8 m/s. The corridor layer was not clearing the path, it was declining to look; this
        // gate then refused the sidestep as "not a rotorcraft". Nine metres at 19.8 m/s is 0.45 s
        // and neither layer was watching — the same silence that put a wing tip into a façade.
        //
        // While the corridor layer is actually commanding it keeps the aircraft, because two layers
        // steering one target is a deadlock this file has already paid for. The eight-tick grace is
        // the same figure the candidate hold below uses, and for the same reason: an ownership that
        // flips every frame is worse than either owner. Read one tick stale by construction —
        // guidance runs before the avoidance probe within a tick — which is the intended question:
        // did the corridor layer steer on the last completed tick.
        let corridorLayerIsSteering = vtolWingborneAvoidanceLatched &&
            (fixedWingAvoidanceLastCommandTick.map { $0 + 8 >= simulationTickCounter } ?? false)
        let airframeIsRotorBorne = selectedDroneProfile.airframeClass == .multirotor
            || (selectedDroneProfile.airframeClass == .hybridVTOL && !corridorLayerIsSteering)
        // The risk score cannot be the only way in, because it is blind past ten metres.
        //
        // `CollisionAnalysisService` builds its distance term as `1 - clearance / 10`, so beyond
        // 10 m that term is exactly zero and only the time-to-collision term is left — and that one
        // is weighted 0.35, below the 0.30 gate's own margin and far below the 0.45 the emergency
        // action needs. For a copter at 5 m/s ten metres is two seconds and the model is right. For
        // a Wingcopter that has given up the wing and is still carrying 25 m/s it is four tenths of
        // a second: the layer reported `avCmd=no avOff=clear` all the way into a façade at 25 m/s,
        // twice. Past the speed where ten metres stops being a second of warning, geometry decides
        // instead — the `immediateRisk || routeThreatened` guard below already does that job, it
        // was simply never reached.
        //
        // The ten-metre speed threshold covers the fast case and leaves the slow one open. Measured
        // on the same flight: 7.2 m/s with the nearest obstacle at 7.3 m and `risk=0.15`, refused
        // every tick — one second of closing distance, and the layer never woke. So the third way in
        // is time rather than either raw number. Two seconds, because the manoeuvre itself needs
        // most of that: the sidestep asks for up to ~3 m of lateral displacement and hover lean is
        // clamped at ±16°, worth about 2.8 m/s² sideways, so the slide alone is ~1.5 s. Waking with
        // less than that leaves the layer nothing to execute with. At rest the term is zero, which
        // is correct — nothing is closing.
        let planarSpeed = simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        let secondsToNearestObstacle = planarSpeed > 0.1
            ? collisionAnalysis.nearestObstacleDistance / planarSpeed
            : .greatestFiniteMagnitude
        guard airframeIsRotorBorne,
              collisionAnalysis.riskScore >= 0.30
                || planarSpeed > 10.0
                || secondsToNearestObstacle < 2.0 else {
            noteRotorBorneSidestep(airframeIsRotorBorne ? "gate_risk_low" : "gate_not_rotorborne")
            multirotorAvoidanceLateralOffset = 0.0
            return nil
        }

        let current = SIMD2<Float>(state.position.x, state.position.z)
        let searchRadius = max(28.0, rotorBorneAvoidanceLookahead() + 26.0)
        let nearbyObstacles = avoidanceObstacles(radius: searchRadius)
            .filter { blocksFlightBand($0) }
        // Steering and clearance use different sets on purpose — see
        // `contactAwareClearanceObstacles`. `nearbyObstacles` picks the target; the mesh geometry
        // below only ever vetoes a path, and it is measured against its own triangles rather than
        // the tile that encloses them.
        let clearanceMeshTriangles = bandRelevantMeshTriangles(
            contactAwareClearanceObstacles(radius: searchRadius)
                .filter { $0.source.hasPrefix("world.mesh.cell") && blocksFlightBand($0) }
        )

        // The nearest *object*, not whatever the risk report named — that can be a mesh bucket,
        // whose 17 m bounding radius would size a sidestep wider than the street it is in.
        guard let obstacle = nearbyObstacles.min(by: {
            $0.planarSignedDistance(to: current) < $1.planarSignedDistance(to: current)
        }) else {
            noteRotorBorneSidestep("no_obstacles_in_band", inBand: 0)
            multirotorAvoidanceLateralOffset = 0.0
            return nil
        }
        let nearestDistance = obstacle.planarSignedDistance(to: current)
        let nominal = SIMD2<Float>(nominalTarget.x, nominalTarget.z)
        let finalPlanar = SIMD2<Float>(finalGoal.x, finalGoal.z)
        var routeVector = nominal - current

        if simd_length_squared(routeVector) < 0.04 {
            routeVector = finalPlanar - current
        }
        if simd_length_squared(routeVector) < 0.04 {
            let planarVelocity = SIMD2<Float>(state.velocity.x, state.velocity.z)
            if simd_length_squared(planarVelocity) > 0.01 {
                routeVector = planarVelocity
            }
        }

        guard simd_length_squared(routeVector) > 0.0001 else {
            noteRotorBorneSidestep(
                "degenerate_route",
                inBand: nearbyObstacles.count,
                nearest: nearestDistance,
                source: obstacle.source,
                meshTris: clearanceMeshTriangles.count
            )
            return nil
        }

        let routeDirection = simd_normalize(routeVector)
        let sideAxis = SIMD2<Float>(-routeDirection.y, routeDirection.x)
        let forwardWindow = max(10.0, rotorBorneAvoidanceLookahead() + obstaclePlanarRadius(obstacle))
        let immediateRisk = collisionAnalysis.nearestObstacleDistance < 2.4 ||
            collisionAnalysis.riskScore >= 0.55

        func routeCoordinates(for candidate: CollisionObstacle) -> (along: Float, lateral: Float) {
            let candidateVector = candidate.planarCenter - current
            return (
                simd_dot(candidateVector, routeDirection),
                simd_dot(candidateVector, sideAxis)
            )
        }

        let routeThreatened = nearbyObstacles.contains { candidate in
            let coordinates = routeCoordinates(for: candidate)
            let protectedWidth = obstaclePlanarRadius(candidate)
                + selectedDroneProfile.collisionRadius + 2.2
            return coordinates.along > -protectedWidth &&
                coordinates.along < forwardWindow &&
                abs(coordinates.lateral) <= protectedWidth
        }

        guard immediateRisk || routeThreatened else {
            noteRotorBorneSidestep(
                "not_threatened",
                inBand: nearbyObstacles.count,
                nearest: nearestDistance,
                source: obstacle.source,
                immediate: immediateRisk,
                threatened: routeThreatened,
                meshTris: clearanceMeshTriangles.count
            )
            multirotorAvoidanceLateralOffset = 0.0
            return nil
        }

        let nearestCoordinates = routeCoordinates(for: obstacle)
        let preferredSign: Float = nearestCoordinates.lateral >= 0.0 ? -1.0 : 1.0
        // How far sideways the search is allowed to look — the obstacle's size is only half of it.
        //
        // Sizing the widest candidate off the obstacle alone asks "how big is it", never "can I get
        // there". Measured: a turn onto the next leg produced `off=-33.7` and then `off=+64.9` on
        // the following tick, with the obstacle 3.3 m away and the aircraft doing 7.4 m/s. Sixty-five
        // metres is not a sidestep at that range, it is a heading command pointing ninety degrees off
        // the route, and the aircraft answered it with bank until the wing tip touched.
        //
        // So the geometric figure is capped by what lean can actually deliver in the time left:
        // `½·a·t²` with the same 2.8 m/s² the ±16° hover clamp is worth and `t` the distance to the
        // obstacle over the closing speed. At 11 m/s with 16 m of room that is ~2.9 m — a real
        // sidestep. At 7.4 m/s with 3.3 m it is ~0.2 m, which is the honest answer: there is no
        // sidestep left, only a stop, and `hold_nothing_clear` below is what says so.
        let geometricSideDistance = max(
            6.0,
            obstacleSupport(obstacle, along: sideAxis)
                + selectedDroneProfile.collisionRadius * 2.2
                + 3.0
        )
        let secondsToNearest = max(0.25, nearestDistance / max(planarSpeed, 0.5))
        let reachableSideDistance = 0.5 * Self.rotorBorneLateralAccelerationMps2 *
            secondsToNearest * secondsToNearest
        let sideDistance = max(1.0, min(geometricSideDistance, reachableSideDistance))
        let remainingDistance = max(2.5, simd_distance(current, finalPlanar))
        let forwardStep = min(
            remainingDistance,
            immediateRisk
                ? max(4.0, min(7.0, nearestCoordinates.along + 2.5))
                : max(4.0, min(8.0, nearestCoordinates.along + 3.0))
        )
        // A ladder with no gap in it.
        //
        // The old rungs were 2.4 m, 4.2 m and then `sideDistance` — nothing in between. Once 4.2 m
        // stopped clearing, the only remaining option was the full obstacle-sized jump, so the
        // search went from "four metres" to "sixty-five" with no middle. Fractions of the (now
        // bounded) ceiling keep the progression continuous, which is what lets the scoring below
        // actually choose rather than fall off a cliff.
        var candidateOffsets: [Float] = [0.0]
        for fraction in [Float(0.35), Float(0.65), Float(1.0)] {
            candidateOffsets.append(preferredSign * fraction * sideDistance)
            candidateOffsets.append(-preferredSign * fraction * sideDistance)
        }
        // Do not cross in front of the thing you are avoiding.
        //
        // `preferredSign` is recomputed every tick from whichever object is nearest, so passing its
        // centre line flips it. Two flights in a row show the result: a committed slide reversing
        // while the obstacle was one to three metres away. Inside the hold window the committed side
        // is the only side offered — straight ahead and the stop are still on the table, so the
        // aircraft can still abandon the slide; it just cannot swap sides mid-manoeuvre.
        if simulationTickCounter <= multirotorAvoidanceHoldUntilTick,
           abs(multirotorAvoidanceLateralOffset) > 0.05 {
            let committedSign: Float = multirotorAvoidanceLateralOffset < 0.0 ? -1.0 : 1.0
            candidateOffsets.removeAll { $0 * committedSign < -0.05 }
        }
        // What counts as "clear" here — and why this is not a new number.
        //
        // `collisionRadius * 0.25` asks only "does the body fit", and a measured flight shows what
        // that buys: `straight_is_clear` held while the margin fell 2.4 → 1.2 m at 15.7 m/s, and a
        // few ticks later the layer measured itself 0.1 m *inside* a building's footprint, in a
        // flight band that same building occupied.
        //
        // The planner refuses exactly this kind of line below `fixedWingRouteCertificationClearance`
        // — 7.2 m for this airframe — for a reason already written down beside it: a 10° bank held
        // for a second moves the aircraft three to five metres off the line, and the wing has to fit
        // in what is left. The reactive layer flies that same line, at cruise speed, while banking
        // on purpose. It has no business certifying twenty times less than the planner would, so it
        // gets the planner's own figure rather than an invented one.
        //
        // Accepted consequence, stated rather than discovered: more `hold_nothing_clear` in tight
        // streets — the aircraft stops instead of threading and the altitude ladder lifts it over.
        // That is this layer's designed answer to "a façade across the route", and it is what
        // happened on that flight anyway, only later and from one metre instead of seven.
        //
        // Multirotors keep the old rule. A copter at walking pace can genuinely thread a one-metre
        // gap, and nothing measured says otherwise.
        let requiredClearance = selectedDroneProfile.airframeClass == .hybridVTOL
            ? fixedWingRouteCertificationClearance
            : max(0.35, selectedDroneProfile.collisionRadius * 0.25)

        func clearance(at point: SIMD2<Float>) -> Float {
            var best = nearbyObstacles.reduce(Float.greatestFiniteMagnitude) { partial, candidate in
                min(
                    partial,
                    candidate.planarSignedDistance(to: point) - selectedDroneProfile.collisionRadius
                )
            }
            for triangle in clearanceMeshTriangles {
                best = min(
                    best,
                    Self.planarDistance(
                        from: point,
                        toTriangle: triangle.0,
                        triangle.1,
                        triangle.2
                    ) - selectedDroneProfile.collisionRadius
                )
            }
            return best
        }

        func segmentClearance(to target: SIMD2<Float>) -> Float {
            var minimumClearance = Float.greatestFiniteMagnitude
            let segment = target - current
            for sample in [Float(0.20), Float(0.45), Float(0.70), Float(0.95)] {
                minimumClearance = min(
                    minimumClearance,
                    clearance(at: current + segment * sample)
                )
            }
            return minimumClearance
        }

        func candidateScore(offset: Float) -> (target: SIMD2<Float>, clearance: Float, score: Float) {
            let candidate = current +
                routeDirection * forwardStep +
                sideAxis * offset
            let candidateClearance = min(clearance(at: candidate), segmentClearance(to: candidate))
            let clearanceScore = min(candidateClearance, 6.0) * 2.2
            let unsafePenalty = candidateClearance < requiredClearance
                ? (requiredClearance - candidateClearance) * 18.0
                : 0.0
            let centerBonus: Float = abs(offset) < 0.10 && candidateClearance >= requiredClearance + 0.55
                ? 4.0
                : 0.0
            let progressScore = simd_dot(candidate - current, routeDirection) * 0.20 -
                simd_distance(candidate, finalPlanar) * 0.025
            let offsetPenalty = abs(offset) * 0.22
            let preferenceScore: Float = offset.sign == preferredSign.sign ? 0.35 : 0.0
            let holdBonus: Float
            if simulationTickCounter <= multirotorAvoidanceHoldUntilTick {
                let distanceFromHeldOffset = abs(offset - multirotorAvoidanceLateralOffset)
                holdBonus = max(0.0, 2.0 - distanceFromHeldOffset * 0.45)
            } else {
                holdBonus = 0.0
            }

            return (
                target: candidate,
                clearance: candidateClearance,
                score: clearanceScore + centerBonus + progressScore + preferenceScore + holdBonus -
                    offsetPenalty - unsafePenalty
            )
        }

        let scoredCandidates = candidateOffsets.map { offset in
            (offset: offset, result: candidateScore(offset: offset))
        }
        guard let bestCandidate = scoredCandidates.max(by: { $0.result.score < $1.result.score }) else {
            noteRotorBorneSidestep(
                "no_candidate",
                inBand: nearbyObstacles.count,
                nearest: nearestDistance,
                source: obstacle.source,
                immediate: immediateRisk,
                threatened: routeThreatened,
                meshTris: clearanceMeshTriangles.count
            )
            multirotorAvoidanceLateralOffset = 0.0
            return nil
        }

        if abs(bestCandidate.offset) < 0.10,
           bestCandidate.result.clearance >= requiredClearance {
            // The layer looked, and going straight on is genuinely the clear choice. Distinct from
            // every other `nil` above: those are refusals to look.
            noteRotorBorneSidestep(
                "straight_is_clear",
                inBand: nearbyObstacles.count,
                nearest: nearestDistance,
                source: obstacle.source,
                immediate: immediateRisk,
                threatened: routeThreatened,
                clearance: bestCandidate.result.clearance,
                meshTris: clearanceMeshTriangles.count
            )
            multirotorAvoidanceLateralOffset = 0.0
            multirotorAvoidanceHoldUntilTick = simulationTickCounter + 8
            return nil
        }

        // Nothing reachable is actually clear — a façade or a whole block across the route, which a
        // local sidestep cannot get around. Hold position instead of advancing on the least-bad
        // option: with only trees in scope the least-bad choice was always survivable, but against a
        // building it is a wall at cruise speed.
        guard bestCandidate.result.clearance >= requiredClearance else {
            noteRotorBorneSidestep(
                "hold_nothing_clear",
                inBand: nearbyObstacles.count,
                nearest: nearestDistance,
                source: obstacle.source,
                immediate: immediateRisk,
                threatened: routeThreatened,
                clearance: bestCandidate.result.clearance,
                meshTris: clearanceMeshTriangles.count
            )
            multirotorAvoidanceLateralOffset = 0.0
            multirotorAvoidanceHoldUntilTick = simulationTickCounter + 12
            return clampToWorldBounds(SIMD3<Float>(current.x, travelAltitude, current.y))
        }

        noteRotorBorneSidestep(
            "sidestep",
            inBand: nearbyObstacles.count,
            nearest: nearestDistance,
            source: obstacle.source,
            immediate: immediateRisk,
            threatened: routeThreatened,
            clearance: bestCandidate.result.clearance,
            offset: bestCandidate.offset,
            meshTris: clearanceMeshTriangles.count
        )
        multirotorAvoidanceLateralOffset = bestCandidate.offset
        multirotorAvoidanceHoldUntilTick = simulationTickCounter + 12
        return clampToWorldBounds(SIMD3<Float>(
            bestCandidate.result.target.x,
            travelAltitude,
            bestCandidate.result.target.y
        ))
    }

    private func shouldRefreshMultirotorMarkerPath(for reason: String) -> Bool {
        if reason == "no_waypoints" {
            return true
        }

        let minimumInterval: UInt64 = (reason == "high_collision_risk" || reason == "route_collision_risk") ? 8 : 18
        guard let lastTick = multirotorMarkerLastPlanTick else {
            return true
        }
        return simulationTickCounter >= lastTick + minimumInterval
    }

    private func multirotorMarkerLookaheadDistance() -> Float {
        let horizontalSpeed = simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        return (10.0 + horizontalSpeed * 1.2).clamped(to: 10.0...18.0)
    }

    /// Seconds of travel the rotor-borne sidestep has to be able to see.
    ///
    /// Chosen as the time to displace the aircraft its own standoff sideways at the lateral
    /// acceleration a rotor-borne VTOL actually has (~3 m/s²): about nine metres in two and a half
    /// seconds. Tune here.
    private static let rotorBorneAvoidanceHorizonSeconds: Float = 2.5
    /// Distance the rotor-borne sidestep searches ahead.
    ///
    /// `multirotorMarkerLookaheadDistance()` caps at 18 m, which is a marker-guidance figure for an
    /// aircraft doing 5–8 m/s. It stays the floor, so slow flight is unchanged; a hybrid that came
    /// out of the wing still carrying cruise speed gets a horizon measured in seconds instead.
    private func rotorBorneAvoidanceLookahead() -> Float {
        let horizontalSpeed = simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        return max(
            multirotorMarkerLookaheadDistance(),
            (horizontalSpeed * Self.rotorBorneAvoidanceHorizonSeconds).clamped(to: 0.0...80.0)
        )
    }

    private func multirotorMarkerFinalApproachDistance() -> Float {
        max(7.5, multirotorMarkerLookaheadDistance() * 0.65)
    }

    private func multirotorMarkerSpeedScale() -> Float {
        switch collisionAnalysis.riskScore {
        case 0.72...:
            return 0.62
        case 0.55..<0.72:
            return 0.76
        default:
            return 1.0
        }
    }

    /// `approachGoal` is the point the leg actually flew to — the marker itself when it stands in
    /// the open, its safe standoff when it does not. Arrival has to be judged against that, or a
    /// marker on a wall is a leg that can never end.
    private func shouldFinishMultirotorMarkerGuidance(
        marker: TargetMarkerState,
        approachGoal: SIMD3<Float>
    ) -> Bool {
        guard activeRouteTargetSource != .mission else {
            return false
        }
        let horizontalSpeed = simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        let verticalSpeed = abs(state.velocity.y)
        let hoverHandoffRadius: Float

        if let dropZone = missionPlanState.dropZone,
           missionPlanState.isDeliveryMissionReady,
           simd_distance(marker.position, dropZone.center) <= 0.001 {
            let releaseRadius = min(dropZone.radius, max(0.8, dropZone.radius * 0.24))
            hoverHandoffRadius = max(0.85, min(1.35, releaseRadius))
        } else {
            hoverHandoffRadius = 0.85
        }

        return marker.distance(from: currentPlanarPosition()) <= hoverHandoffRadius &&
            horizontalSpeed <= 0.95 &&
            verticalSpeed <= 0.55
    }

    private func hybridVTOLMarkerGuidanceReachedTarget() -> Bool {
        guard let marker = targetMarkerState,
              hybridVTOLReadyForPrecisionHover() else {
            return false
        }
        let horizontalSpeed = simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        let verticalSpeed = abs(state.velocity.y)
        return marker.distance(from: currentPlanarPosition()) <= 1.10 &&
            horizontalSpeed <= 1.40 &&
            verticalSpeed <= 0.75
    }

    private func finishTargetMarkerAutoNavigation() {
        navigationSnapshot = .idle
        resetFixedWingAutopilotCommands()
        if selectedDroneProfile.airframeClass == .multirotor {
            hover()
            return
        }
        if selectedDroneProfile.airframeClass == .hybridVTOL {
            hover()
            return
        }

        setFlightMode(.manual, reason: "fixed_wing_marker_target_reached")
        let cruiseThrottle = Double(resolvedFlightBaseline(for: .autoPath).cruiseReferenceThrottle)
        updateControlValues({ values in
            values.x = Double(state.position.x)
            values.z = Double(state.position.z)
            values.y = Double(state.position.y)
            values.roll = 0.0
            values.pitch = 0.0
            values.yaw = Double(state.orientation.z.radiansToDegrees)
            values.throttle = max(cruiseThrottle, values.throttle * 0.96)
        }, markManual: false)
    }

    @discardableResult
    private func applyFixedWingMarkerGuidance(
        deltaTime: Float
    ) -> FixedWingAutopilotOutput? {
        guard let marker = targetMarkerState,
              canStartTargetMarkerAutoNavigation else {
            cancelTargetMarkerAutoNavigation()
            if mode == .autoPath {
                setFlightMode(.manual, reason: "fixed_wing_marker_guidance_unavailable")
            }
            return nil
        }

        let targetAltitude = targetMarkerTravelAltitude()
        let markerWorld = marker.worldPosition(altitude: targetAltitude)
        let guidanceSource: FixedWingGuidanceSource = activeRouteTargetSource == .mission ? .mission : .marker
        setFixedWingGuidanceSource(guidanceSource, reason: "fixed_wing_route_guidance_active")

        if activeRouteTargetSource != .mission {
            let wing = activeFixedWingParameters()
            var recomputeReason = "fixed_wing_marker_route"
            var forceReplan = false
            if let reason = autoPathPlanner.replanReasonIfNeeded(
                currentPosition: state.position,
                collisionRisk: collisionAnalysis.riskScore,
                deviationTolerance: max(5.5, terrain.worldHalfExtent * 0.05)
            ) {
                recomputeReason = reason
                forceReplan = true
            }

            autoPathPlanner.planIfNeeded(
                start: state.position,
                goal: markerWorld,
                terrain: terrain,
                obstacles: navigationObstaclesIncludingNoFlyZones(),
                obstacleSignature: navigationObstacleSignatureIncludingNoFlyZones(),
                droneRadius: fixedWingNavigationEnvelopeRadius,
                minimumObstacleRadiusFactor: 1.0,
                additionalHardClearance: HybridVTOLFlightPolicy
                    .genericPlannerUsesWholeTurnHardClearance(
                        airframeClass: selectedDroneProfile.airframeClass
                    )
                    ? fixedWingPlannerAdditionalHardClearance(
                        to: markerWorld,
                        targetAltitude: targetAltitude,
                        wing: wing
                    )
                    : 0.0,
                modeTag: "fixed_wing_marker",
                forceRecompute: forceReplan,
                reason: recomputeReason
            )
            navigationSnapshot = autoPathPlanner.snapshot(currentPosition: state.position)
        }

        return applyAutopilotTrackingControl(
            target: markerWorld,
            targetAltitude: targetAltitude,
            speedScale: collisionAnalysis.riskScore >= 0.55 ? 0.54 : 1.0,
            yawAlignToHome: false,
            deltaTime: deltaTime
        )
    }

    private func updateAutoFlightPath(deltaTime: Float) {
        if autoFlightGoal == nil {
            autoFlightGoal = nextAutoPatrolGoal(resetCycle: true)
            autoPathPlanner.invalidate()
        }

        guard let goal = autoFlightGoal else {
            navigationSnapshot = .idle
            return
        }

        if selectedDroneProfile.airframeClass == .multirotor,
           simd_distance(state.position, goal) < 2.4 {
            autoFlightGoal = nextAutoPatrolGoal(resetCycle: false)
            autoPathPlanner.invalidate()
        }

        guard let activeGoal = autoFlightGoal else {
            navigationSnapshot = .idle
            return
        }

        let travelAltitude: Float
        if selectedDroneProfile.airframeClass == .hybridVTOL {
            travelAltitude = hybridVTOLRouteAltitude(defaultAltitude: max(10.0, homePosition.y + 8.0))
        } else {
            travelAltitude = max(3.2, homePosition.y + 4.0)
        }
        var plannedGoal = clampToWorldBounds(SIMD3<Float>(activeGoal.x, travelAltitude, activeGoal.z))
        plannedGoal.y = min(plannedGoal.y, terrain.maxFlightAltitude - 2.0)

        var recomputeReason = "auto_update"
        var forceReplan = false
        if let reason = autoPathPlanner.replanReasonIfNeeded(
            currentPosition: state.position,
            collisionRisk: collisionAnalysis.riskScore,
            deviationTolerance: max(4.5, terrain.worldHalfExtent * 0.045)
        ) {
            recomputeReason = reason
            forceReplan = true
        }

        autoPathPlanner.planIfNeeded(
            start: state.position,
            goal: plannedGoal,
            terrain: terrain,
            obstacles: navigationObstaclesIncludingNoFlyZones(),
            obstacleSignature: navigationObstacleSignatureIncludingNoFlyZones(),
            droneRadius: activeAirframeUsesWingNavigation
                ? fixedWingNavigationEnvelopeRadius
                : selectedDroneProfile.collisionRadius,
            minimumObstacleRadiusFactor: activeAirframeUsesWingNavigation ? 1.0 : 0.0,
            additionalHardClearance: HybridVTOLFlightPolicy
                .genericPlannerUsesWholeTurnHardClearance(
                    airframeClass: selectedDroneProfile.airframeClass
                )
                ? fixedWingPlannerAdditionalHardClearance(
                    to: plannedGoal,
                    targetAltitude: travelAltitude,
                    wing: activeFixedWingParameters()
                )
                : 0.0,
            modeTag: "auto_flight",
            forceRecompute: forceReplan,
            reason: recomputeReason
        )

        if selectedDroneProfile.airframeClass == .fixedWing {
            navigationSnapshot = autoPathPlanner.snapshot(currentPosition: state.position)
            let output = applyAutopilotTrackingControl(
                target: plannedGoal,
                targetAltitude: travelAltitude,
                speedScale: collisionAnalysis.riskScore >= 0.55 ? 0.45 : 1.0,
                yawAlignToHome: false,
                deltaTime: deltaTime
            )

            if output?.hasCompletedRoute == true ||
                autoPathPlanner.hasReachedGoal(
                    currentPosition: state.position,
                    threshold: activeFixedWingParameters().waypointAcceptanceRadiusMeters
                ) {
                autoFlightGoal = nextAutoPatrolGoal(resetCycle: false)
                autoPathPlanner.invalidate()
            }
            return
        }

        autoPathPlanner.updateProgress(
            currentPosition: state.position,
            arrivalRadius: selectedDroneProfile.airframeClass == .multirotor
                ? 1.6
                : max(3.4, selectedDroneProfile.fixedWingParameters?.waypointAcceptanceRadiusMeters ?? 3.4),
            planarOnly: selectedDroneProfile.airframeClass == .multirotor
        )
        navigationSnapshot = autoPathPlanner.snapshot(currentPosition: state.position)

        guard let target = autoPathPlanner.currentTarget() else {
            if selectedDroneProfile.airframeClass == .hybridVTOL,
               autoPathPlanner.hasReachedGoal(
                   currentPosition: state.position,
                   threshold: max(
                       5.0,
                       selectedDroneProfile.fixedWingParameters?.waypointAcceptanceRadiusMeters ?? 5.0
                   )
               ) {
                autoFlightGoal = nextAutoPatrolGoal(resetCycle: false)
                autoPathPlanner.invalidate()
                return
            }
            let holdThrottle = Double(resolvedFlightBaseline(for: .autoPath).cruiseReferenceThrottle)
            updateControlValues({ values in
                values.roll = 0.0
                values.pitch = 0.0
                values.throttle = max(values.throttle, holdThrottle)
                if selectedDroneProfile.airframeClass == .hybridVTOL {
                    values.vtolTransitionLever = state.vtolTransitionProgress > 0.08 ? -1.0 : 0.0
                }
            }, markManual: false)
            return
        }

        let output = applyAutopilotTrackingControl(
            target: target,
            targetAltitude: travelAltitude,
            speedScale: collisionAnalysis.riskScore >= 0.55 ? 0.45 : 1.0,
            yawAlignToHome: false,
            deltaTime: deltaTime
        )
        if selectedDroneProfile.airframeClass == .hybridVTOL,
           output?.hasCompletedRoute == true ||
            autoPathPlanner.hasReachedGoal(
                currentPosition: state.position,
                threshold: max(
                    5.0,
                    selectedDroneProfile.fixedWingParameters?.waypointAcceptanceRadiusMeters ?? 5.0
                )
            ) {
            autoFlightGoal = nextAutoPatrolGoal(resetCycle: false)
            autoPathPlanner.invalidate()
        }
    }

    private func updateReturnHomePath(deltaTime: Float) {
        let defaultSafeTravelAltitude = min(terrain.maxFlightAltitude - 2.0, max(homePosition.y + 6.0, state.position.y + 2.5))
        let safeTravelAltitude: Float = {
            if selectedDroneProfile.airframeClass == .hybridVTOL {
                return hybridVTOLRouteAltitude(
                    defaultAltitude: max(10.0, homePosition.y + 8.0, state.position.y)
                )
            }
            if selectedDroneProfile.airframeClass == .fixedWing {
                if let fixedWingReturnHomeTravelAltitude {
                    return fixedWingReturnHomeTravelAltitude
                }
                fixedWingReturnHomeTravelAltitude = defaultSafeTravelAltitude
            }
            return defaultSafeTravelAltitude
        }()

        if selectedDroneProfile.airframeClass == .fixedWing, returnHomeStage == .ascend {
            returnHomeStage = .navigate
        }

        switch returnHomeStage {
        case .idle:
            fixedWingReturnHomeTravelAltitude = nil
            returnHomeStage = .ascend
            navigationSnapshot = .idle

        case .ascend:
            navigationSnapshot = .idle
            let ascentThrottle = Double(resolvedFlightBaseline(for: .takeoff).takeoffThrottleReference)
            updateControlValues({ values in
                values.x = Double(state.position.x)
                values.z = Double(state.position.z)
                values.y = Double(safeTravelAltitude)
                values.roll = 0.0
                values.pitch = 0.0
                values.throttle = max(values.throttle, ascentThrottle)
                if selectedDroneProfile.airframeClass == .hybridVTOL {
                    values.vtolTransitionLever = 0.0
                }
            }, markManual: false)

            if state.position.y >= safeTravelAltitude - 0.35 {
                returnHomeStage = .navigate
                autoPathPlanner.invalidate()
            }

        case .navigate:
            let goal = clampToWorldBounds(SIMD3<Float>(homePosition.x, safeTravelAltitude, homePosition.z))
            var recomputeReason = "rth_navigate"
            var forceReplan = false
            if let reason = autoPathPlanner.replanReasonIfNeeded(
                currentPosition: state.position,
                collisionRisk: collisionAnalysis.riskScore,
                deviationTolerance: max(4.0, terrain.worldHalfExtent * 0.04)
            ) {
                recomputeReason = reason
                forceReplan = true
            }

            autoPathPlanner.planIfNeeded(
                start: state.position,
                goal: goal,
                terrain: terrain,
                obstacles: navigationObstaclesIncludingNoFlyZones(),
                obstacleSignature: navigationObstacleSignatureIncludingNoFlyZones(),
                droneRadius: activeAirframeUsesWingNavigation
                    ? fixedWingNavigationEnvelopeRadius
                    : selectedDroneProfile.collisionRadius,
                minimumObstacleRadiusFactor: activeAirframeUsesWingNavigation ? 1.0 : 0.0,
                additionalHardClearance: HybridVTOLFlightPolicy
                    .genericPlannerUsesWholeTurnHardClearance(
                        airframeClass: selectedDroneProfile.airframeClass
                    )
                    ? fixedWingPlannerAdditionalHardClearance(
                        to: goal,
                        targetAltitude: safeTravelAltitude,
                        wing: activeFixedWingParameters()
                    )
                    : 0.0,
                modeTag: "return_home",
                forceRecompute: forceReplan,
                reason: recomputeReason
            )

            if selectedDroneProfile.airframeClass == .fixedWing {
                navigationSnapshot = autoPathPlanner.snapshot(currentPosition: state.position)
                _ = applyAutopilotTrackingControl(
                    target: goal,
                    targetAltitude: safeTravelAltitude,
                    speedScale: collisionAnalysis.riskScore >= 0.5 ? 0.42 : 0.78,
                    yawAlignToHome: true,
                    deltaTime: deltaTime
                )

                let horizontalDistance = simd_length(SIMD2<Float>(state.position.x - homePosition.x, state.position.z - homePosition.z))
                let wing = selectedDroneProfile.fixedWingParameters
                let fixedWingArrivalRadius = max(
                    10.0,
                    (wing?.waypointAcceptanceRadiusMeters ?? 5.0) * 1.85
                )
                if horizontalDistance < fixedWingArrivalRadius {
                    returnHomeStage = .align
                    autoPathPlanner.invalidate()
                }
                return
            }

            autoPathPlanner.updateProgress(
                currentPosition: state.position,
                arrivalRadius: selectedDroneProfile.airframeClass == .multirotor
                    ? 1.4
                    : max(
                        6.4,
                        (selectedDroneProfile.fixedWingParameters?.waypointAcceptanceRadiusMeters ?? 3.6) * 1.45
                    ),
                planarOnly: selectedDroneProfile.airframeClass == .multirotor
            )
            navigationSnapshot = autoPathPlanner.snapshot(currentPosition: state.position)

            if let target = autoPathPlanner.currentTarget() {
                applyAutopilotTrackingControl(
                    target: target,
                    targetAltitude: safeTravelAltitude,
                    speedScale: collisionAnalysis.riskScore >= 0.5 ? 0.42 : 0.78,
                    yawAlignToHome: true,
                    deltaTime: deltaTime
                )
            } else {
                let cruiseThrottle = Double(resolvedFlightBaseline(for: .returnHome).cruiseReferenceThrottle)
                updateControlValues({ values in
                    values.roll = 0.0
                    values.pitch = 0.0
                    values.throttle = max(values.throttle, cruiseThrottle)
                }, markManual: false)
            }

            let horizontalDistance = simd_length(SIMD2<Float>(state.position.x - homePosition.x, state.position.z - homePosition.z))
            if selectedDroneProfile.airframeClass == .fixedWing {
                let wing = selectedDroneProfile.fixedWingParameters
                let fixedWingArrivalRadius = max(
                    10.0,
                    (wing?.waypointAcceptanceRadiusMeters ?? 5.0) * 1.85
                )
                if horizontalDistance < fixedWingArrivalRadius {
                    returnHomeStage = .align
                    autoPathPlanner.invalidate()
                }
            } else if selectedDroneProfile.airframeClass == .hybridVTOL {
                let wing = selectedDroneProfile.fixedWingParameters
                let vtolArrivalRadius = max(
                    8.0,
                    (wing?.waypointAcceptanceRadiusMeters ?? 5.0) * 1.45
                )
                if horizontalDistance < vtolArrivalRadius {
                    returnHomeStage = .align
                    autoPathPlanner.invalidate()
                }
            } else if horizontalDistance < 1.5 {
                returnHomeStage = .align
            }

        case .align:
            navigationSnapshot = autoPathPlanner.snapshot(currentPosition: state.position)
            if selectedDroneProfile.airframeClass == .fixedWing {
                let cruiseThrottle = Double(resolvedFlightBaseline(for: .returnHome).cruiseReferenceThrottle)
                applyAutopilotTrackingControl(
                    target: SIMD3<Float>(homePosition.x, max(homePosition.y + 5.0, safeTravelAltitude), homePosition.z),
                    targetAltitude: max(homePosition.y + 5.0, safeTravelAltitude),
                    speedScale: 0.56,
                    yawAlignToHome: false,
                    deltaTime: deltaTime
                )

                let horizontalDistance = simd_length(SIMD2<Float>(state.position.x - homePosition.x, state.position.z - homePosition.z))
                let wing = selectedDroneProfile.fixedWingParameters
                let loiterRadius = max(8.0, (wing?.waypointAcceptanceRadiusMeters ?? 5.0) * 1.4)
                if horizontalDistance < loiterRadius {
                    setFlightMode(.manual, reason: "return_home_fixed_wing_loiter_complete")
                    setFixedWingGuidanceSource(.none, reason: "return_home_fixed_wing_completed")
                    returnHomeStage = .idle
                    autoPathPlanner.invalidate()
                    navigationSnapshot = .idle
                    updateControlValues({ values in
                        values.roll = 0.0
                        values.pitch = max(1.0, min(values.pitch, 5.0))
                        values.yaw = Double(state.orientation.z.radiansToDegrees)
                        values.throttle = max(cruiseThrottle, values.throttle * 0.94)
                    }, markManual: false)
                }
                return
            }

            if selectedDroneProfile.airframeClass == .hybridVTOL {
                let readyForPrecisionHover = hybridVTOLReadyForPrecisionHover()
                let alignmentAltitude = readyForPrecisionHover
                    ? max(homePosition.y + 1.8, state.position.y)
                    : max(homePosition.y + 3.0, state.position.y)
                let alignmentTarget = SIMD3<Float>(
                    homePosition.x,
                    alignmentAltitude,
                    homePosition.z
                )
                let alignmentContext = AutopilotTrackingContext(
                    state: state,
                    physicalState: physicalState,
                    target: alignmentTarget,
                    targetAltitude: alignmentAltitude,
                    speedScale: readyForPrecisionHover ? 0.42 : 0.32,
                    yawAlignToHome: true,
                    yawOverrideRadians: 0.0,
                    deltaTime: deltaTime,
                    flightBaseline: resolvedFlightBaseline(for: .hover)
                )
                applyHybridVTOLHoverAutopilotCommand(
                    context: alignmentContext,
                    target: alignmentTarget,
                    targetAltitude: alignmentAltitude,
                    speedScale: readyForPrecisionHover ? 0.42 : 0.32,
                    yawOverrideRadians: 0.0,
                    vtolTransitionLever: state.vtolTransitionProgress > 0.08 ? -1.0 : 0.0,
                    minimumThrottle: resolvedFlightBaseline(for: .hover).hoverLockThrottle,
                    reason: readyForPrecisionHover
                        ? "vtol_return_home_precision_align"
                        : "vtol_return_home_transition_to_hover",
                    deltaTime: deltaTime
                )
                let horizontalDistance = simd_length(SIMD2<Float>(
                    state.position.x - homePosition.x,
                    state.position.z - homePosition.z
                ))
                if readyForPrecisionHover && horizontalDistance < 0.45 {
                    returnHomeStage = .descend
                }
                return
            }

            let alignmentBaseline = resolvedFlightBaseline(for: .returnHome)
            let alignmentThrottle = Double(
                alignmentBaseline.hoverCapable
                    ? alignmentBaseline.hoverLockThrottle
                    : alignmentBaseline.cruiseReferenceThrottle
            )
            updateControlValues({ values in
                values.x = Double(homePosition.x)
                values.z = Double(homePosition.z)
                values.y = Double(max(homePosition.y + 1.8, state.position.y))
                values.roll = 0.0
                values.pitch = 0.0
                values.yaw = 0.0
                values.throttle = max(alignmentThrottle, values.throttle * 0.96)
                if selectedDroneProfile.airframeClass == .hybridVTOL {
                    values.vtolTransitionLever = 0.0
                }
            }, markManual: false)

            let horizontalDistance = simd_length(SIMD2<Float>(state.position.x - homePosition.x, state.position.z - homePosition.z))
            if horizontalDistance < 0.45 {
                returnHomeStage = .descend
            }

        case .descend:
            navigationSnapshot = autoPathPlanner.snapshot(currentPosition: state.position)
            if selectedDroneProfile.airframeClass == .hybridVTOL,
               !hybridVTOLReadyForPrecisionHover() {
                returnHomeStage = .align
                return
            }
            let landingThrottle = Double(resolvedFlightBaseline(for: .landing).landingThrottleReference)
            updateControlValues({ values in
                values.x = Double(homePosition.x)
                values.z = Double(homePosition.z)
                values.y = Double(homePosition.y)
                values.roll = 0.0
                values.pitch = 0.0
                values.yaw = 0.0
                values.throttle = max(0.22, min(values.throttle, landingThrottle))
                if selectedDroneProfile.airframeClass == .hybridVTOL {
                    values.vtolTransitionLever = -1.0
                }
            }, markManual: false)

            let horizontalDistance = simd_length(SIMD2<Float>(state.position.x - homePosition.x, state.position.z - homePosition.z))
            if horizontalDistance < 0.4 && state.position.y <= homePosition.y + 0.10 && abs(state.velocity.y) < 0.25 {
                setFlightMode(.manual, reason: "return_home_landing_complete")
                setFixedWingGuidanceSource(.none, reason: "return_home_completed")
                returnHomeStage = .idle
                autoPathPlanner.invalidate()
                navigationSnapshot = .idle
                updateControlValues({ values in
                    values.y = Double(homePosition.y)
                    values.throttle = 0.0
                    values.roll = 0.0
                    values.pitch = 0.0
                    values.yaw = 0.0
                }, markManual: false)
            }
        }
    }

    private func updateHybridVTOLLandingCommand(deltaTime: Float) {
        guard selectedDroneProfile.airframeClass == .hybridVTOL else {
            return
        }

        let readyForDescent = hybridVTOLReadyForPrecisionHover()
        let targetAltitude = readyForDescent
            ? homePosition.y
            : max(homePosition.y + 1.8, state.position.y)
        let target = SIMD3<Float>(
            state.position.x,
            targetAltitude,
            state.position.z
        )
        let baseline = resolvedFlightBaseline(for: readyForDescent ? .landing : .hover)
        let context = AutopilotTrackingContext(
            state: state,
            physicalState: physicalState,
            target: target,
            targetAltitude: targetAltitude,
            speedScale: readyForDescent ? 0.35 : 0.50,
            yawAlignToHome: false,
            yawOverrideRadians: state.orientation.z,
            deltaTime: deltaTime,
            flightBaseline: baseline
        )
        applyHybridVTOLHoverAutopilotCommand(
            context: context,
            target: target,
            targetAltitude: targetAltitude,
            speedScale: readyForDescent ? 0.35 : 0.50,
            yawOverrideRadians: state.orientation.z,
            vtolTransitionLever: -1.0,
            minimumThrottle: readyForDescent ? nil : baseline.hoverLockThrottle,
            reason: readyForDescent ? "vtol_vertical_landing" : "vtol_transition_to_hover_before_landing",
            deltaTime: deltaTime
        )
    }

    @discardableResult
    private func applyAutopilotTrackingControl(
        target: SIMD3<Float>,
        targetAltitude: Float,
        speedScale: Float,
        yawAlignToHome: Bool,
        deltaTime: Float,
        yawOverrideRadians: Float? = nil
    ) -> FixedWingAutopilotOutput? {
        let speedBoost: Float = (simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z)) < 1.0 && speedScale > 0.6) ? 1.2 : 1.0
        let controlScale = speedScale * speedBoost
        let flightBaseline = resolvedFlightBaseline(for: mode)
        let context = AutopilotTrackingContext(
            state: state,
            physicalState: physicalState,
            target: target,
            targetAltitude: targetAltitude,
            speedScale: controlScale,
            yawAlignToHome: yawAlignToHome,
            yawOverrideRadians: yawOverrideRadians,
            deltaTime: deltaTime,
            flightBaseline: flightBaseline,
            heightAboveSurfaceMeters: heightAboveSupportSurface(for: state.position)
        )

        switch selectedDroneProfile.airframeClass {
        case .multirotor:
            setFixedWingGuidanceSource(.none, reason: "multicopter_autopilot_active")
            let command = multicopterAutopilotController.command(for: context)
            fixedWingAutopilotDebugState = .idle
            applyAutopilotCommand(command, deltaTime: deltaTime)
            return nil
        case .fixedWing:
            return applyFixedWingAutopilotTracking(
                context: context,
                target: target,
                deltaTime: deltaTime
            )
        case .hybridVTOL:
            return applyHybridVTOLAutopilotTracking(
                context: context,
                deltaTime: deltaTime
            )
        }
    }

    @discardableResult
    private func applyFixedWingAutopilotTracking(
        context: AutopilotTrackingContext,
        target: SIMD3<Float>,
        deltaTime: Float,
        vtolTransitionLever: Double? = nil,
        routeTrackingOverride: FixedWingRouteTrackingContext? = nil
    ) -> FixedWingAutopilotOutput? {
        let fixedWingGuidanceSource = fixedWingGuidanceSourceForCurrentRoute()
        setFixedWingGuidanceSource(fixedWingGuidanceSource, reason: "fixed_wing_autopilot_tracking")

        let routeTracking = routeTrackingOverride ??
            currentFixedWingRouteTrackingContext(fallbackTarget: target)
        let missionSpeedConstraints = fixedWingGuidanceSource == .mission ? currentMissionPlan?.constraints.speed : nil
        let output = fixedWingAutopilotController.trackingCommand(
            for: context,
            parameters: activeFixedWingParameters(),
            launchMode: activeLaunchMode(),
            launchAsset: activeLaunchAsset(),
            routeTracking: routeTracking,
            missionMinAirspeed: missionSpeedConstraints?.minimumMetersPerSecond,
            missionMaxAirspeed: missionSpeedConstraints.map {
                $0.effectiveMaximum(profileMaxSpeed: activeFixedWingParameters().maxAirspeed)
            },
            useHybridVTOLCruiseStabilization: selectedDroneProfile.airframeClass == .hybridVTOL
        )
        fixedWingAutopilotAltitudeCommand = output.command.positionTarget.y
        fixedWingAutopilotCourseCommand = output.command.yawDegrees.degreesToRadians
        fixedWingLatestAutopilotRollCommandDegrees = output.command.rollDegrees
        fixedWingLatestAutopilotCourseCommandRadians = output.command.yawDegrees
            .degreesToRadians
        fixedWingLastTransitionReason = output.transitionReason
        fixedWingAutopilotDebugState = output.debugState
        updateFixedWingNavigationSnapshot(
            routeTracking: routeTracking,
            debugState: output.debugState
        )

        // Hand/catapult launch is owned exclusively by
        // `fixedWingLaunchController`. The legacy route-autopilot launch phase
        // must never overwrite its release/climb state while the new sequence
        // is active (or after it has produced a terminal snapshot).
        if launchRuntimeSnapshot.state == .idle {
            if output.launchPhase != nil {
                updateLegacyLaunchState(
                    legacyLaunchState(for: output, launchMode: activeLaunchMode()),
                    deltaTime: deltaTime
                )
            } else if launchState != .idle,
                      activeLaunchMode() == .standard {
                updateLegacyLaunchState(.completed)
            }
        }

        if output.phase == .failed {
            // Planner timeout/unreachable is not a reason to abandon a non-hovering aircraft to
            // manual continuation. Keep AUTO authority: the controller supplies a level/climb
            // command and the always-on swept avoidance layer below can still choose an escape.
            setFixedWingGuidanceSource(
                fixedWingGuidanceSource,
                reason: "fixed_wing_route_blocked_holding_auto"
            )
            if output.transitionReason == "fly_by_entry_missed_replan"
                || output.transitionReason == "fly_by_envelope_changed_replan"
                || output.transitionReason == "fly_by_geometry_invalid_replan" {
                // The old runtime join is behind the aircraft. Re-anchor it at the physical
                // position and clear only controller capture state; next tick rebuilds and
                // validates a new route instead of accepting the corner late.
                fixedWingAutopilotController.reset()
                resetFixedWingRuntimeRouteStart()
            }
        }

        applyAutopilotCommand(
            output.command,
            deltaTime: deltaTime,
            vtolTransitionLever: vtolTransitionLever
        )
        return output
    }

    private func fixedWingGuidanceSourceForCurrentRoute() -> FixedWingGuidanceSource {
        if mode == .returnHome {
            return .returnHome
        }
        if activeRouteTargetSource == .mission {
            return .mission
        }
        if targetMarkerState != nil {
            return .marker
        }
        return activeFixedWingGuidanceSource == .none ? .mission : activeFixedWingGuidanceSource
    }

    /// Whether the planner answered with a maze rather than a detour.
    ///
    /// Length against the straight line, measured in the plane — the route sits at one altitude, so
    /// a 3-D length would only add the aircraft's own height error to the comparison. A two-point
    /// route is by definition the straight line and can never qualify.
    private func hybridVTOLRouteIsMaze(
        route: FixedWingRouteTrackingContext?,
        finalTarget: SIMD3<Float>
    ) -> Bool {
        guard let route, route.waypoints.count >= 3 else { return false }
        let planarPoints = route.waypoints.map { SIMD2<Float>($0.position.x, $0.position.z) }
        let plannedLength = zip(planarPoints, planarPoints.dropFirst())
            .reduce(Float(0.0)) { $0 + simd_distance($1.0, $1.1) }
        let directLength = simd_distance(
            SIMD2<Float>(state.position.x, state.position.z),
            SIMD2<Float>(finalTarget.x, finalTarget.z)
        )
        guard plannedLength.isFinite,
              directLength.isFinite,
              directLength > Self.hybridVTOLRouteMazeMinimumDirectMeters else {
            return false
        }
        return plannedLength > directLength * Self.hybridVTOLRouteMazeLengthRatio
    }

    @discardableResult
    private func applyHybridVTOLAutopilotTracking(
        context: AutopilotTrackingContext,
        deltaTime: Float
    ) -> FixedWingAutopilotOutput? {
        let wing = activeFixedWingParameters()
        let baseRouteAltitude = hybridVTOLRouteAltitude(defaultAltitude: context.targetAltitude)
        let routeAltitudeCeiling = max(6.0, terrain.maxFlightAltitude - 2.0)
        let routeAltitude = min(
            routeAltitudeCeiling,
            baseRouteAltitude + hybridVTOLRouteAltitudeLift
        )
        // Anchor the navigation band before any branch runs, so the obstacle set this tick plans
        // against cannot depend on the branch that tick's plan produces.
        hybridVTOLNavigationBandAltitude = routeAltitude
        let finalTarget = hybridVTOLActiveLegTarget(
            context: context,
            routeAltitude: routeAltitude
        )
        let protectedRoute = currentFixedWingRouteTrackingContext(
            fallbackTarget: finalTarget
        )
        let routeGuidance = hybridVTOLRouteCursor.update(
            route: protectedRoute,
            expectedFinalTarget: finalTarget,
            position: state.position,
            controllerDebug: fixedWingAutopilotDebugState,
            intermediateRadius: max(
                2.0,
                min(5.0, fixedWingNavigationEnvelopeRadius + 1.0)
            ),
            corridorRadius: max(
                6.0,
                fixedWingNavigationEnvelopeRadius + 3.0
            ),
            planarSpeed: simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        )
        switch routeGuidance.status {
        case .ready:
            hybridVTOLRouteGuidanceDiagnostic = "ready"
        case .blocked(let reason):
            hybridVTOLRouteGuidanceDiagnostic = reason
        }
        #if DEBUG
        // Which node the cursor is on, which route it belongs to, and how far the aircraft is from
        // it. A stop-and-pivot aircraft that stops making progress does so for one of exactly two
        // reasons, and only these three fields separate them: the node index standing still while
        // `nodeDist` refuses to fall below the capture radius (the aircraft cannot hold position
        // tightly enough to be credited with reaching the node), or the index resetting because the
        // route identifier changed underneath it (the plan is being rebuilt, not followed).
        // Route *shape*, not just cursor position.
        //
        // A flight showed the first route node 790 m away on a mission whose whole four-waypoint
        // path is 678 m, and the aircraft flew to it faithfully — the guidance was correct, the
        // route was not. Three different causes produce that one symptom and each is fixed
        // somewhere else, so log the three numbers that separate them:
        //
        //   src   which target the route was built to — a mission waypoint, a manual marker, or
        //         the auto-patrol goal, which is scattered anywhere in a 6.4 km world;
        //   pts   node count: a two-point route means no detour was planned at all;
        //   len   total planned path length against `dir`, the straight line to the target.
        //
        // len ≈ dir with pts=2 means the goal itself is wrong; len ≫ dir with many points is a
        // genuine detour around blocked geometry; len ≫ dir with 2-3 points means compaction
        // collapsed the middle and the "straight" leg is not actually clear.
        let routePoints = protectedRoute?.waypoints.map(\.position) ?? []
        let routeLength: Float = routePoints.count >= 2
            ? zip(routePoints, routePoints.dropFirst()).reduce(0.0) { $0 + simd_distance($1.0, $1.1) }
            : -1.0
        let planarPosition = SIMD2<Float>(state.position.x, state.position.z)
        hybridVTOLRouteNodeDiagnostic = String(
            format: "%@/%d@%.1f src=%@ pts=%d len=%.0f dir=%.0f",
            (routeGuidance.routeIdentifier.map {
                String(format: "%04x", UInt16(truncatingIfNeeded: $0.hashValue))
            } ?? "----") as NSString,
            routeGuidance.activeRouteIndex ?? -1,
            Double(
                routeGuidance.guidanceTarget.map {
                    simd_distance(planarPosition, SIMD2<Float>($0.x, $0.z))
                } ?? -1.0
            ),
            {
                switch activeRouteTargetSource {
                case .mission: return "mission"
                case .manualMarker: return "marker"
                case .none: return "none"
                }
            }() as NSString,
            routePoints.count,
            Double(routeLength),
            Double(simd_distance(planarPosition, SIMD2<Float>(finalTarget.x, finalTarget.z)))
        )
        #endif
        if routeGuidance.isReady {
            hybridVTOLProtectedRouteHoldPosition = nil
        } else {
            hybridVTOLStopAndPivotGate.reset()
            // No route means no leg to commit to; the next one decides for itself.
            hybridVTOLTransitionCommitted = false
        }
        // A blocked route and a route that is mostly detour are the same complaint — there is no
        // room at this altitude — and they have always had the same answer. Only the first one was
        // ever asked.
        //
        // The ladder used to run solely when planning *failed*. A city planner rarely fails; it
        // succeeds, with a street maze. Measured on a WingtraOne over the Financial District at
        // 29 m: the 797 m leg came back `pts=61 len=1616` — sixty-one nodes about five metres
        // apart, each one a stop-and-pivot between façades. That single artifact is both the
        // "коридор" and the crawl the operator reported, and every node of it was certified clear,
        // so nothing downstream had grounds to object. The direct line was rejected there for
        // 2.35 m of penetration; the same line certified with 17.8 m to spare once the aircraft
        // reached 89 m — which it only ever got to for unrelated reasons, two thirds of the way in.
        //
        // So a plan that is mostly detour now buys a climb, exactly as no plan does. The lift is
        // held rather than released the moment a route appears, so the aircraft does not sink back
        // into the altitude that had none and start the cycle over; it is released with the rest of
        // the leg state when the route is reset.
        let routeWantsAltitude = !routeGuidance.isReady
            || hybridVTOLRouteIsMaze(route: protectedRoute, finalTarget: finalTarget)
        if routeWantsAltitude {
            hybridVTOLRouteBlockedSeconds += deltaTime
            if hybridVTOLRouteBlockedSeconds >= Self.hybridVTOLRouteLiftDelaySeconds,
               routeAltitude < routeAltitudeCeiling - 0.5,
               // A climb is only an escape while the way up is open. Anything overhead is a
               // reason to keep waiting rather than to press into it.
               collisionAnalysis.riskScore < 0.55 {
                hybridVTOLRouteAltitudeLift = min(
                    hybridVTOLRouteAltitudeLift + Self.hybridVTOLRouteLiftStepMeters,
                    max(0.0, routeAltitudeCeiling - baseRouteAltitude)
                )
                hybridVTOLRouteBlockedSeconds = 0.0
            }
        } else {
            hybridVTOLRouteBlockedSeconds = 0.0
            // No descent ratchet here, and the omission is deliberate.
            //
            // One was tried: release a storey after six seconds of continuously ready route. It
            // stalled an aircraft outright. Measured on the next flight — `lift=24` (route altitude
            // 41.3 m) gave `ready` in 110 of 112 samples; `lift=12` (29.3 m) gave
            // `route_unavailable:point_safe_route_rejected` in 38 of 39, because the lower band
            // pulled 15 217 obstacles into consideration instead of 5 734. So the ladder dropped a
            // storey every six seconds, killed the route, spent two seconds blocked, climbed back,
            // and repeated. The aircraft closed **two metres** toward its waypoint in the whole
            // flight.
            //
            // The flaw is not the delay, it is the evidence. "The route is ready" cannot license a
            // descent, because the route is ready *because of the lift*: acting on that evidence
            // destroys it. A sound release would have to show the route still stands one storey
            // lower, which costs a second certification at a hypothetical altitude — worth building
            // if the lift ever needs to come down mid-mission. It does not today: the collapses
            // that made this look necessary were the two resets above discarding the ladder, and
            // those are fixed. What remains is an aircraft that keeps the altitude its worst leg
            // needed, which is safe and which no measured flight has complained about.
        }
        var decision = hybridVTOLAutopilotDecision(
            context: context,
            wing: wing,
            routeAltitude: routeAltitude,
            finalTarget: finalTarget,
            routeGuidance: routeGuidance
        )
        vtolAutopilotPhase = decision.phase
        // The safety verdict stops here otherwise. It is the only thing that knows *why* the
        // aircraft is holding — low battery, insufficient altitude, damage, a blocked corridor —
        // and none of that reached the operator, who saw a VTOL sit in a hover with no explanation
        // until the mission monitor eventually reported a stall, which is the symptom rather than
        // the cause. `DroneWarningBuilder` turns it into a warning.
        hybridVTOLSafetyState = decision.safetyState
        decision.targetAltitude = hybridVTOLSinkLimitedAltitude(
            decision.targetAltitude,
            phase: decision.phase,
            maxSinkRate: decision.maxSinkRate
        )

        // Rotor-borne translation gets the same lateral sidestep a multirotor gets.
        //
        // Until now a hybrid VTOL had no avoidance layer of its own in either regime: the
        // predictive corridor proof was gated on `airframeClass == .fixedWing` and this sidestep on
        // `== .multirotor`, so the only thing standing between a translating Wingcopter and a
        // façade was `handleAutoCollisionInterventions` — a risk >= 0.65 emergency that stops or
        // backs off 4 m, not something that flies around anything.
        //
        // Applied to the decision's target rather than inside the hover command so the phase
        // machine, the speed scale and the vertical channel all keep their own logic; only where it
        // is heading changes.
        switch decision.phase {
        case .hoverHold, .precisionHover, .transitionToHover, .emergencyHover:
            // Stop-and-pivot holds are route geometry, not generic nominal targets. The sidestep
            // helper falls back to the final waypoint when nominal == current pose; applying it
            // while aligning would move 4–8 m across the certified A* corner.
            guard HybridVTOLFlightPolicy.allowsReactiveHoverSidestep(
                decisionReason: decision.reason
            ) else {
                // Silence here is a decision, not an absence, so say so: without this line a
                // missing `[Sidestep]` could mean either "the layer found nothing" or "the layer
                // was never asked", and those need opposite fixes.
                noteRotorBorneSidestep("not_called_policy:\(decision.reason)")
                break
            }
            if let adjusted = multirotorCollisionAvoidanceTarget(
                nominalTarget: decision.target,
                finalGoal: finalTarget,
                travelAltitude: decision.targetAltitude
            ) {
                decision.target = adjusted
                // Moving the target was never going to be enough on its own.
                //
                // The sidestep places its target four to eight metres ahead and up to a few metres
                // to the side. A hovering rotorcraft answers a displaced target with lean, and lean
                // buys about 2.8 m/s² of lateral acceleration — perfectly adequate at the walking
                // speeds this helper was written for, and meaningless to an aircraft that has just
                // put the wing away and is still carrying 24 m/s, where those eight metres are a
                // third of a second away. The neighbouring `transitionToCruise` branch already
                // draws that conclusion and cuts to 0.45; the same obstacle in front of the same
                // airframe in hover deserves the same answer, so this is that number rather than a
                // new one.
                decision.speedScale = min(decision.speedScale, 0.45)
            }
        case .transitionToCruise:
            // The gap where nothing was watching.
            //
            // Coverage is split by regime: the forward corridor proof owns the aircraft once
            // `vtolWingborneAvoidanceLatched` is set, and the sidestep owns it while it is not. The
            // latch engages at `wb >= 0.65` and releases at `wb < 0.45`, so a transition sitting
            // anywhere between those two had neither — the wing layer refused it as not yet an
            // aeroplane, and this switch refused it as no longer a rotorcraft.
            //
            // A Wingcopter flew into a building through exactly that gap, climbing at `vy=5.66`
            // with `wb=0.47 wbLatch=no fwdCov=no avOff=clear`: the layer was not reporting a clear
            // corridor, it was not running at all. `criticalImpact ... vN=15.65`.
            //
            // While the latch is off the aircraft is still rotor-borne enough to slide, so it gets
            // the sidestep — and it also gets told to stop accelerating into whatever it is sliding
            // around. Half speed is what the neighbouring protective branches already use for
            // "something is there": `transitionToHover` for a waypoint runs at 0.42 and the blocked
            // hold at 0.25, so a transition with an obstacle live in front of it belongs between
            // them rather than at full cruise scale. Judgement, stated here rather than buried.
            if !vtolWingborneAvoidanceLatched,
               HybridVTOLFlightPolicy.allowsReactiveHoverSidestep(
                   decisionReason: decision.reason
               ),
               let adjusted = multirotorCollisionAvoidanceTarget(
                   nominalTarget: decision.target,
                   finalGoal: finalTarget,
                   travelAltitude: decision.targetAltitude
               ) {
                decision.target = adjusted
                decision.speedScale = min(decision.speedScale, 0.45)
            }
        case .idleGrounded, .verticalTakeoff, .verticalLanding, .forcedLanding,
             .transitionAbort, .wingborneCruise:
            // `wingborneCruise` belongs to the forward corridor layer and the rest are not
            // translating at all, so no sidestep is expected — but the phase still has to appear,
            // or a strike in one of them reads as the sidestep having failed.
            noteRotorBorneSidestep("not_called_phase:\(decision.phase)")
        }

        switch decision.phase {
        case .idleGrounded, .hoverHold, .precisionHover:
            applyHybridVTOLHoverAutopilotCommand(
                context: context,
                target: decision.target,
                targetAltitude: decision.targetAltitude,
                speedScale: decision.speedScale,
                yawOverrideRadians: decision.targetHeading ?? context.yawOverrideRadians,
                vtolTransitionLever: decision.transitionLever,
                minimumThrottle: nil,
                reason: decision.reason,
                deltaTime: deltaTime
            )
            return nil
        case .verticalTakeoff:
            applyHybridVTOLHoverAutopilotCommand(
                context: context,
                target: decision.target,
                targetAltitude: decision.targetAltitude,
                speedScale: decision.speedScale,
                yawOverrideRadians: decision.targetHeading ?? context.yawOverrideRadians,
                vtolTransitionLever: decision.transitionLever,
                minimumThrottle: resolvedFlightBaseline(for: .takeoff).takeoffThrottleReference,
                reason: decision.reason,
                deltaTime: deltaTime
            )
            return nil
        case .transitionToHover, .transitionAbort, .emergencyHover, .forcedLanding, .verticalLanding:
            let throttleFloor: Float?
            switch decision.phase {
            case .emergencyHover:
                // The altitude controller must be able to command below
                // hover thrust to arrest an existing climb. Its neutral
                // command already is hoverLockThrottle, so an extra floor
                // adds no lift safety and turns "hold" into a one-way climb.
                throttleFloor = nil
            case .forcedLanding, .verticalLanding:
                throttleFloor = resolvedFlightBaseline(for: .landing).landingThrottleReference
            default:
                throttleFloor = nil
            }
            applyHybridVTOLHoverAutopilotCommand(
                context: context,
                target: decision.target,
                targetAltitude: decision.targetAltitude,
                speedScale: decision.speedScale,
                yawOverrideRadians: decision.targetHeading ?? context.yawOverrideRadians,
                vtolTransitionLever: decision.transitionLever,
                minimumThrottle: throttleFloor,
                reason: decision.reason,
                deltaTime: deltaTime
            )
            return nil
        case .transitionToCruise:
            applyHybridVTOLTransitionToCruiseCommand(
                context: context,
                decision: decision,
                wing: wing,
                routeAltitude: routeAltitude,
                deltaTime: deltaTime
            )
            // The transition has no speed loop of its own — the fixed-wing controller does not own
            // throttle until cruise — so this is the only thing standing between a VTOL and an
            // unbounded acceleration once its rotors point forward.
            applyHybridVTOLAirspeedLimit(decision.targetAirspeed, wing: wing)
            return nil
        case .wingborneCruise:
            var cruiseRoute = protectedRoute
            if let activeRouteIndex = routeGuidance.activeRouteIndex,
               var synchronizedRoute = cruiseRoute {
                // `FixedWingAutopilotController` converts this external route index to its
                // internal target index by subtracting one. Advancing the minimum by one keeps the
                // wing controller on the cursor's current detour node instead of sending a newly
                // transitioned VTOL back to an already-crossed corner.
                synchronizedRoute.minimumWaypointIndex = max(
                    synchronizedRoute.minimumWaypointIndex ?? 0,
                    activeRouteIndex + 1
                )
                cruiseRoute = synchronizedRoute
            }
            let cruiseContext = AutopilotTrackingContext(
                state: state,
                physicalState: physicalState,
                target: finalTarget,
                targetAltitude: routeAltitude,
                speedScale: context.speedScale,
                yawAlignToHome: context.yawAlignToHome,
                yawOverrideRadians: decision.targetHeading ?? context.yawOverrideRadians,
                deltaTime: context.deltaTime,
                flightBaseline: context.flightBaseline
            )
            let cruiseTracking = applyFixedWingAutopilotTracking(
                context: cruiseContext,
                target: finalTarget,
                deltaTime: deltaTime,
                vtolTransitionLever: 1.0,
                routeTrackingOverride: cruiseRoute
            )
            // Backs up the wing controller's own speed loop rather than competing with it: it can
            // only lower throttle, and only above the requested speed, so where that loop is
            // already slowing down this changes nothing.
            applyHybridVTOLAirspeedLimit(decision.targetAirspeed, wing: wing)
            return cruiseTracking
        }
    }

    /// Bounds a commanded descent to the sink rate the decision asked for.
    ///
    /// `VTOLAutopilotDecision.maxSinkRate` — the airframe's nominal sink rate plus a third — was
    /// computed on every tick and read by nobody, so guidance had no descent limit at all. The
    /// physics step has one, but it is the airframe's *absolute* limit (`maxDescentSpeedMps`, up
    /// to 20 m/s), which is an airframe survival bound, not a thing an autopilot should ever fly
    /// at. An unbounded descent is also how height became speed on this airframe: at these
    /// lift-to-drag ratios a couple of degrees nose-down contributes an along-path weight
    /// component about the size of the whole engine's thrust.
    ///
    /// Deliberately a rate guard rather than a shaped descent profile, and deliberately with no
    /// tuning constant of its own: while the aircraft is already sinking faster than allowed it
    /// simply stops asking to go lower than where it is, and the altitude controller arrests. Once
    /// back inside the limit the descent resumes. Climbs are never touched, and neither is a
    /// landing — descending to the ground is the entire point of those phases.
    private func hybridVTOLSinkLimitedAltitude(
        _ targetAltitude: Float,
        phase: VTOLAutopilotPhase,
        maxSinkRate: Float
    ) -> Float {
        switch phase {
        case .verticalLanding, .forcedLanding:
            return targetAltitude
        case .idleGrounded, .hoverHold, .precisionHover, .verticalTakeoff, .transitionToHover,
             .transitionAbort, .emergencyHover, .transitionToCruise, .wingborneCruise:
            break
        }
        guard maxSinkRate.isFinite, maxSinkRate > 0.05,
              targetAltitude < state.position.y,
              state.velocity.y < -maxSinkRate else {
            return targetAltitude
        }
        return max(targetAltitude, state.position.y)
    }

    /// Holds a wing-borne VTOL to the airspeed its own decision asked for.
    ///
    /// `VTOLAutopilotDecision.targetAirspeed` was computed on every cruise and transition tick and
    /// then read by nobody — so there was no airspeed hold anywhere in VTOL guidance. Recorded
    /// flights cruised at 40-44 m/s against 17-22 m/s published figures, and since turn radius goes
    /// as the square of speed, every route margin derived from the profile's cruise figure was out
    /// by four to seven times. That is why aircraft flew into buildings they had detected: they
    /// could not turn in anything like the radius the planner had assumed.
    ///
    /// This is envelope protection, not a second controller. It only ever *lowers* throttle, and
    /// only above the requested speed, so it cannot fight the fixed-wing speed loop that owns
    /// throttle during cruise — it agrees with it and backs it up where that loop does not run at
    /// all (the transition). Both anchors are published numbers rather than invented ones: at the
    /// target speed the ceiling is exactly `cruiseReferenceThrottle`, which the thrust map defines
    /// as level flight at cruise, and it reaches idle at the airframe's own `maxAirspeed`.
    ///
    /// It needs the throttle floor to have been fixed to be worth anything: while the wing-borne
    /// floor sat at `cruiseReferenceThrottle`, the physics step clamped any lower command straight
    /// back up and no ceiling below cruise power could take effect.
    private func applyHybridVTOLAirspeedLimit(
        _ targetAirspeed: Float?,
        wing: FixedWingParameters
    ) {
        guard let targetAirspeed, targetAirspeed.isFinite, targetAirspeed > 0.5 else {
            return
        }
        let planarSpeed = simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        let airspeed = max(state.forwardAirspeed, planarSpeed)
        guard airspeed.isFinite, airspeed > targetAirspeed else {
            return
        }
        let ceilingSpeed = max(targetAirspeed + 1.0, wing.maxAirspeed)
        let overspeed = ((airspeed - targetAirspeed) / (ceilingSpeed - targetAirspeed))
            .clamped(to: 0.0...1.0)
        let cruiseReference = resolvedFlightBaseline().cruiseReferenceThrottle
        let throttleCeiling = Double(max(0.0, cruiseReference * (1.0 - overspeed)))
        updateControlValues({ values in
            values.throttle = min(values.throttle, throttleCeiling)
        }, markManual: false)
    }

    private func hybridVTOLAutopilotDecision(
        context: AutopilotTrackingContext,
        wing: FixedWingParameters,
        routeAltitude: Float,
        finalTarget: SIMD3<Float>,
        routeGuidance: HybridVTOLRouteGuidance
    ) -> VTOLAutopilotDecision {
        let target = routeGuidance.guidanceTarget ?? finalTarget
        let currentPlanar = SIMD2<Float>(state.position.x, state.position.z)
        let finalTargetPlanar = SIMD2<Float>(finalTarget.x, finalTarget.z)
        let targetPlanar = SIMD2<Float>(target.x, target.z)
        let routeVector = targetPlanar - currentPlanar
        let planarDistance = simd_length(routeVector)
        let finalPlanarDistance = simd_distance(currentPlanar, finalTargetPlanar)
        let planarSpeed = simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        let airspeed = max(state.forwardAirspeed, planarSpeed)
        let liftRatio = max(state.vtolWingLiftRatio, state.vtolWingborneBlend)
        let routeYaw: Float? = planarDistance > 0.5
            ? fixedWingCourseRadians(from: routeVector)
            : context.yawOverrideRadians
        let stopAndPivotHoverHeading = selectedDroneProfile.airframeStyle == .tailsitterVTOL
            ? tailsitterHoverHeadingRadians()
            : state.orientation.z
        let stopAndPivotYawRate = HybridVTOLFlightPolicy.stopAndPivotYawRate(
            isTailsitter: selectedDroneProfile.airframeStyle == .tailsitterVTOL,
            tailsitterBodyXRate: state.bodyAngularVelocity.x,
            conventionalYawRate: state.angularVelocity.z
        )
        let stopAndPivotGuidance = hybridVTOLStopAndPivotGate.update(
            traversalMode: routeGuidance.traversalMode,
            routeIdentifier: routeGuidance.routeIdentifier,
            routeIndex: routeGuidance.activeRouteIndex,
            position: state.position,
            planarSpeed: planarSpeed,
            headingErrorRadians: routeYaw.map {
                shortestAngleRadians($0 - stopAndPivotHoverHeading)
            } ?? 0.0,
            yawRateRadiansPerSecond: stopAndPivotYawRate
        )
        let precisionRadius = hybridVTOLPrecisionEntryRadius(wing: wing)
        let cruiseEntryDistance = hybridVTOLCruiseEntryDistance(wing: wing, precisionRadius: precisionRadius)
        let cruiseExitDistance = hybridVTOLCruiseExitDistance(wing: wing, precisionRadius: precisionRadius)
        let cruiseWasEstablished = vtolAutopilotPhase == .wingborneCruise
        // Decide the regime once per leg, from the whole leg.
        //
        // A VTOL pays for cruise twice — one transition out of hover and one back into it — so the
        // question is whether the leg is long enough to earn that, and the answer cannot change
        // while the aircraft is flying it. `cruiseEntryDistance` is roughly a cruise turn radius,
        // and legs of a city mission are frequently the same order; evaluated against the
        // *remaining* distance it therefore flips from true to false partway along every leg. This
        // reads it at the moment the leg becomes active and holds it. See
        // `vtolActiveLegTargetPlanar`.
        if routeGuidance.isReady {
            let legChanged = vtolActiveLegTargetPlanar.map {
                simd_distance($0, finalTargetPlanar) > 1.0
            } ?? true
            if legChanged {
                vtolActiveLegTargetPlanar = finalTargetPlanar
                // Does the turn at the end of this leg fit the radius the aircraft will actually
                // fly it at? If not, the leg ends in a stop-and-pivot instead of a fly-through —
                // which is the whole point of having rotors. What it must *not* do is fly the
                // corner wide: a 140 m leg ending in a 90 deg corner needs the turn's run-out on
                // both sides, the aircraft cannot make it, and it sails past the waypoint and
                // orbits back for it.
                let cornerFits = hybridVTOLLegCornerAllowsCruise(
                    legLengthMeters: routeGuidance.remainingPathMeters,
                    finalTargetPlanar: finalTargetPlanar,
                    wing: wing,
                    airspeed: airspeed
                )
                // Cruise has to earn itself twice over: the run-up into the wing *and* the distance
                // it takes to get back out of it. That second half is now paid at every waypoint,
                // so the budget carries it unconditionally — otherwise a leg just long enough to
                // enter the wing would be handed straight back out of it again.
                let cruiseBudget = cruiseEntryDistance
                    + hybridVTOLStopDistance(airspeed: airspeed, wing: wing)
                vtolActiveLegUsesCruise = routeGuidance.remainingPathMeters > cruiseBudget
                #if DEBUG
                print(String(
                    format: "[Regime] leg len=%.0f budget=%.0f spd=%.1f R=%.0f cornerFits=%@ cruise=%@ "
                        // Whether this waypoint is reached along a hover bridge, and how long it is.
                        // A waypoint set against a building shows a non-zero `bridge`; one in open
                        // ground shows zero. It is added on top of the braking reserve, because the
                        // wing has to be given up before the bridge's entry.
                        + "bridge=%.0f",
                    Double(routeGuidance.remainingPathMeters),
                    Double(cruiseBudget),
                    Double(airspeed),
                    Double(wing.minimumTurnRadius(airspeed: max(wing.cruiseAirspeed, airspeed))),
                    (cornerFits ? "yes" : "no") as NSString,
                    (vtolActiveLegUsesCruise ? "yes" : "no") as NSString,
                    Double(max(0.0, hybridVTOLRouteApproachBridgeMeters))
                ))
                #endif
            }
        } else {
            // `.infinity` is the blocked sentinel, not a real leg length. Leave the regime choice
            // unlatched so it is evaluated from the validated path when planning succeeds.
            vtolActiveLegTargetPlanar = nil
            vtolActiveLegUsesCruise = false
        }
        // How far out the wing has to be given up so the aircraft is stopped *at* the waypoint.
        //
        // The nominal exit distance sizes a fly-through, not a stop, and it is derived from the
        // profile's cruise speed rather than the speed being flown. Both were wrong in the same
        // direction: a leg ending in a corner no wing can fly still handed the aircraft back to the
        // rotors a waypoint-radius out, which is nowhere near enough to arrest cruise speed, so it
        // arrived fast and either overshot or was still translating when it met the next façade.
        //
        // The reserve is taken at *every* mission waypoint now, not only at one the corner rule
        // called un-flyable. A corner the wing can geometrically make is still a corner arrived at
        // under a façade: measured on a Wingcopter, W1→W2 passed `cornerFits=yes`, so the exit was
        // sized by `cruiseExitDistance` (~35 m at 23 m/s) while the aircraft's own braking distance
        // was 77 m, and it threaded the gap between two buildings on the wing. A Quantum flew the
        // same rule into a building. Arriving as a rotorcraft, pivoting onto the next leg and
        // re-accelerating is both safer and shorter than correcting afterwards.
        //
        // A waypoint reached along a hover bridge is braked for at the bridge's *entry*, not at the
        // waypoint behind it: the bridge is a certified straight hover leg a few metres long, and a
        // wing carrying a 40-80 m turn radius cannot turn into it. This is geometry, not an
        // allowance — it is exactly the length the planner had to project the goal out by.
        let exitDistance = max(
            cruiseExitDistance,
            hybridVTOLStopDistance(airspeed: airspeed, wing: wing)
        ) + max(0.0, hybridVTOLRouteApproachBridgeMeters)
        // The exit distance still hands the leg back to hover for the capture itself, and an
        // already-established cruise is never yanked out of the air mid-leg: that rule exists so a
        // *length* threshold re-evaluated against the shrinking remaining distance cannot drop the
        // aircraft out of the wing halfway along.
        let sustainedCruise = cruiseWasEstablished
        // A tailsitter has no independently tilting lift rotors: at progress
        // zero its two fixed propellers point vertically and it cannot chase
        // a horizontal waypoint in "hover".  Any validated leg outside the
        // precision envelope must therefore enter the wing transition even
        // when it is shorter than the generic VTOL cruise-economy threshold.
        // It gets the same stop distance as everything else, though — standing on its tail does
        // not make it stop any sooner.
        let tailsitterNeedsWingTranslation = HybridVTOLFlightPolicy
            .tailsitterValidatedLegRequiresWingTransition(
                isTailsitter: selectedDroneProfile.airframeStyle == .tailsitterVTOL,
                routeIsValidated: routeGuidance.isReady,
                isFinalSegment: routeGuidance.isFinalSegment,
                finalPlanarDistance: finalPlanarDistance,
                precisionRadius: max(precisionRadius, exitDistance)
            )
        // A leg that ends in a stop is judged on the distance to the waypoint itself, not on which
        // segment of the protected route the cursor happens to be on. The braking distance can be
        // longer than the last segment, and "we are not on the final segment yet" is no reason to
        // still be carrying cruise speed into a corner that has to be flown at zero.
        // Judged on the distance to the waypoint itself, never on which route segment the cursor
        // happens to be on. The reserve is now routinely longer than the last segment of a city
        // route, and "we are not on the final segment yet" would defer the exit past the point
        // where it can still be flown — which is the failure the reserve exists to prevent.
        let withinStopExit = finalPlanarDistance <= exitDistance
        let wantsCruise = tailsitterNeedsWingTranslation || (
            (vtolActiveLegUsesCruise || sustainedCruise) && !withinStopExit
        )
        let airborne = !physicalState.isGroundRestState && state.position.y > 0.45
        let maxSinkRate = max(1.4, min(3.2, wing.nominalSinkRateMps * 1.35))

        func decision(
            _ phase: VTOLAutopilotPhase,
            target: SIMD3<Float> = target,
            altitude: Float = routeAltitude,
            lever: Double,
            speedScale: Float,
            safety: VTOLAutopilotSafetyState = .nominal,
            reason: String
        ) -> VTOLAutopilotDecision {
            VTOLAutopilotDecision(
                phase: phase,
                target: target,
                targetAltitude: altitude,
                targetAirspeed: phase == .wingborneCruise || phase == .transitionToCruise ? wing.cruiseAirspeed : nil,
                targetHeading: routeYaw,
                maxSinkRate: maxSinkRate,
                transitionLever: lever,
                speedScale: speedScale,
                safetyState: safety,
                reason: reason
            )
        }

        if !isArmed && physicalState.isGroundRestState {
            return decision(
                .idleGrounded,
                target: SIMD3<Float>(state.position.x, max(0.0, state.position.y), state.position.z),
                altitude: max(0.0, state.position.y),
                lever: 0.0,
                speedScale: 0.0,
                reason: "vtol_idle_grounded"
            )
        }

        if mode == .landing {
            return decision(
                .verticalLanding,
                target: SIMD3<Float>(state.position.x, 0.0, state.position.z),
                altitude: 0.0,
                lever: -1.0,
                speedScale: 0.35,
                reason: "vtol_vertical_landing"
            )
        }

        // "No flyable course" means stop, for an aircraft that can.
        //
        // `fixedWingAvoidanceNoSafeTrajectory` is the avoidance layer reporting that *every*
        // candidate course ends in geometry. A fixed wing must then fly the least-bad one — it
        // cannot stop. A VTOL can, and inheriting the aeroplane's escape law made it bank into the
        // best of several buildings instead. Measured on the flight this comment comes from:
        // `avOff=blocked(+10) avCrsErr=+9.0 avRawBank=+12.9 rollCmd=13.6`, a steady 14° bank held
        // for three seconds straight into a façade, with `avRawBank` and `rollCmd` matching sign
        // and magnitude — the layer was flying it there deliberately, having judged +10° the least
        // bad of a fan of blocked options.
        //
        // The risk score alone was too late a trigger: it is a proximity measure and only crosses
        // 0.82 once the obstacle is already close, whereas the rollout knows several seconds ahead.
        if airborne && (collisionAnalysis.riskScore >= 0.82 || fixedWingAvoidanceNoSafeTrajectory) {
            if hybridVTOLEmergencyHoldPosition == nil {
                hybridVTOLEmergencyHoldPosition = state.position
            }
            let holdPosition = hybridVTOLEmergencyHoldPosition ?? state.position
            var emergencyDecision = decision(
                .emergencyHover,
                target: holdPosition,
                altitude: holdPosition.y,
                lever: -1.0,
                speedScale: 0.25,
                safety: .emergencyHover("corridorBlocked"),
                reason: "vtol_emergency_hover_corridor_blocked"
            )
            emergencyDecision.targetHeading = selectedDroneProfile.airframeStyle == .tailsitterVTOL
                ? tailsitterHoverHeadingRadians()
                : state.orientation.z
            return emergencyDecision
        }
        hybridVTOLEmergencyHoldPosition = nil

        if airborne && (batteryState.chargePercent <= 4.0 || hasFlightCriticalGraphDamage) {
            return decision(
                .forcedLanding,
                target: SIMD3<Float>(state.position.x, 0.0, state.position.z),
                altitude: 0.0,
                lever: -1.0,
                speedScale: 0.25,
                safety: .forcedLanding(batteryState.chargePercent <= 4.0 ? "lowBattery" : "damageCritical"),
                reason: "vtol_forced_landing"
            )
        }

        // Climb vertically only until the departure is clear, then climb *and* translate.
        //
        // This used to hold the aircraft in a pure vertical climb until it reached the full route
        // altitude, and `hybridVTOLRouteAltitude` reaches for `terrain.maxFlightAltitude`. Measured
        // on a 222 m three-waypoint mission: 65 → 215 m at a constant 5.8 m/s with `pitch=89`
        // (still hovering nose-up), `prog=0.01` and zero progress toward W1 — 150 m of vertical
        // spent going nowhere, then a 13.8 m/s dive and another climb. The altitude channel already
        // carries `routeAltitude` into every later phase, so the climb continues on its own; what
        // this gate must decide is only when it is safe to *start moving*, which is a departure
        // question, not a cruise-altitude one.
        let verticalDepartureAltitude = min(
            routeAltitude,
            supportSurfaceY(for: state.position) + max(12.0, wing.initialClimbTargetAltitude)
        )
        if state.position.y < verticalDepartureAltitude - 0.85 && state.vtolTransitionProgress < 0.20 {
            var takeoffDecision = decision(
                .verticalTakeoff,
                target: SIMD3<Float>(state.position.x, routeAltitude, state.position.z),
                altitude: routeAltitude,
                lever: 0.0,
                speedScale: min(context.speedScale, 0.55),
                reason: "vtol_vertical_takeoff_to_departure_altitude"
            )
            // Do not rotate toward an unproven/distant route while still in
            // the near-ground vertical departure.  Tailsitters align at the
            // departure altitude in the explicit phase below.
            takeoffDecision.targetHeading = selectedDroneProfile.airframeStyle == .tailsitterVTOL
                ? tailsitterHoverHeadingRadians()
                : state.orientation.z
            return takeoffDecision
        }

        // Route construction is authoritative for every horizontal phase. If a mesh/OSM route is
        // unavailable or fails validation, a hover-capable aircraft can wait safely for the next
        // planner retry; it must never silently fall back to the raw waypoint through geometry.
        if case .blocked = routeGuidance.status {
            let needsTransitionToHover = state.vtolTransitionProgress > 0.08 ||
                vtolAutopilotPhase == .wingborneCruise
            // Blocked is a *lateral* hold: the aircraft stops where it is horizontally and waits
            // for a route. Vertically it follows `routeAltitude`, which the escalation above walks
            // upward precisely because no route existed lower down — freezing the altitude here
            // instead is what turned "no route" into a permanent hover with nothing to change it.
            // Never a descent, though: the way down is the geometry it has already ruled out.
            if hybridVTOLProtectedRouteHoldPosition == nil {
                hybridVTOLProtectedRouteHoldPosition = state.position
            }
            var holdPosition = hybridVTOLProtectedRouteHoldPosition ?? state.position
            let holdAltitude = max(holdPosition.y, routeAltitude)
            holdPosition.y = holdAltitude
            var blockedDecision = decision(
                needsTransitionToHover ? .emergencyHover : .hoverHold,
                target: holdPosition,
                altitude: holdAltitude,
                lever: needsTransitionToHover ? -1.0 : 0.0,
                speedScale: needsTransitionToHover ? 0.25 : 0.20,
                safety: needsTransitionToHover
                    ? .emergencyHover("protectedRouteBlocked")
                    : .nominal,
                reason: "vtol_protected_route_blocked"
            )
            blockedDecision.targetHeading = selectedDroneProfile.airframeStyle == .tailsitterVTOL
                ? tailsitterHoverHeadingRadians()
                : state.orientation.z
            return blockedDecision
        }

        if routeGuidance.isFinalSegment && finalPlanarDistance <= precisionRadius {
            let needsHoverCapture = state.vtolTransitionProgress > 0.08 ||
                planarSpeed > max(4.5, wing.minSafeAirspeed * 0.28)
            if needsHoverCapture {
                return decision(
                    .transitionToHover,
                    lever: -1.0,
                    speedScale: min(context.speedScale, 0.42),
                    reason: "vtol_transition_to_hover_for_waypoint"
                )
            }
            return decision(
                .precisionHover,
                lever: 0.0,
                speedScale: min(context.speedScale, 0.35),
                reason: "vtol_precision_hover_waypoint"
            )
        }

        if routeGuidance.traversalMode == .stopAndPivotVTOL {
            // This polyline is certified as collision-free straight hover legs, not as a
            // continuous fixed-wing turn. Return fully to the rotor-borne regime, stop on every
            // cursor node, yaw onto the next leg, and only then translate. The fixed-wing latch
            // cannot engage because this mode never commands a cruise transition.
            let needsRotorborneHandoff = state.vtolTransitionProgress > 0.08
            if needsRotorborneHandoff {
                let hold = stopAndPivotGuidance.holdPosition ?? state.position
                return decision(
                    .transitionToHover,
                    target: hold,
                    altitude: routeAltitude,
                    lever: -1.0,
                    speedScale: min(context.speedScale, 0.30),
                    reason: "vtol_stop_and_pivot_return_to_hover"
                )
            }
            if stopAndPivotGuidance.shouldHold {
                return decision(
                    .hoverHold,
                    target: stopAndPivotGuidance.holdPosition ?? state.position,
                    altitude: routeAltitude,
                    lever: 0.0,
                    speedScale: min(context.speedScale, 0.28),
                    reason: "vtol_stop_and_pivot_align"
                )
            }
            // Slow down *before* the node, not after reaching it.
            //
            // The gate releases a node only below 0.55 m/s, and rotor-borne braking is bounded by
            // the tilt envelope: measured entry speeds of 2 / 4 / 8 m/s need 3.3 / 6.5 / 11.3 m to
            // stop, so arriving at cruise speed guarantees an overshoot. In flight that read as the
            // aircraft sailing past its own waypoint and then coming back for it — node distance
            // 14.8 -> 24.4 -> back down — which is both slower and a wing-tip's worth of geometry
            // the protected route never approved.
            //
            // Cap the commanded speed by what can still be arrested in the distance remaining. The
            // 1.4 s figure is the measured stopping-distance slope; the 1.0 m offset leaves the
            // final metre to the position loop, which settles inside 0.44 m.
            let arrivalSpeedLimit = max(
                HybridVTOLStopAndPivotGate.maximumPlanarSpeedMps,
                (planarDistance - 1.0) / 1.4
            )
            let approachScale = planarSpeed > arrivalSpeedLimit
                ? (arrivalSpeedLimit / max(planarSpeed, 0.05)).clamped(to: 0.05...1.0)
                : 1.0
            return decision(
                .hoverHold,
                lever: 0.0,
                speedScale: min(context.speedScale, 0.52) * approachScale,
                reason: "vtol_stop_and_pivot_track"
            )
        }

        if !wantsCruise {
            let hoverLever = state.vtolTransitionProgress > 0.08 ? -1.0 : 0.0
            return decision(
                hoverLever < 0.0 ? .transitionToHover : .hoverHold,
                lever: hoverLever,
                speedScale: min(context.speedScale, 0.62),
                reason: hoverLever < 0.0 ? "vtol_transition_to_hover_short_leg" : "vtol_hover_hold_short_leg"
            )
        }

        // A tailsitter chooses its cruise direction by rotating around the
        // vertical thrust axis first, then pitching the whole airframe down.
        // Starting both motions at once is unsafe for a large initial course
        // change: the pitch axis is still pointing across the requested
        // route, and the ordinary forward-vector Euler yaw is singular here.
        // Align on the quaternion-derived hover heading and let both angular
        // and vertical rates settle before handing the pitch axis to the
        // transition. Departure reaches its altitude at the +5.8 m/s climb
        // governor; pitching the fixed propellers forward at that instant
        // converts an uncontrolled ballistic overshoot into the first leg.
        if selectedDroneProfile.airframeStyle == .tailsitterVTOL,
           !hybridVTOLDepartureAlignmentComplete,
           state.vtolTransitionProgress < 0.08,
           let routeYaw {
            let headingError = shortestAngleRadians(
                routeYaw - tailsitterHoverHeadingRadians()
            )
            let headingRate = abs(state.bodyAngularVelocity.x)
            // One-sided on purpose. This gate asks "has the vertical departure finished?", and
            // being *above* the departure altitude is the answer being yes with margin to spare —
            // it is not a reason to refuse the transition.
            //
            // The symmetric ±2.25 m window it replaces was a deadlock by construction: departure
            // climbs at the +5.8 m/s governor and, on this mission, only had 8 m to climb
            // (pad 9.2 m, departure altitude 17.3 m). Arresting 5.8 m/s takes longer than 2.25 m,
            // so the aircraft always came to rest above the window — measured settling at 20.18 m
            // against a 17.3 m departure, 2.88 m out, `vy=-0.00`, and holding
            // `vtol_tailsitter_align_before_transition` indefinitely with the route ready and the
            // heading aligned. What still has to hold is that the aircraft is not *short* of the
            // departure altitude and that its vertical rate has actually settled.
            let verticalDepartureSettled =
                state.position.y >= verticalDepartureAltitude - 2.25 &&
                abs(state.velocity.y) <= 0.45
            if abs(headingError) > Float(6.0).degreesToRadians ||
                headingRate > 0.16 ||
                !verticalDepartureSettled {
                // Hold where the aircraft *is*, never below it.
                //
                // The condition above was made one-sided — being above the departure altitude
                // counts as departed — but the hold target was not, and it commanded that altitude
                // outright. For an aircraft already well above it that is a dive order, and the
                // dive is what keeps the gate open: sinking at 6.9 m/s fails the 0.45 m/s settling
                // test the gate is waiting for, so it commands the descent again. Measured on the
                // imported city: `rAlt=89.3 dAlt=26.0` with the aircraft porpoising 42 → 33 → 42 m
                // at ±6 m/s, and every crossing changed the altitude band under the planner — 5 734
                // obstacles up high, 15 217 down low — so the certified route flipped between an
                // 11-node street plan and a straight line on alternating ticks. What looked like
                // crawling was the aircraft oscillating across its own route, not along it.
                let holdAltitude = max(
                    verticalDepartureAltitude,
                    min(state.position.y, routeAltitude)
                )
                return decision(
                    .hoverHold,
                    target: SIMD3<Float>(
                        state.position.x,
                        holdAltitude,
                        state.position.z
                    ),
                    altitude: holdAltitude,
                    lever: 0.0,
                    speedScale: min(context.speedScale, 0.42),
                    reason: "vtol_tailsitter_align_before_transition"
                )
            }
            // Settled, aligned, and at the departure altitude: the one-time rotation is done and
            // this gate closes for the rest of the route.
            hybridVTOLDepartureAlignmentComplete = true
        }

        let transitionSafety = hybridVTOLTransitionSafetyState(
            airspeed: airspeed,
            routeAltitude: routeAltitude,
            wing: wing,
            cruiseWasEstablished: cruiseWasEstablished
        )
        switch transitionSafety {
        case .nominal:
            break
        case .transitionBlocked(let reason):
            if state.position.y < routeAltitude - 0.45 {
                return decision(
                    .verticalTakeoff,
                    target: SIMD3<Float>(state.position.x, routeAltitude, state.position.z),
                    altitude: routeAltitude,
                    lever: 0.0,
                    speedScale: min(context.speedScale, 0.50),
                    safety: transitionSafety,
                    reason: "vtol_transition_blocked_\(reason)"
                )
            }
            return decision(
                .hoverHold,
                target: SIMD3<Float>(state.position.x, routeAltitude, state.position.z),
                altitude: routeAltitude,
                lever: state.vtolTransitionProgress > 0.08 ? -1.0 : 0.0,
                speedScale: min(context.speedScale, 0.45),
                safety: transitionSafety,
                reason: "vtol_transition_blocked_\(reason)"
            )
        case .transitionAborting(let reason):
            return decision(
                .transitionAbort,
                target: SIMD3<Float>(state.position.x, max(routeAltitude, state.position.y), state.position.z),
                altitude: max(routeAltitude, state.position.y),
                lever: -1.0,
                speedScale: 0.32,
                safety: transitionSafety,
                reason: "vtol_transition_abort_\(reason)"
            )
        case .emergencyHover(let reason):
            return decision(
                .emergencyHover,
                target: SIMD3<Float>(state.position.x, max(routeAltitude, state.position.y), state.position.z),
                altitude: max(routeAltitude, state.position.y),
                lever: -1.0,
                speedScale: 0.25,
                safety: transitionSafety,
                reason: "vtol_emergency_hover_\(reason)"
            )
        case .forcedLanding(_):
            return decision(
                .forcedLanding,
                target: SIMD3<Float>(state.position.x, 0.0, state.position.z),
                altitude: 0.0,
                lever: -1.0,
                speedScale: 0.25,
                safety: transitionSafety,
                reason: "vtol_forced_landing"
            )
        }

        // A tailsitter must not bounce back to the transition controller every
        // time lift ratio or vertical speed crosses a cruise-entry threshold by
        // a small amount. That controller handoff replaces the fixed-wing pitch
        // command with a multicopter command, producing the visible Wingtra
        // pitch "saw" and making the AUTO telemetry alternate ON/OFF. Once
        // cruise has been established, retain it until the safety evaluator
        // above reports a genuine loss of speed, sink-rate margin, or corridor.
        if cruiseWasEstablished,
           selectedDroneProfile.airframeStyle == .tailsitterVTOL {
            return decision(
                .wingborneCruise,
                lever: 1.0,
                speedScale: context.speedScale,
                reason: "vtol_cruise_retained_hysteresis"
            )
        }

        if hybridVTOLCruiseReady(wing: wing) {
            return decision(
                .wingborneCruise,
                lever: 1.0,
                speedScale: context.speedScale,
                reason: "vtol_cruise_accepted_lift_ready"
            )
        }

        let rawTransitionLever = hybridVTOLTransitionLever(
            wing: wing,
            airspeed: airspeed,
            liftRatio: liftRatio,
            transitionProgress: state.vtolTransitionProgress
        )
        // The lever may not reverse faster than the rotors can answer it.
        //
        // Everything above this point is a *safety* decision and returns on its own, so what is
        // left here is the ordinary "should we be going wingborne now?" question — and that
        // question was being re-answered from scratch every tick against thresholds the aircraft
        // sits exactly on. Measured across a whole 795 m leg: `prog` walking 0.49, 0.46, 0.12,
        // 0.33, 0.16, 0.17, 0.44, 0.15 … with `why` alternating `vtol_transition_to_cruise` /
        // `vtol_transition_delayed_lift_or_speed`, the aircraft never wingborne and never fully
        // rotor-borne, crossing the whole leg at about 10 m/s. The tilt takes ~2 s to answer; an
        // order reversed every tick is not an order, it is noise, and the airframe averages it.
        //
        // So the *class* of the lever — pushing forward versus not — is held for a dwell period
        // once chosen. Magnitude still moves freely inside a class, and a genuine abort still
        // wins instantly because it never reaches this line.
        let rawPushesForward = rawTransitionLever > 0.05
        let transitionLever: Double
        if let latched = hybridVTOLTransitionLeverLatched,
           let since = hybridVTOLTransitionLeverLatchedSince,
           (latched > 0.05) != rawPushesForward,
           simulationTime - since < Self.hybridVTOLTransitionLeverDwellSeconds {
            transitionLever = latched
        } else {
            if (hybridVTOLTransitionLeverLatched.map { ($0 > 0.05) != rawPushesForward }) ?? true {
                hybridVTOLTransitionLeverLatchedSince = simulationTime
                #if DEBUG
                // Printed only when the class actually flips, so a steady transition is silent and
                // a dithering one names its own rate. `[TailTick]` samples at 1 Hz and cannot see
                // this: the whole oscillation lives between two of its lines.
                print(String(
                    format: "[Regime] lever %@ raw=%.2f prog=%.2f spd=%.1f lift=%.2f blocked=%@",
                    rawPushesForward ? "FORWARD" : "hold",
                    rawTransitionLever,
                    state.vtolTransitionProgress,
                    airspeed,
                    liftRatio,
                    state.vtolTransitionBlocked ? "yes" : "no"
                ))
                #endif
            }
            hybridVTOLTransitionLeverLatched = rawTransitionLever
            transitionLever = rawTransitionLever
        }
        let transitionReason = transitionLever > 0.05
            ? "vtol_transition_to_cruise"
            : "vtol_transition_delayed_lift_or_speed"
        return decision(
            .transitionToCruise,
            lever: transitionLever,
            speedScale: min(max(context.speedScale, 0.58), 0.84),
            reason: transitionReason
        )
    }

    private func applyHybridVTOLTransitionToCruiseCommand(
        context: AutopilotTrackingContext,
        decision: VTOLAutopilotDecision,
        wing: FixedWingParameters,
        routeAltitude: Float,
        deltaTime: Float
    ) {
        let currentPlanar = SIMD2<Float>(state.position.x, state.position.z)
        let targetPlanar = SIMD2<Float>(decision.target.x, decision.target.z)
        let routeVector = targetPlanar - currentPlanar
        let planarDistance = simd_length(routeVector)
        let direction: SIMD2<Float>
        if planarDistance > 0.01 {
            direction = routeVector / planarDistance
        } else {
            let yaw = state.orientation.z
            direction = SIMD2<Float>(-sin(yaw), -cos(yaw))
        }
        let lookaheadUpperBound = max(24.0, wing.cruiseAirspeed * 1.6)
        // A close protected-route corner is a hard bound. The previous 12 m minimum projected the
        // transition command past short detour nodes and cut the very obstacle the A* route had
        // gone around.
        let transitionLookahead = min(
            planarDistance,
            min(max(planarDistance * 0.45, 12.0), lookaheadUpperBound)
        )
        let transitionTarget = SIMD3<Float>(
            state.position.x + direction.x * transitionLookahead,
            routeAltitude,
            state.position.z + direction.y * transitionLookahead
        )
        let transitionBaseline = resolvedFlightBaseline(for: mode)
        var transitionContext = AutopilotTrackingContext(
            state: state,
            physicalState: physicalState,
            target: transitionTarget,
            targetAltitude: routeAltitude,
            speedScale: decision.speedScale,
            yawAlignToHome: context.yawAlignToHome,
            yawOverrideRadians: decision.targetHeading ?? context.yawOverrideRadians,
            deltaTime: context.deltaTime,
            flightBaseline: transitionBaseline
        )
        transitionContext.verticalVelocityDampingGain = 0.075
        var command = multicopterAutopilotController.command(for: transitionContext)
        let attitudeScale = (1.0 - state.vtolTransitionProgress * 0.65).clamped(to: 0.25...1.0)
        command.rollDegrees *= attitudeScale
        command.pitchDegrees *= attitudeScale
        // The transition floor is anti-sink. Above the route altitude it is a climb order.
        //
        // `MulticopterAutopilotController` already *starts* from `hoverLockThrottle` and subtracts
        // an altitude/vertical-rate term from it, so below the route altitude this floor adds
        // nothing the controller would not ask for anyway — while above it, it discards the whole
        // correction. For a hybrid VTOL `hoverLockThrottle` is `max(hover, transition)`, i.e. the
        // *transition* figure: measured on this airframe at 0.60 against a hover equilibrium near
        // 0.45, which is the +5.8 m/s ascent governor held flat.
        //
        // Measured across one mission, every leg overshot its own route altitude and the next leg
        // then took its baseline from wherever the overshoot had left the aircraft
        // (`targetMarkerTravelAltitude` reads `state.position.y + 3.4`): 20 → 107 m at `rAlt=17.3`,
        // 118 → 211 m at `rAlt=89.3`, 164 → 243 m at `rAlt=161.3`. `thr=0.60 vy=5.80` on every
        // transition tick, while the controller's own command had long since clamped to 0.18 asking
        // for the descent this `max` threw away. The ratchet then parked the aircraft over rooftops
        // for the next leg, where a start or goal cell inside the stale low band read as occupied
        // (`start_projected_seg0`) and the altitude escalation spent another 72 m escaping it.
        //
        // `SimpleDronePhysicsEngine` already drops its own throttle floor to zero for exactly this
        // case (`rotorBorneAltitudeControl`); this floor is what left that opening unusable. Same
        // reasoning as the `.emergencyHover` branch, which carries no floor for the same reason.
        // Anti-sink was only half of what this floor is for. The other half is acceleration.
        //
        // Making it conditional on being *below* the route altitude fixed the ratchet and created a
        // deadlock, because a transition normally runs at the route altitude: no floor, so the
        // throttle fell to whatever the altitude controller wanted — enough to hover, not enough to
        // accelerate. Measured over a whole leg with `[Regime]` at full rate, the same cycle dozens
        // of times: `prog` climbs 0.05 → 0.20, `tiltAdvanceIsSafe` refuses to advance (`blocked=yes`,
        // `lift=0.26`), the tilt falls back to 0.05, and round again — with airspeed pinned at
        // 8-10 m/s and `thr` between 0.36 and 0.61 throughout. This airframe needs roughly twice
        // that speed before the wing carries. The handful of transitions that *did* complete all
        // show `thr=0.92` alongside.
        //
        // A transition is an acceleration and needs the thrust to perform one. So the floor holds
        // until the wing is actually carrying; past that the altitude governor gets its authority
        // back and the ratchet reasoning above applies unchanged.
        let wingIsCarrying = state.vtolWingborneBlend >= 0.85
        if !wingIsCarrying || state.position.y < routeAltitude - 0.30 {
            command.throttle = max(
                command.throttle,
                transitionBaseline.hoverLockThrottle,
                transitionBaseline.cruiseReferenceThrottle,
                resolvedFlightBaseline(for: .takeoff).takeoffThrottleReference
            )
        }
        fixedWingAutopilotAltitudeCommand = routeAltitude
        fixedWingAutopilotCourseCommand = decision.targetHeading
        fixedWingAutopilotDebugState = .idle
        fixedWingLastTransitionReason = decision.reason
        applyAutopilotCommand(
            command,
            deltaTime: deltaTime,
            vtolTransitionLever: decision.transitionLever
        )
    }

    private func hybridVTOLActiveLegTarget(
        context: AutopilotTrackingContext,
        routeAltitude: Float
    ) -> SIMD3<Float> {
        if activeRouteTargetSource == .mission,
           missionExecutionState.status == .running,
           let activeTarget = missionExecutionState.activeTarget,
           isFiniteVector2(activeTarget.position) {
            return SIMD3<Float>(
                activeTarget.position.x,
                routeAltitude,
                activeTarget.position.y
            )
        }
        if mode == .returnHome {
            return SIMD3<Float>(homePosition.x, routeAltitude, homePosition.z)
        }
        if activeRouteTargetSource == .manualMarker,
           let marker = targetMarkerState {
            return marker.worldPosition(altitude: routeAltitude)
        }
        if mode == .autoPath,
           let autoFlightGoal {
            return SIMD3<Float>(autoFlightGoal.x, routeAltitude, autoFlightGoal.z)
        }
        return SIMD3<Float>(context.target.x, routeAltitude, context.target.z)
    }

    private func hybridVTOLPrecisionEntryRadius(wing: FixedWingParameters) -> Float {
        let captureRadius = wing.waypointCaptureRadius(airspeed: wing.cruiseAirspeed)
        let turnRadius = wing.minimumTurnRadius(airspeed: wing.cruiseAirspeed)
        if wing.family == .surveyEVTOL {
            return max(
                12.0,
                captureRadius * 0.95,
                min(turnRadius * 0.55, captureRadius * 2.4)
            )
        }
        return max(
            16.0,
            captureRadius * 1.10,
            min(turnRadius * 0.65, captureRadius * 2.6)
        )
    }

    private func hybridVTOLCruiseEntryDistance(
        wing: FixedWingParameters,
        precisionRadius: Float
    ) -> Float {
        let turnRadius = wing.minimumTurnRadius(airspeed: wing.cruiseAirspeed)
        return max(
            precisionRadius * 1.75,
            min(turnRadius * 1.10, precisionRadius * 3.4),
            wing.cruiseAirspeed * 3.5
        )
    }

    /// Whether the turn this leg ends in fits the cruise turn radius, given the leg it turns onto.
    ///
    /// A corner of `theta` flown at radius `R` consumes `R · tan(theta/2)` of straight line on
    /// each side of the waypoint. Both of those legs are shared with the corner at their far end,
    /// so no more than half of either may be spent here; the fraction below keeps a margin under
    /// that half. Fail the test and the leg is flown rotor-borne, which is precisely the capability
    /// a VTOL has and a fixed wing does not.
    /// Distance a wing-borne VTOL needs to arrive stopped: the whole transition back out of the
    /// wing, flown at the speed it enters with.
    ///
    /// It is deliberately keyed on the airspeed actually being flown rather than the profile's
    /// cruise figure. Recorded flights cruise well above the datasheet — a Quantum Trinity with a
    /// 17 m/s cruise was measured at 44 m/s, a Wingcopter 198 with a 22 m/s cruise at 40 m/s — and
    /// stopping distance grows with the speed that exists, not the one in the profile.
    private func hybridVTOLStopDistance(airspeed: Float, wing: FixedWingParameters) -> Float {
        let speed = max(wing.cruiseAirspeed, airspeed.isFinite ? airspeed : 0.0)
        return speed * hybridVTOLTransitionOutSeconds()
    }

    /// How long this airframe takes to get out of the wing and back into hover, end to end.
    ///
    /// The two rigs answer a transition in different ways and the figure cannot be shared. A
    /// tilt-rotor has to drive its nacelles round and wait out the aerodynamic state that follows;
    /// the operator measures 6-7 s for a Wingcopter and a Quantum, and everything sized from the
    /// old 3.35 s let both of them meet a building still wing-borne.
    ///
    /// A tailsitter has no actuator in the loop — it pitches the whole airframe — and 7 s is simply
    /// not what it does. Applied to a WingtraOne the long figure inflated `exitDistance` to about
    /// 180 m, which then fed `precisionRadius:` in `tailsitterValidatedLegRequiresWingTransition`
    /// and suppressed the wing over the whole of every city leg: it crawled between waypoints in
    /// hover and only reached cruise on the long run into the last one. Its own figure is the one it
    /// flew correctly before — 3.35 s — and a measurement for it would replace this outright.
    private func hybridVTOLTransitionOutSeconds() -> Float {
        selectedDroneProfile.airframeStyle == .tailsitterVTOL
            ? Self.hybridVTOLTailsitterTransitionOutSeconds
            : Self.hybridVTOLTiltRotorTransitionOutSeconds
    }

    private func hybridVTOLLegCornerAllowsCruise(
        legLengthMeters: Float,
        finalTargetPlanar: SIMD2<Float>,
        wing: FixedWingParameters,
        airspeed: Float
    ) -> Bool {
        guard legLengthMeters.isFinite,
              let nextTargetPlanar = nextMissionTargetPlanar(after: finalTargetPlanar) else {
            return true
        }

        let incoming = finalTargetPlanar - SIMD2<Float>(state.position.x, state.position.z)
        let outgoing = nextTargetPlanar - finalTargetPlanar
        let incomingLength = simd_length(incoming)
        let outgoingLength = simd_length(outgoing)
        guard incomingLength > 0.5, outgoingLength > 0.5 else {
            return true
        }

        let cosine = simd_dot(incoming / incomingLength, outgoing / outgoingLength)
        let turnAngle = acos(max(Float(-1.0), min(Float(1.0), cosine)))
        guard turnAngle > Self.hybridVTOLNegligibleCornerRadians else {
            return true
        }

        // The radius the aircraft will really turn at, not the one its datasheet implies. Radius
        // goes as the square of speed, so a Quantum measured at 44 m/s against a 17 m/s cruise
        // needs 257 m where the profile says 38 m — and every corner the planner judged flyable
        // on the profile figure was nothing of the sort.
        let turnRadius = wing.minimumTurnRadius(
            airspeed: max(wing.cruiseAirspeed, airspeed.isFinite ? airspeed : 0.0)
        )
        // Cap the half-angle short of 90 deg: a reversal sends `tan` to infinity, and the capped
        // value already fails the comparison by a wide margin.
        let halfAngle = min(turnAngle * 0.5, Self.hybridVTOLMaximumCornerHalfAngleRadians)
        let runOut = turnRadius * tan(halfAngle)
        let available = min(legLengthMeters, outgoingLength)
        return runOut <= Self.hybridVTOLCornerCruiseLegFraction * available
    }

    /// The mission waypoint after the one currently being flown, when the leg in progress really
    /// is that mission leg. A manual marker or a return-home leg has no next corner to plan for.
    private func nextMissionTargetPlanar(after finalTargetPlanar: SIMD2<Float>) -> SIMD2<Float>? {
        guard let plan = currentMissionPlan,
              let activeTarget = missionExecutionState.activeTarget,
              simd_distance(activeTarget.position, finalTargetPlanar) <= 3.0,
              let activeIndex = plan.executionTargets.firstIndex(where: { $0.id == activeTarget.id }),
              plan.executionTargets.indices.contains(activeIndex + 1) else {
            return nil
        }
        return plan.executionTargets[activeIndex + 1].position
    }

    private func hybridVTOLCruiseExitDistance(
        wing: FixedWingParameters,
        precisionRadius: Float
    ) -> Float {
        let turnRadius = wing.minimumTurnRadius(airspeed: wing.cruiseAirspeed)
        return max(
            precisionRadius * 1.15,
            min(turnRadius * 0.72, precisionRadius * 2.2)
        )
    }

    private func hybridVTOLTransitionSafetyState(
        airspeed: Float,
        routeAltitude: Float,
        wing: FixedWingParameters,
        cruiseWasEstablished: Bool
    ) -> VTOLAutopilotSafetyState {
        let latchedTailsitterCruise = cruiseWasEstablished &&
            selectedDroneProfile.airframeStyle == .tailsitterVTOL
        let minimumAltitude = max(8.0, homePosition.y + 6.0)
        if state.position.y < minimumAltitude {
            return .transitionBlocked("insufficientAltitude")
        }
        if batteryState.chargePercent < 12.0 {
            return .transitionBlocked("lowBattery")
        }
        if hasFlightCriticalGraphDamage || damageState.averageHealth < 0.35 {
            return .transitionBlocked("damageCritical")
        }
        if collisionAnalysis.riskScore >= 0.70 {
            return .emergencyHover("corridorBlocked")
        }
        let sinkLimit = latchedTailsitterCruise
            ? max(2.4, wing.nominalSinkRateMps * 1.75)
            : max(1.2, wing.nominalSinkRateMps * 1.15)
        if state.vtolTransitionProgress > 0.10,
           state.velocity.y < -sinkLimit {
            return .transitionAborting("sinkRateExceeded")
        }
        let lateTiltSpeedScale: Float = latchedTailsitterCruise ? 0.62 : 0.72
        let tooSlowForLateTilt = state.vtolTransitionProgress > 0.62 &&
            airspeed < wing.minSustainableSpeedMps * lateTiltSpeedScale
        if tooSlowForLateTilt {
            return .transitionAborting("insufficientAirspeed")
        }
        if !latchedTailsitterCruise,
           state.vtolTransitionBlocked,
           state.vtolTransitionProgress > 0.20,
           state.velocity.y < -0.6 {
            return .transitionAborting("liftReserveLost")
        }
        // An abort means the manoeuvre is *losing* altitude, not that the aircraft is momentarily
        // below a target the climb controller is already reaching for.
        //
        // Being 1.6 m low was enough on its own, and a tailsitter transition contains that sag by
        // construction: rotor thrust tilts away before the wing carries. Measured over one leg with
        // `rAlt=75.4`, the aircraft sat 3-9 m low while `prog` oscillated 0.34 ↔ 0.37 — squarely
        // across the 0.35 gate below — so the abort fired, the tilt fell back, the gate released,
        // the lever pushed again, and round it went. Half of those aborts fired while the aircraft
        // was *climbing*: `vy` +0.60, +0.59, +0.18. The loop cost 22 m of altitude, 72 → 50 m,
        // which is the opposite of what the abort exists to prevent. It also bypasses every piece of
        // hysteresis in this controller, because an abort returns before any of it.
        //
        // Sustained sink is what genuinely says "this transition is not working", and it already has
        // its own check above. What is left for this one is the slower version of the same thing: low
        // *and* still going down *and* staying that way.
        //
        // It also needs a ceiling, and never had one.
        //
        // Measured on a Quantum Trinity Pro: three aborts on one leg at `prog` 0.97, 0.95 and 0.96,
        // each with `wb` 0.86-1.00 — the wing was already carrying. The trigger was not a failing
        // manoeuvre but the altitude loop's standing offset: `rAlt=63.2` against 59.5-62.6 held, a
        // 2.5-3.6 m deficit versus this rule's 1.6 m, so the aircraft sat inside the abort condition
        // permanently and `vy=-0.19` was enough to fire it. Each abort cost the six or seven seconds
        // of actuator travel the transition had already spent, `prog` falling to 0.70 then 0.17,
        // and two seconds later it started again.
        //
        // An abort is worth taking while the transition is still cheap to give up. Past 0.80 it
        // costs the same as finishing, so there is nothing to save. Real sink is still caught by
        // `sinkRateExceeded` above at every progress — and its silence through all three of those
        // aborts is exactly the point: there was no sink to catch.
        if !latchedTailsitterCruise,
           state.position.y < routeAltitude - 1.6,
           state.vtolTransitionProgress > 0.35,
           state.vtolTransitionProgress <= Self.hybridVTOLAltitudeAbortMaximumProgress,
           state.velocity.y < -0.15 {
            let since = hybridVTOLAltitudeAbortSince ?? simulationTime
            hybridVTOLAltitudeAbortSince = since
            if simulationTime - since >= Self.hybridVTOLAltitudeAbortDwellSeconds {
                return .transitionAborting("altitudeNotHeld")
            }
        } else {
            hybridVTOLAltitudeAbortSince = nil
        }
        return .nominal
    }

    private func hybridVTOLTransitionLever(
        wing: FixedWingParameters,
        airspeed: Float,
        liftRatio: Float,
        transitionProgress: Float
    ) -> Double {
        // The three aborts below are the only things that may un-commit a transition, and they are
        // evaluated before the latch precisely so that a committed transition still stops for a
        // real failure.
        guard collisionAnalysis.riskScore < 0.70 else {
            hybridVTOLTransitionCommitted = false
            return 0.0
        }
        let sinkLimit = max(1.2, wing.nominalSinkRateMps * 1.15)
        guard state.velocity.y >= -sinkLimit else {
            hybridVTOLTransitionCommitted = false
            return 0.0
        }
        guard !state.vtolTransitionBlocked else {
            hybridVTOLTransitionCommitted = false
            return 0.0
        }
        if transitionProgress < 0.18 {
            return 1.0
        }
        let progress = transitionProgress.clamped(to: 0.0...1.0)
        let requiredLiftRatio = min(0.86, 0.10 + progress * 0.74)
        let requiredAirspeed = max(
            wing.minSafeAirspeed * (0.42 + progress * 0.38),
            wing.minSustainableSpeedMps * (0.38 + progress * 0.42)
        )
        if liftRatio >= requiredLiftRatio && airspeed >= requiredAirspeed {
            // Demonstrated once: this leg is going to the wing.
            hybridVTOLTransitionCommitted = true
            return 1.0
        }
        // Committed, and none of the aborts above fired. Momentary dips in lift ratio as the wing
        // swings through its own stall angle are what the transition *is*; they are not a reason to
        // reverse the tilt and start over.
        if hybridVTOLTransitionCommitted {
            return 1.0
        }
        let degradedLiftOK = liftRatio >= requiredLiftRatio * 0.78
        let degradedSpeedOK = airspeed >= requiredAirspeed * 0.92
        if degradedLiftOK && degradedSpeedOK {
            return 0.45
        }
        // Not yet flying, but a zero lever is not the answer: in the physics step
        // `lever == 0` means "hold this tilt", not "go back". Combined with the unconditional
        // push above ending at exactly the same 0.18 the requirement starts at, that made a
        // deadlock at the boundary — measured over twenty consecutive ticks of one flight,
        // `prog` pinned at 0.18 and `pitch` at 63.6 deg while the aircraft crossed 240 m of
        // ground at 9 m/s, never reaching the wing. It cannot escape on its own: at 63 deg the
        // thrust vector is still mostly vertical, so there is no horizontal acceleration, the
        // wing sits past its stall angle, `wb` stays at 0.12 against the 0.182 the degraded
        // gate needs, and nothing in the loop can raise either term.
        //
        // A tailsitter accelerates *by* tilting — the tilt is what points thrust forward — so
        // keep tilting slowly instead of freezing. The genuine aborts are already handled above
        // and still fire every tick: excessive sink, `vtolTransitionBlocked`, and obstacle risk
        // all return zero before this point, so a transition that really is failing still stops.
        return 0.18
    }

    private func applyHybridVTOLHoverAutopilotCommand(
        context: AutopilotTrackingContext,
        target: SIMD3<Float>,
        targetAltitude: Float,
        speedScale: Float,
        yawOverrideRadians: Float?,
        vtolTransitionLever: Double,
        minimumThrottle: Float?,
        reason: String,
        deltaTime: Float
    ) {
        let hoverBaseline = resolvedFlightBaseline(for: .hover)
        var hoverContext = AutopilotTrackingContext(
            state: state,
            physicalState: physicalState,
            target: target,
            targetAltitude: targetAltitude,
            speedScale: speedScale,
            yawAlignToHome: context.yawAlignToHome,
            yawOverrideRadians: yawOverrideRadians,
            deltaTime: context.deltaTime,
            flightBaseline: hoverBaseline
        )
        if selectedDroneProfile.airframeClass == .hybridVTOL,
           state.vtolTransitionProgress < 0.25 {
            hoverContext.verticalVelocityDampingGain = 0.075
        }
        hoverContext.maximumTranslationSpeedMps = Self.hybridVTOLRotorBorneTranslationCeilingMps
        var command = multicopterAutopilotController.command(for: hoverContext)
        if state.vtolTransitionProgress > 0.12 {
            let attitudeScale = (1.0 - state.vtolTransitionProgress * 0.55).clamped(to: 0.35...1.0)
            command.rollDegrees *= attitudeScale
            command.pitchDegrees *= attitudeScale
        }
        if let minimumThrottle {
            command.throttle = max(command.throttle, minimumThrottle)
        }

        fixedWingAutopilotAltitudeCommand = targetAltitude
        fixedWingAutopilotCourseCommand = command.yawDegrees.degreesToRadians
        fixedWingAutopilotDebugState = .idle
        fixedWingLastTransitionReason = reason
        applyAutopilotCommand(
            command,
            deltaTime: deltaTime,
            vtolTransitionLever: vtolTransitionLever
        )
    }

    private func hybridVTOLCruiseReady(wing: FixedWingParameters) -> Bool {
        let planarSpeed = simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        let airspeed = max(state.forwardAirspeed, planarSpeed)
        let liftRatio = max(state.vtolWingLiftRatio, state.vtolWingborneBlend)
        let altitudeStable = state.velocity.y > -max(1.1, wing.nominalSinkRateMps * 0.65)
        guard altitudeStable else {
            return false
        }
        if selectedDroneProfile.airframeStyle == .surveyEVTOL {
            return state.vtolTransitionProgress >= 0.72 &&
                liftRatio >= 0.62 &&
                airspeed >= wing.minSustainableSpeedMps * 0.78
        }

        return state.vtolTransitionProgress >= 0.86 &&
            liftRatio >= 0.74 &&
            airspeed >= wing.minSustainableSpeedMps * 0.82
    }

    /// Course a nose-up tailsitter will take when it pitches toward cruise.
    /// Body forward is vertical (and therefore has no X/Z heading) in hover;
    /// body -Y remains horizontal and is the non-singular physical reference.
    private func tailsitterHoverHeadingRadians() -> Float {
        let transitionDirection = -simd_act(
            state.fixedWingOrientationQuat,
            SIMD3<Float>(0, 1, 0)
        )
        let planar = SIMD2<Float>(transitionDirection.x, transitionDirection.z)
        guard simd_length_squared(planar) > 1e-8 else {
            return state.orientation.z
        }
        return atan2(-planar.x, -planar.y)
    }

    private func hybridVTOLReadyForPrecisionHover() -> Bool {
        guard selectedDroneProfile.airframeClass == .hybridVTOL else {
            return true
        }
        let planarSpeed = simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        return state.vtolTransitionProgress <= 0.10 && planarSpeed <= 5.5
    }

    private func hybridVTOLRouteAltitude(defaultAltitude: Float) -> Float {
        let ceiling = max(6.0, terrain.maxFlightAltitude - 2.0)
        let cruiseFloor = max(10.0, homePosition.y + 8.0)
        return min(ceiling, max(defaultAltitude, cruiseFloor))
    }

    private func prepareHybridVTOLAutopilotForForwardRoute() {
        guard selectedDroneProfile.airframeClass == .hybridVTOL else {
            return
        }
        updateControlValues({ values in
            values.vtolTransitionLever = 0.0
        }, markManual: false)
    }

    private func updateFixedWingNavigationSnapshot(
        routeTracking: FixedWingRouteTrackingContext?,
        debugState: FixedWingAutopilotDebugState
    ) {
        guard let routeTracking,
              routeTracking.waypoints.count >= 2 else {
            return
        }

        let positions = routeTracking.waypoints.map(\.position)
        let clampedIndex = min(debugState.activeSegmentIndex + 1, max(0, positions.count - 1))
        navigationSnapshot = NavigationPathSnapshot(
            status: .valid,
            currentWaypointIndex: clampedIndex,
            remainingWaypoints: max(0, positions.count - clampedIndex),
            pathLengthMeters: fixedWingPathLength(of: positions),
            remainingDistanceMeters: max(0.0, debugState.remainingDistance),
            waypoints: positions,
            start: positions.first,
            goal: positions.last,
            reason: debugState.missionState.rawValue
        )
    }

    private func applyAutopilotCommand(
        _ command: AutopilotControlCommand,
        deltaTime: Float,
        vtolTransitionLever: Double? = nil
    ) {
        updateControlValues({ values in
            values.x = Double(command.positionTarget.x)
            values.y = Double(command.positionTarget.y)
            values.z = Double(command.positionTarget.z)
            values.roll = Double(command.rollDegrees)
            values.pitch = Double(command.pitchDegrees)
            values.yaw = Double(command.yawDegrees)

            let followBlend = (deltaTime * 3.4).clamped(to: 0.06...0.30)
            let blendedThrottle = Float(values.throttle) + (command.throttle - Float(values.throttle)) * followBlend
            values.throttle = Double(blendedThrottle.clamped(to: 0.0...1.0))
            if let vtolTransitionLever {
                values.vtolTransitionLever = vtolTransitionLever
            }
        }, markManual: false)
    }

    private func nextAutoPatrolGoal(resetCycle: Bool) -> SIMD3<Float> {
        let goals = autoPatrolGoals()
        if goals.isEmpty {
            return clampToWorldBounds(homePosition + SIMD3<Float>(0.0, 4.0, 0.0))
        }

        if resetCycle {
            autoFlightGoalIndex = 0
        } else {
            autoFlightGoalIndex = (autoFlightGoalIndex + 1) % goals.count
        }
        return goals[autoFlightGoalIndex]
    }

    private func autoPatrolGoals() -> [SIMD3<Float>] {
        let radius = max(8.0, min(terrain.worldHalfExtent * 0.55, 54.0))
        let altitude = max(3.2, homePosition.y + 4.2)
        let base = homePosition
        let raw: [SIMD3<Float>] = [
            SIMD3<Float>(base.x + radius, altitude, base.z),
            SIMD3<Float>(base.x, altitude, base.z + radius),
            SIMD3<Float>(base.x - radius, altitude, base.z),
            SIMD3<Float>(base.x, altitude, base.z - radius),
            SIMD3<Float>(base.x + radius * 0.5, altitude, base.z + radius * 0.5),
            SIMD3<Float>(base.x - radius * 0.5, altitude, base.z - radius * 0.5)
        ]
        return raw.map { clampToWorldBounds($0) }
    }

    private func clampToWorldBounds(_ point: SIMD3<Float>) -> SIMD3<Float> {
        let maxAltitude = max(10.0, terrain.maxFlightAltitude - 2.0)
        let planar = clampPlanarToBoundarySquare(
            SIMD2<Float>(point.x, point.z),
            halfExtent: hardWorldBoundsRadius
        )
        return SIMD3<Float>(
            planar.x,
            point.y.clamped(to: 0.0...maxAltitude),
            planar.y
        )
    }

    /// Engages an assist mode the operator chose before the aircraft could accept it.
    ///
    /// Deliberately keyed on *state*, not on a transition. Hooking it to
    /// `takeoff_completed_fixed_wing` looked right and never fired: a launch ends through the
    /// launch state machine's own `fixed_wing_launch_completed`, so the request was stored and
    /// then silently sat there — the operator pressed "intercept selected" in the planner and the
    /// autopilot simply never came on. Any path that leaves the aircraft armed, airborne and in
    /// manual now picks it up on the next tick.
    private func engagePendingFixedWingAssistIfReady() {
        guard let pending = pendingFixedWingAssistMode,
              selectedDroneProfile.airframeClass == .fixedWing,
              isArmed,
              mode == .manual,
              physicalState == .airborne,
              physicalState != .crashed,
              !launchState.blocksRouteCapture else {
            return
        }

        if pending == .waypointIntercept {
            // A pre-proven launch route is required only when the preflight actually produced one.
            // When it warned instead, the operator accepted an unproven departure — and refusing
            // to engage the intercept there would silently leave the aircraft in heading hold: the
            // launch would be permitted and the route still not flown, which is the worst of both.
            // The in-flight planner then owns the route, exactly as on the standard launch path.
            let requiresPreparedLaunchRoute = activeLaunchMode().runsLaunchSequence
                && fixedWingLaunchPreflightWarningReason == nil
            guard let queuedWaypoint = pendingFixedWingAssistWaypoint,
                  let liveIndex = fixedWingAssistWaypointOptions.firstIndex(where: {
                      $0.id == queuedWaypoint.id &&
                          simd_distance($0.position, queuedWaypoint.position) <= 0.05
                  }),
                  (!requiresPreparedLaunchRoute || fixedWingPendingLaunchAssistRoute.map {
                      $0.targetID == queuedWaypoint.id &&
                          simd_distance($0.targetPosition, queuedWaypoint.position) <= 0.05 &&
                          fixedWingLaunchAssistRouteIsCurrent(
                              $0,
                              wing: activeFixedWingParameters(),
                              noFlyZones: activeNoFlyZonesForNavigation()
                          )
                  } == true) else {
                // The exact requested point vanished or moved while launching. Do not substitute
                // the first/current array entry. Likewise, a request queued after preflight has no
                // proven launch-to-route handoff. Hold course and require a fresh airborne choice.
                pendingFixedWingAssistMode = nil
                pendingFixedWingAssistWaypoint = nil
                fixedWingPendingLaunchAssistRoute = nil
                fixedWingAssistState.targetHeadingRadians = state.orientation.z
                fixedWingAssistState.targetAltitudeMeters = state.position.y
                activateFixedWingAssist(.headingHold)
                fixedWingLastTransitionReason = "fixed_wing_pending_launch_route_invalidated"
                return
            }
            let liveWaypoint = fixedWingAssistWaypointOptions[liveIndex]
            fixedWingAssistPinnedWaypoint = FixedWingAssistWaypointOption(
                id: queuedWaypoint.id,
                label: liveWaypoint.label,
                position: queuedWaypoint.position
            )
            fixedWingAssistState.selectedWaypointID = queuedWaypoint.id
            fixedWingAssistState.activeWaypointIndex = liveIndex
        }
        activateFixedWingAssist(pending)
        if fixedWingAssistState.mode == pending {
            pendingFixedWingAssistMode = nil
            pendingFixedWingAssistWaypoint = nil
        }
    }

    /// Bank the avoidance may assume when predicting a turn.
    ///
    /// Not the profile's unrestricted maximum: while the altitude controller is holding the real
    /// aircraft to 15-18°, assuming the full envelope underestimated the turn radius by roughly a
    /// factor of three, and the aircraft committed to gaps it could not physically make.
    /// Steers the aeroplane away, rather than swapping the guidance target.
    ///
    /// Substituting `interceptTarget` was the wrong integration and the flight log shows exactly
    /// why: on a tick where no safe course exists the substitution falls back to the waypoint, so
    /// the command flipped `blocked → −30° → blocked` and `rollCmd` slammed +18 → −0.3 → +24.6 →
    /// −12.6 → −27.5 until the aircraft was uncontrollable. Avoidance owns roll, course, pitch
    /// floor and power directly while it is active — an aeroplane escapes a street canyon with all
    /// four, not with a different waypoint.
    /// The operator is flying by hand with nothing engaged — no flight-mode autopilot, no assist,
    /// no assist pending.
    ///
    /// Forward avoidance is evaluated for any airborne fixed wing regardless of mode, deliberately
    /// (it has to be live through the launch, where it matters most). But *evaluating* and *taking
    /// the stick* are different things, and it was doing both: while it owned the lateral axis the
    /// assist branch wrote `values.roll = values.roll`, so a hand-flown aircraft had roll, yaw,
    /// pitch floor and throttle cap driven by a layer the pilot never switched on.
    ///
    /// Here the layers keep watching and keep reporting — `avoid=`, the risk score and the HUD
    /// warnings are unchanged — but they do not command. In every engaged mode (assist, autopilot,
    /// take-off, return-home, any VTOL auto phase) nothing changes.
    var operatorHasFullManualAuthority: Bool {
        mode == .manual
            && fixedWingAssistState.mode == .manual
            && pendingFixedWingAssistMode == nil
    }

    private func applyFixedWingCollisionAvoidance(
        target avoidanceTarget: SIMD2<Float>,
        wing: FixedWingParameters,
        deltaTime: Float
    ) {
        guard !operatorHasFullManualAuthority else { return }
        let current = currentPlanarPosition()
        let avoidanceCourse = fixedWingCourseRadians(from: avoidanceTarget - current)
        let courseError = shortestAngleRadians(avoidanceCourse - state.orientation.z)
        let bankLimit = fixedWingAvoidanceBankLimitDegrees(wing: wing)
        fixedWingAvoidanceReleaseRemaining = 0.0
        fixedWingAvoidanceReleaseCourseRadians = nil
        fixedWingAvoidanceLateralCommandWasActive = true
        fixedWingAvoidanceLastCommandTick = simulationTickCounter

        // Avoidance owns the roll axis while an escape course is active. Filter the bounded course
        // command so ownership changes cannot recreate the old left/right bank reversals.
        let commandBankLimit = min(Self.fixedWingAvoidanceCommandBankLimitDegrees, bankLimit)
        let commandBankLimitRadians = commandBankLimit.degreesToRadians
        let yawDamping = state.bodyAngularVelocity.z * 0.45
        var rawBiasRadians = (courseError * 0.55 - yawDamping).clamped(
            to: -commandBankLimitRadians...commandBankLimitRadians
        )

        if fixedWingAvoidanceNoSafeTrajectory {
            // A `blocked` reading is an escape, not a course correction, and the proportional law
            // is far too soft to serve as one. The committed candidate is picked only ~10 deg off
            // the present course — it is the least-bad prefix, not a scenic detour — and 0.55 of
            // that is 5.5 deg of bank: a 2.2 deg/s turn needing over 100 m of travel to deliver
            // 10 deg of heading. The flight log is exactly that number, `rollCmd=4.6` held for
            // three consecutive samples into a facade with the obstacle already inside 100 m.
            //
            // Demand the full authority the limit allows and taper only as the escape course is
            // actually reached, so the turn is delivered in the distance that remains instead of
            // asymptotically. The clamp, not the gain, is what bounds this.
            let escapeDemand = (courseError / Self.fixedWingAvoidanceEscapeTaperRadians)
                .clamped(to: -1.0...1.0) * commandBankLimitRadians
            rawBiasRadians = (escapeDemand - yawDamping).clamped(
                to: -commandBankLimitRadians...commandBankLimitRadians
            )
        }

        if abs(courseError) < 0.04 {
            rawBiasRadians *= 0.4
        }
        fixedWingAvoidanceDiagCourseErrorDegrees = courseError.radiansToDegrees
        fixedWingAvoidanceDiagRawBankDegrees = rawBiasRadians.radiansToDegrees
        let rawBias = rawBiasRadians.radiansToDegrees
        // The command filter is a comfort setting in cruise and a delay budget in an escape: at
        // 0.45 s the bias reaches only 63% of demand after nearly half a second of the little
        // distance that is left. Roll in far faster once the trajectory is blocked.
        let responseSeconds: Float = fixedWingAvoidanceNoSafeTrajectory ? 0.18 : 0.45
        let alpha = 1.0 - exp(-max(0.0001, deltaTime) / responseSeconds)
        fixedWingAvoidanceBiasDegrees += (rawBias - fixedWingAvoidanceBiasDegrees) * alpha

        let climbFloor = fixedWingAvoidanceClimbFloorDegrees(
            wing: wing,
            requireLowAltitude: true
        )
        let bias = Double(fixedWingAvoidanceBiasDegrees)
        let avoidanceBaseline = resolvedFlightBaseline(for: .autoPath)
        let noSafeThrottleCap = max(
            max(
                wing.minThrottle,
                avoidanceBaseline.effectiveMinimumSafeFlightThrottle
            ),
            avoidanceBaseline.cruiseReferenceThrottle * (
                fixedWingAvoidanceCoverageUnknown ? 0.72 : 1.0
            )
        )
        // Shedding energy is the right answer in cruise and the wrong one on departure: the launch
        // floor exists precisely because the aircraft needs every watt to reach flying speed.
        // Shedding energy is a cruise manoeuvre. Below cruise altitude or cruise speed the
        // aircraft has none to give, and taking it is how a detectable obstacle became an
        // unrecoverable mush in the flight log.
        let mayShedEnergyForSafety = fixedWingAvoidanceNoSafeTrajectory
            && !fixedWingLaunchClimbProtectionActive
            && fixedWingHasEnergyMarginForAvoidance
        if mayShedEnergyForSafety {
            fixedWingPhysicsThrottleCeiling = min(
                fixedWingPhysicsThrottleCeiling ?? noSafeThrottleCap,
                noSafeThrottleCap
            )
        }

        // Stored for the predictor and for the smooth release path; never accumulate it into the
        // persistent control value.
        fixedWingAvoidanceAppliedBiasDegrees = bias

        updateControlValues({ values in
            // Absolute, not an increment.
            //
            // The increment form belonged to the arrangement where the assist owned the axis and
            // avoidance leaned on it. Now that avoidance holds the axis while its escape is live,
            // the same form contributes almost nothing: the filtered bias barely changes tick to
            // tick, so `- previousBias + bias` ≈ 0 and the axis keeps whatever bank the assist left
            // behind at hand-over. The flight log is unambiguous — avoidance asking `+6` while the
            // aircraft sat at `rollCmd=-6.0` and flew that residual left bank into a façade.
            values.roll = bias.clamped(to: -Double(bankLimit)...Double(bankLimit))
            // Keep rudder and bank on one coordinated escape course. Letting waypoint guidance
            // overwrite yaw while avoidance owned roll produced the reported yaw weave and a
            // wing-first contact even though the commanded bank was nearly level.
            values.yaw = Double(avoidanceCourse.radiansToDegrees)
            if mayShedEnergyForSafety, climbFloor <= 0.0 {
                // Cancel an assist/launch climb request when there is no airspeed reserve. Below
                // the safe floor, use a small unloading command so speed recovery outranks height.
                let recoveryPitchCeiling = state.forwardAirspeed < wing.minSafeAirspeed
                    ? -2.0
                    : 0.0
                values.pitch = min(values.pitch, recoveryPitchCeiling)
            } else {
                values.pitch = max(values.pitch, Double(climbFloor))
            }
            if mayShedEnergyForSafety {
                // No complete escape exists: shed energy toward cruise/minimum sustainable power
                // while using the longest proven prefix. Full takeoff power shortens the remaining
                // reaction time and enlarges the turn radius.
                values.throttle = min(values.throttle, Double(noSafeThrottleCap))
            } else if selectedDroneProfile.airframeClass == .hybridVTOL {
                // A VTOL does not climb over an obstacle on wing power, so the takeoff-throttle
                // floor buys it nothing — and the branch above already names what it costs:
                // "full takeoff power shortens the remaining reaction time and enlarges the turn
                // radius". On a hybrid VTOL that cost is far larger than on a fixed wing, because
                // in cruise the throttle drives every tilted rotor: thrust is sized as
                // `throttle · dragAtCruise / cruiseReferenceThrottle`, so 0.92 against a ~0.3
                // reference is about three times the drag-balancing thrust, and speed settles
                // near its square root above cruise. The recorded flights show exactly that —
                // every `avCmd=yes` tick carries `thr=0.92`, and the aircraft that were avoiding
                // obstacles were doing it at 40-44 m/s against 17-22 m/s published cruise, which
                // is a four-to-seven-fold turn radius and is why they could not turn away from
                // the building they had detected.
                //
                // Leave the throttle to the speed loop. Avoidance owns roll, yaw and the climb
                // floor here; it has no business adding energy to an airframe whose escape is a
                // turn, not a zoom.
            } else {
                values.throttle = max(
                    values.throttle,
                    Double(max(
                        resolvedFlightBaseline(for: .takeoff).takeoffThrottleReference,
                        wing.maxThrottle * 0.92
                    ))
                )
            }
        }, markManual: false)
    }

    /// Climbing is useful only while the wing has an airspeed reserve. The previous unconditional
    /// 12-degree floor combined a below-stall throttle ceiling with a climb command, converting an
    /// obstacle response into a guaranteed energy loss.
    private func fixedWingAvoidanceClimbFloorDegrees(
        wing: FixedWingParameters,
        requireLowAltitude: Bool
    ) -> Float {
        if requireLowAltitude,
           heightAboveSupportSurface(for: state.position) >= 16.0 {
            return 0.0
        }
        let requiredReserve = max(1.5, wing.minSafeAirspeed * 0.08)
        guard state.forwardAirspeed - wing.minSafeAirspeed >= requiredReserve else {
            return 0.0
        }
        return min(
            wing.maxPitchUpDeg,
            max(wing.initialClimbPitchDeg, 12.0)
        )
    }

    /// Fraction of full bank authority the low-altitude protection permits, from height above the
    /// surface. Quantised to 5 m so a continuously changing height cannot churn the planner's grid
    /// and route-validation cache keys.
    private func fixedWingLowAltitudeBankAuthority(wing: FixedWingParameters) -> Float {
        let height = max(0.0, heightAboveSupportSurface(for: state.position))
        let quantized = (height / 5.0).rounded(.down) * 5.0
        return (quantized / max(wing.initialClimbTargetAltitude, 1.0)).clamped(to: 0.35...1.0)
    }

    private func fixedWingAvoidanceBankLimitDegrees(
        wing: FixedWingParameters
    ) -> Float {
        // Height above the surface, not distance below the route's cruise level.
        //
        // Keyed on the deficit this pinned at its 0.35 floor for an entire climb to a high cruise
        // altitude, and that one number drove every downstream failure: 0.35 authority is ~10 deg
        // of bank, which predicts a 213 m turn radius at 20 m/s, which makes the escape horizon
        // longer than any city street, which makes `blocked` permanent, which hands both lateral
        // axes to a layer that then cannot turn — `rollCmd` frozen at -1.7 for twelve consecutive
        // samples, straight into a facade. The hazard being guarded against is a banked turn close
        // to the ground; an aircraft 38 m over a city is not in it merely because its cruise level
        // is another 57 m up.
        let bankAuthority = fixedWingLowAltitudeBankAuthority(wing: wing)
        // This is a command limit, not a promise of instantaneous achieved bank. The trajectory
        // rollout below starts at actual roll and applies both command and airframe response lag.
        let permitted = max(wing.maxInitialBankDeg, wing.maxBankAngleDeg * bankAuthority)
        return min(Self.fixedWingAvoidanceCommandBankLimitDegrees, permitted * 0.75)
    }

    /// True while the launch controller owns the departure: from release until it hands over.
    ///
    /// Reactive avoidance is a cruise safety layer. During a hand launch or catapult throw the
    /// aircraft is at its lowest energy and inside a corridor the launch preflight (or the
    /// operator) already chose, and its horizon requirement cannot be met from ground level in a
    /// city — so it reports `blocked` from the first airborne tick and then acts on that. The
    /// flight log shows what acting on it costs: throttle capped at 0.45 against a takeoff floor
    /// of ~0.65, speed decaying 16.9 -> 16.4 m/s at 15 degrees of pitch, and a -10 degree escape
    /// command on both lateral axes that the pilot could not override. That is a worse departure
    /// than the one it was protecting against.
    /// Final throttle ceiling handed to the physics: the existing safety ceiling, further limited
    /// so the aircraft cannot run away from its own airspeed envelope.
    ///
    /// Sizing thrust for the declared climb rate is what finally let a fixed wing get above a
    /// city, but the climb reserve is only useful while it buys height. At the 0.92 throttle the
    /// launch and climb logic commands, that reserve instead accelerated the aircraft to 30.6 m/s
    /// against a 19.5 m/s cruise — and turn radius goes as the square of speed, so the predicted
    /// radius went past 280 m and the aeroplane could no longer turn at all. It flew level into a
    /// building at 465 J with `avoid` reporting blocked the whole way.
    ///
    /// A real autopilot answers this with an airspeed limiter, not by giving the climb back.
    private func fixedWingAirspeedLimitedThrottleCeiling() -> Float? {
        guard let wing = selectedDroneProfile.fixedWingParameters else {
            return fixedWingPhysicsThrottleCeiling
        }
        let limit = max(wing.climbAirspeed, wing.cruiseAirspeed)
            * Self.fixedWingAirspeedLimitFactor
        let airspeed = max(0.0, state.forwardAirspeed)
        guard airspeed > limit else { return fixedWingPhysicsThrottleCeiling }
        // Proportional bleed rather than a step: a throttle cliff at the limit is its own
        // oscillation, and the aircraft still needs power to hold height while it slows.
        let overspeed = (airspeed - limit) / max(1.0, limit)
        let baseline = resolvedFlightBaseline(for: .autoPath)
        let ceiling = max(
            max(wing.minThrottle, baseline.effectiveMinimumSafeFlightThrottle),
            baseline.cruiseReferenceThrottle * (1.0 - overspeed * 2.0)
        )
        guard let existing = fixedWingPhysicsThrottleCeiling else { return ceiling }
        return min(existing, ceiling)
    }

    /// How far above its own climb/cruise airspeed a fixed wing may run before power is bled.
    ///
    /// Deliberately generous. At 1.12 the limit landed on 21.8 m/s, which is exactly the speed the
    /// aircraft naturally settles at in a full-power climb — so the limiter fought the climb it was
    /// supposed to protect and the rate fell back to ~1.2 m/s. The runaway this exists to catch was
    /// 30.6 m/s, not 22. At 1.25 the limit is 24.4 m/s: normal climb is untouched, the runaway is
    /// still caught, and the turn radius at the limit stays near 150 m rather than 280.
    private static let fixedWingAirspeedLimitFactor: Float = 1.25

    private var fixedWingLaunchClimbProtectionActive: Bool {
        guard selectedDroneProfile.airframeClass == .fixedWing else { return false }
        if mode == .takeoff || launchState.blocksRouteCapture { return true }
        // The launch state machine hands over at roughly 25 m, not at cruise. Ending the
        // protection there put the aircraft straight back under the blocked-branch throttle cap
        // with no energy to absorb it: the flight log shows throttle collapsing 0.92 -> 0.45 on
        // the very tick `fixed_wing_launch_completed` fires, airspeed then decaying 18.5 -> 16.7
        // and the climb dying to 0.14 m/s at 28 m — a mush straight into a building. The aircraft
        // is still establishing until it has both its cruise level and its cruise speed.
        return !fixedWingHasEnergyMarginForAvoidance
    }

    /// Whether the aircraft has energy it can afford to spend on an avoidance manoeuvre.
    ///
    /// Below cruise altitude or below cruise speed it does not: every joule is committed to
    /// getting established, and a safety layer that takes some is making the situation worse than
    /// the one it is responding to.
    private var fixedWingHasEnergyMarginForAvoidance: Bool {
        guard let wing = selectedDroneProfile.fixedWingParameters else { return true }
        let cruiseTarget = fixedWingAssistState.targetAltitudeMeters
            ?? fixedWingAutopilotAltitudeCommand
            ?? activeRouteTargetAltitude
        if let cruiseTarget, state.position.y < cruiseTarget - 8.0 {
            return false
        }
        return state.forwardAirspeed >= wing.cruiseAirspeed * 0.97
    }

    private func resetFixedWingAvoidanceState() {
        fixedWingAvoidanceHeadingOffset = nil
        fixedWingAvoidanceNoSafeTrajectory = false
        fixedWingAvoidanceCoverageUnknown = false
        fixedWingAvoidanceCourseRadians = nil
        fixedWingAvoidanceTurnSign = nil
        fixedWingAvoidanceOppositeSideEscapeUsed = false
        fixedWingAvoidanceReplanEpisodeActive = false
        fixedWingAvoidanceClearSinceTime = nil
        fixedWingAvoidanceBlockedSinceTime = nil
        fixedWingAvoidanceEvaluationTick = nil
        fixedWingAvoidanceNextEvaluationTime = 0.0
        fixedWingAvoidanceCachedTarget = nil
        fixedWingAvoidancePredictedTurnRadiusMeters = nil
        fixedWingMeshSpeedGovernorTargetMps = nil
        fixedWingPhysicsThrottleCeiling = nil
        fixedWingAvoidanceHoldCourse = nil
        fixedWingAvoidanceHoldRemaining = 0.0
        fixedWingAvoidanceHoldSign = 0
        fixedWingAvoidanceBiasDegrees = 0.0
        fixedWingAvoidanceAppliedBiasDegrees = 0.0
        fixedWingAvoidanceReleaseCourseRadians = nil
        fixedWingAvoidanceReleaseRemaining = 0.0
        fixedWingAvoidanceLateralCommandWasActive = false
        fixedWingAvoidanceHoldWasFresh = true
    }

    /// Rebuild only the moving join to the current target, once per blocked episode. The selected
    /// user waypoint (or mission target/index) stays intact; clearing it here would turn collision
    /// avoidance into another route-skip mechanism.
    private func requestFixedWingAvoidanceReplanIfNeeded() {
        guard !fixedWingAvoidanceReplanEpisodeActive else { return }
        fixedWingAvoidanceReplanEpisodeActive = true

        fixedWingSafeRouteCacheKey = nil
        fixedWingSafeRouteCacheRoute = nil
        fixedWingSafeRouteCacheStoresNil = false
        fixedWingSafeRouteLastFailureWasTransient = false
        fixedWingRoutePlanner.invalidate()

        if fixedWingAssistState.mode == .waypointIntercept {
            fixedWingProtectedRouteProgress = nil
            fixedWingFlyByPlanCacheKey = nil
            fixedWingFlyByPlanCache = nil
        } else {
            fixedWingAutopilotController.reset()
        }
        resetFixedWingRuntimeRouteStart()
    }

    /// Which airframes the predictive forward-avoidance layer owns.
    ///
    /// It was `airframeClass == .fixedWing`, which left every hybrid VTOL with no predictive
    /// avoidance at all — not because the physics did not suit them, but because of the class
    /// label. A tilt-rotor or tailsitter in wingborne cruise *is* a banking, turn-radius-limited
    /// aeroplane and needs the same ~800 m corridor proof; in hover it is a multirotor and needs
    /// the lateral sidestep instead (see `multirotorCollisionAvoidanceTarget`). The regime, not the
    /// catalogue entry, decides.
    ///
    /// VTOLs additionally require an automatic mode: unlike the fixed wing, whose avoidance is
    /// deliberately always live, a hand-flown VTOL is left to its pilot.
    /// The operator is flying the VTOL by hand — manual mode with nothing routing it.
    ///
    /// In manual the pilot answers for the aircraft and the layers only warn, so coverage is
    /// withheld here. A running or paused mission, or a live route altitude, means the autopilot
    /// has the aircraft even if `mode` briefly reads `.hover` or `.manual` while a leg hands over.
    private var operatorIsHandFlyingVTOL: Bool {
        mode == .manual
            && missionExecutionState.status != .running
            && missionExecutionState.status != .paused
            && activeRouteTargetAltitude == nil
    }

    private var forwardAvoidanceCoversActiveAirframe: Bool {
        guard physicalState == .airborne else { return false }
        switch selectedDroneProfile.airframeClass {
        case .fixedWing:
            return true
        case .hybridVTOL:
            // Cover the situation, not the mode label.
            //
            // `mode.isAutoControlled` dropped coverage one tick before an impact while the wing was
            // still carrying 88% of the weight at cruise speed beside a building: measured
            // `fwdCov=no auto=no wbLatch=yes wb=0.88`, and the label had gone `autoPath → hover →
            // manual` under a *running* mission. The physical question is whether this thing is
            // currently flying like an aeroplane — that is `vtolWingborneAvoidanceLatched` — and
            // the only reason to withhold the layer is that the operator has taken the aircraft,
            // which a transient mode label during an autopilot leg is not.
            return vtolWingborneAvoidanceLatched && !operatorIsHandFlyingVTOL
        case .multirotor:
            return false
        }
    }

    /// Updates which avoidance controller owns the hybrid from physical transition state.
    private func refreshVTOLWingborneAvoidanceLatch() {
        guard selectedDroneProfile.airframeClass == .hybridVTOL else {
            vtolWingborneAvoidanceLatched = false
            return
        }
        // The protected route and multirotor sidestep own rotor-borne flight;
        // the bank/roll avoidance law must engage only after the airframe has
        // physically started its wing transition.  Ground speed is not a
        // valid regime signal: the reported Wingtra fall reached the old
        // threshold at `progress=0, wingborne=0`, latched fixed-wing bank
        // commands during a tumble, and made recovery worse.  Transition
        // progress gives early coverage before lift jumps to 1.0, while the
        // lower release thresholds keep the hand-back to hover hysteretic.
        let wasLatched = vtolWingborneAvoidanceLatched
        vtolWingborneAvoidanceLatched = HybridVTOLFlightPolicy
            .nextFixedWingAvoidanceLatchState(
                isLatched: wasLatched,
                transitionProgress: state.vtolTransitionProgress,
                wingborneBlend: state.vtolWingborneBlend
            )
        if wasLatched && !vtolWingborneAvoidanceLatched {
            resetFixedWingAvoidanceState()
        }
    }

    private func fixedWingForwardAvoidanceTarget(wing: FixedWingParameters) -> SIMD2<Float>? {
        if fixedWingAvoidanceEvaluationTick == simulationTickCounter {
            return fixedWingAvoidanceCachedTarget
        }
        if fixedWingAvoidanceEvaluationTick != nil,
           simulationTime < fixedWingAvoidanceNextEvaluationTime {
            fixedWingAvoidanceEvaluationTick = simulationTickCounter
            return fixedWingAvoidanceCachedTarget
        }

        var evaluatedTarget: SIMD2<Float>?
        defer {
            fixedWingAvoidanceEvaluationTick = simulationTickCounter
            fixedWingAvoidanceCachedTarget = evaluatedTarget
            // 10 Hz while an escape is active, 5 Hz in clear flight. At 20 m/s these are 2 m and
            // 4 m respectively, both below the protected corridor sampling/clearance envelope.
            fixedWingAvoidanceNextEvaluationTime = simulationTime + (
                fixedWingAvoidanceCourseRadians != nil || fixedWingAvoidanceNoSafeTrajectory
                    ? 0.10
                    : 0.20
            )
        }
        fixedWingAvoidanceNoSafeTrajectory = false
        fixedWingAvoidanceCoverageUnknown = false

        // Turn dynamics depend on true airspeed; displacement over the city depends on ground
        // velocity. Treating one as the other made the predicted radius wrong in wind and moved
        // the collision samples to the wrong side of a facade.
        let airspeed = max(6.0, state.forwardAirspeed)
        let currentGroundSpeed = max(
            6.0,
            simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        )
        let windXZ = SIMD2<Float>(weather.windVector.x, weather.windVector.z)
        // Predict with the bank authority available *now*, not with the profile's maximum bank.
        // In the failed run the altitude target was 95.5 m while the aircraft was at 32 m, so
        // low-altitude protection allowed about 15° of bank. The old max-bank radius predicted a
        // ~45 m turn; the aircraft actually needed well over 100 m and its "clear" final ray was
        // reached only after the intervening arc had gone through the façade.
        let bankLimitDegrees = fixedWingAvoidanceBankLimitDegrees(wing: wing)
        let bankRadians = max(5.0, bankLimitDegrees).degreesToRadians
        let bankLimitedTurnRadius = airspeed * airspeed / max(
            0.1,
            9.81 * tan(bankRadians)
        )
        let turnRadius = max(
            wing.waypointAcceptanceRadiusMeters * 1.1,
            bankLimitedTurnRadius
        )
        fixedWingAvoidancePredictedTurnRadiusMeters = turnRadius
        let requiredLookahead = fixedWingRequiredObstacleLookahead(
            airspeed: airspeed,
            turnRadius: turnRadius
        )
        let lookahead: Float
        if usesMeshCellsForPlanning,
           requiredLookahead > Self.fixedWingMaximumMeshLookaheadMeters {
            // The narrow trajectory-tube query below is no longer limited to a 700 m square.
            // Keep the speed governor as a manoeuvrability preference, but never truncate the
            // safety proof to its old cache window.
            fixedWingMeshSpeedGovernorTargetMps = fixedWingMaximumAirspeedForMeshHorizon(
                wing: wing,
                bankLimitDegrees: bankLimitDegrees
            ) ?? (wing.minSafeAirspeed * 1.05)
            lookahead = requiredLookahead
        } else {
            fixedWingMeshSpeedGovernorTargetMps = nil
            lookahead = requiredLookahead
        }
        let position = currentPlanarPosition()
        let heading = state.orientation.z
        let commandedGuidanceCourse: Float = {
            // Once an escape is committed, `heading` is the useful forward-clear reference; the
            // locked course is evaluated separately below. Otherwise model the turn guidance has
            // already requested. Proving a straight nose ray while the previous tick's waypoint
            // command is banking into a facade is a direct fail-open.
            if fixedWingAvoidanceCourseRadians != nil {
                return heading
            }
            if fixedWingAssistState.mode != .manual,
               let target = fixedWingAssistState.targetHeadingRadians {
                return target
            }
            if let target = fixedWingAutopilotCourseCommand {
                return target
            }
            return heading
        }()
        let guidanceUsesAssistLateralLoop = fixedWingAssistState.mode != .manual
        let guidanceUsesAutopilotLateralLoop = !guidanceUsesAssistLateralLoop
            && (mode == .autoPath || mode == .returnHome || mode == .takeoff)
            && fixedWingAutopilotCourseCommand != nil
        let guidanceUsesNominalLateralLoop = guidanceUsesAssistLateralLoop
            || guidanceUsesAutopilotLateralLoop
        let measuredAirVelocity = SIMD2<Float>(
            state.velocity.x - windXZ.x,
            state.velocity.z - windXZ.y
        )
        let measuredAirVelocityMagnitude = simd_length(measuredAirVelocity)
        let initialAirCourse = measuredAirVelocityMagnitude > 0.75
            ? fixedWingCourseRadians(from: measuredAirVelocity / measuredAirVelocityMagnitude)
            : heading
        let corridorHalfWidth = max(5.0, fixedWingNavigationEnvelopeRadius + 2.0)
        let rolloutGroundSpeedBound = max(
            currentGroundSpeed,
            airspeed + simd_length(windXZ),
            6.0
        )
        // Sample at less than half the protected corridor width. Mesh contacts are swept between
        // poses, while this bound also prevents a thin semantic tree from passing entirely between
        // two signed-distance samples at high ground speed.
        let rolloutStepTime = min(
            0.40,
            max(0.04, max(1.5, corridorHalfWidth * 0.45) / rolloutGroundSpeedBound)
        )
        let rolloutTargetAltitude: Float = {
            if fixedWingAssistState.mode == .waypointIntercept,
               let altitude = fixedWingAssistState.targetAltitudeMeters {
                return altitude
            }
            return fixedWingAutopilotAltitudeCommand
                ?? activeRouteTargetAltitude
                ?? state.position.y
        }()
        let fullRolloutDuration = max(
            8.0,
            turnRadius * 1.60 / airspeed + Self.fixedWingTurnRollInSeconds,
            lookahead / currentGroundSpeed
        )
        // A candidate is a constant-course rollout; it does not magically join and begin following
        // `fixedWingProtectedRouteProgress` at the next corner. Truncating here turned a collision
        // at 2.1 s into a clear 2.0 s proof. Always validate the complete dynamic horizon.
        let rolloutDuration = fullRolloutDuration
        let requestedVerticalRate = (rolloutTargetAltitude - state.position.y) / rolloutDuration
        // A safety rollout may not assume the aircraft will achieve a requested climb before a
        // roof/facade. Retain descent risk, but give zero credit for future positive altitude.
        let boundedRequestedVerticalRate = requestedVerticalRate.clamped(
            to: -max(0.1, selectedDroneProfile.maxDescentSpeedMps)...max(
                0.1,
                selectedDroneProfile.maxAscentSpeedMps
            )
        )
        let verticalRate = min(0.0, boundedRequestedVerticalRate)
        let upperVerticalRate = max(0.0, boundedRequestedVerticalRate)

        // Broad-phase sampling: one point per ~24 m of track rather than one per integration step.
        // The chord that replaces each kept arc deviates from it by at most c²/(8R), so the query
        // margin below absorbs exactly that and the returned obstacle set stays a superset.
        let queryPointSpacingMeters: Float = 24.0
        let rolloutStepDistance = max(0.5, rolloutStepTime * rolloutGroundSpeedBound)
        let queryEmitStride = max(1, Int((queryPointSpacingMeters / rolloutStepDistance).rounded(.down)))
        let queryChordMeters = rolloutStepDistance * Float(queryEmitStride)
        let queryChordSagittaMeters = queryChordMeters * queryChordMeters
            / (8.0 * max(20.0, turnRadius))
        let queryMargin = corridorHalfWidth + 24.0 + queryChordSagittaMeters

        let candidateMagnitudes: [Float] = [0.17, 0.35, 0.52, 0.79, 1.05, 1.40]

        // Build the same lagged, coordinated-turn trajectories once for the world query. A tube
        // scales with route length, whereas the old square radius scaled with horizon squared and
        // silently returned no mesh at all past its cell limit.
        func obstacleQueryPath(
            course desiredCourse: Float,
            duration requestedDuration: Float? = nil,
            useAssistController: Bool = false,
            useAutopilotController: Bool = false,
            useUpperVerticalEnvelope: Bool = false
        ) -> [SIMD3<Float>] {
            let predictionDuration = min(rolloutDuration, max(0.0, requestedDuration ?? rolloutDuration))
            var point = position
            var altitude = state.position.y
            var course = initialAirCourse
            var filteredBankDegrees: Float = {
                if useAssistController {
                    return fixedWingLatestAssistRollCommandDegrees ?? 0.0
                }
                if useAutopilotController {
                    return fixedWingLatestAutopilotRollCommandDegrees ?? 0.0
                }
                return fixedWingAvoidanceBiasDegrees
            }()
            var predictedFilteredCourse: Float = {
                if useAssistController {
                    return fixedWingLatestAssistCourseCommandRadians ?? desiredCourse
                }
                if useAutopilotController {
                    return fixedWingLatestAutopilotCourseCommandRadians ?? desiredCourse
                }
                return desiredCourse
            }()
            var achievedBankDegrees = state.orientation.x.radiansToDegrees
            var predictedYawRate = state.bodyAngularVelocity.z
            var predictedRollRateDegrees = state.bodyAngularVelocity.x.radiansToDegrees
            var predictedVerticalVelocity = useUpperVerticalEnvelope
                ? max(state.velocity.y, 0.0)
                : min(state.velocity.y, 0.0)
            var elapsed: Float = 0.0
            let timeStep = rolloutStepTime
            var path = [SIMD3<Float>(point.x, altitude, point.y)]
            var emittedStepIndex = 0

            while elapsed < predictionDuration {
                let stepTime = min(timeStep, predictionDuration - elapsed)
                guard stepTime > 0.0001 else { break }
                if useAssistController || useAutopilotController {
                    let courseFilterTau = useAssistController
                        ? FixedWingAssistLateralTuning.courseFilterTau
                        : FixedWingAutopilotLateralTuning.courseFilterTau
                    let courseAlpha = 1.0 - exp(
                        -stepTime / courseFilterTau
                    )
                    predictedFilteredCourse = shortestAngleRadians(
                        predictedFilteredCourse
                            + shortestAngleRadians(
                                desiredCourse - predictedFilteredCourse
                            ) * courseAlpha
                    )
                }
                let controllerCourse = useAssistController || useAutopilotController
                    ? predictedFilteredCourse
                    : desiredCourse
                let courseError = shortestAngleRadians(controllerCourse - course)
                // Mirrors the controllers' own low-altitude protection, which is keyed on height
                // above the surface. The rollout climbs with the aircraft, so track that height.
                let assistAltitudeFactor = (
                    max(0.0, heightAboveSupportSurface(for: state.position)
                        + (altitude - state.position.y))
                        / max(wing.initialClimbTargetAltitude, 1.0)
                ).clamped(to: 0.35...1.0)
                let commandBankLimit: Float = {
                    if useAssistController {
                        return min(
                        FixedWingAssistLateralTuning.maxBankDeg,
                        wing.maxBankAngleDeg
                        ) * assistAltitudeFactor
                    }
                    if useAutopilotController {
                        return wing.maxBankAngleDeg
                            * FixedWingAutopilotLateralTuning.maximumBankScale
                            * assistAltitudeFactor
                    }
                    return bankLimitDegrees
                }()
                let headingGain = useAssistController
                    ? FixedWingAssistLateralTuning.headingBankGain
                    : (useAutopilotController
                        ? FixedWingAutopilotLateralTuning.bankProportionalGain
                        : 0.55)
                let rateGain = useAssistController
                    ? FixedWingAssistLateralTuning.headingRateDampingGain
                    : (useAutopilotController ? 0.0 : 0.45)
                let rawBankRadians = (
                    courseError * headingGain - predictedYawRate * rateGain
                ).clamped(
                    to: -commandBankLimit.degreesToRadians...commandBankLimit.degreesToRadians
                )
                let rawBankDegrees = rawBankRadians.radiansToDegrees
                let commandAlpha = 1.0 - exp(-stepTime / (
                    useAssistController
                        ? FixedWingAssistLateralTuning.bankFilterTau
                        : (useAutopilotController
                            ? FixedWingAutopilotLateralTuning.bankFilterTau
                            : 0.45)
                ))
                filteredBankDegrees += (rawBankDegrees - filteredBankDegrees) * commandAlpha
                let previousAchievedBank = achievedBankDegrees
                let targetRollRateDegrees = (
                    (filteredBankDegrees - achievedBankDegrees) /
                        Self.fixedWingAvoidancePredictedRollResponseSeconds
                ).clamped(to: -60.0...60.0)
                let rollRateAlpha = 1.0 - exp(-stepTime / 0.35)
                predictedRollRateDegrees += (
                    targetRollRateDegrees - predictedRollRateDegrees
                ) * rollRateAlpha
                achievedBankDegrees += predictedRollRateDegrees * stepTime
                achievedBankDegrees = achievedBankDegrees.clamped(
                    to: -wing.maxBankAngleDeg...wing.maxBankAngleDeg
                )
                let midpointBank = (previousAchievedBank + achievedBankDegrees) * 0.5
                let coordinatedYawRate = 9.81 * tan(midpointBank.degreesToRadians) / airspeed
                let yawRateAlpha = 1.0 - exp(-stepTime / 0.45)
                predictedYawRate += (coordinatedYawRate - predictedYawRate) * yawRateAlpha
                let courseStep = predictedYawRate * stepTime
                let midpointCourse = course + courseStep * 0.5
                let airVelocity = SIMD2<Float>(
                    -sin(midpointCourse),
                    -cos(midpointCourse)
                ) * airspeed
                let groundVelocity = airVelocity + windXZ
                let displacement = groundVelocity * stepTime
                point += displacement
                let verticalAlpha = 1.0 - exp(-stepTime / 1.0)
                let selectedVerticalRate = useUpperVerticalEnvelope
                    ? upperVerticalRate
                    : verticalRate
                predictedVerticalVelocity += (
                    selectedVerticalRate - predictedVerticalVelocity
                ) * verticalAlpha
                altitude += predictedVerticalVelocity * stepTime
                course = shortestAngleRadians(course + courseStep)
                elapsed += stepTime
                emittedStepIndex += 1
                // Integrate finely, emit coarsely.
                //
                // These polylines exist only to ask the world "what is near this tube" — the
                // narrow phase rebuilds its own trajectories. Emitting every integration step
                // sampled the tube ~7x finer than its own 24 m+ margin can distinguish, and both
                // the broad-phase query and the envelope pass are linear in point count. Measured:
                // this probe was 40-55 ms of a 42-57 ms tick, i.e. essentially the entire frame,
                // with ~15 courses x 3 envelope paths x ~244 points at 44 m/s.
                //
                // The integration itself is untouched, so the geometry is identical; only the
                // chords between kept samples are longer, and `queryChordSagittaMeters` below pays
                // for exactly that by widening the query margin. Lower/upper stay index-aligned
                // because they share the stride, so the bridge path still pairs correctly.
                if emittedStepIndex % queryEmitStride == 0 || elapsed >= predictionDuration {
                    path.append(SIMD3<Float>(point.x, altitude, point.y))
                }
            }
            return path
        }

        func obstacleQueryEnvelopePaths(
            course desiredCourse: Float,
            duration requestedDuration: Float? = nil,
            useAssistController: Bool = false,
            useAutopilotController: Bool = false
        ) -> [[SIMD3<Float>]] {
            let lower = obstacleQueryPath(
                course: desiredCourse,
                duration: requestedDuration,
                useAssistController: useAssistController,
                useAutopilotController: useAutopilotController
            )
            let upper = obstacleQueryPath(
                course: desiredCourse,
                duration: requestedDuration,
                useAssistController: useAssistController,
                useAutopilotController: useAutopilotController,
                useUpperVerticalEnvelope: true
            )
            let pairedChordCount = min(lower.count, upper.count) - 1
            guard pairedChordCount > 0 else {
                return [lower, upper]
            }

            // One continuous serpentine path covers every lower↔upper midpoint bridge while its
            // connectors alternate along the already-required boundary trajectories. Including it
            // in the SceneController query prevents an obstacle in the gap from being absent from
            // the later narrow-phase index.
            var bridge = [SIMD3<Float>]()
            bridge.reserveCapacity(pairedChordCount * 2)
            for index in 0..<pairedChordCount {
                let lowerMidpoint = (lower[index] + lower[index + 1]) * 0.5
                let upperMidpoint = (upper[index] + upper[index + 1]) * 0.5
                if index.isMultiple(of: 2) {
                    bridge.append(lowerMidpoint)
                    bridge.append(upperMidpoint)
                } else {
                    bridge.append(upperMidpoint)
                    bridge.append(lowerMidpoint)
                }
            }
            return [lower, upper, bridge]
        }

        func obstaclesWithinAvoidanceEnvelope(
            _ candidates: [CollisionObstacle],
            paths: [[SIMD3<Float>]]
        ) -> [CollisionObstacle] {
            var minimumY = Float.greatestFiniteMagnitude
            var maximumY = -Float.greatestFiniteMagnitude
            for path in paths {
                for point in path where point.y.isFinite {
                    minimumY = min(minimumY, point.y)
                    maximumY = max(maximumY, point.y)
                }
            }
            guard minimumY.isFinite, maximumY.isFinite else {
                // Invalid predictor geometry must never make a corridor appear empty/clear.
                // Retain every candidate so the narrow phase remains conservative.
                return candidates
            }
            let protectedMinimumY = minimumY - corridorHalfWidth
            let protectedMaximumY = maximumY + corridorHalfWidth
            return candidates.filter { obstacle in
                obstacle.topY >= protectedMinimumY && obstacle.baseY <= protectedMaximumY
            }
        }

        var queryPaths = obstacleQueryEnvelopePaths(
            course: commandedGuidanceCourse,
            useAssistController: guidanceUsesAssistLateralLoop,
            useAutopilotController: guidanceUsesAutopilotLateralLoop
        )
        if guidanceUsesNominalLateralLoop {
            // Bound controller-state uncertainty with both the live faster assist loop and the
            // slower avoidance takeover model. A corridor is forward-clear only if both are.
            queryPaths.append(contentsOf: obstacleQueryEnvelopePaths(
                course: commandedGuidanceCourse
            ))
        }
        if let lockedCourse = fixedWingAvoidanceCourseRadians {
            queryPaths.append(contentsOf: obstacleQueryEnvelopePaths(course: lockedCourse))
        }
        for magnitude in candidateMagnitudes {
            queryPaths.append(contentsOf: obstacleQueryEnvelopePaths(
                course: shortestAngleRadians(heading + magnitude)
            ))
            queryPaths.append(contentsOf: obstacleQueryEnvelopePaths(
                course: shortestAngleRadians(heading - magnitude)
            ))
        }
        let obstacleQuery = sceneController.nearbyEnvironmentObstacles(
            along: queryPaths,
            margin: queryMargin,
            includeMesh: usesMeshCellsForPlanning
        )
        let obstacleCoverageComplete = obstacleQuery.isComplete
        let obstacles = obstaclesWithinAvoidanceEnvelope(
            obstacleQuery.obstacles,
            paths: queryPaths
        )
        let sharedMeshObstacles = obstacles.filter {
            $0.source.hasPrefix("world.mesh.cell")
        }
        let sharedShapedObstacles = obstacles.filter {
            !$0.source.hasPrefix("world.mesh.cell")
        }
        let sharedMeshObstacleIndex = CollisionObstacleSpatialIndex(
            obstacles: sharedMeshObstacles,
            cellSize: 24.0
        )
        let sharedShapedObstacleIndex = CollisionObstacleSpatialIndex(
            obstacles: sharedShapedObstacles,
            cellSize: 32.0
        )
        // Lower and upper rollouts are evaluated sequentially for one candidate. Retain the
        // lower chords so the upper pass can sweep the complete bridge between both reachable
        // trajectories instead of checking two disconnected optimistic lines.
        var currentLowerRolloutChords: [(start: SIMD3<Float>, end: SIMD3<Float>)] = []

        func computeTrajectoryAssessment(
            course desiredCourse: Float,
            useAssistController: Bool,
            useAutopilotController: Bool,
            useUpperVerticalEnvelope: Bool
        ) -> FixedWingAvoidanceTrajectoryAssessment {
            // A very wide fan can exceed the union-query budget even though each individual tube
            // is answerable. Retry this exact candidate on its own before declaring coverage
            // unknown. If even that is too long, prove a bounded local prefix and score it only as
            // an emergency prefix — never as a fully clear trajectory.
            let assessmentObstacles: [CollisionObstacle]
            let assessmentCoversFullHorizon: Bool
            let assessmentDuration: Float
            if obstacleCoverageComplete {
                assessmentObstacles = obstacles
                assessmentCoversFullHorizon = true
                assessmentDuration = rolloutDuration
            } else {
                let singleCoursePaths = obstacleQueryEnvelopePaths(
                    course: desiredCourse,
                    useAssistController: useAssistController,
                    useAutopilotController: useAutopilotController
                )
                let singleCourseQuery = sceneController.nearbyEnvironmentObstacles(
                    along: singleCoursePaths,
                    margin: queryMargin,
                    includeMesh: usesMeshCellsForPlanning
                )
                if singleCourseQuery.isComplete {
                    assessmentObstacles = obstaclesWithinAvoidanceEnvelope(
                        singleCourseQuery.obstacles,
                        paths: singleCoursePaths
                    )
                    assessmentCoversFullHorizon = true
                    assessmentDuration = rolloutDuration
                } else {
                    let localDuration = min(
                        rolloutDuration,
                        max(4.0, min(8.0, 600.0 / rolloutGroundSpeedBound))
                    )
                    let localPaths = obstacleQueryEnvelopePaths(
                        course: desiredCourse,
                        duration: localDuration,
                        useAssistController: useAssistController,
                        useAutopilotController: useAutopilotController
                    )
                    let localQuery = sceneController.nearbyEnvironmentObstacles(
                        along: localPaths,
                        margin: queryMargin,
                        includeMesh: usesMeshCellsForPlanning
                    )
                    guard localQuery.isComplete else {
                        return FixedWingAvoidanceTrajectoryAssessment(
                            isClear: false,
                            hasKnownCoverage: false,
                            firstContactDistanceMeters: 0.0,
                            minimumClearanceMeters: 0.0
                        )
                    }
                    assessmentObstacles = obstaclesWithinAvoidanceEnvelope(
                        localQuery.obstacles,
                        paths: localPaths
                    )
                    assessmentCoversFullHorizon = false
                    assessmentDuration = localDuration
                }
            }

            let assessmentMeshObstacles: [CollisionObstacle]
            let assessmentShapedObstacles: [CollisionObstacle]
            let assessmentMeshObstacleIndex: CollisionObstacleSpatialIndex
            let assessmentShapedObstacleIndex: CollisionObstacleSpatialIndex
            if obstacleCoverageComplete {
                assessmentMeshObstacles = sharedMeshObstacles
                assessmentShapedObstacles = sharedShapedObstacles
                assessmentMeshObstacleIndex = sharedMeshObstacleIndex
                assessmentShapedObstacleIndex = sharedShapedObstacleIndex
            } else {
                assessmentMeshObstacles = assessmentObstacles.filter {
                    $0.source.hasPrefix("world.mesh.cell")
                }
                assessmentShapedObstacles = assessmentObstacles.filter {
                    !$0.source.hasPrefix("world.mesh.cell")
                }
                assessmentMeshObstacleIndex = CollisionObstacleSpatialIndex(
                    obstacles: assessmentMeshObstacles,
                    cellSize: 24.0
                )
                assessmentShapedObstacleIndex = CollisionObstacleSpatialIndex(
                    obstacles: assessmentShapedObstacles,
                    cellSize: 32.0
                )
            }
            // The lower pass still records its dynamic chords when this individual query is
            // empty. With an incomplete union the upper query can contain different obstacles,
            // and its closed-volume proof needs the paired lower geometry.
            if assessmentObstacles.isEmpty, useUpperVerticalEnvelope {
                return FixedWingAvoidanceTrajectoryAssessment(
                    isClear: assessmentCoversFullHorizon,
                    hasKnownCoverage: true,
                    firstContactDistanceMeters: assessmentCoversFullHorizon
                        ? .greatestFiniteMagnitude
                        : assessmentDuration * rolloutGroundSpeedBound,
                    minimumClearanceMeters: .greatestFiniteMagnitude
                )
            }

            var worst = Float.greatestFiniteMagnitude
            var point = position
            var altitude = state.position.y
            var travelled: Float = 0.0
            var course = initialAirCourse
            var filteredBankDegrees: Float = {
                if useAssistController {
                    return fixedWingLatestAssistRollCommandDegrees ?? 0.0
                }
                if useAutopilotController {
                    return fixedWingLatestAutopilotRollCommandDegrees ?? 0.0
                }
                return fixedWingAvoidanceBiasDegrees
            }()
            var predictedFilteredCourse: Float = {
                if useAssistController {
                    return fixedWingLatestAssistCourseCommandRadians ?? desiredCourse
                }
                if useAutopilotController {
                    return fixedWingLatestAutopilotCourseCommandRadians ?? desiredCourse
                }
                return desiredCourse
            }()
            var achievedBankDegrees = state.orientation.x.radiansToDegrees
            var predictedYawRate = state.bodyAngularVelocity.z
            var predictedRollRateDegrees = state.bodyAngularVelocity.x.radiansToDegrees
            var predictedVerticalVelocity = useUpperVerticalEnvelope
                ? max(state.velocity.y, 0.0)
                : min(state.velocity.y, 0.0)
            var elapsed: Float = 0.0
            var rolloutChordIndex = 0
            let timeStep = rolloutStepTime

            func measure(
                from start: SIMD2<Float>,
                to sample: SIMD2<Float>,
                fromAltitude: Float,
                toAltitude: Float,
                chordIndex: Int
            ) -> Bool {
                let start3D = SIMD3<Float>(start.x, fromAltitude, start.y)
                let sample3D = SIMD3<Float>(sample.x, toAltitude, sample.y)
                if !useUpperVerticalEnvelope {
                    currentLowerRolloutChords.append((start3D, sample3D))
                }
                // Keep a scoring halo beyond the hard corridor, but query only the spatial buckets
                // touched by this rollout chord instead of rescanning every nearby city object.
                let nearbyShaped = assessmentShapedObstacleIndex.query(
                    from: start3D,
                    to: sample3D,
                    margin: corridorHalfWidth + 24.0
                )
                for obstacle in nearbyShaped {
                    worst = min(
                        worst,
                        min(
                            obstacle.planarSignedDistance(to: start),
                            obstacle.planarSignedDistance(to: sample)
                        )
                    )
                }
                // Validate the whole reachable altitude band, not just one optimistic Y sample.
                // This catches a tree crown, bridge underside or building ledge that lies between
                // the no-climb and commanded-climb rollouts.
                if !nearbyShaped.isEmpty,
                   fixedWingPathNeedsObstacleReroute(
                       [start, sample],
                       obstacles: nearbyShaped,
                       targetAltitude: rolloutTargetAltitude
                   ) {
                    worst = min(worst, 0.0)
                    return false
                }
                // Sweep the whole chord. Endpoint-only signed distances let a thin tree pass
                // between samples (or let a wing graze a box tangentially) while both endpoints
                // remained clear.
                if !nearbyShaped.isEmpty,
                   collisionService.firstSweptCenterCollision(
                       from: start3D,
                       to: sample3D,
                       radius: corridorHalfWidth,
                       obstacles: nearbyShaped
                   ) != nil {
                    worst = min(worst, 0.0)
                    return false
                }

                // A photogrammetric cell is a triangle bucket, not a solid 24 m building. Sweep a
                // conservative sphere enclosing the complete airframe against its real triangles.
                // This is fail-closed for wings/tail and avoids a separate triangle sweep per
                // contact sphere on every candidate chord.
                if !assessmentMeshObstacles.isEmpty {
                    let nearbyMesh = assessmentMeshObstacleIndex.query(
                        from: start3D,
                        to: sample3D,
                        margin: corridorHalfWidth + 4.0
                    )
                    let meshContact = !nearbyMesh.isEmpty && collisionService.firstSweptCenterCollision(
                        from: start3D,
                        to: sample3D,
                        radius: corridorHalfWidth,
                        obstacles: nearbyMesh
                    ) != nil
                    if meshContact {
                        worst = min(worst, 0.0)
                        return false
                    }
                }

                if useUpperVerticalEnvelope {
                    guard currentLowerRolloutChords.indices.contains(chordIndex) else {
                        worst = min(worst, 0.0)
                        return false
                    }
                    let lowerChord = currentLowerRolloutChords[chordIndex]
                    let lowerMidpoint = (lowerChord.start + lowerChord.end) * 0.5
                    let upperMidpoint = (start3D + sample3D) * 0.5

                    // Each rollout chord advances by less than 0.45 of this radius. Sweeping the
                    // enclosing sphere between paired chord midpoints therefore contains the full
                    // ruled volume of intermediate altitude/bank responses, not just two boundary
                    // curves that an obstacle could sit between.
                    let bridgeShaped = assessmentShapedObstacleIndex.query(
                        from: lowerMidpoint,
                        to: upperMidpoint,
                        margin: corridorHalfWidth + 24.0
                    )
                    if !bridgeShaped.isEmpty,
                       collisionService.firstSweptCenterCollision(
                           from: lowerMidpoint,
                           to: upperMidpoint,
                           radius: corridorHalfWidth,
                           obstacles: bridgeShaped
                       ) != nil {
                        worst = min(worst, 0.0)
                        return false
                    }
                    let bridgeMesh = assessmentMeshObstacleIndex.query(
                        from: lowerMidpoint,
                        to: upperMidpoint,
                        margin: corridorHalfWidth + 4.0
                    )
                    if !bridgeMesh.isEmpty,
                       collisionService.firstSweptCenterCollision(
                           from: lowerMidpoint,
                           to: upperMidpoint,
                           radius: corridorHalfWidth,
                           obstacles: bridgeMesh
                       ) != nil {
                        worst = min(worst, 0.0)
                        return false
                    }
                }
                return true
            }

            // Roll out the same closed loop that will fly the candidate: P course command, 22°
            // cap, the 0.45 s command filter, then conservative roll response and coordinated yaw.
            // The old ideal constant-radius arc assumed 30° immediately while the impact log shows
            // 9.5° commanded / 12.3° achieved; it declared the facade clear one tick before impact.
            while elapsed < assessmentDuration {
                let stepTime = min(timeStep, assessmentDuration - elapsed)
                guard stepTime > 0.0001 else { break }
                if useAssistController || useAutopilotController {
                    let courseFilterTau = useAssistController
                        ? FixedWingAssistLateralTuning.courseFilterTau
                        : FixedWingAutopilotLateralTuning.courseFilterTau
                    let courseAlpha = 1.0 - exp(
                        -stepTime / courseFilterTau
                    )
                    predictedFilteredCourse = shortestAngleRadians(
                        predictedFilteredCourse
                            + shortestAngleRadians(
                                desiredCourse - predictedFilteredCourse
                            ) * courseAlpha
                    )
                }
                let controllerCourse = useAssistController || useAutopilotController
                    ? predictedFilteredCourse
                    : desiredCourse
                let courseError = shortestAngleRadians(controllerCourse - course)
                let assistAltitudeFactor = (
                    max(0.0, heightAboveSupportSurface(for: state.position)
                        + (altitude - state.position.y))
                        / max(wing.initialClimbTargetAltitude, 1.0)
                ).clamped(to: 0.35...1.0)
                let commandBankLimit: Float = {
                    if useAssistController {
                        return min(
                            FixedWingAssistLateralTuning.maxBankDeg,
                            wing.maxBankAngleDeg
                        ) * assistAltitudeFactor
                    }
                    if useAutopilotController {
                        return wing.maxBankAngleDeg
                            * FixedWingAutopilotLateralTuning.maximumBankScale
                            * assistAltitudeFactor
                    }
                    return bankLimitDegrees
                }()
                let headingGain = useAssistController
                    ? FixedWingAssistLateralTuning.headingBankGain
                    : (useAutopilotController
                        ? FixedWingAutopilotLateralTuning.bankProportionalGain
                        : 0.55)
                let rateGain = useAssistController
                    ? FixedWingAssistLateralTuning.headingRateDampingGain
                    : (useAutopilotController ? 0.0 : 0.45)
                let rawBankRadians = (
                    courseError * headingGain - predictedYawRate * rateGain
                ).clamped(
                    to: -commandBankLimit.degreesToRadians...commandBankLimit.degreesToRadians
                )
                let rawBankDegrees = rawBankRadians.radiansToDegrees
                let commandAlpha = 1.0 - exp(-stepTime / (
                    useAssistController
                        ? FixedWingAssistLateralTuning.bankFilterTau
                        : (useAutopilotController
                            ? FixedWingAutopilotLateralTuning.bankFilterTau
                            : 0.45)
                ))
                filteredBankDegrees += (rawBankDegrees - filteredBankDegrees) * commandAlpha
                let previousAchievedBank = achievedBankDegrees
                let targetRollRateDegrees = (
                    (filteredBankDegrees - achievedBankDegrees) /
                        Self.fixedWingAvoidancePredictedRollResponseSeconds
                ).clamped(to: -60.0...60.0)
                let rollRateAlpha = 1.0 - exp(-stepTime / 0.35)
                predictedRollRateDegrees += (
                    targetRollRateDegrees - predictedRollRateDegrees
                ) * rollRateAlpha
                achievedBankDegrees += predictedRollRateDegrees * stepTime
                achievedBankDegrees = achievedBankDegrees.clamped(
                    to: -wing.maxBankAngleDeg...wing.maxBankAngleDeg
                )
                let midpointBank = (previousAchievedBank + achievedBankDegrees) * 0.5
                let coordinatedYawRate = 9.81 * tan(midpointBank.degreesToRadians) / airspeed
                let yawRateAlpha = 1.0 - exp(-stepTime / 0.45)
                predictedYawRate += (coordinatedYawRate - predictedYawRate) * yawRateAlpha
                let courseStep = predictedYawRate * stepTime
                let midpointCourse = course + courseStep * 0.5
                let airVelocity = SIMD2<Float>(
                    -sin(midpointCourse),
                    -cos(midpointCourse)
                ) * airspeed
                let groundVelocity = airVelocity + windXZ
                let previousPoint = point
                let previousAltitude = altitude
                let previousTravelled = travelled
                let displacement = groundVelocity * stepTime
                point += displacement
                let verticalAlpha = 1.0 - exp(-stepTime / 1.0)
                let selectedVerticalRate = useUpperVerticalEnvelope
                    ? upperVerticalRate
                    : verticalRate
                predictedVerticalVelocity += (
                    selectedVerticalRate - predictedVerticalVelocity
                ) * verticalAlpha
                altitude = previousAltitude + predictedVerticalVelocity * stepTime
                course = shortestAngleRadians(course + courseStep)
                travelled += simd_length(displacement)
                elapsed += stepTime
                let chordIndex = rolloutChordIndex
                rolloutChordIndex += 1
                if !measure(
                    from: previousPoint,
                    to: point,
                    fromAltitude: previousAltitude,
                    toAltitude: altitude,
                    chordIndex: chordIndex
                ) {
                    return FixedWingAvoidanceTrajectoryAssessment(
                        isClear: false,
                        hasKnownCoverage: true,
                        firstContactDistanceMeters: previousTravelled,
                        minimumClearanceMeters: worst
                    )
                }
            }
            return FixedWingAvoidanceTrajectoryAssessment(
                isClear: assessmentCoversFullHorizon,
                hasKnownCoverage: true,
                firstContactDistanceMeters: assessmentCoversFullHorizon
                    ? .greatestFiniteMagnitude
                    : travelled,
                minimumClearanceMeters: worst
            )
        }

        // Forward/locked/candidate passes can ask for the same course more than once. In the
        // incomplete-union case each miss otherwise repeats a mesh tube query and rebuilds two
        // indexes on the main actor during the same evaluation.
        var trajectoryAssessmentCache: [UInt64: FixedWingAvoidanceTrajectoryAssessment] = [:]
        func trajectoryAssessment(
            course desiredCourse: Float,
            useAssistController: Bool = false,
            useAutopilotController: Bool = false
        ) -> FixedWingAvoidanceTrajectoryAssessment {
            let key = (UInt64(shortestAngleRadians(desiredCourse).bitPattern) << 2)
                | (useAssistController ? 1 : 0)
                | (useAutopilotController ? 2 : 0)
            if let cached = trajectoryAssessmentCache[key] {
                return cached
            }
            currentLowerRolloutChords.removeAll(keepingCapacity: true)
            let lowerAssessment = computeTrajectoryAssessment(
                course: desiredCourse,
                useAssistController: useAssistController,
                useAutopilotController: useAutopilotController,
                useUpperVerticalEnvelope: false
            )
            guard lowerAssessment.isClear else {
                trajectoryAssessmentCache[key] = lowerAssessment
                return lowerAssessment
            }
            let upperAssessment = computeTrajectoryAssessment(
                course: desiredCourse,
                useAssistController: useAssistController,
                useAutopilotController: useAutopilotController,
                useUpperVerticalEnvelope: true
            )
            let assessment = FixedWingAvoidanceTrajectoryAssessment(
                isClear: lowerAssessment.isClear && upperAssessment.isClear,
                hasKnownCoverage: lowerAssessment.hasKnownCoverage
                    && upperAssessment.hasKnownCoverage,
                firstContactDistanceMeters: min(
                    lowerAssessment.firstContactDistanceMeters,
                    upperAssessment.firstContactDistanceMeters
                ),
                minimumClearanceMeters: min(
                    lowerAssessment.minimumClearanceMeters,
                    upperAssessment.minimumClearanceMeters
                )
            )
            trajectoryAssessmentCache[key] = assessment
            return assessment
        }

        func target(on course: Float) -> SIMD2<Float> {
            let direction = SIMD2<Float>(-sin(course), -cos(course))
            return position + direction * lookahead
        }

        let forwardAssessment = trajectoryAssessment(
            course: commandedGuidanceCourse,
            useAssistController: guidanceUsesAssistLateralLoop,
            useAutopilotController: guidanceUsesAutopilotLateralLoop
        )
        let takeoverAssessment = guidanceUsesNominalLateralLoop
            ? trajectoryAssessment(course: commandedGuidanceCourse)
            : forwardAssessment
        // "Blocked" must mean a contact the aircraft can no longer turn away from, not "the
        // several-hundred-metre horizon is not provably empty".
        //
        // Requiring the full horizon made blocked the resting state of urban flight: the logs show
        // it asserted continuously from the first airborne tick, and everything it then does —
        // seizing both lateral axes, capping power, commanding a degraded escape — is applied
        // permanently rather than in an emergency. What actually has to fit is the lateral
        // displacement needed to miss what is ahead: on a constant-radius turn an offset `y` costs
        // an along-track run of sqrt(2*R*y), which at a 150 m radius and one corridor width is
        // about 55 m, not 240 m. Beyond that distance an obstacle is route guidance's problem.
        let escapeDistance = (
            airspeed * Self.fixedWingTurnRollInSeconds
                + (2.0 * max(1.0, turnRadius) * max(1.0, corridorHalfWidth * 2.0)).squareRoot()
        ) * 1.25
        func reachesEscapeDistance(
            _ assessment: FixedWingAvoidanceTrajectoryAssessment
        ) -> Bool {
            assessment.isClear || (
                assessment.hasKnownCoverage
                    && assessment.firstContactDistanceMeters >= escapeDistance
            )
        }
        let forwardBlocked = !reachesEscapeDistance(forwardAssessment)
            || !reachesEscapeDistance(takeoverAssessment)

        if let lockedCourse = fixedWingAvoidanceCourseRadians {
            // Course persistence suppresses left/right hunting, but never outranks collision
            // safety. Re-check the complete arc on every tick; the aircraft may have moved close
            // enough that yesterday's safe corridor is no longer flyable.
            let lockedAssessment = trajectoryAssessment(course: lockedCourse)
            let lockedCourseIsSafe = reachesEscapeDistance(lockedAssessment)
            if lockedCourseIsSafe {
                if forwardBlocked {
                    fixedWingAvoidanceClearSinceTime = nil
                } else {
                    if fixedWingAvoidanceClearSinceTime == nil {
                        fixedWingAvoidanceClearSinceTime = simulationTime
                    }
                    let clearDuration = simulationTime - (fixedWingAvoidanceClearSinceTime ?? simulationTime)
                    if clearDuration >= 3.0 {
                        // Three seconds of continuously clear flight puts roughly 50 m between
                        // this airframe and the last façade. Only now may waypoint guidance resume.
                        fixedWingAvoidanceCourseRadians = nil
                        fixedWingAvoidanceTurnSign = nil
                        fixedWingAvoidanceOppositeSideEscapeUsed = false
                        fixedWingAvoidanceReplanEpisodeActive = false
                        fixedWingAvoidanceClearSinceTime = nil
                        fixedWingAvoidanceHeadingOffset = nil
                        evaluatedTarget = nil
                        return nil
                    }
                }

                // A safe absolute course remains authoritative while the obstacle is being
                // cleared. The nose may move, but the selected escape does not.
                if forwardBlocked ||
                    simulationTime - (fixedWingAvoidanceClearSinceTime ?? simulationTime) < 3.0 {
                    fixedWingAvoidanceHeadingOffset = shortestAngleRadians(lockedCourse - heading)
                    evaluatedTarget = target(on: lockedCourse)
                    return evaluatedTarget
                }
            }

            // Never keep commanding a course after its swept rollout has become unsafe. The side
            // commitment survives and the search below may alter magnitude on that same side, so
            // stability does not require another half-second of knowingly flying toward contact.
            fixedWingAvoidanceCourseRadians = nil
            fixedWingAvoidanceClearSinceTime = nil
            fixedWingAvoidanceHeadingOffset = nil
        }

        guard forwardBlocked else {
            fixedWingAvoidanceCourseRadians = nil
            fixedWingAvoidanceTurnSign = nil
            fixedWingAvoidanceOppositeSideEscapeUsed = false
            fixedWingAvoidanceReplanEpisodeActive = false
            fixedWingAvoidanceClearSinceTime = nil
            fixedWingAvoidanceBlockedSinceTime = nil
            fixedWingAvoidanceHeadingOffset = nil
            evaluatedTarget = nil
            return nil
        }

        // Steer for the widest fully flyable gap, not for the first heading that happens to look
        // clear at its endpoint. A candidate is eligible only when its complete bank-limited arc
        // and exit corridor retain the aircraft clearance. The failed run had no such candidate;
        // selecting the "least bad" one deliberately changed a safe-looking street departure into
        // the logged +14°...+26° turn through a façade.
        let committedSign = fixedWingAvoidanceTurnSign
        let candidateSigns = committedSign.map { [$0] } ?? [Float(1.0), Float(-1.0)]
        var bestOffset: Float?
        var bestScore = -Float.greatestFiniteMagnitude
        var bestEmergencyOffset: Float?
        var bestEmergencyContactDistance: Float = -1.0
        var bestEmergencyClearance = -Float.greatestFiniteMagnitude
        for magnitude in candidateMagnitudes {
            for sign in candidateSigns {
                let offset = magnitude * sign
                let assessment = trajectoryAssessment(course: heading + offset)
                guard reachesEscapeDistance(assessment) else {
                    guard assessment.hasKnownCoverage else { continue }
                    let contactDistance = assessment.firstContactDistanceMeters
                    let isBetterPrefix = contactDistance > bestEmergencyContactDistance + 0.5
                    let isBetterTie = abs(contactDistance - bestEmergencyContactDistance) <= 0.5 &&
                        assessment.minimumClearanceMeters > bestEmergencyClearance + 0.1
                    if isBetterPrefix || isBetterTie {
                        bestEmergencyContactDistance = contactDistance
                        bestEmergencyClearance = assessment.minimumClearanceMeters
                        bestEmergencyOffset = offset
                    }
                    continue
                }
                // A turn has to earn its course change: half a metre of extra room per 10° is the
                // threshold, so shallow turns win unless a steeper one is genuinely better.
                let score = assessment.minimumClearanceMeters - magnitude * 3.0
                if score > bestScore {
                    bestScore = score
                    bestOffset = offset
                }
            }
        }

        // A committed side is retained through the obstacle episode. The only legal side change
        // is a one-time switch to an opposite rollout that is completely clear; a merely longer
        // collision prefix is not enough evidence to cross the nose and start weaving again.
        if bestOffset == nil,
           let committedSign,
           !fixedWingAvoidanceOppositeSideEscapeUsed {
            var oppositeOffset: Float?
            var oppositeScore = -Float.greatestFiniteMagnitude
            for magnitude in candidateMagnitudes {
                let offset = -committedSign * magnitude
                let assessment = trajectoryAssessment(course: heading + offset)
                guard reachesEscapeDistance(assessment) else { continue }
                let score = assessment.minimumClearanceMeters - magnitude * 3.0
                if score > oppositeScore {
                    oppositeScore = score
                    oppositeOffset = offset
                }
            }
            if let oppositeOffset {
                bestOffset = oppositeOffset
                fixedWingAvoidanceOppositeSideEscapeUsed = true
            }
        }

        guard let offset = bestOffset else {
            fixedWingAvoidanceNoSafeTrajectory = true
            fixedWingAvoidanceCoverageUnknown = bestEmergencyOffset == nil
            requestFixedWingAvoidanceReplanIfNeeded()
            if fixedWingAvoidanceBlockedSinceTime == nil {
                fixedWingAvoidanceBlockedSinceTime = simulationTime
            }

            // Prefer the longest collision-free prefix actually measured. If no local corridor
            // could be queried at all, preserve current air-track momentum instead of inventing an
            // unchecked ±80° turn beside an unknown facade.
            let momentumOffset = shortestAngleRadians(initialAirCourse - heading)
            let emergencyOffset = bestEmergencyOffset ?? momentumOffset
            let escapeSign: Float = {
                if abs(emergencyOffset) > 0.01 {
                    return emergencyOffset >= 0.0 ? 1.0 : -1.0
                }
                return committedSign ?? (state.orientation.x >= 0.0 ? 1.0 : -1.0)
            }()
            // Same rate limit as the nominal branch below, and for the same reason: this branch
            // writes the offset too, so leaving it unbounded reopened the very oscillation the
            // other one closes. A flight logged the pair alternating -30, blocked(-30),
            // blocked(+10), +71 within a couple of seconds. An escape turn is still a turn.
            //
            // The step is doubled here — an emergency may out-turn a nominal detour, it just may
            // not teleport the commanded course.
            let emergencyStep = Float(1.8).degreesToRadians
            let smoothedEmergencyOffset: Float
            if let previous = fixedWingAvoidanceHeadingOffset, previous.isFinite {
                let delta = shortestAngleRadians(emergencyOffset - previous)
                smoothedEmergencyOffset = previous + delta.clamped(to: -emergencyStep...emergencyStep)
            } else {
                smoothedEmergencyOffset = emergencyOffset
            }
            let emergencyCourse = shortestAngleRadians(heading + smoothedEmergencyOffset)
            fixedWingAvoidanceCourseRadians = emergencyCourse
            fixedWingAvoidanceTurnSign = escapeSign
            fixedWingAvoidanceClearSinceTime = nil
            fixedWingAvoidanceHeadingOffset = smoothedEmergencyOffset
            evaluatedTarget = target(on: emergencyCourse)
            return evaluatedTarget
        }
        fixedWingAvoidanceBlockedSinceTime = nil

        // Rate-limit the avoidance offset instead of re-aiming from scratch every tick.
        //
        // The offset is re-chosen from the current corridor sample each tick, and the samples
        // disagree: one flight logged `avOff` going +18, +12, +9, clear, +51, blocked(+45), -43
        // over a couple of seconds — the aircraft was told to turn 45 deg left, then 51 deg right,
        // while the A* route underneath it was valid the whole time (`vtolWhy=ready`). What the
        // operator sees is the aircraft weaving around obstacles the route had already cleared.
        //
        // A detour is a manoeuvre, not an opinion: it has to be flyable, which means bounded
        // angular rate. The step below is ~0.9 deg per tick, i.e. about 50 deg/s at 60 Hz and
        // proportionally less when the frame rate drops — still faster than the airframe can
        // actually turn, so a genuine escape is not slowed, while single-tick reversals are.
        let smoothedOffset: Float
        if let previous = fixedWingAvoidanceHeadingOffset, previous.isFinite {
            let step = Float(0.9).degreesToRadians
            let delta = shortestAngleRadians(offset - previous)
            smoothedOffset = previous + delta.clamped(to: -step...step)
        } else {
            smoothedOffset = offset
        }
        let course = shortestAngleRadians(heading + smoothedOffset)
        fixedWingAvoidanceCourseRadians = course
        fixedWingAvoidanceTurnSign = smoothedOffset >= 0.0 ? 1.0 : -1.0
        fixedWingAvoidanceClearSinceTime = nil
        fixedWingAvoidanceHeadingOffset = smoothedOffset
        evaluatedTarget = target(on: course)
        return evaluatedTarget
    }

    /// Cruise altitude for the fixed-wing assist's waypoint intercept.
    ///
    /// The assist latches `targetAltitudeMeters` at the moment it is engaged — and it is normally
    /// engaged **on the pad**, so the hold altitude was the launch deck's. After a hand launch the
    /// aircraft therefore pushed its nose down to return to eleven metres and held that, at cruise
    /// speed, through a city: the flight log shows it arming at y 11.1 and descending 14.4 → 12.5 →
    /// 11.8 → 10.8 straight into a façade. The hold altitude has to belong to the *route*, not to
    /// the spot the pilot happened to arm it from. Computed once per intercepted waypoint so it
    /// cannot walk upward tick by tick, the way three other altitude bugs in this stage did.

    private static let fixedWingRouteClearanceMeters: Float = 20.0
    private static let fixedWingRouteClimbLimitMeters: Float = 70.0

    private func fixedWingRouteClearanceAltitude(to goal: SIMD2<Float>) -> Float {
        let start = currentPlanarPosition()
        let segment = goal - start
        let length = simd_length(segment)
        guard length > 0.1 else { return 0.0 }

        let corridor = max(8.0, fixedWingNavigationEnvelopeRadius + 4.0)
        let sampleCount = max(1, Int(ceil(length / 140.0)))
        var seen = Set<UUID>()
        var candidates: [CollisionObstacle] = []
        for index in 0...sampleCount {
            let fraction = Float(index) / Float(sampleCount)
            let point = start + segment * fraction
            let queryPosition = SIMD3<Float>(point.x, state.position.y, point.y)
            for obstacle in sceneController.nearbyEnvironmentObstacles(
                near: queryPosition,
                radius: corridor + 28.0
            ) where seen.insert(obstacle.id).inserted {
                candidates.append(obstacle)
            }
        }

        var highest: Float = 0.0
        for obstacle in candidates {
            // Trees remain mandatory lateral obstacles. Climbing to every crown would make the
            // route unnecessarily long and unstable; buildings/mesh fabric may be overflown only
            // within the bounded climb below, while taller structures remain walls to route around.
            if obstacle.source.contains("tree") { continue }
            let distance = planarDistanceToSegment(
                point: obstacle.planarCenter,
                segmentStart: start,
                segmentEnd: goal
            )
            if distance <= obstaclePlanarRadius(obstacle) + corridor {
                highest = max(highest, obstacle.topY)
            }
        }
        guard highest > 0.0 else { return 0.0 }
        return min(
            highest + Self.fixedWingRouteClearanceMeters,
            state.position.y + Self.fixedWingRouteClimbLimitMeters
        )
    }

    private func fixedWingAssistCruiseAltitude(
        waypointID: UUID?,
        goal: SIMD2<Float>
    ) -> Float {
        let environmentRevision = sceneController.environmentRevision
        if let cached = fixedWingAssistCruiseCache,
           cached.waypointID == waypointID,
           cached.environmentRevision == environmentRevision {
            return cached.altitude
        }

        let ceiling = max(6.0, terrain.maxFlightAltitude - 2.0)
        let routeReferenceAltitude = fixedWingAssistRouteCruiseAltitude ?? state.position.y
        let baseline = currentMissionPlan?.constraints.baselineTravelAltitude(
            currentAltitude: routeReferenceAltitude,
            dockAltitude: currentSpawnPoint().y,
            terrainMaxAltitude: ceiling,
            airframeClass: .fixedWing
        ) ?? min(
            ceiling,
            max(
                10.0,
                homePosition.y + 8.0,
                routeReferenceAltitude + (fixedWingAssistRouteCruiseAltitude == nil ? 3.4 : 0.0)
            )
        )
        let requested = max(baseline, fixedWingRouteClearanceAltitude(to: goal))
        let missionClamped = missionAutopilotAdapter.resolvedTravelAltitude(
            for: currentMissionPlan,
            baselineAltitude: requested,
            launchAltitude: currentSpawnPoint().y,
            terrainMaxAltitude: ceiling
        )
        // Engaging in flight must never command an immediate descent. Once the route owns a
        // cruise level, keep that level across waypoint hand-offs and only raise it when the new
        // corridor genuinely requires more clearance.
        let altitude = min(ceiling, max(routeReferenceAltitude, missionClamped))
        fixedWingAssistRouteCruiseAltitude = altitude
        fixedWingAssistCruiseCache = (
            waypointID: waypointID,
            environmentRevision: environmentRevision,
            altitude: altitude
        )
        return altitude
    }

    private func latchFixedWingAssistCruiseAltitude(
        for waypoint: FixedWingAssistWaypointOption
    ) {
        let cruise = fixedWingAssistCruiseAltitude(
            waypointID: waypoint.id,
            goal: waypoint.position
        )
        fixedWingAssistState.targetAltitudeMeters = cruise
        let wing = activeFixedWingParameters()
        let speed = max(
            state.forwardAirspeed,
            simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        )
        if !fixedWingAssistWasIntercepting ||
            state.position.y < cruise - 6.0 ||
            speed < wing.minSafeAirspeed * 1.10 {
            fixedWingAssistClimbOutLatched = true
            fixedWingClimbOutStartAltitude = state.position.y
        }
        fixedWingAssistWasIntercepting = true
    }

    @discardableResult
    private func updateFixedWingAssistClimbOut(wing: FixedWingParameters) -> Bool {
        guard fixedWingAssistClimbOutLatched else { return false }
        let startAltitude = fixedWingClimbOutStartAltitude ?? state.position.y
        let cruise = fixedWingAssistState.targetAltitudeMeters ?? state.position.y
        let releaseAltitude = min(cruise - 3.0, startAltitude + 20.0)
        let speed = max(
            state.forwardAirspeed,
            simd_length(SIMD2<Float>(state.velocity.x, state.velocity.z))
        )
        let hasFlyingEnergy = speed >= max(wing.climbAirspeed * 0.90, wing.minSafeAirspeed)
            && state.velocity.y > -0.20
        if state.position.y >= cruise - 2.0 ||
            (state.position.y >= releaseAltitude && hasFlyingEnergy) {
            fixedWingAssistClimbOutLatched = false
            fixedWingClimbOutStartAltitude = nil
            return false
        }
        return true
    }

    private func handleModeTransitions() {
        engagePendingFixedWingAssistIfReady()
        if mode == .takeoff {
            if selectedDroneProfile.airframeClass == .fixedWing {
                if activeLaunchMode() != .standard, launchState.blocksRouteCapture {
                    return
                }
                let liftOffSpeed = selectedDroneProfile.fixedWingParameters?.minSustainableSpeedMps ?? 9.0
                // Hand over a *flying* aircraft, high enough and nose-up.
                //
                // The old test was `physicalState == .airborne || position.y >= 1.0 || speed >=
                // 0.92 * liftOff`. All three are satisfied before the launch achieves anything:
                // `position.y >= 1.0` is an absolute world altitude written for a world whose
                // ground is y = 0, and the catapult here sits at 0.79 m, while a cradled aircraft
                // already reads `.airborne`. Height is therefore measured against the support
                // surface.
                //
                // Six metres, not two, and the nose may not be below level. The flight log shows
                // why: handover came at 3.9 m with the aircraft at −1.2° while accelerating
                // 2 → 28.6 m/s, and it sank into the ground before climbing away. It survived —
                // one 6.4 J wingtip scrape — but a departure should not touch anything.
                let launchHeight = heightAboveSupportSurface(for: state.position)
                let noseIsUp = state.orientation.y > -0.02
                if physicalState == .airborne,
                   launchHeight >= 6.0,
                   state.forwardAirspeed >= liftOffSpeed,
                   state.velocity.y > -0.15,
                   noseIsUp {
                    setFlightMode(.manual, reason: "takeoff_completed_fixed_wing")
                    setFixedWingGuidanceSource(.none, reason: "fixed_wing_takeoff_completed")

                    // Hand over a *flying* aircraft: attitude and power, wings level.
                    //
                    // Measured across two launches: at the handover tick the command collapsed
                    // from pitch 15.0° / throttle 0.88 to pitch 2.1° / throttle 0.52, at 17 m/s
                    // and five metres altitude. Nothing commanded a descent — manual was simply
                    // handed controls that neither hold power nor ask for climb, and the aircraft
                    // was on the ground within the second (`vy` −1.11 then −3.47). So manual
                    // inherits what the aircraft already has: the attitude it is holding and at
                    // least cruise power.
                    //
                    // Roll is the one thing that must NOT be inherited. Launch guidance banks to
                    // pick up its route, and an earlier log caught that bank surviving the
                    // handover as a *command* — roll settling on exactly −8.9° and staying there
                    // for the rest of the flight with no autopilot engaged, which reads as "it
                    // will not fly straight".
                    let heldPitchDegrees = Double(state.orientation.y.radiansToDegrees)
                    let cruiseThrottle = Double(
                        resolvedFlightBaseline(for: .manual).cruiseReferenceThrottle
                    )
                    updateControlValues({ values in
                        // Never inherit a nose-down attitude: it is the one part of the launch
                        // state that must not survive, for the same reason as the bank.
                        values.pitch = max(0.0, heldPitchDegrees)
                        // The altitude target, which was still the launch pad's.
                        //
                        // This is what actually drove the nose down. The take-off controller flies
                        // a clean departure — 12°→14° of pitch, throttle 0.95, a steady +2.4 m/s —
                        // and the instant control left it the command became **−2.2°** while the
                        // aircraft was climbing at 3.6 m/s. Nothing had failed: the hold loop was
                        // still aiming at 0.8 m, the height of the catapult, so from 3.3 m the only
                        // correct thing it could do was descend. Handing over pitch, power and roll
                        // while leaving the target where the aircraft started is the same omission
                        // three times over.
                        values.y = Double(state.position.y)
                        values.throttle = max(Double(state.throttle), cruiseThrottle)
                        values.roll = 0.0
                    }, markManual: false)

                }
            } else {
                let targetAltitude = Float(controlValues.y)
                if selectedDroneProfile.airframeStyle == .tailsitterVTOL,
                   state.position.y >= targetAltitude - 0.08 {
                    setFlightMode(.hover, reason: "takeoff_completed_tailsitter")
                    updateControlValues({ values in
                        values.x = Double(state.position.x)
                        values.y = Double(state.position.y)
                        values.z = Double(state.position.z)
                        values.roll = 0.0
                        values.pitch = 0.0
                        values.yaw = Double(state.orientation.z.radiansToDegrees)
                        values.throttle = Double(resolvedFlightBaseline(for: .hover).hoverLockThrottle)
                        values.vtolTransitionLever = 0.0
                    }, markManual: false)
                } else if physicalState == .airborne && state.position.y >= targetAltitude - 0.08 && abs(state.velocity.y) < 0.45 {
                    setFlightMode(.hover, reason: "takeoff_completed_multicopter")
                    lockControlsToCurrentState(overrideThrottle: Double(resolvedFlightBaseline(for: .hover).hoverLockThrottle))
                }
            }
        }

        if mode == .landing,
           physicalState == .landed {
            setFlightMode(.manual, reason: "landing_completed")
            if selectedDroneProfile.airframeClass == .fixedWing {
                isArmed = false
                transitionPhysicalState(.disarmed)
            }
            updateControlValues({ values in
                values.y = 0.0
                values.throttle = 0.0
                values.roll = 0.0
                values.pitch = 0.0
            }, markManual: false)
        }

    }

    private func updateFleetStatus(deltaTime: Float) -> [CollisionObstacle] {
        guard fleetStatus.enabled, fleetStatus.mode != .off else {
            fleetInterDroneRisk = 0.0
            fleetNearestInterDroneDistance = .infinity
            wingmen.removeAll()
            return []
        }

        let leader = DroneEntity(
            id: fleetLeaderID,
            position: state.position,
            velocity: state.velocity,
            collisionRadius: selectedDroneProfile.collisionRadius
        )

        wingmen = fleetManager.stepWingmen(
            current: wingmen,
            leaderPosition: state.position,
            leaderVelocity: state.velocity,
            leaderYaw: state.orientation.z,
            mode: fleetStatus.mode,
            requestedCount: fleetStatus.wingmanCount,
            separation: fleetStatus.separationDistance,
            radius: selectedDroneProfile.collisionRadius,
            deltaTime: deltaTime
        )

        let interDrone = fleetManager.interDroneCollisionSnapshot(
            leader: leader,
            wingmen: wingmen
        )

        fleetInterDroneRisk = interDrone.riskScore
        fleetNearestInterDroneDistance = interDrone.nearestSeparation

        return fleetManager.collisionObstacles(for: wingmen)
    }

    private func lockControlsToCurrentState(overrideThrottle: Double) {
        updateControlValues({ values in
            values.x = Double(state.position.x)
            values.y = Double(state.position.y)
            values.z = Double(state.position.z)
            values.roll = Double(state.orientation.x.radiansToDegrees)
            values.pitch = Double(state.orientation.y.radiansToDegrees)
            values.yaw = Double(state.orientation.z.radiansToDegrees)
            values.throttle = overrideThrottle
        }, markManual: false)
    }

    private func resolvedFlightBaseline(for flightMode: DroneFlightMode? = nil) -> ResolvedFlightBaseline {
        FlightBaselineResolver.resolve(
            runtimeProfile: selectedDroneProfile,
            activeUAVProfile: activeUAVProfile,
            vehicleMassModel: vehicleMassModel,
            flightMode: flightMode ?? mode
        )
    }

    private func buildControlInput(from controls: DroneControlValues) -> DroneControlInput {
        let builder = DroneControlInputBuilder(
            controls: controls,
            state: state,
            isArmed: isArmed,
            mode: mode,
            controlMode: resolvedFlightControlMode(for: flightControlRouter.currentAuthority),
            manualYawIntent: manualYawIntent,
            usesTargetYawWhileManual: fixedWingAssistUsesTargetYawWhileManual
        )
        return builder.build()
    }

    private var canStartTargetMarkerAutoNavigation: Bool {
        guard fixedWingAutonomousRouteExecutionEnabled else {
            return false
        }
        guard targetMarkerState != nil else {
            return false
        }
        return canBindMissionTargetToAutopilot
    }

    private var fixedWingAutonomousRouteExecutionEnabled: Bool { true }

    private func disengageFixedWingAutonomousRouteExecution(reason: String) {
        guard selectedDroneProfile.airframeClass == .fixedWing else {
            return
        }

        autoNavigationController.cancel()
        autoPathPlanner.invalidate()
        navigationSnapshot = .idle
        autoFlightGoal = nil
        returnHomeStage = .idle
        resetFixedWingAutopilotCommands()

        if mode == .autoPath || mode == .returnHome {
            setFlightMode(.manual, reason: reason)
        }

        refreshFlightControlDiagnostics()
    }

    private var canBindMissionTargetToAutopilot: Bool {
        guard isArmed, !signalState.isInteractionBlocking else {
            return false
        }
        guard physicalState != .disarmed, physicalState != .crashed else {
            return false
        }
        return mode != .emergencyStop
    }

    private func cancelTargetMarkerAutoNavigation() {
        autoNavigationController.cancel()
        navigationSnapshot = .idle
        resetFixedWingAutopilotCommands()
        resetActiveRouteTargetGuidanceCache()
    }

    /// - Parameter releasingAltitudeLadder: whether the climb the previous leg had to earn is
    ///   discarded too. True when the aircraft is left with no route target at all — a cancel, a
    ///   mode takeover, a cleared marker — because then the geometry it climbed over stops being
    ///   its problem. False when one waypoint simply hands over to the next: the aircraft has not
    ///   moved, the next leg starts among the same towers, and dropping the ladder there is what
    ///   put a 296 m collapse into the log twice running.
    private func resetActiveRouteTargetGuidanceCache(
        releasingAltitudeLadder: Bool = true
    ) {
        activeRouteTargetAltitude = nil
        activeRouteTargetAltitudeMarkerID = nil
        multirotorMarkerLastPlanTick = nil
        multirotorAvoidanceLateralOffset = 0.0
        multirotorAvoidanceHoldUntilTick = 0
        // A leg's regime decision belongs to that leg and to that flight.
        vtolActiveLegTargetPlanar = nil
        vtolActiveLegUsesCruise = false
        // The safety verdict belonged to the leg that just ended; a stale one would keep warning
        // the operator about a condition the aircraft is no longer in.
        hybridVTOLSafetyState = .nominal
        // Same for a hold taken on that leg: the obstacle it stopped for is no longer on the way.
        clearCollisionInterventionHold()
        hybridVTOLRouteCursor.reset()
        hybridVTOLStopAndPivotGate.reset()
        hybridVTOLProtectedRouteHoldPosition = nil
        hybridVTOLEmergencyHoldPosition = nil
        hybridVTOLNavigationBandAltitude = nil
        hybridVTOLDepartureAlignmentComplete = false
        hybridVTOLTransitionCommitted = false
        hybridVTOLTransitionLeverLatched = nil
        hybridVTOLTransitionLeverLatchedSince = nil
        hybridVTOLAltitudeAbortSince = nil
        if releasingAltitudeLadder {
            hybridVTOLRouteAltitudeLift = 0.0
        }
        hybridVTOLRouteBlockedSeconds = 0.0
        multicopterAutopilotController.reset()
    }

    private var activeMissionAutopilotPlan: MissionPlan? {
        activeRouteTargetSource == .mission ? currentMissionPlan : nil
    }

    private func targetMarkerTravelAltitude() -> Float {
        let executionCeiling = max(6.0, terrain.maxFlightAltitude - 2.0)
        if let marker = targetMarkerState,
           activeRouteTargetSource != .none,
           activeRouteTargetAltitudeMarkerID == marker.id,
           let cachedAltitude = activeRouteTargetAltitude {
            return cachedAltitude.clamped(to: 0.0...executionCeiling)
        }

        let baselineAltitude: Float
        switch selectedDroneProfile.airframeClass {
        case .multirotor:
            baselineAltitude = min(
                executionCeiling,
                max(3.4, homePosition.y + 4.0, state.position.y + (physicalState.isGroundRestState ? 3.0 : 0.8))
            )
        case .fixedWing, .hybridVTOL:
            baselineAltitude = min(
                executionCeiling,
                max(10.0, homePosition.y + 8.0, state.position.y + 3.4)
            )
        }
        let resolvedAltitude = missionAutopilotAdapter.resolvedTravelAltitude(
            for: activeMissionAutopilotPlan,
            baselineAltitude: baselineAltitude,
            launchAltitude: currentSpawnPoint().y,
            terrainMaxAltitude: executionCeiling
        )
        if let marker = targetMarkerState,
           activeRouteTargetSource != .none {
            let clampedAltitude = resolvedAltitude.clamped(to: 0.0...executionCeiling)
            activeRouteTargetAltitudeMarkerID = marker.id
            activeRouteTargetAltitude = clampedAltitude
            return clampedAltitude
        }
        return resolvedAltitude
    }

    private func buildFlightInputState(from controlState: ResolvedControlState) -> FlightInputState {
        FlightInputState(
            controlState: controlState,
            payloadViewActive: (
                cameraConfiguration.mode == .payload && payloadCameraStatus.isActive
            ) || cameraConfiguration.mode == .payloadOptics,
            mapOverlayActive: isTerrainMapVisible || isMissionMapVisible
        )
    }

    private func buildFlightControlRoutingContext() -> FlightControlRoutingContext {
        FlightControlRoutingContext(
            isArmed: isArmed,
            isInteractionBlocked: signalState.isInteractionBlocking,
            isSignalLost: signalState == .signalLost || signalState == .recoveryPending,
            isBlockedState: physicalState == .crashed || mode == .emergencyStop,
            isDisarmedState: physicalState == .disarmed || !isArmed,
            hasMarkerTarget: targetMarkerState != nil,
            canUseMarkerGuidance: canStartTargetMarkerAutoNavigation,
            markerGuidanceRequested: mode == .autoPath && targetMarkerState != nil
        )
    }

    private func refreshFlightControlDiagnostics(
        using controlState: ResolvedControlState? = nil,
        authorityOverride: FlightControlAuthority? = nil,
        contextOverride: FlightControlRoutingContext? = nil
    ) {
        let resolvedControlState = controlState ?? resolvedInputState
        let inputState = buildFlightInputState(from: resolvedControlState)
        let context = contextOverride ?? buildFlightControlRoutingContext()
        let authority = authorityOverride ?? flightControlRouter.currentAuthority
        flightControlDiagnostics = flightControlRouter.diagnostics(
            authority: authority,
            inputState: inputState,
            context: context
        )
        refreshMissionStatus()
    }

    private func resolvedFlightControlMode(for authority: FlightControlAuthority) -> FlightControlMode {
        if selectedDroneProfile.airframeClass == .fixedWing || selectedDroneProfile.airframeClass == .hybridVTOL {
            switch mode {
            case .autoPath, .returnHome, .takeoff, .landing:
                return .stabilized
            case .manual, .hover, .emergencyStop:
                break
            }
        }

        if selectedDroneProfile.airframeClass == .multirotor,
           mode == .hover {
            return .hoverAssist
        }

        if selectedDroneProfile.airframeClass == .multirotor,
           authority == .markerGuidance,
           mode == .autoPath,
           targetMarkerState != nil {
            return .hoverAssist
        }
        return flightControlMode
    }

    private func resetFlightControlRouting() {
        flightControlRouter.reset()
        manualYawIntent = 0.0
        resolvedInputState = .neutral
        refreshFlightControlDiagnostics(authorityOverride: FlightControlAuthority.none)
    }

    private func resolveControllerInteractionMode() -> ControllerInteractionMode {
        if controllerUIBridge.isTextInputPresented {
            return .textInput
        }

        if isControllerHubVisible ||
            externalControllerOverlayActive ||
            isMissionMapVisible ||
            isPayloadPanelVisible ||
            isCommsLinkPanelVisible ||
            (isParametersPanelVisible && activeControlModule != nil) ||
            isControllerCursorEnabled {
            return .uiNavigation
        }

        return .flight
    }

    private func syncControllerInteractionMode() {
        let nextMode = resolveControllerInteractionMode()
        if controllerInteractionMode != nextMode {
            controllerInteractionMode = nextMode
            debugControllerLog("Mode -> \(nextMode.rawValue)")
        }
    }

    private func handleControllerSystemActions(
        using controlState: ResolvedControlState
    ) {
        if controlState.toggleControllerCursorTriggered {
            toggleControllerCursor()
        }

        if controlState.openControllerHubTriggered {
            toggleControllerHub()
        }

        if isControllerHubVisible {
            if controlState.uiSectionPreviousTriggered {
                cycleControllerHubSection(step: -1)
            }
            if controlState.uiSectionNextTriggered {
                cycleControllerHubSection(step: 1)
            }
        }
    }

    private func processControllerUIInput(
        using controlState: ResolvedControlState,
        deltaTime: TimeInterval
    ) {
        handleControllerSystemActions(using: controlState)
        syncControllerInteractionMode()
        controllerUIBridge.update(
            from: controlState,
            mode: controllerInteractionMode,
            cursorEnabled: isControllerCursorEnabled,
            controllerConnected: inputManager.isSourceConnected(.gameController),
            deltaTime: deltaTime
        )
        controllerUIBridge.routeScroll(
            from: controlState,
            mode: controllerInteractionMode,
            deltaTime: deltaTime
        )
    }

    private func updateInputPipeline(deltaTime: TimeInterval) -> ResolvedControlState {
        inputManager.update(deltaTime: deltaTime)
        resolvedInputState = inputManager.currentState
        refreshGameControllerPresentation()
        return resolvedInputState
    }

    private func updateSpectatorRuntime(deltaTime: Float) {
        guard isSpectatorMode else {
            return
        }

        let keyboardSnapshot = keyboardInputService.currentInputSnapshot()
        let axis = keyboardSnapshot.axisInput
        let speedMultiplier: Float = axis.speedBoost ? 2.0 : 1.0
        sceneController.moveSpectatorCamera(
            forward: axis.forward,
            strafe: axis.strafe,
            deltaTime: deltaTime,
            speed: cameraConfiguration.free.moveSpeed * speedMultiplier
        )
        sceneController.updateSpectatorRuntime(camera: cameraConfiguration)
    }

    private func controllerResolvedControlState(
        from snapshot: InputSnapshot?
    ) -> ResolvedControlState {
        guard let snapshot, snapshot.isConnected else {
            return .neutral
        }

        return ResolvedControlState(
            yaw: snapshot.yaw,
            pitch: snapshot.pitch,
            roll: snapshot.roll,
            throttle: snapshot.throttle,
            cameraPan: snapshot.cameraPan,
            cameraTilt: snapshot.cameraTilt,
            uiPointerX: snapshot.uiPointerX,
            uiPointerY: snapshot.uiPointerY,
            uiScrollX: snapshot.uiScrollX,
            uiScrollY: snapshot.uiScrollY,
            precisionMode: snapshot.precisionMode,
            boostMode: snapshot.boostMode,
            isHoseSprayHeld: snapshot.isHoseSprayHeld,
            actions: snapshot.actions,
            dominantSource: .gameController
        )
    }

    private func refreshGameControllerPresentation(force: Bool = false) {
        let nextSourceKind = resolvedInputState.dominantSource
        if force || activeInputSourceKind != nextSourceKind {
            activeInputSourceKind = nextSourceKind
        }

        let nextActiveControllerName = gameControllerInputProvider.activeControllerName
        if force || activeGameControllerName != nextActiveControllerName {
            activeGameControllerName = nextActiveControllerName
        }

        let nextControllers = gameControllerInputProvider.connectedDeviceSummaries()
        if force || connectedGameControllers != nextControllers {
            connectedGameControllers = nextControllers
        }
        if nextControllers.isEmpty {
            if isControllerCursorEnabled {
                isControllerCursorEnabled = false
            }
            if isControllerHubVisible {
                isControllerHubVisible = false
            }
        }

        let nextRightStickMode = gameControllerInputProvider.currentRightStickHorizontalMode
        if force || gameControllerRightStickHorizontalMode != nextRightStickMode {
            gameControllerRightStickHorizontalMode = nextRightStickMode
        }

        if nextControllers.isEmpty {
            syncControllerInteractionMode()
        }
    }

    private func debugControllerLog(_ message: String) {
        #if DEBUG
        print("[ControllerInteraction] \(message)")
        #endif
    }

    private func currentAutoNavigationStatus() -> AutoNavigationStatus {
        if let synthesizedStatus = currentFixedWingAutoNavigationStatus() {
            return synthesizedStatus
        }
        if let synthesizedStatus = currentMultirotorMarkerNavigationStatus() {
            return synthesizedStatus
        }
        let safePosition = finiteVector(state.position, fallback: lastFiniteState.position)
        return autoNavigationController.status(
            from: SIMD2<Float>(safePosition.x, safePosition.z)
        )
    }

    private func currentMultirotorMarkerNavigationStatus() -> AutoNavigationStatus? {
        guard selectedDroneProfile.airframeClass == .multirotor,
              mode == .autoPath,
              let marker = targetMarkerState else {
            return nil
        }

        let planarPosition = currentPlanarPosition()
        let distance = marker.distance(from: planarPosition)
        let bearing = marker.bearingDegrees(from: planarPosition)
        let travelAltitude = targetMarkerTravelAltitude()
        let phase: AutoNavigationPhase
        if distance <= 1.2 {
            phase = .hold
        } else if physicalState.isGroundRestState || state.position.y < travelAltitude - 1.2 {
            phase = .takeoff
        } else {
            phase = distance > 9.5 ? .cruise : .approach
        }

        return AutoNavigationStatus(
            isActive: true,
            phase: phase,
            distanceToTarget: distance,
            bearingDegrees: bearing,
            hasTarget: true
        )
    }

    private func currentFixedWingAutoNavigationStatus() -> AutoNavigationStatus? {
        guard selectedDroneProfile.airframeClass == .fixedWing ||
                selectedDroneProfile.airframeClass == .hybridVTOL,
              let routePhase = fixedWingAutoNavigationPhase(
                for: fixedWingAutopilotDebugState,
                guidanceSource: activeFixedWingGuidanceSource
              ) else {
            return nil
        }

        let planarPosition = currentPlanarPosition()
        let distanceToTarget: Float = {
            if let activeTarget = missionExecutionState.activeTarget {
                let waypointDistance = simd_distance(planarPosition, activeTarget.position)
                if waypointDistance.isFinite {
                    return waypointDistance
                }
            }
            let remainingDistance = max(0.0, fixedWingAutopilotDebugState.remainingDistance)
            return remainingDistance.isFinite ? remainingDistance : .nan
        }()
        let bearingDegrees: Float = {
            if let marker = targetMarkerState {
                let markerBearing = marker.bearingDegrees(from: planarPosition)
                if markerBearing.isFinite {
                    return markerBearing
                }
            }
            let debugBearing = fixedWingAutopilotDebugState.desiredCourseDeg
            return debugBearing.isFinite ? debugBearing : .nan
        }()
        let isActive = mode == .autoPath || mode == .returnHome

        return AutoNavigationStatus(
            isActive: isActive,
            phase: routePhase,
            distanceToTarget: distanceToTarget,
            bearingDegrees: bearingDegrees,
            hasTarget: targetMarkerState != nil || activeRouteTargetSource == .mission
        )
    }

    private func fixedWingAutoNavigationPhase(
        for debugState: FixedWingAutopilotDebugState,
        guidanceSource: FixedWingGuidanceSource
    ) -> AutoNavigationPhase? {
        if guidanceSource == .none {
            return nil
        }
        switch debugState.missionState {
        case .idle, .failed:
            return nil
        case .aligningToLaunch, .climbout:
            return .takeoff
        case .capturingLeg, .trackingLeg, .recoveringSpeed:
            return .cruise
        case .flyByTurn:
            return .approach
        case .loitering, .completed:
            return .hold
        }
    }

    private func refreshCompassOverlay() {
        let safePosition = finiteVector(state.position, fallback: lastFiniteState.position)
        compassViewModel.update(
            headingRadians: finiteVector(state.orientation, fallback: lastFiniteState.orientation).z,
            dronePlanarPosition: SIMD2<Float>(safePosition.x, safePosition.z),
            targetMarker: targetMarkerState
        )
    }

    private var isMountedPayloadCameraAvailable: Bool {
        if mountedCADPayload != nil {
            return payloadState == .attached
        }

        guard payloadState == .attached, payloadMountState == .occupied else {
            return false
        }

        switch payloadDraftConfiguration.payloadType {
        case .cameraGimbal, .thermalCamera, .custom:
            return true
        case .cargoBox, .lidarModule, .laserRangefinder, .fireHose, .fireCapsuleLauncher, .agriculturalSprayer, .rescuePack, .sensorModule, .radioRelay:
            return false
        }
    }

    /// Stricter than `isMountedPayloadCameraAvailable`: excludes mounted CAD payloads, since
    /// those carry no `PayloadType` and the quick-select thermal binds must only fire when an
    /// actual EO/thermal-capable payload is on the airframe.
    private var isMountedThermalCapablePayload: Bool {
        guard mountedCADPayload == nil else {
            return false
        }

        guard payloadState == .attached, payloadMountState == .occupied else {
            return false
        }

        switch payloadDraftConfiguration.payloadType {
        case .cameraGimbal, .thermalCamera, .custom:
            return true
        case .cargoBox, .lidarModule, .laserRangefinder, .fireHose, .fireCapsuleLauncher, .agriculturalSprayer, .rescuePack, .sensorModule, .radioRelay:
            return false
        }
    }

    private var isMountedRangefinderAvailable: Bool {
        guard mountedCADPayload == nil else {
            return false
        }

        guard payloadState == .attached, payloadMountState == .occupied else {
            return false
        }

        return payloadDraftConfiguration.payloadType == .laserRangefinder
    }

    private var isMountedLidarAvailable: Bool {
        guard mountedCADPayload == nil else {
            return false
        }
        guard payloadState == .attached, payloadMountState == .occupied else {
            return false
        }
        return payloadDraftConfiguration.payloadType == .lidarModule
    }

    private var isMountedHoseAvailable: Bool {
        guard mountedCADPayload == nil else {
            return false
        }

        guard payloadState == .attached, payloadMountState == .occupied else {
            return false
        }

        return payloadDraftConfiguration.payloadType == .fireHose
    }

    private var isMountedCapsuleLauncherAvailable: Bool {
        guard mountedCADPayload == nil else {
            return false
        }

        guard payloadState == .attached, payloadMountState == .occupied else {
            return false
        }

        return payloadDraftConfiguration.payloadType == .fireCapsuleLauncher
    }

    /// Unlike the fire hose/capsule launcher, not gated to a specific mission scenario kind —
    /// the sprayer is a general-purpose payload usable in sandbox flight or any mission.
    private var isMountedAgriculturalSprayerAvailable: Bool {
        guard mountedCADPayload == nil else {
            return false
        }

        guard payloadState == .attached, payloadMountState == .occupied else {
            return false
        }

        return payloadDraftConfiguration.payloadType == .agriculturalSprayer
    }

    private var payloadCameraFeedLabel: String {
        switch payloadCameraController.opticsState.mode {
        case .optical:
            return "EO CAM"
        case .thermalStub:
            return "THERMAL"
        case .nightStub:
            return "NV CAM"
        }
    }

    private func publishPayloadCameraOpticsState() {
        payloadCameraOpticsState = payloadCameraController.opticsState
        sceneController.setPayloadCameraOpticsState(payloadCameraOpticsState)
        payloadThermalState.isAvailable = payloadCameraOpticsState.isAvailable
        payloadThermalState.isEnabled = payloadCameraOpticsState.isAvailable
            && payloadCameraOpticsState.mode == .thermalStub
    }

    private func refreshPayloadCameraStatus(deltaTime: TimeInterval = 0.0) {
        if !isMountedPayloadCameraAvailable {
            previousPayloadCameraVelocity = nil
            previousPayloadCameraAngularVelocity = nil
        }
        payloadCameraController.setOpticsAvailability(
            isAvailable: isMountedPayloadCameraAvailable,
            isPowered: isMountedPayloadCameraAvailable,
            feedLabel: payloadCameraFeedLabel
        )
        let targetDistance = sceneController.payloadCameraTargetDistance(maxDistance: 500.0)
        let linearSpeed = Double(simd_length(state.velocity))
        let angularSpeed = Double(simd_length(state.angularVelocity))
        let linearAcceleration: Double
        let angularAcceleration: Double
        if deltaTime > 0.0001,
           let previousVelocity = previousPayloadCameraVelocity,
           let previousAngularVelocity = previousPayloadCameraAngularVelocity {
            linearAcceleration = Double(simd_length((state.velocity - previousVelocity) / Float(deltaTime)))
            angularAcceleration = Double(simd_length((state.angularVelocity - previousAngularVelocity) / Float(deltaTime)))
        } else {
            linearAcceleration = 0.0
            angularAcceleration = 0.0
        }

        let speedStabilityLimit = selectedDroneProfile.airframeClass == .multirotor
            ? max(payloadCameraController.opticsState.stabilizationSpeedLimitMps, 3.0)
            : 14.0
        let linearStability = min(max(1.0 - linearSpeed / speedStabilityLimit, 0.0), 1.0)
        let angularStability = min(max(1.0 - angularSpeed / 0.65, 0.0), 1.0)
        let accelerationStability = min(max(1.0 - linearAcceleration / 3.6, 0.0), 1.0)
        let angularAccelerationStability = min(max(1.0 - angularAcceleration / 5.0, 0.0), 1.0)
        let platformStability = min(
            max(
                linearStability * 0.42 +
                angularStability * 0.34 +
                accelerationStability * 0.12 +
                angularAccelerationStability * 0.12,
                0.0
            ),
            1.0
        )

        let motionDisturbance = min(
            max(
                angularSpeed / 0.55 * 0.46 +
                angularAcceleration / 3.0 * 0.34 +
                linearAcceleration / 2.8 * 0.14 +
                linearSpeed / 1.2 * 0.06,
                0.0
            ),
            1.0
        )
        payloadCameraController.updateStabilization(
            speedMetersPerSecond: linearSpeed,
            airframeClass: selectedDroneProfile.airframeClass
        )
        payloadCameraController.updateTargetDistance(targetDistance)
        payloadCameraController.updateOptics(
            dt: deltaTime,
            platformStability: platformStability,
            motionDisturbance: motionDisturbance
        )
        publishPayloadCameraOpticsState()
        previousPayloadCameraVelocity = state.velocity
        previousPayloadCameraAngularVelocity = state.angularVelocity

        sceneController.setPayloadCameraFocusReleaseID(payloadCameraController.trackedReleaseID)
        let sceneSnapshot = sceneController.payloadCameraSnapshot(for: payloadCameraController.trackedReleaseID)
        if let restoreMode = payloadCameraController.sync(
            sceneSnapshot: sceneSnapshot,
            currentMode: cameraConfiguration.mode
        ) {
            let oldMode = cameraConfiguration.mode
            cameraConfiguration.mode = restoreMode
            syncCameraSystem(from: oldMode)
        }
        payloadCameraStatus = payloadCameraController.status
        let signals = payloadCameraController.consumeMissionSignals()
        if !signals.isEmpty {
            payloadMissionSignals.append(contentsOf: signals)
            if payloadMissionSignals.count > 24 {
                payloadMissionSignals.removeFirst(payloadMissionSignals.count - 24)
            }
        }
        refreshRangefinderStatus()
        refreshLidarStatus()
        refreshHoseAimStatus(deltaTime: deltaTime)
        refreshCapsuleLauncherStatus(deltaTime: deltaTime)
        refreshAgriculturalSprayerStatus(deltaTime: deltaTime)
        refreshFlightControlDiagnostics()
    }

    /// No aim/raycast needed at all (unlike the hose) — the launcher just needs to know it's
    /// mounted, keep its ammo/rig state in sync, run the truck-recharge timer, and keep the
    /// ground-projected blast-radius reticle plus the bombardier camera rig following the drone.
    /// Cheap enough to run unconditionally every tick.
    private func refreshCapsuleLauncherStatus(deltaTime: TimeInterval = 0.0) {
        capsuleController.setAvailability(
            isAvailable: isMountedCapsuleLauncherAvailable,
            isPowered: isMountedCapsuleLauncherAvailable,
            rigSize: payloadDraftConfiguration.fireCapsuleSize,
            rigCount: payloadDraftConfiguration.fireCapsuleCount
        )
        capsuleController.updateRecharge(
            isEligible: isCapsuleRechargeEligible(),
            secondsPerCapsule: FireCapsuleTuning.rechargeSecondsPerCapsule(
                for: missionScenarioConfiguration?.parameters.difficulty ?? .medium
            ),
            deltaTime: deltaTime
        )
        capsuleState = capsuleController.state
        sceneController.setCapsuleLauncherOpticsAvailability(capsuleState.isAvailable)

        if capsuleState.isAvailable {
            sceneController.setFireCapsuleTargetReticle(
                dronePlanarPosition: currentPlanarPosition(),
                radiusMeters: capsuleState.capsuleSize.blastRadiusMeters
            )
        } else {
            sceneController.setFireCapsuleTargetReticle(dronePlanarPosition: nil, radiusMeters: 0)
        }

        let capsuleSignals = capsuleController.consumeMissionSignals()
        if !capsuleSignals.isEmpty {
            payloadMissionSignals.append(contentsOf: capsuleSignals)
            if payloadMissionSignals.count > 24 {
                payloadMissionSignals.removeFirst(payloadMissionSignals.count - 24)
            }
        }
    }

    /// No aim/gimbal, no mission-scenario gating (unlike the hose/capsule launcher) — the
    /// sprayer just needs to know it's mounted and drain its tank while the trigger is held.
    /// The tank's liquid mass is mutated live into `installedPayloadConfiguration.payloadMass`
    /// so the airframe actually gets lighter (and more agile) as it empties, same idea as the
    /// fiber-optic reel losing mass as it pays out.
    private func refreshAgriculturalSprayerStatus(deltaTime: TimeInterval = 0.0) {
        agriculturalSprayerController.setAvailability(
            isAvailable: isMountedAgriculturalSprayerAvailable,
            isPowered: isMountedAgriculturalSprayerAvailable,
            configuredTankLiters: Double(payloadDraftConfiguration.agriculturalSprayerTankLiters)
        )
        let drainedLiters = agriculturalSprayerController.drain(deltaTime: Float(deltaTime))
        if drainedLiters > 0.0, let currentMass = installedPayloadConfiguration?.payloadMass,
           installedPayloadConfiguration?.payloadType == .agriculturalSprayer {
            let drainedMassKg = Float(drainedLiters) * AgriculturalSprayerTuning.liquidDensityKgPerLiter
            let newMass = max(AgriculturalSprayerTuning.hardwareOverheadKg, currentMass - drainedMassKg)
            installedPayloadConfiguration?.payloadMass = newMass
            refreshPayloadRuntimeState()
        }
        agriculturalSprayerState = agriculturalSprayerController.state
        sceneController.setAgriculturalSprayerSpraying(
            agriculturalSprayerState.isSpraying,
            dronePlanarPosition: currentPlanarPosition()
        )

        #if DEBUG
        let debugSummary = "mounted=\(isMountedAgriculturalSprayerAvailable) " +
            "type=\(payloadDraftConfiguration.payloadType.rawValue) " +
            "available=\(agriculturalSprayerState.isAvailable) powered=\(agriculturalSprayerState.isPowered) " +
            "spraying=\(agriculturalSprayerState.isSpraying) tank=\(agriculturalSprayerState.tankRemainingLiters)"
        if debugSummary != lastLoggedAgriSprayerDebugState {
            print("[AgriSprayer] \(debugSummary)")
            lastLoggedAgriSprayerDebugState = debugSummary
        }
        #endif
    }

    /// The drone must actually LAND (not just hover) within a small radius of the fire truck to
    /// reload — mirrors `enforceHoseTetherConstraint`'s distance-to-truck calc, but only reads
    /// distance, doesn't clamp position (there's no physical tether for the capsule launcher).
    private func isCapsuleRechargeEligible() -> Bool {
        guard activeMissionScenarioKind == .fireResponse,
              capsuleController.state.isAvailable,
              physicalState == .landed,
              let truckPosition = sceneController.currentFireTruckWorldPosition() else {
            return false
        }
        return simd_length(state.position - truckPosition) <= FireCapsuleTuning.rechargeZoneRadiusMeters
    }

    private func refreshLidarStatus(forcePublish: Bool = false) {
        let wasScanning = lidarWasScanning
        lidarController.setAvailability(
            isAvailable: isMountedLidarAvailable,
            isPowered: isMountedLidarAvailable
        )
        sceneController.updateLidarGimbal(state: lidarController.opticsState)
        let stats = sceneController.scanLidarSweep(state: lidarController.opticsState)
        lidarController.updateStatistics(
            capturedPointCount: stats.mapPointCount,
            rawReturnCount: stats.rawReturnCount,
            coverageSquareMeters: stats.coverageSquareMeters,
            meanReturnsPerPoint: stats.meanReturnsPerPoint,
            scanCount: stats.scanCount,
            isBufferFull: stats.isBufferFull
        )
        // Stopping the scan — by button, by losing power, by unmounting — finalises what is on
        // disk: the vertex count is patched in and both files are complete up to that instant,
        // while remaining open so resuming continues the same recording.
        if wasScanning, !lidarController.opticsState.isScanning {
            sceneController.snapshotLidarStreams()
        }
        lidarWasScanning = lidarController.opticsState.isScanning

        // Publishing every tick redrew the whole LiDAR panel at frame rate for a counter the pilot
        // cannot read that fast. Statistics land at 5 Hz; anything the pilot actually operates
        // (power, scan enable, gimbal, filter, colour) publishes immediately through its own path.
        let now = CACurrentMediaTime()
        if forcePublish || now - lidarStatePublishTime >= 0.2 {
            lidarStatePublishTime = now
            lidarOpticsState = lidarController.opticsState
        }

        let lidarSignals = lidarController.consumeMissionSignals()
        if !lidarSignals.isEmpty {
            payloadMissionSignals.append(contentsOf: lidarSignals)
            if payloadMissionSignals.count > 24 {
                payloadMissionSignals.removeFirst(payloadMissionSignals.count - 24)
            }
        }
    }

    private func refreshRangefinderStatus() {
        rangefinderController.setAvailability(
            isAvailable: isMountedRangefinderAvailable,
            isPowered: isMountedRangefinderAvailable
        )
        sceneController.updateRangefinderGimbal(state: rangefinderController.opticsState)
        let distance = rangefinderController.opticsState.isArmed
            ? sceneController.rangefinderTargetDistance(maxDistance: rangefinderController.opticsState.maxRangeMeters)
            : nil
        rangefinderController.updateMeasuredDistance(distance)
        sceneController.updateRangefinderBeam(state: rangefinderController.opticsState)
        rangefinderOpticsState = rangefinderController.opticsState

        let rangefinderSignals = rangefinderController.consumeMissionSignals()
        if !rangefinderSignals.isEmpty {
            payloadMissionSignals.append(contentsOf: rangefinderSignals)
            if payloadMissionSignals.count > 24 {
                payloadMissionSignals.removeFirst(payloadMissionSignals.count - 24)
            }
        }
    }

    private func refreshHoseAimStatus(deltaTime: TimeInterval = 0.0) {
        let hoseIsMounted = isMountedHoseAvailable
        hoseController.setAvailability(
            isAvailable: hoseIsMounted,
            isPowered: hoseIsMounted
        )
        // The supply truck is equipment for the mounted hose, not a mission-only prop. In a fire
        // response the scenario truck wins; in sandbox/free flight the scene creates one beside
        // the dock. Turning the payload off removes only that sandbox support truck.
        sceneController.setFireHoseSupportActive(hoseIsMounted)
        guard hoseIsMounted else {
            if isExternalHoseAimActive {
                isExternalHoseAimActive = false
            }
            hoseOpticsState = hoseController.opticsState
            return
        }
        let installedHose = installedPayloadConfiguration
        sceneController.updateHoseGimbal(
            state: hoseController.opticsState,
            tetherLengthMeters: installedHose?.fireHoseLengthMeters ?? 1.0,
            diameterClass: installedHose?.fireHoseDiameterClass ?? .standard,
            deltaTime: Float(deltaTime)
        )

        // The nozzle raycast (`updateHoseAimAndSpray`) is a full-scene hit-test — by far the most
        // expensive thing this function does, and it used to run unconditionally every tick
        // whenever a hose was mounted, whether or not the operator was even looking at it. The
        // suppression mechanic only reacts to the aimed tree while the trigger is held
        // (`FireResponseRuntime.applySuppression` ignores `aimedFireIndex` whenever `isSpraying`
        // is false), and the HUD's aim indicator is only ever visible while actually looking
        // through the hose's own payload-optics view — so flying around normally with a hose
        // mounted (most of a fire-response mission) can skip the raycast entirely.
        let isSpraying = hoseController.opticsState.isSpraying
        let isViewingHoseOptics = cameraConfiguration.mode == .payloadOptics
            && !payloadCameraOpticsState.isAvailable
            && !rangefinderOpticsState.isAvailable
            && hoseController.opticsState.isAvailable
        let shouldSampleAim = hoseController.opticsState.isAvailable
            && (isSpraying || isViewingHoseOptics || isExternalHoseAimActive)

        let aimedIndex: Int?
        if shouldSampleAim {
            aimedIndex = sceneController.updateHoseAimAndSpray(
                fireTreeNodes: sceneController.fireTreeNodes,
                isSpraying: isSpraying
            )
        } else {
            aimedIndex = nil
            sceneController.hideHoseSprayVisual()
        }

        hoseController.updateAimedFire(
            index: aimedIndex,
            progress: fireResponseRuntime?.suppressionProgress(for: aimedIndex) ?? 0.0
        )
        hoseOpticsState = hoseController.opticsState

        let hoseSignals = hoseController.consumeMissionSignals()
        if !hoseSignals.isEmpty {
            payloadMissionSignals.append(contentsOf: hoseSignals)
            if payloadMissionSignals.count > 24 {
                payloadMissionSignals.removeFirst(payloadMissionSignals.count - 24)
            }
        }
    }

    private func buildWarnings() -> [String] {
        let fleetWarningStatus = currentFleetStatusSnapshot()
        var output = DroneWarningBuilder(
            isArmed: isArmed,
            physicalState: physicalState,
            collisionAnalysis: collisionAnalysis,
            weather: weather,
            batteryState: batteryState,
            batteryFireActive: batteryFireActive,
            damageState: damageState,
            collisionAftermathState: collisionAftermathState,
            signalLossCause: signalLossCause,
            payloadSelfInteractionSeverity: payloadSelfInteractionSeverity,
            selectedDroneProfile: selectedDroneProfile,
            state: state,
            fleetStatus: fleetWarningStatus,
            mode: mode,
            hybridVTOLSafetyState: hybridVTOLSafetyState
        ).build()
        if let mountedCADPayload {
            output.append(contentsOf: mountedCADPayload.runtimeWarningKeys(
                maxPayloadMass: activeUAVProfile?.payloadDataResolution.maxPayloadMass
            ))
        }
        if isHoseTetherTaut {
            output.append("warning.hose_tether_taut")
        }
        return Array(NSOrderedSet(array: output)) as? [String] ?? output
    }

    private func buildTelemetryMetadata() -> TelemetrySessionMetadata {
        TelemetrySessionMetadata(
            projectID: currentProjectID,
            projectName: currentProjectName,
            modelID: selectedDroneProfile.id,
            modelName: selectedDroneProfile.displayName,
            manufacturer: selectedDroneProfile.manufacturer,
            isAbstractModel: selectedDroneProfile.isAbstract,
            abstractParametersSummary: selectedDroneProfile.isAbstract ? abstractParametersSummary : "n/a",
            weatherPreset: weather.preset.title,
            weatherIntensity: weather.intensity,
            terrainPreset: terrain.preset.title,
            terrainDensity: terrain.density,
            cameraMode: cameraConfiguration.mode.title,
            controlMode: flightControlMode.title
        )
    }

